-- ============================================================================
-- EasyMeals Supabase: XOA DU LIEU CU va NHAP MOI (TheMealDB tieng Viet)
-- Chay voi SUPABASE_SERVICE_ROLE_KEY (qua SQL Editor hoac psql)
-- ============================================================================

-- Buoc 1: Xoa du lieu cu (theo thu tu foreign key)
DELETE FROM public.recipe_ingredients;
DELETE FROM public.recipes;
DELETE FROM public.ingredient_aliases;
DELETE FROM public.ingredients;

-- Buoc 2: Nhap nguyen lieu


-- Buoc 3: Nhap cong thuc va nguyen lieu cua cong thuc


-- Buoc 4: Kiem tra ket qua
SELECT 'ingredients' AS tbl, count(*) FROM public.ingredients
UNION ALL SELECT 'recipes', count(*) FROM public.recipes
UNION ALL SELECT 'recipe_ingredients', count(*) FROM public.recipe_ingredients;

