INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7b6c47a1-cd79-55d2-9556-f1fef28daaba', 'Tôm sốt cà chua Hy Lạp (Garides Saganaki)', 'man'::public.dish_category, '["Đặt tôm vào nồi và thêm đủ nước để ngâm. Luộc trong 5 phút. Đổ nước, giữ lại nước, và để một bên.", "Đun 2 muỗng canh dầu trong nồi. Thêm hành tây; nấu và khuấy cho đến khi mềm. Trộn ngô tay, rượu vang, cà chua, tỏi và phần dầu ô liu còn lại. Sôi nhẹ, thỉnh thoảng khuấy, trong khoảng 30 phút, hoặc cho đến khi sốt đặc.", "Trong khi sốt sôi nhẹ, tôm nên nguội đủ để bắt tay. Trước hết bóc chân bằng cách nhúp chúng, sau đó kéo vỏ ra, để đầu và đuôi nguyên.", "Khi sốt đã đặc, khuấy tôm vào. Đun sôi nhẹ lại nếu sốt đã nguội với tôm, và nấu khoảng 5 phút. Thêm phô mai feta và bớt khỏi lửa. Đ để đến khi phô mai bắt đầu tan. Ăn nóng với lát bánh mì vỏ giòn.", "Hoặc hoàn toàn không truyền thống, bạn có thể thêm một vài muỗng canh nước dùng hoặc sốt cà chua vào công thức này để tạo sốt mì ngon. Trộn với mì sau khi thêm feta, và ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7b6c47a1-cd79-55d2-9556-f1fef28daaba', '0b3c601a-12db-550f-ac0a-3c1b3c7410c5', 500.0, 'g'::public.quantity_unit);
