INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a95fb525-230d-561c-821a-cf92446070c1', 'Nướng gà enchilada (Chicken Enchilada Casserole)', 'man'::public.dish_category, '["Cắt mỗi ngực gà thành khoảng 3 miếng, để nó chín nhanh hơn và cho vào nồi nhỏ. Đổ sốt Enchilada lên nó và nấu đậy nắp trên lửa thấp đến trung bình cho đến khi gà chín qua, khoảng 20 phút. Không cần nước, gà sẽ nấu trong sốt Enchilada. Đảm bảo bạn khuấy đôi khi để nó không dính đáy.", "Lấy gà khỏi nồi và xé bằng hai nĩa.", "Đun lò trước đến 190°C.", "Bắt đầu xếp lớp nướng. Bắt đầu với khoảng 60 ml sốt Enchilada còn lại dưới đáy đĩa nướng. Tôi dùng một chiếc đĩa nướng dài, vì vậy tôi có thể đặt 2 bánh tráng ngô trên đáy. Đặt 2 bánh tráng ngô trên đáy,위에 với ⅓ gà và ⅓ phần sốt còn lại. Rắc ⅓ phô mai và lặp lại bắt đầu với 2 bánh tráng ngô nữa, sau đó gà, sốt, phô mai. Lặp lại với lớp cuối cùng với các nguyên liệu còn lại, bánh tráng ngô, gà, sốt và phô mai.", "Nấu trong 20 đến 30 phút không đậy nắp, cho đến khi nổi bọt và phô mai đã nở và bắt đầu vàng trên đầu.", "Ăn khi ấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a95fb525-230d-561c-821a-cf92446070c1', '7c0def60-47c2-5c0f-9be5-472dfea354b6', 396.9, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a95fb525-230d-561c-821a-cf92446070c1', '4ea2d1e0-1e66-5fa8-9f10-d62c6048bdde', 720.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a95fb525-230d-561c-821a-cf92446070c1', '917d678b-9605-5e7c-a441-3b218e7ddbb8', 6.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a95fb525-230d-561c-821a-cf92446070c1', '7c9a15f2-fae9-5394-bcbb-9bbae8011db7', 2.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('801bcbca-0a88-50dc-b8c5-e20f67471e57', 'Kapsalon Hà Lan (Kapsalon)', 'man'::public.dish_category, '["Cắt thịt thành các sợi. Đun dầu trong chảo và chiên các sợi trong 6 phút cho đến khi chín.", "Nướng khoai tây chiên cho đến khi vàng trong chiên nồi. Khi sẵn sàng chuyển sang đĩa nướng. Đảm bảo khoai tây chiên được trải khắp toàn bộ đĩa.", "Phủ khoai tây chiên với một lớp thịt mới và trải đều.", "Thêm một lớp phô mai lên thịt. Bạn cũng có thể dùng phô mai đã xay. Khi xong đặt vào lô trong vài phút cho đến khi phô mai tan.", "Băm xà lách, cà chua và dưa leo thành các miếng nhỏ và trộn cùng nhau. làm salad cơ bản. Thêm vào đó bạn có thể thêm ô liu và ớt jalapenos và hành tím đỏ.", "Chia salad lên đĩa và ăn với sốt tỏi và sốt cay."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('801bcbca-0a88-50dc-b8c5-e20f67471e57', 'aa1cf493-d9e5-5879-9b2d-2de9e262d7c0', 250.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('801bcbca-0a88-50dc-b8c5-e20f67471e57', '3284d34f-d066-5af4-97b0-b116a5f7c514', 500.0, 'g'::public.quantity_unit);
