INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c70af49d-07a0-5359-841e-9a1c5e3d4dbc', 'Mì Ý sốt thịt bò băm (Spaghetti Bolognese)', 'man'::public.dish_category, '["Đặt hành tây và dầu vào chảo lớn và chiên trên lửa khá cao trong 3-4 phút. Thêm tỏi và thịt bò băm và chiên cho đến khi cả hai đều vàng. Thêm nấm và thảo mộc, và nấu thêm vài phút.", "Khuấy vào cà chua, nước dùng bò, sốt cà chua hoặc nét cà chua, sốt Worcestershire và nems. Đun sôi, rồi giảm lửa, nắp và ninh, khuấy đôi khi, trong 30 phút.", "Trong lúc đó, nấu mì Ý trong chảo lớn nước sôi muối, theo hướng dẫn trên bao bì. Rarget nước tốt, vò nước nóng qua nó, trả vào chảo và thêm chút dầu ô liu nếu muốn, rồi khuấy vào sốt thịt. Phục vụ trong tô nóng và truyền phô mai Parmesan để rắc lên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c70af49d-07a0-5359-841e-9a1c5e3d4dbc', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 2.0, 'piece'::public.quantity_unit);
