INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8c150487-7673-5c39-99ef-c53e025507c5', 'Penne sốt cà chua cay (Spicy Arrabiata Penne)', 'rau'::public.dish_category, '["Đun nồi lớn nước cho sôi. Thêm muối vào nước sôi, rồi thêm mì Ý. Nấu theo hướng dẫn trên bao bì, khoảng 9 phút.", "Trong chảo xào lớn trên lửa vừa-cao, thêm dầu ô liu và đun cho đến khi dầu rọi. Thêm tỏi và nấu, khuấy, cho đến khi thơm, 1 đến 2 phút. Thêm cà chua đã nghiền, ớt khô, gia vị thảo mộc hỗn hợp Ý và muối và tiêu theo khẩu vị. Đun sôi và nấu trong 5 phút. Bớt bấm và thêm húng quế tây.", "Rarget mì Ý và thêm vào sốt. Trang trí bằng mảnh phô mai Parmigiano-Reggiano và thêm húng quế tây và phục vụ khi ấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8c150487-7673-5c39-99ef-c53e025507c5', '08043ecc-1220-5c4f-903b-43e8a06e5749', 453.6, 'g'::public.quantity_unit);
