INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('04053ba5-f7a0-51fb-b9d4-837567cfc41a', 'Cá hồi sốt mật ong Teriyaki (Honey Teriyaki Salmon)', 'man'::public.dish_category, '["Trộn tất cả nguyên liệu trong sốt mật ong Teriyaki cùng nhau. Đánh trộn để hòa quyện tốt. Hợp cá hồi và sốt cùng nhau.", "Đun chảo trên lửa thấp vừa. Thêm dầu, Chiên cá hồi trên cả hai bên cho đến khi hoàn toàn chín bên trong và sốt đặc.", "Rắc vừng lên và ăn ngay."]'::jsonb, 4);
