INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7e2ffd72-48b9-5a77-ad5d-33b3da992527', 'Mì xào Pad See Ew Thái (Pad See Ew)', 'man'::public.dish_category, '["Trộn sốt trong bát nhỏ.", "Đập băm tỏi vào wok với dầu. Đặt lên lửa lớn, khi nóng, thêm thịt gà và cuống cải làn, nấu cho đến khi thịt gà nhẹ vàng.", "Dồn sang bên wok, đập trứng vào và xào trộn. Đừng lo nếu trứng dính đáy wok - nó sẽ cháy nhẹ và tạo vị đặc trưng.", "Thêm mì, lá cải làn và sốt. Trộn nhẹ nhàng cho đến khi mì bị tối màu và lá héo. Dùng ngay!"]'::jsonb, 4);
