INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9be7e339-4083-5e76-9197-ebcf71b45f68', 'Lasagna chay (Vegan Lasagna)', 'rau'::public.dish_category, '["1. Đun lò 180 độ C.", "2. Luộc rau 5-7 phút cho đến khi mềm. Thêm đậu lăng đỏ xanh và đun sôi nhẹ, thêm viên súp nếu muốn. Tiếp tục nấu và khuấy cho đến khi đậu lăng mềm, mất khoảng 20 phút.", "3. Đặt cải bó xôi vào nước sôi vài phút, rồi lấy ra và để một bên.", "4. Thêm nước vào chảo và nấu lá mì lasagne. Khi chín, rổ nước và để một bên.", "5. Để làm sốt, nung bơ thực vật thuần chay và thêm bột mì, rồi dan dần thêm sữa đậu nành cùng mù tạt và giấm. Nấu và khuấy cho đến khi mịn và sau đó xếp lasagne theo ý muốn trong khay nướng.", "6. Nướng trong lò đã đun khoảng 25 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9be7e339-4083-5e76-9197-ebcf71b45f68', '90c6ad07-f649-59d9-a036-dfc5495edda1', 240.0, 'ml'::public.quantity_unit);
