INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5531275e-a7e9-5e2a-968d-459f06e6cece', 'Salad nui Địa Trung Hải (Mediterranean Pasta Salad)', 'man'::public.dish_category, '["Đun sôi nồi lớn nước có muối.", "Cho nui vào, khuấy một lần và nấu khoảng 10 phút hoặc theo hướng dẫn trên bao bì.", "Trong lúc đó, rửa cà chua và cắt thành tư phần. Cắt lát ô liu. Rửa húng quế tây.", "Cho cà chua vào bát salad và vặn lá húng quế qua trên. Thêm 1 muỗng canh dầu ô liu và trộn.", "Khi nui đã chín, ráo vào cái rổ và tưới nước lạnh qua để nguội nhanh.", "Trộn nui vào bát salad với cà chua và húng quế.", "Thêm ô liu đã lát, viên phô mai Mozzarella tươi đã ráo và miếng cá ngừ. Trộn đều và để salad nghỉ ít nhất nửa giờ cho vị hòa nhau.", "Rắc nui với chút tiêu đen xay nhè và rưới dầu ô liu còn lại ngay trước khi ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5531275e-a7e9-5e2a-968d-459f06e6cece', '8a635132-7bb6-5680-84b4-0ee256d3d219', 200.0, 'g'::public.quantity_unit);
