INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('65db5e1b-f06b-565f-bf60-b4c102c67b43', 'Đậu Rang Dal (Dal fry)', 'rau'::public.dish_category, '["Rửa và ngâm đậu Toor Dal tách đôi trong khoảng 720 ml nước lọc, trong ít nhất một giờ. Đậu sẽ tăng gấp đôi thể tích sau khi ngâm. Ráo nước.", "Nấu đậu với 600 ml nước và thêm muối, nghệ, trên lửa cao vừa, cho đến khi mềm (khoảng 30 phút) nó nên như sup đặc.", "Trong một chảo chiên, đun nóng Ghee. Thêm hạt thì là Cumin, và hạt mù tạt. Sau khi hạt nứt, thêm lá nguyệt quế, ớt xanh, gừng và bột ớt. Khuấy trong vài giây.", "Thêm cà chua thái nhỏ, muối và đường khuấy và nấu cho đến khi cà chua mềm và nhừ.", "Thêm ngò rí và bột gia vị Garam Masala nấu khoảng một phút.", "Đổ phần nêm qua đậu trộn nó tốt và nấu thêm một phút nữa.", "Phục vụ với Naan."]'::jsonb, 4);
