INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0c60d06a-a6c1-51b5-82a4-d1fbd40ec153', 'Bánh sô cô la chay', 'rau'::public.dish_category, '["Trộn tất cả nguyên liệu khô với nguyên liệu ẩm và xay trộn đều. Nướng 45 phút ở 180 độ. Trang trí với chút sô cô la chay đã nung."]'::jsonb, 4);
