INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0254355d-88fc-5612-b3a2-e0753f522330', 'Gà Handi (Chicken Handi)', 'man'::public.dish_category, '["Lấy một nồi lớn hoặc wok, đủ lớn để nấu tất cả gà, và đun nóng dầu thực vật trong đó. Khi dầu nóng, cho hành tây đã cắt vào và chiên chúng cho đến khi vàng đậm. Sau đó lấy ra đĩa và để một bên.", "Đến cùng nồi, cho tỏi đã kẹo vào và xào trong một phút. Sau đó thêm cà chua đã kẹo và nấu cho đến khi cà chua mềm. Điều này sẽ mất khoảng 5 phút.", "Sau đó trả hành đã chiên vào nồi và khuấy. Thêm Sot đặc gừng và xào kỹ.", "Bây giờ thêm hạt thì là Cumin, nửa hạt ngò rí và ớt xanh đã kẹo. Cho chúng khuấy nhanh.", "Tiếp theo vào các gia vị – Bột nghệ và Bột ớt. Xào các gia vị tốt trong vài phút.", "Thêm các miếng gà vào wok, nêm muối theo khẩu vị và nấu gà đậy nắp trên lửa thấp đến trung bình cho đến khi gà gần chín qua. Điều này sẽ mất khoảng 15 phút. Xào chậm gà sẽ tăng hương vị, vì vậy không vội bước này bằng cách đặt nó trên lửa cao.", "Khi dầu tách khỏi các gia vị, thêm sữa chua đã đánh giữ lửa thấp nhất để sữa chua không tách. Rắc hạt ngò rí còn lại và thêm nửa lá Cỏ ca ri Fenugreek khô. Trộn đều.", "Cuối cùng thêm kem sữa và cho một trộn cuối cùng để kết hợp mọi thứ tốt.", "Rắc phần Cỏ ca ri Fenugreek khô còn lại và bột gia vị Garam Masala và phục vụ gà Handi nóng với naan hoặc rotis."]'::jsonb, 4);
