INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('69785421-3e3c-5895-88a8-a8a5734686db', 'Salad khoai tây cay kiểu Bắc Phi (Spicy North African Potato Salad)', 'rau'::public.dish_category, '["Nấu khoai tây - đặt khoai tây vào nồi nước lạnh, và đun cho sôi. Luộc trong 20 phút, hoặc cho đến khi khoai tây mềm. Bạn biết chúng đã chín khi bạn có thể đâm dao vào chúng và dao cắm thẳng vào.", "Trộn gia vị ớt harissa, dầu ô liu, muối và tiêu và nước cốt chanh trong tô nhỏ và đánh trộn cho đến khi kết hợp.", "Khi khoai tây đã chín, rarget nước và cắt khoai tây thành nửa.", "Thêm hỗn hợp harissa và hành lá vào khoai tây và khuấy.", "Trong tô salad lớn, rải rau rocket ra.", "Đặt hỗn hợp khoai tây lên trên và khuấy.", "Thêm feta, bạc hà và rắc hạt thông lên trên.", "Điều chỉnh muối và tiêu theo khẩu vị."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('69785421-3e3c-5895-88a8-a8a5734686db', '75b6798c-8d17-53d4-904f-41c5c967c058', 650.0, 'g'::public.quantity_unit);
