INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('33d15e3d-0aa7-514b-a2ea-2da0be980912', 'Bánh wellington bò', 'man'::public.dish_category, '["Đặt nấm vào máy xay thực phẩm với ít gia vị và xay nhịp nhàng thành sốt đặc thô. Lấy sốt vào chảo và nấu trên lửa cao khoảng 10 phút, khuân thường xuyên, để bay hơi nước từ nấm. Rải ra trên đĩa để nguội.", "Đun trong chảo chiên và thêm ít dầu ô liu. Nems thịt bò và rang trong chảo nóng chỉ 30 giây mỗi mặt. (Bạn không muốn nấu nó ở giai đoạn này, chỉ muốn tạo màu). Lấy thịt bò ra khỏi chảo và để nguội, rồi quét đều bằng mù tạt.", "Đặt một tờ bọc thực phẩm trên bề mặt làm việc và sắp xếp các lát giăm bông Parma lên trên, các hàng chồng chéo nhẹ. Dùng dao bề dày, rải sốt nấm lên giăm bông, rồi đặt miếng thăn đã rang vào chính giữa. Giữ chặt bọc thực phẩm từ cạnh, cuộn ngăn nắp giăm bông Parma và nấm quanh thịt bò để tạo hình hình trụ chặt. Xoắn hai đầu của bọc thực phẩm để cố định. Để trong tủ lạnh 15-20 phút để thịt bò kết dính và giữ hình dạng.", "Trình bột ngàn lớp trên bề mặt đã bón bột thành hình chữ nhật lớn, dày như một đồng xu £1. Bớp bọc thực phẩm khỏi thịt bò, rồi đặt vào chính giữa. Quét bột xung quanh bằng lòng đỏ trứng. Gấp các đầu lên, rồi bọc bột quanh thịt bò, cắt bỏ phần thừa. Lật ngược, để đường keo nằm dưới, và đặt lên khay nướng. Quét toàn bộ bột bằng trứng và để trong tủ lạnh khoảng 15 phút để bột nghỉ.", "Đun lò đến 200°C.", "Chét nhẹ bột mỗi khoảng 1cm và quét lại bằng lòng đỏ trứng đánh tan. Nướng 20 phút, rồi giảm lò xuống 180°C và nấu thêm 15 phút. Để nghỉ 10-15 phút trước khi cắt lát và phục vụ với các món kèm bạn chọn. Thịt bò vẫn nên còn hồng ở chính giữa khi bạn phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('33d15e3d-0aa7-514b-a2ea-2da0be980912', 'e5d6f15f-da22-5023-a84c-79eba0d033e4', 400.0, 'g'::public.quantity_unit);
