INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('33d15e3d-0aa7-514b-a2ea-2da0be980912', '2ffc5396-f90c-5cd5-9948-be792752eec6', 2.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('871546bb-379f-504f-9797-07616d8b2cf0', 'Cơm nạo cừu Ấn Độ (Lamb Biryani)', 'man'::public.dish_category, '["Xay nhuyễn hạt điều, hạt anh túc và hạt thì là thành hỗn hợp mịn, dùng ít nước nhất có thể. Để riêng.", "Chiên đều hành tây đã cắt khi nóng. Không cho quá nhiều hành vào dầu. Khi hành vàng nhạt, vớt ra và ráo trên khăn giấy. Hành chiên sẽ giòn khi ráo. Chiên hạt điều cho vàng. Để riêng.", "Rửa gạo, ngâm trong nước hai mươi phút.", "Trong lúc đó, lấy chảo lớn rộng, cho dầu cần lên lửa vừa, cho hành thái lát, cho hỗn hợp đã xay, thêm ớt xanh, hỗn hợp gừng tỏi và tỏi, xào một phút.", "Rồi thêm cà chua, xào kỹ cho chín nhưng không nhừ.", "Thêm bột ớt đỏ, gia vị cơm biryani, lá bạc hà, lá ngò rí, xào kỹ.", "Thêm sữa chua nguyên kem, khuấy đều. Luôn dời chảo khỏi bếp khi thêm sữa chua để tránh hiện tượng lát.", "Đưa chảo trở lại bếp, thêm thịt cừu đã rửa, muối và nửa chén nước, khuấy đều. Nấu một giờ, đậy nắp hỏa vừa-nên hoặc nồi áp lực 6 tiếng. Nếu nước chưa cạn hoàn toàn, hở nắp cho khô.", "Lấy nồi lớn khác, thêm gạo gấp ba lần lượng gạo dùng, đun sôi. Khi sôi mãnh, thêm gạo, muối và hạt thì là, khuấy đều. Sau đúng 7 phút hoặc khi gạo chín 80%, tắt bếp, ráo nước.", "Bắt đầu xếp lớp. Bóp nhẹ và trải đều thịt cừu. Cho gạo nóng đã ráo lên trên. Trangs trí bằng hành chiên, bơ tinh chế, lá bạc hà, lá ngò rí và nhụy hoa nghệ tây đã hòa trong sữa.", "Đậy nắp nồi, nướng lò 175°C 15 phút hoặc cho đến khi chín nhưng không nhừ. Hoặc nấu trên bếp hỏa vừa 12 phút rồi hỏa thấp nhất 5 phút. Tắt bếp. Trộn đều và dùng nóng.", "Lưu ý:", "1. Nếu nướng lò, hãy dùng nồi lớn chịu nhiệt, đậy kín nắp và để trong lò bước cuối.", "2. Có thể bỏ gia vị biryani nếu không có, chỉ thêm garam masala (1 muỗng cà phê và bột ớt đỏ 3 muỗng cà phê thay cho 1 muỗng cà phê).", "3. Nếu cuối cùng quá cay, vắt chút chanh, sẽ giảm cay và làm nổi bật vị."]'::jsonb, 4);
