INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6ac5cc64-2bc6-59f7-91db-8deb3431248d', 'Gà nướng Tandoori', 'man'::public.dish_category, '["Trộn nước cốt chanh với bột ớt ngọt paprika và hành tím trong đĩa lớn thấp. Chĩa mỗi đùi gà ba lần, rồi lăn trong nước cốt và để một bên 10 phút.", "Trộn đều tất cả nguyên liệu ngâm, rồi đổ lên gà. Trộn đều mọi thứ, rồi đậy nắp và để tủ lạnh ít nhất 1 giờ. Có thể làm trước tới một ngày.", "Đun lò nướng. Đặt miếng gà trên giá đỡ đặt trên khay nướng. Chọc ít dầu và nướng 8 phút mỗi phía hoặc cho đến khi nhạt cháy và chín hết."]'::jsonb, 4);
