INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('24794406-3bb1-504c-874c-52a7540c9f52', 'Cà tím khói kiểu Ấn Độ (baingan bharta)', 'rau'::public.dish_category, '["Rửa cà tím trong nước. Khô khăn bếp. Thoa dầu toàn bộ và", "để nướng trên ngọn lửa mở. Bạn cũng có thể nướng cà tím hoặc nướng trong lò. Nhưng sau đó bạn sẽ không có", "mùi khói của cà tím. Quay cà tím sau 2 đến 3 phút trên lửa, để nó chín đều", "chín. Bạn cũng có thể nhét vài tép tỏi vào cà tím rồi nướng nó.", "Nướng cà tím cho đến khi chín hoàn toàn và mềm. Dùng dao kiểm tra độ chín. Dao nên trơn trượt", "dễ dàng trong cà tím mà không có cản trở. Lấy cà tím ra và ngâm trong bát nước cho đến khi nguội", "hoàn toàn.", "3. Bạn cũng có thể làm kỹ thuật dhungar phun mùi khói than vào cà tím. Đây là bước tùy chọn.", "Dùng than tự nhiên cho phương pháp này. Đun một mảnh than nhỏ trên lửa cho đến khi nó khói và đỏ.", "4. Cắt một số vết nhỏ trên cà tím bằng dao. Đặt mảnh than đỏ nóng vào đĩa tương tự nơi cà tím nướng", "được giữ. Thêm vài giọt dầu lên than. Than sẽ bắt đầu khói.", "5. Sớm như khói bắt đầu phát ra từ than, đậy nắp chặt toàn bộ đĩa bằng bát lớn. Để", "khói than thấm vào trong 1 đến 2 phút. Càng làm nhiều, món càng khói hơn", "trở thành. Tôi chỉ giữ một phút. Thay vào đó, bạn cũng có thể làm phương pháp dhungar này khi cà tím đã chín,", "chín, giống như cách chúng ta làm cho Dal Tadka.", "6. Bóc vỏ cà tím đã nướng và khói.", "7. Cắt nhuyễn cà tím đã nấu hoặc bạn thậm chí có thể nghiền nó.", "8. Trong wok hoặc chảo, đun nóng dầu. Rồi thêm hành tây và tỏi đã cắt nhuyễn.", "9. Xào hành cho đến khi trong suốt. Không để vàng.", "10. Thêm ớt xanh đã cắt nhỏ và xào một phút.", "11. Thêm cà chua đã cắt nhỏ và trộn tốt.", "12. Xào cà chua cho đến khi dầu bắt đầu tách ra khỏi hỗn hợp.", "13. Thêm bột ớt đỏ. Khuân và trộn tốt.", "14. Thêm cà tím đã cắt nhỏ và nấu.", "15. Khuân và trộn rất tốt cà tím đã cắt nhỏ với hỗn hợp gia vị hành cà chua.", "16. Nems muối. Khuân và xào thêm 4 đến 5 phút nữa.", "17. Cuối cùng khuân lá ngò rí vào cà tím hoặc trang trí bằng chúng. Phục vụ cà tím với", "phulkas, rotis hoặc chapatis. Món cũng ngon kèm bánh mì, bánh mì nướng hoặc nướng và cơm trắng hoặc cơm jeera."]'::jsonb, 4);
