INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7509ad09-c358-5e34-93d3-6544c72542fe', 'Cừu kho Rogan josh (Lamb Rogan josh)', 'man'::public.dish_category, '["Cho hành tây vào máy xay, xay nhuyễn rất mịn. Đun nóng dầu trong chảo nặng lớn, chiên hành với nắp đậy, khuấy thỉnh thoảng cho đến khi thật vàng và mềm. Thêm tỏi và gừng, chiên thêm 5 phút.", "Đổ sốt cà ri, tất cả gia vị và lá nguyệt quế vào chảo cùng cà chua xay nhuyễn. Khuấy kỹ trên lửa khoảng 30 giây, rồi thêm thịt cừu và 300 ml nước. Khuấy trộn, hạ lửa, rồi thêm sữa chua Hy Lạp.", "Đậy nắp chảo, hôi nhẹ 40-60 phút cho đến khi thịt mềm và sốt đặc đậm. Đặt ra đĩa, rắc lá ngò rí, ăn kèm gạo Basmati hoặc cơm nạo thường."]'::jsonb, 4);
