INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d16d72c8-05d9-546f-b03d-d6426becbba1', 'Cá Recheado Masala Ấn Độ', 'man'::public.dish_category, '["Ngâm tất cả gia vị, gừng, tỏi, vỏ me và ớt Kashmir trừ dầu trong giấm.", "Thêm đường và muối.", "Cũng thêm bột nghệ.", "Trộn tất cả tốt và ướp 35-40 phút.", "Xay hỗn hợp cho đến khi mềm và mịn. Thêm thêm giấm nếu cần nhưng đảm bảo hồ phải đặc nên thêm giấm tương ứng. Nếu hồ masala nhạt thì nó sẽ không dính vào cá.", "Rửa cá cắt từ giữa và chọc vài vết từ trên. Bạn có thể xem cá dưới đây để rõ.", "Bây giờ nhét hồ vào giữa và vào vết cắt. phủ toàn bộ cá với hồ này. ướp cá 30 phút.", "Cho dầu vào chảo nông, khi dầu nóng khá, chiên nhẹ các cá thu đã nhét.", "Chiên cho đến khi vàng nâu từ cả hai mặt", "Dùng các cá thu Recheado nóng với salad, lát chanh xanh, cơm và cà ri.", "Lưu ý:", "1. Đảm bảo hồ masala đặc nếu không kết quả sẽ không tốt.", "2. Nếu bạn không tìm thấy ớt Kashmir thì dùng ớt Bedgi hoặc bột ớt đỏ Kashmir.", "3. Bạn có thể dùng giấm trắng hoặc giấm dừa.", "4. Bất kỳ hồ thừa nào có thể được lưu trong tủ lạnh để dùng sau.", "5. Thanh quế có thể bị bỏ qua vì đó là gia vị mạnh thường dùng cho thịt hoặc gà."]'::jsonb, 4);
