INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4c3a881c-10d8-5b78-ba56-1f2b6c5bdc4f', 'Gà chiên Kentucky (Kentucky Fried Chicken)', 'man'::public.dish_category, '["Đun chiên nồi đến 175°C. Trộn kỹ tất cả nguyên liệu hỗn hợp gia vị.", "Kết hợp hỗn hợp gia vị với bột mì, đường nâu và muối.", "Trám các miếng gà vào lòng trắng trứng để phủ nhẹ, rồi chuyển vào hỗn hợp bột mì. Lật vài lần và đảm bảo hỗn hợp bột thực sự dính vào gà. Làm lại với tất cả các miếng gà.", "Để các miếng gà nghỉ trong 5 phút để lớp vỏ có thời gian khô một chút.", "Chiên gà theo lượt. Ức gà và cánh sẽ mất 12-14 phút, và chân và đùi sẽ cần thêm vài phút. Các miếng gà chín khi một nhiệt kế thịt được đâm vào phần dày nhất cho thấy 74°C.", "Để gà ráo trên một số giấy bếp khi nó lấy ra khỏi chiên nồi. Ăn nóng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4c3a881c-10d8-5b78-ba56-1f2b6c5bdc4f', '44a6a37a-69a3-5573-9fd1-730baf90fb5b', 1.0, 'piece'::public.quantity_unit);
