INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8da52ef9-79f8-5160-afd8-23c8bdcbd285', 'Nui macaroni gà fajita và phô mai (Chicken Fajita Mac and Cheese)', 'man'::public.dish_category, '["Chiên hành tây, ớt chuông đỏ và tỏi trong dầu ô liu cho đến khi nhờn sáng. Làm một hốc trong rau và thêm gà. Thêm gia vị ướp Fajita và muối. Cho đến khi hơi vàng.", "Thêm kem béo, nước dùng gà và nui Macaroni.", "Nấu trên lửa thấp trong 20 phút. Thêm các loại phô mai, khuấy để trộn.", "Trangs trí bằng ớt chuông đỏ đã nướng và ngò tây."]'::jsonb, 4);
