INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2a408656-b923-50da-b305-e65eb781a8aa', 'Taco cá gia vị Cajun Mexico', 'man'::public.dish_category, '["Nấu cá trong marinade gia vị Cajun và ớt bột cayenne làm cho cá này rất nhiều nước và có hương vị. Đặt một lớp dressing tươi lên trên và phục vụ trong tortilla cho một món chính nhanh, không phiền phức, rất thích hợp cho mùa hè.", "Trên đĩa lớn, trộn gia vị Cajun và ớt bột cayenne với một ít gia vị và dùng để bọc cá toàn bộ.", "Đun một ít dầu trong chảo chiên, thêm cá và nấu trên lửa trung bình cho đến khi vàng. Giảm bớt lửa và tiếp tục chiên cho đến khi cá chín qua, khoảng 10 phút. Nấu theo từng đợt nếu bạn không có đủ chỗ trong chảo.", "Cùng lúc đó, chuẩn bị dressing bằng cách trộn tất cả các nguyên liệu với một ít gia vị.", "Làm mềm tortilla bằng cách hâm trong lò vi sóng trong 5-10 giây. Xếp cao bơ quả, xà lách búp và hành lá, thêm một thìa sốt cà chua, đặt miếng cá lớn lên trên và rưới dressing lên trên."]'::jsonb, 4);
