INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('75ceb3a4-d26a-5152-a680-01d242ae5a77', 'Cà ri gà Katsu Nhật (Katsu Chicken curry)', 'man'::public.dish_category, '["1. Chuẩn bị: 15 phút › Nấu: 30 phút › Sẵn sàng trong: 45 phút", "2. Để làm sốt cà ri: Đun dầu trong nồi không dính trung bình, thêm hành tây và tỏi và nấu cho đến khi mềm. Khuấy cà rốt vào và nấu trên lửa thấp trong 10 đến 12 phút.", "3. Thêm bột mì và bột cà ri; nấu trong 1 phút. Dần dần khuấy nước dùng vào cho đến khi kết hợp; thêm mật ong, nước tương và lá nguyệt quế. Dần đun sôi.", "4. Giảm lửa và sôi nhẹ trong 20 phút hoặc cho đến khi sốt đặc nhưng vẫn đủ loãng để rót. Khuấy bột gia vị Garam Masala vào. Rút sốt cà ri qua một rổ lọc; trả về nồi và giữ trên lửa thấp cho đến khi sẵn sàng ăn.", "5. Để làm gà: Nêm muối và tiêu vào cả hai bên của ức gà. Đặt bột mì, trứng và bột chiên xù vào các bát riêng và sắp xếp thành một hàng. Bọc ức gà trong bột mì, rồi trám chúng vào trứng, rồi bọc trong bột chiên xù, đảm bảo bạn phủ cả hai bên.", "6. Đun dầu trong chảo chiên lớn trên lửa cao vừa. Đặt gà vào dầu nóng và nấu cho đến khi vàng nâu, khoảng 3 hoặc 4 phút mỗi bên. Khi đã chín, đặt lên giấy bếp để hấp thụ dầu thừa.", "7. Rưới sốt cà ri lên gà, ăn với cơm trắng và thưởng thức!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('75ceb3a4-d26a-5152-a680-01d242ae5a77', 'ad351e7b-f3ad-58e4-ac0a-01692efe9c9e', 4.0, 'piece'::public.quantity_unit);
