INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c702111c-7d04-5b45-bf0d-b0b16c31cdcc', 'Mì tôm lớn Laksa Malaysia (Laksa King Prawn Noodles)', 'man'::public.dish_category, '["Đun dầu trong nồi vừa và thêm ớt. Nấu trong 1 phút, sau đó thêm sốt cà ri, khuấy và nấu thêm 1 phút. Tan viên nước dùng trong một bình lớn trong 700 ml nước sôi, rồi rót vào chảo và khuấy để kết hợp. Đổ nước cốt dừa vào và đun sôi.", "Thêm nước mắm và một chút gia vị. Cho mì vào và nấu thêm 3-4 phút cho đến khi mềm. Vắt nước cốt chanh vào, thêm tôm và nấu cho đến khi nóng, khoảng 2-3 phút. Rắc một ít ngô rí lên trên.", "Ăn trong bát với phần ngô rí còn lại và lát chanh xanh trên đầu để vắt lên."]'::jsonb, 4);
