INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2a1ef73f-9cf2-593d-9ff7-6565ad7735a4', 'Xúc xích nướng trong bột (Toad In The Hole)', 'man'::public.dish_category, '["Đun lò 200°C. Chiên xúc xích trong chảo không dính cho đến khi vàng.", "Chọc dầu thực vật vào khay n sâu 30 x 25 x 6 cm và đun trong lò 5 phút.", "Cho bột mì đa dụng vào tô, đập trứng gà vào, rồi khuấy mù tạt củ cải ngựa xay vào. Dan dần đánh sữa tươi vào. Nêm nếm.", "Cho xúc xích vào khay nướng nóng và đổ bột lên. Đặt cà chua bi trên cành lên trên và nấu 30 phút cho đến khi phồng và vàng."]'::jsonb, 4);
