INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ff5c16a8-1dac-5431-bd9c-67e9e75b8a68', 'Risotto cá hồi và tôm (Salmon Prawn Risotto)', 'man'::public.dish_category, '["Cho bơ vào nồi đáy dày và nấu nhẹ hành tây cho đến khi không đổi màu và mềm.", "Thêm gạo và khuấy cho đến khi tất cả các hạt được phủ bơ.", "Thêm rượu vang và nấu nhẹ, khuấy cho đến khi hấp thụ hết.", "Dần dần thêm nước dùng nóng, khuấy cho đến khi mỗi lần thêm được hấp thụ. Tiếp tục khuấy cho đến khi gạo mềm.", "Nems với nước chanh và vỏ chanh, và tiêu theo khẩu vị. (Có thể có đủ độ mặn từ cá hồi không cần thêm muối) Khuấy nhẹ cho nóng lên.", "Phục vụ rắc phô mai Parmesan và rau mùa bên trên.", "Nướng cá hồi và nhẹ nhàng đặt lên risotto cùng tôm và măng tây."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('ff5c16a8-1dac-5431-bd9c-67e9e75b8a68', '5b335556-d749-5751-acbe-0db2ff3196c9', 50.0, 'g'::public.quantity_unit);
