INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('115c1314-b4a8-5ddb-b390-fec7ea0a3d40', 'Bò hầm sốt ớt Mexico', 'man'::public.dish_category, '["Đun lò đến 120°C.", "Lấy thịt ra khỏi tủ lạnh để giải tỏa lạnh. Xoay nhẹ hành và tỏi trong máy xay thực phẩm cho đến khi cắt nhuyễn. Đun 2 muỗng canh dầu ô liu trong nồi hầm lớn và rang thịt mọi bên cho đến khi vàng.", "Đặt một bên và thêm một chút dầu khác để rang xúc xích chorizo. Lấy ra và thêm hành và tỏi, gia vị, thảo mộc và ớt rồi nấu cho đến khi mềm trong mỡ xúc xích chorizo. Nems muối và tiêu và thêm giấm, cà chua, sốt cà chua đặc và đường.", "Trả tất cả thịt vào nồi với 400 ml nước (hoặc rượu vang đỏ nếu bạn thích), đun đến sôi nhẹ và nấu, đậy nắp, trong lò thấp.", "Sau 2 giờ, kiểm tra thịt và thêm đậu. Nấu thêm 1 giờ và ngay trước khi phục vụ, kéo thịt bằng cặp nĩa."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('115c1314-b4a8-5ddb-b390-fec7ea0a3d40', 'fda67982-c921-54e6-9568-e2184abae4d6', 1000.0, 'g'::public.quantity_unit);
