INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('67ded336-0983-513a-9ea8-aae0f73e4121', 'Bò cà ri Massaman', 'man'::public.dish_category, '["Đầy lò 200°C, rang đậu phộng trên khay nướng 5 phút cho vàng. Khi nguội nắm tay được, băm thô. Giảm lò xuống 180°C.", "Đun nóng 2 muỗng canh kem dừa trong nồi nướng có nắp. Thêm sốt cà ri Massaman, chiên 1 phút, rồi khuấy thịt bò vào và chiên cho đều clo. Thêm phần dừa còn lại cùng nửa lon nước, khoai tây, hành tây, lá chanh Thái, thanh quế, cốt me, đường, nước mắm và phần lớn đậu phộng. Đun hôi, đậy nắp và nấu 2 giờ trong lò cho đến khi thịt bò mềm.", "Rắc ớt lát và đậu phộng còn lại, rồi dùng ngay từ nồi cùng gạo thơm Jasmine."]'::jsonb, 4);
