INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('dbbe4fdc-2e8b-5408-86c7-428136c2ca8d', 'Tacos gà nấu nồi Crock (Crock Pot Chicken Baked Tacos)', 'man'::public.dish_category, '["Đặt các ngực gà chưa nấu vào nồi Crock nồi. Đổ toàn bộ chai sốt salad lên gà. Rắc phần còn lại của các nguyên liệu lên trên và trộn chúng một chút bằng thìa.", "Đậy nắp nồi Crock nồi và nấu trên mức cao trong 4 giờ.", "Lấy tất cả các ngực gà khỏi nồi Crock nồi và để nguội.", "Xé các ngực gà và chuyển vào bát kính.", "Đổ phần lớn nước lên trên gà đã xé.", "ĐỐI VỚI CÁC TACOS:", "Làm sốt guacamole bằng cách trộn bơ quả và salsa xanh cùng nhau. Đổ hỗn hợp guacamole qua một cái lọc cho đến khi mịn và chuyển vào chiếc bình xốp. Cắt đầu của nắp bình xốp để làm lỗ mở rộng hơn nếu cần.", "Làm sốt kem chua bằng cách trộn kem chua và sữa tươi cùng nhau cho đến khi bạn có một loại sốt kem chua lỏng hơn. Chuyển vào chiếc bình xốp.", "Trong một cái đĩa nướng kính 9x 13, điền tất cả 12+ tacos với một lớp đậu nghiền, gà đã nấu và phô mai đã xé.", "Nướng ở 230°C trong 10-15 phút cho đến khi phô mai đã nở và nổi bọt.", "R khỏi lò phủ tất cả các tacos với cà chua bi quả nho đã lát, ớt Jalapeño và ngô tây.", "Hoàn thành bằng cách rắc chút sốt guacamole và kem chua."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('dbbe4fdc-2e8b-5408-86c7-428136c2ca8d', '7c9a15f2-fae9-5394-bcbb-9bbae8011db7', 6.0, 'piece'::public.quantity_unit);
