INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0a5e690b-983f-5f44-9627-5f8821213a97', 'Gà chiên kiểu Nhật Karaage (Chicken Karaage)', 'man'::public.dish_category, '["Thêm gừng, tỏi, nước tương, rượu Sake và đường vào bát và đánh trộn. Thêm gà, rồi khuấy để đều. Đậy nắp và để trong tủ lạnh ít nhất 1 giờ.", "Thêm khoảng 2,5 cm dầu thực vật vào nồi đáy dày và đun cho đến khi dầu đạt 180°C. Lót giá sắt bằng 2 tờ khăn giấy và chuẩn bị kìm. Đặt tinh bột khoai tây vào bát", "Thêm một nắm gà vào tinh bột khoai tây và lắc để phủ đều từng miếng.", "Chiên karaage theo đợt cho đến khi bên ngoài màu vàng trung bình và gà chín qua. Chuyển gà đã chiên lên giá sắt đã lót khăn giấy. Nếu muốn karaage giòn lâu hơn, bạn có thể chiên gà lần thứ hai, cho đến khi màu tối hơn sau khi nguội một lần. Ăn với miếng chanh vàng."]'::jsonb, 4);
