INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('cf50339d-facc-5fef-8ec4-973ccc012b53', 'Bò stroganoff', 'man'::public.dish_category, '["Đun dầu ô liu trong chảo không dính rồi thêm hành đã cắt lát và nấu trên lửa trung bình cho đến khi hoàn toàn mềm, khoảng 15 phút, thêm ít nước nếu chúng bắt đầu dính. Ép tỏi vào và nấu thêm 2-3 phút, rồi thêm bơ. Khi bơ bắt đầu bọt nhẹ, thêm nấm và nấu khoảng 5 phút cho đến khi hoàn toàn mềm. Nems mọi thứ rất tốt rồi đổ lên đĩa.", "Đổ bột mì vào bát với một nắm lớn muối và tiêu, rồi lăn các miếng thăn trong bột đã nems. Thêm các miếng thăn vào chảo, thêm ít dầu nếu chảo trông đặc biệt khô, và chiên 3-4 phút, cho đến khi vàng đẹp. Đổ hành và nấm trở lại vào chảo. Khuân crème fraîche, mù tạt và nước dùng bò cùng nhau, rồi đổ vào chảo. Nấu trên lửa trung bình khoảng 5 phút. Rắc ngô tây lên trên rồi phục vụ với mì pappardelle hoặc cơm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('cf50339d-facc-5fef-8ec4-973ccc012b53', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 1.0, 'piece'::public.quantity_unit);
