INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2d84aa74-edb3-5fab-a110-c933612dcea0', 'Mì fideuà hải sản (Seafood fideuà)', 'man'::public.dish_category, '["Sôi bình nước. Đổ hàu vào lá rổ và vò dưới nước lạnh. Vứt bất kỳ cái nào có vỡ vỏ. Xem xét từng vỏ, gõ từng cái vào bên bồn rửa – chúng nên đóng hoặc chậm đóng khi bị gõ – nếu chúng vẫn mở, vứt chúng đi. Nếu bất kỳ vỏ nào còn có cuchòn hoặc râu dây dính, kéo chúng ra bằng dao ăn và vò sạch vỏ. Giữ trong lá rổ, phủ bằng khăn lạnh ẩm, cho đến khi bạn sẵn sàng nấu. Bóc vỏ tôm chỉ phần thân – để đầu và đuôi nguyên vẹn. Chọc xuống lưng và kéo bất kỳ nội tộ cát ra. Để trong tủ lạnh cho đến khi bạn sẵn sàng nấu.", "Đặt nhụy hoa nghệ tây vào tô nhỏ, ngập 50 ml nước nóng từ bình và để trong 10 phút. Nếu dùng mì sợi nhỏ, cho vào tô và nát thành các mảnh nhỏ (khoảng 1 cm) bằng tay.", "Đun nóng dầu trong chảo chiên lớn có mép ít nhất 3cm, hoặc chảo paella 40cm. Thêm hành tây và khuấy quanh chảo trong 5 phút cho đến khi mềm. Thêm tỏi và nấu thêm 1 phút, rồi đổ mì sợi nhỏ vào và nấu trong 5 phút, khuấy đôi khi cho đến khi mì sợi nhỏ vàng nâu. Khuấy vào bột ớt ngọt Paprika.", "Giữ lửa vừa, khuấy qua cá, mực và nhụy hoa nghệ tây cùng nước của nó, nems nếm thật. Đặt thành lớp đều, rồi đổ nước dùng nóng lên và rải cà chua lên trên. Đun sôi nhỏ lửa, rồi nắp lên toàn bộ món bằng nắp khít (hoặc giấy nhôm). Xoay lửa lên vừa và nấu trong 6 phút.", "Mở nắp và khuấy để hòa lớp pasta khô phía trên. Đặt hàu vào pasta sao cho chúng đứng thẳng. Xếp tôm lên trên, nắp chặt và nấu thêm 6 phút hoặc cho đến khi hàu mở, tôm hồng và pasta chín đều. Để ninh thêm 2-3 phút để tách phần lớn nước còn lại (để lại ít nước trong chảo để ngăn pasta dính nhau). Để ngâm 2-3 phút, rồi vắt nước chanh lên và xếp lát chanh lên trên. Rắc ngô tây trước khi phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2d84aa74-edb3-5fab-a110-c933612dcea0', '1c83908a-3526-5ba7-8893-cc12b3af8e79', 400.0, 'g'::public.quantity_unit);
