INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a5d49f69-df14-56a5-a8ef-23b5ba1e3036', 'Súp bông cải xanh phô mai xanh Stilton', 'canh'::public.dish_category, '["Đun dầu hạt cải trong nồi lớn và rồi thêm hành. Nấu trên lửa trung bình cho đến khi mềm. Thêm một chút nước nếu hành bắt đầu dính.", "Thêm cần tây, hành lá, khoai tây và một đống bơ. Khuân cho đến khi nung chảy, rồi đậy nắp. Để hầm nhẹ trong 5 phút. Mở nắp.", "Đổ nước dùng vào và thêm bất kỳ mảnh dục của cuống bông cải xanh. Nấu 10 – 15 phút cho đến khi tất cả các rau mềm.", "Thêm phần còn lại của bông cải xanh và nấu thêm 5 phút. Cẩn thận chuyển vào máy xay và khuôn cho đến khi mịn. Khuân stilton vào, cho phép một vài cục còn lại. Nems tiêu đen và phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a5d49f69-df14-56a5-a8ef-23b5ba1e3036', 'cdadb656-1960-506f-b7e6-70b7cd2bb6bc', 30.0, 'ml'::public.quantity_unit);
