INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3b16f8a3-55b0-5a43-b1d7-a60f4bb7d994', 'Cừu Tagine Maroc (Lamb Tagine)', 'man'::public.dish_category, '["Đun nóng dầu ô liu trong chảo nặng, cho hành tây và cà rốt. Nấu 3-4 phút cho mềm.", "Thêm thịt cừu cắt khối, chiên vàng đều. Khuấy tỏi và tất cả gia vị, nấu thêm vài phút cho đến khi mùi hương được thả ra.", "Thêm mật ong và mơ khô, thứ viên súp vào, rót khoảng 500 ml nước sôi hoặc đủ ngập thịt. Khuấy kỹ và đun sôi. Hạ lửa hôi, đậy nắp, nấu một giờ.", "Mở nắp, nấu thêm 30 phút, rồi khuấy thêm bí đỏ hồ lô. Nấu thêm 20-30 phút cho đến khi bí mềm và thịt cừu nhũn. Ăn kèm gạo hoặc couscous, rắc ngò tây và hạt sung, nếu dùng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3b16f8a3-55b0-5a43-b1d7-a60f4bb7d994', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 30.0, 'ml'::public.quantity_unit);
