INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9ef223ce-85fb-5337-8cd3-17b977456600', 'Nồi gà nấm (Chicken & mushroom Hotpot)', 'man'::public.dish_category, '["Đun lò đến 200°C. Cho bơ vào nồi trung bình, đặt trên lửa vừa. Cho hành tây vào và nấu trong 5 phút, gọi đôi khi. Thêm nấm vào nồi cùng với hành tây.", "Khi hành tây và nấm gần chín, thêm bột mì đa dụng – phần này sẽ tạo thành hỗn hợp đặc gọi là roux. Nếu dùng viên súp gà, nghiền viên súp vào roux và trộn đều. Đặt roux trên lửa nhỏ và trộn liên tục trong 2 phút – điều này sẽ nấu chín bột mì và ngăn sốt có vị bột.", "Nâng roux khỏi lửa. Chậm chạp thêm nước dùng tươi, nếu dùng, hoặc đổ vào 500ml nước nếu đã dùng viên súp gà, luôn trộn đều. Khi tất cả nước đã thêm, nêm tiêu, một chút nhục đậu khấu và bột mù tạt. Đặt nồi lại trên lửa vừa và đun sôi chậm, luôn trộn. Khi sốt đã đặc, đặt trên lửa rất thấp. Thêm gà chín và rau vào sốt và trộn đều. Nhớt nhẹ một cái đĩa nướng trung bình bằng chút bơ và rót phần nhân gà nấm vào.", "Trải khoai tây lên trên phần nhân nồi nóng, chồng lên nhau nhẹ, gần như mặt bánh.", "Chà khoai tây bằng chút bơ đã đun hóa và nấu trong lò trong khoảng 35 phút. Nồi nương sẵn khi khoai tây đã chín và vàng nụi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9ef223ce-85fb-5337-8cd3-17b977456600', '5b335556-d749-5751-acbe-0db2ff3196c9', 50.0, 'g'::public.quantity_unit);
