INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c3d4b847-fd46-522e-95fa-61a2c78285c9', 'Cassoulet heo Pháp (Pork Cassoulet)', 'man'::public.dish_category, '["Đậy lò 140°C. Đặt nồi chịu nhiệt lớn (có nắp khít) trên lửa lớn. Thêm mỡ và thịt cắt khối, nấu vài phút để khép cạnh, khuấy nhanh để nấu đều. Giảm nhiệt xuống thấp, thêm hành lát, tép tỏi nguyên bản, cà rốt và hạt hồi, và nấu nhẹ để làm mềm rau vài phút.", "Rót giấm rượu vang đỏ qua, khử nồi các múi thịt dính đáy chảo. Thêm nước dùng, cà chua xay nhuyễn, và nửa số hồi thảo và ngô tây. Đun sôi và hôi 10 phút, rồi nems, đậy nắp và cho vào lò 2 giờ, mở nắp cho giờ cuối của việc nấu. Khuấy thỉnh thoảng và thêm đậu với 30 phút còn lại.", "Vớt chảo ra khỏi lò và đun grill. Rắc bề mặt với gia vị và bột chiên xù còn lại, rưới ít dầu lên trên, và trả lại lò 5-10 phút, cho đến khi bột chiên xù vàng. Dùng với bánh mì vỏ giòn và rau xanh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c3d4b847-fd46-522e-95fa-61a2c78285c9', 'da5f79bb-1b95-5515-9641-150a591b5102', 60.0, 'ml'::public.quantity_unit);
