INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('85ab7a05-0585-51ed-b87b-4ca3ef58f426', 'Cannelloni cải bó xôi và phô mai ricotta (Spinach & Ricotta Cannelloni)', 'rau'::public.dish_category, '["Đầu tiên làm sốt cà chua. Đun nóng dầu trong chảo lớn và chiên tỏi trong 1 phút. Thêm đường, giấm, cà chua và một ít nems và ninh trong 20 phút, khuấy đôi khi, cho đến khi đặc. Thêm húng quế tây và chia sốt vào 2 hoặc nhiều cái đĩa chống nồi (xem Mẹo cho đóng băng, bên dưới). Để riêng. Làm sốt bằng cách đánh phô mai mascarpone với sữa cho đến khi mịn, nems, rồi để riêng.", "Đặt cải bó xôi vào lá rổ lớn và rót ấm nước sôi từ bình vào để mà nó (bạn có thể cần làm theo từng đợt). Khi đủ mát để bắt tay, vớt lấy nước thừa. Cắt thô cải bó xôi và trộn trong bát lớn với 100g phô mai Parmesan và ricotta. Nems thật với muối, tiêu và hạt 육두구."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('85ab7a05-0585-51ed-b87b-4ca3ef58f426', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 45.0, 'ml'::public.quantity_unit);
