INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d26fbee7-dbef-52a0-83f3-b64224a8e2e6', 'Gà nấu với couscous (Chicken Couscous)', 'man'::public.dish_category, '["Đun nóng dầu ô liu trong chảo lớn và chiên hành tây trong 1-2 phút cho đến khi vừa mềm. Thêm gà và chiên trong 7-10 phút cho đến khi chín và hành tây đã vàng. Xén gừng lên trên, trộn gia vị ớt Harissa để phủ tất cả và nấu thêm 1 phút.", "Đổ quả mơ sấy khô, đậu gà Chickpeas và couscous vào, sau đó rót nước dùng gà lên và khuấy một lần. Đậy nắp hoặc đậy chảo bằng giấy bạc và để trong khoảng 5 phút cho đến khi couscous đã hấp thụ hết nước dùng và mềm. Làm couscous trở nên松 nĩa và rắc ngò rí để ăn. Ăn kèm thêm gia vị ớt Harissa, nếu muốn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d26fbee7-dbef-52a0-83f3-b64224a8e2e6', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 15.0, 'ml'::public.quantity_unit);
