INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('459767f5-fa61-529f-903c-8c32bd6c6060', 'Cà ri gà bơ đậu phộng', 'man'::public.dish_category, '["Cắt mỏng một phần tư ớt đỏ, rồi cho phần còn lại vào máy xay cùng gừng, tỏi, cuống ngô rí và một phần ba lá. Xay thành hồ thô với chút nước nếu cần.", "Đun dầu trong chảo, rồi chiên nhanh khối thịt gà vàng 1 phút. Khuấy hồ thêm 1 phút, rồi thêm bơ đậu phộng, nước dùng và sữa chua Hy Lạp. Khi sốt nhẹ hôi, nấu 10 phút cho đến khi thịt gà vừa chín và sốt đặc. Khuấy phần lớn ngô rí còn lại, rồi rắc phần còn lại lên trên cùng với ớt, nếu dùng. Ăn kèm cơm hoặc khoai lang nghiền."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('459767f5-fa61-529f-903c-8c32bd6c6060', '0dc398a0-befb-5b35-aaf4-977a2e66a143', 1.0, 'piece'::public.quantity_unit);
