INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2d66c1fc-3b75-593d-8016-5d0749e92492', 'Salad cá ngừ Nicoise', 'man'::public.dish_category, '["Đun lò 200°C. Trộn khoai tây với 2 muỗng cà phê dầu và ít nêm nếm. Đổ vào khay nướng lớn, rồi nướng 20 phút, khuấy giữa lúc, cho đến khi giòn, vàng và chín hết.", "Cùng lúc, cho trứng vào nồi nhỏ nước, đun sôi, rồi hầm sôi nhẹ 8-10 phút, tùy theo mức chín bạn thích. Cho vào tô nước lạnh để nguội vài phút. Bóc vỏ, rồi cắt thành nửa.", "Trong tô salad lớn, đánh trộn dầu còn lại, giấm rượu vang đỏ, nụ bạch hoa và cà chua cắt nhỏ. Nêm nếm, cho hành tím tây, cải bó xôi, cá ngừ và khoai tây vào, rồi nhẹ nhàng trộn cùng. Đặt trứng lên trên, rồi dùng ngay lập tức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2d66c1fc-3b75-593d-8016-5d0749e92492', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 450.0, 'g'::public.quantity_unit);
