INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9cecc0ae-3628-5919-ad20-aed3eae2afe0', 'Nồi hầm chay (Vegetarian Casserole)', 'rau'::public.dish_category, '["Đun nóng dầu trong chảo lớn đáy dày. Thêm hành tây và nấu nhẹ 5 – 10 phút cho đến khi mềm.", "Thêm tỏi, gia vị, xạ hương khô, cà rốt, cần tây và ớt chuông và nấu 5 phút.", "Thêm cà chua, nước dùng, bí ngòi xanh và xạ hương tươi và nấu 20 - 25 phút.", "Lấy nhánh xạ hương ra. Khuấy đậu lăng vào và đun sôi nhẹ trở lại. Dùng với gạo basmati lẻ và trắng, nghiền hoặc quinoa."]'::jsonb, 4);
