INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ecc0e35d-daa6-5934-b11e-ff6612a5b195', 'Rotolo nấm hạt dẻ Anh (Mushroom & Chestnut Rotolo)', 'rau'::public.dish_category, '["Ngâm nấm khô trong 350 ml nước sôi và để riêng cho đến khi cần. Xay 3/4 hạt dẻ với 150 ml nước cho đến khi mịn như kem. Băm thô phần hạt dẻ còn lại.", "Đun 2 muỗng canh dầu ô liu trong chảo không dính lớn. Chiên hành tím với chút muối cho đến khi mềm, rồi thêm tỏi, hạt dẻ băm và hồi thảo, chiên thêm 2 phút. Thêm nấm rừng tự nhiên, 2 muỗng canh dầu và chút nems nếm. Nấu 3 phút cho đến khi bắt đầu mềm. Ráo và băm thô nấm khô (giữ nước ngâm), rồi thêm chúng vào cùng với xì dầu, và chiên thêm 2 phút.", "Trộn rượu vang trắng, nước ngâm nấm đã giữ lại và kem hạt dẻ để tạo sốt. Nems, rồi thêm nửa vào hỗn hợp nấm trong chảo và nấu 1 phút cho đến khi sốt bóng. Vớt bỏ nhánh hồi thảo, rồi để hỗn hợp riêng.", "Đậy lò 180°C. Đun nồi lớn nước có muối và chuẩn bị bát lớn nước đá. Cho lá mì Lasagne vào nước sôi 2 phút cho đến khi uốn được và chín một chút, rồi ngay lập tức nhúng vào nước lạnh. Dùng tay tách cẩn thận các lá và chuyển lên khăn bếp sạch. Rải một muỗng sốt ở dưới hai phần ba mỗi lá, rồi cuộn từ đầu ngắn. Cắt mỗi cuộn thành nửa, đặt các cuộn mặt cắt lên trong ô nướng. Nếu còn sốt nấm sau khi cuộn hết, hãy nhấn vào một cuộn 드러 lộn.", "Rót phần sốt còn lại lên trên pasta, rồi nướng 10 phút cho đến khi pasta không còn cản khi kiểm tra bằng xiên.", "Trong lúc đó, cho bột chiên xù, 2 muỗng canh dầu ô liu cuối, lá xo thơm và chút nems nếm vào bát, trộn hết với nhau. Rắc bột và lá xo thơm lên rotolo, rồi nướng thêm 10 phút cho đến khi bề mặt vàng và lá xo thơm giòn. Để nguội 10 phút cho pasta thấm sốt, rồi rưới chút dầu nấm Truffle nếu thích, trước khi mang món lên bàn."]'::jsonb, 4);
