INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b9956f08-b3bb-5dcd-a77a-d98ed3594bd2', 'Đậu Hà Lan Paneer Ấn Độ (Matar Paneer)', 'rau'::public.dish_category, '["Đun nóng dầu trong chảo trên lửa lớn cho đến khi nóng hổi. Cho phô mai tươi Ấn Độ Paneer vào, rồi hạ lửa một chút. Chiên cho đến khi bắt đầu vàng ở các cạnh, rồi lật ra và chiên vàng cả hai mặt – phô mai sẽ vàng nhanh hơn bạn nghĩ, đừng rời đi. Vớt phô mai ra khỏi chảo và ráo trên khăn bếp giấy.", "Cho gừng, thì là, nghệ, ngô rí băm và ớt vào chảo, xào hết trong 1 phút. Thêm cà chua, nghiền bằng muỗng và hôi hết trong 5 phút cho đến khi sốt thơm. Thêm chút nước nếu quá đặc. Nems kỹ. Thêm đậu Hà Lan và hôi thêm 2 phút, rồi khuấy phô mai vào và rắc bột gia vị Garam Masala. Chia ra hai bát, rắc lá ngô rí trên đầu và dùng kèm bánh nan, roti hoặc cơm."]'::jsonb, 4);
