INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3be9e29f-4e60-511b-abd7-262f900bd40e', 'Mì linguine và bí ngô (Squash linguine)', 'rau'::public.dish_category, '["Đun lò lên 200°C. Đặt bí ngô và tỏi vào khay nướng và rưới dầu ô liu. Nướng trong 35-40 phút cho đến khi mềm. Nems.", "Nấu mì ý theo hướng dẫn trên bao bì. Rarget nước, nhưng giữ nước luộc. Dùng máy xay cầm tay để xay bí ngô với 400ml nước luộc. Đun chút dầu trong chảo xào, chiên húng lùi cho đến khi giòn, rồi rarget trên giấy tầu. Đổ mì và sốt vào chảo và nóng qua. Rắc húng lùi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3be9e29f-4e60-511b-abd7-262f900bd40e', 'e8754853-9cff-5b2b-932b-da77f532117c', 350.0, 'g'::public.quantity_unit);
