INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e340278e-347d-54c2-9386-33d03aaead45', 'Chili chay', 'rau'::public.dish_category, '["Đun lò 200°C. Nấu rau củ trong nồi hầm 15 phút. Cho đậu đỏ và cà chua vào, nêm nếm và nấu thêm 10-15 phút cho đến khi nóng bỏng. Đun túi trong lò vi sóng trên cao 1 phút và dùng với chili."]'::jsonb, 4);
