INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fa2f808f-d9ee-527e-ba60-af11934d7f42', 'Cà ri đậu đỏ Ấn Độ (Kidney Bean Curry)', 'rau'::public.dish_category, '["Đun dầu trong chảo chiên lớn trên lửa thấp vừa. Thêm hành tây và một chút muối và nấu chậm, khuấy thỉnh thoảng, cho đến khi mềm và chỉ bắt đầu đổi màu. Thêm tỏi, gừng và cuống ngô rí và nấu thêm 2 phút, cho đến khi thơm.", "Thêm gia vị vào chảo và nấu thêm 1 phút, đến lúc này mọi thứ nên có mùi thơm. Đổ cà chua đã băm và đậu đỏ Kidney trong nước của chúng vào, rồi đun sôi.", "Giảm lửa và hầm nhẹ trong 15 phút cho đến khi cà ri tốt và đặc. Nêm theo khẩu vị, rồi ăn với gạo Basmati và lá ngô rí."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('fa2f808f-d9ee-527e-ba60-af11934d7f42', '41e2849c-302d-5cf6-9f07-ca579b4604a3', 1.0, 'piece'::public.quantity_unit);
