INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7cbd7435-9f5f-5b1e-b4b3-6b718497e792', 'Đậu lăng sốt mè tahini (Tahini Lentils)', 'rau'::public.dish_category, '["Trong một bát lớn, trộn sốt mè tahini với vỏ và nước cốt chanh cùng 50 ml nước lạnh thành sốt loãng. Nêm nếp theo khẩu vị, rồi để một bên.", "Đun nóng dầu trong wok hoặc chảo lớn trên lửa vừa đến cao. Thêm hành tím, cùng một chút muối, chiên khoảng 2 phút cho đến khi bắt đầu mềm và đổi màu. Thêm tỏi, ớt chuông vàng, đậu que và bí ngòi xanh, chiên thêm 5 phút, khuấy liên tục.", "Cho cải xoăn kale, đậu lăng và sốt mè tahini vào nồi. Giữ nồi trên lửa vài phút, khuấy trộn đều cho đến khi cải xoăn úa và tất cả đều được phủ bởi sốt kem."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7cbd7435-9f5f-5b1e-b4b3-6b718497e792', '703ab500-1c2a-5468-bc9e-aec0acf9ee21', 50.0, 'g'::public.quantity_unit);
