INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5e5b790f-b5a1-5bf2-91b1-b91960e537b0', 'Fajitas đậu gà (Chickpea Fajitas)', 'rau'::public.dish_category, '["Đun lò đến 200°C/180°C/mức 6 và lót khay nướng bằng giấy bạc. Ráo đậu gà Chickpeas, thấm khô và đổ lên khay nướng đã chuẩn bị. Thêm dầu và bột ớt ngọt Paprika, lắc để phủ, sau đó nướng trong 20-25 phút cho đến khi vàng và giòn, lắc giữa quá trình nấu.", "Cùng lúc đó, cho cà chua cà chua và hành tím tây vào một bát nhỏ với giấm rượu vang đỏ và để một bên để muối. Cho bơ quả vào một bát khác và nghiền bằng nĩa, để lại các mảng lớn hơn. Khuấy vào nước cốt chanh xanh và nêm tốt. Trộn kem chua kem chua với gia vị ớt Harissa và đặt một bên cho đến khi sẵn sàng phục vụ.", "Đun chảo nướng cho đến khi gần khói. Thêm bánh tráng ngô Tortilla, một lá một lúc, nướng cada mặt cho đến khi nóng với vết nướng.", "Đặt mọi thứ lên bàn và xây fajitas : trải chút sốt harissa kem lên bánh tráng ngô, phủ đậu gà đã nướng, guacamole, salsa đã muối và ngò rí, nếu muốn. Ăn với các miếng chanh xanh để vắt lên trên."]'::jsonb, 4);
