INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a9b16f54-f292-5677-bf27-e5bcc340dfbf', 'Mì Udon xào kiểu Nhật (Yaki Udon)', 'rau'::public.dish_category, '["Đun sôi nước trong nồi lớn. Thêm 250 ml nước lạnh và mì Udon. (Vì chúng rất dày, thêm nước lạnh giúp chúng nấu chậm hơn một chút để phần giữa chín qua). Nếu dùng mì đông lạnh hoặc tươi, nấu 2 phút hoặc cho đến khi al dente; mì khô sẽ mất nhiều thời gian hơn, khoảng 5-6 phút. Rổ nước và để trong xáo ráo.", "Đun nóng 1 muỗng canh dầu, thêm hành tây và bắp cải và xào 5 phút cho đến khi mềm. Thêm nấm và một ít hành lá, và xào thêm 1 phút. Đổ dầu mè còn lại và mì vào. Nếu dùng mì lạnh, để chúng nóng qua trước khi thêm các nguyên liệu cho sốt – nếu không, đổ ngay vào và tiếp tục xào cho đến khi dính và nóng bỏng. Rắc hành lá còn lại lên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a9b16f54-f292-5677-bf27-e5bcc340dfbf', '066cda69-bc15-563f-9202-ce2aedb6c047', 250.0, 'g'::public.quantity_unit);
