INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0dfcbf97-79b9-58cf-a6bd-ddde777298c6', 'Trứng om kiểu Tây Ban Nha (Spanish Tortilla)', 'rau'::public.dish_category, '["Đặt chảo xào không dính lớn trên lửa thấp. Nấu hành tây chậm trong dầu và bơ cho đến khi mềm nhưng không vàng – nên mất khoảng 15 phút. Thêm khoai tây, nắp chảo và nấu thêm 15-20 phút, khuấy đôi khi để đảm bảo chúng chiên đều.", "Khi khoai tây mềm và hành tây bóng, nát 2 tép tỏi và khuấy vào, rồi thêm trứng đã đánh.", "Đậy nắp chảo lại và để tortilla nấu nhẹ. Sau 20 phút, các cạnh và đáy nên vàng, phần trên kết nhưng phần giữa vẫn hơi run. Để lật nó lên, trượt nó lên đĩa và đặt đĩa khác lên trên, lật toàn bộ rồi trượt trở lại chảo để nấu phần còn lại. Khi chín, chuyển sang đĩa và phục vụ tortilla khi ấm hoặc lạnh, rắc ngô tây đã cắt nhỏ.", "Để ăn kèm, lấy lát bánh mì baguette đã hâm, chọc khắp nơi bằng nĩa và chà với tỏi còn lại, đống cà chua đã nghiền lên trên và nems với muối biển và chút dầu ô liu."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('0dfcbf97-79b9-58cf-a6bd-ddde777298c6', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 1.0, 'piece'::public.quantity_unit);
