INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('21ab6d69-d946-5b98-b3b8-723ba63f7166', 'Cháo bò bánh bao', 'man'::public.dish_category, '["Đun lò đến 180°C.", "Với cháo bò, đun dầu và bơ trong nồi chống lửa và chiên thịt bò cho đến khi vàng mọi bên.", "Rắc bột mì lên và nấu thêm 2-3 phút.", "Thêm tỏi và tất cả rau và chiên 1-2 phút.", "Khuân rượu vang, nước dùng và thảo mộc vào, rồi thêm sốt Worcestershire và giấm balsamic, vừa đủ. Nems muối và tiêu đen xay tươi.", "Đậy nắp, chuyển vào lò và nấu khoảng hai giờ, hoặc cho đến khi thịt mềm.", "Với bánh bao, rây bột mì, bột nở (baking powder) và muối vào bát.", "Thêm mỡ thận và đủ nước để tạo thành hỗn hợp đặc.", "Tay đã bón bột, cuộn thìa hỗn hợp thành các viên nhỏ.", "Sau hai giờ, lấy nắp khỏi cháo và đặt các viên lên trên cháo. Đậy nắp, quay trở lại lò và nấu thêm 20 phút, hoặc cho đến khi các bánh bao đã nở và mềm. (Nếu bạn thích bánh bao có mặt trên vàng, hãy để nắp mở khi quay trở lại lò.)", "Để phục vụ, đặt một thìa khoai nghiền lên mỗi đĩa phục vụ và đặt cháo và bánh bao lên trên. Rắc ngô tây đã cắt nhỏ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('21ab6d69-d946-5b98-b3b8-723ba63f7166', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 30.0, 'ml'::public.quantity_unit);
