INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a8083070-79fc-53dd-9144-92542f4c8603', 'Bánh bò mù tạt', 'man'::public.dish_category, '["Đun lò đến 150°C.", "Trộn thịt bò và bột mì trong bát với ít muối và tiêu đen.", "Đun nồi lớn cho đến khi nóng, thêm nửa lượng dầu hạt cải và đủ thịt bò để phủ đáy nồi.", "Chiên cho đến khi vàng mỗi bên, rồi lấy ra và đặt một bên. Làm tương tự với dầu và thịt còn lại.", "Trả thịt bò vào chảo, thêm rượu vang và nấu cho đến khi thể tích dịch cạn một nửa, rồi thêm nước dùng, hành tây, cà rốt, xạ hương và mù tạt, và nems muối và tiêu vừa đủ.", "Đậy nắp và đặt vào lò trong hai giờ.", "Lấy ra khỏi lò, kiểm tra gia vị và để một bên nguội. Bớp xạ hương.", "Khi thịt bò đã nguội và sẵn sàng ghép bánh, đun lò đến 200°C.", "Chuyển thịt bò vào đĩa bánh, quét viền bằng lòng đỏ trứng đã đánh tan và đặt bột ngàn lớp lên trên. Quét mặt bột ngàn lớp bằng thêm trứng đánh tan.", "Cắt tỉa bột ngàn lớp để chỉ còn đủ phần thừa để héo các cạnh, rồi đặt vào lò và nướng 30 phút, hoặc cho đến khi bột ngàn lớp vàng nâu và chín qua.", "Với đậu que, đun nồi nước muối đến sôi, thêm đậu và nấu 4-5 phút, hoặc cho đến khi vừa mềm.", "Để thoát nước và trộn với bơ, rồi nems tiêu đen.", "Để phục vụ, đặt một thìa lớn bánh lên mỗi đĩa cùng với ít đậu que bên cạnh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a8083070-79fc-53dd-9144-92542f4c8603', 'fda67982-c921-54e6-9568-e2184abae4d6', 1000.0, 'g'::public.quantity_unit);
