INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('75dc760c-739f-5cf9-b6e6-4b76802a53dd', 'Bánh pudding thịt bò xay', 'man'::public.dish_category, '["Đầy lò 200°C.", "Đun dầu trong chảo sâu và chiên thịt bò xay 4-5 phút, dùng muỗng gỗ đập nát khi vàng.", "Thêm hành tây và nấu 2-3 phút, rồi khuấy cà chua xay nhuyễn vào và nấu thêm 2-3 phút. Khuấy bột mì vào và nấu thêm một phút, rồi thêm nấm đã băm, nước dùng bò hoặc bia đen và một chút sốt Worcestershire. Đun sôi, hạ lửa, đậy nắp nồi và để hôi 20 phút. Để riêng và để nguội, rồi đổ hỗn hợp thịt vào ô n wun một lít.", "Luồn vở bánh trên bề mặt làm việc rắc bột cho đến khi lớn hơn ô n wun một chút. Nhẹ nhàng đặt vở lên khay, đ sát vào các cạnh. Cắt bớt, rồi tạo bo tròn các cạnh.", "Cắt một số hình lá từ phần vở thừa và trang trí bề mặt bánh, dán chúng vào vở bằng lòng đỏ trứng đánh tan.", "Làm ba hoặc bốn vết cắt trên vở để hơi thoát ra, rồi sơn bánh bằng phần còn lại của lòng đỏ đánh tan và nướng trong lò 20-25 phút, hoặc cho đến khi vàng.", "Khi dùng, cắt thành từng miếng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('75dc760c-739f-5cf9-b6e6-4b76802a53dd', '41e2849c-302d-5cf6-9f07-ca579b4604a3', 30.0, 'ml'::public.quantity_unit);
