INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d7c885c4-612e-5011-a92e-a7bc65a6b7ca', 'Bánh pudding cừu khoai tây (Lamb Pie)', 'man'::public.dish_category, '["Bắc nhẹ bột mì lên miếng thịt cừu.", "Đun nóng đủ dầu thực vật trong nồi lớn đến hết đáy, chiên hành tây và thịt cừu cho nhẹ vàng. Nems muối tiêu.", "Thêm cà rốt, nước dùng và nêm thêm theo khẩu vị.", "Đun sôi, đậy nắp, hãm lửa cho nhỏ. Hôi ít nhất một giờ hoặc cho đến khi thịt cừu mềm. Nấu chậm cho ngon, nấu lâu thì vị càng đậm.", "Đầy lò 180°C.", "Cho củ khoai tây đã thái khối và ráo nước vào thịt cừu.", "Đổ hỗn hợp vào ô nướng hoặc nồi đất, phủ bằng vở bánh vỏ giòn. Làm ba vết cắt trên bề mặt vở bánh để hơi nước thoát ra khi nướng.", "Sơn trứng đánh tan rồi nướng khoảng 40 phút cho đến khi vở bánh vàng.", "Dùng ngay."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d7c885c4-612e-5011-a92e-a7bc65a6b7ca', '183f4755-c7d4-5017-9d66-3e0028f10788', 500.0, 'g'::public.quantity_unit);
