INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d7c885c4-612e-5011-a92e-a7bc65a6b7ca', '02f04e5e-25f7-5664-9c2e-4ad36fc921c1', 450.0, 'g'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5c44b78a-fe07-5d1c-96ad-e345697a5706', 'Bánh bò hàu', 'man'::public.dish_category, '["Nems các khối thịt bò với muối và tiêu đen. Đun một muỗng canh dầu trong chảo chiên và chiên thịt trên lửa lớn. Làm trong ba đợt để không quá đông chảo, chuyển thịt vào nồi lớn chống cháy khi đã vàng hết mọi bên. Thêm dầu nếu chảo vơi khô.", "Trong cùng chảo, thêm một muỗng canh dầu khác và nấu hành tím 4-5 phút, rồi thêm tỏi và chiên 30 giây. Thêm xúc xích khói và chiên cho đến khi hơi vàng. Chuyển hỗn hợp hành và xúc xích vào nồi và thêm các lá thảo mộc.", "Đun lò đến 180°C.", "Đổ bia stout vào chảo chiên và đun đến sôi, khuân để nhấc các mảnh vàng đen dính đáy chảo. Đổ bia stout lên thịt bò trong nồi và thêm nước dùng. Đậy nắp nồi và đặt vào lò trong 1,5-2 giờ, hoặc cho đến khi thịt bò mềm và sốt đặc hơn.", "Bớp béo trên bề mặt, nếm và thêm muối và tiêu nếu cần, rồi khuân bột bắp đặc. Đặt nồi trên bếp – đừng quên nó sẽ nóng – và đun sôi nhẹ 1-2 phút, khuân, cho đến khi đặc. Để nguội.", "Tăng lò lên 200°C. Làm bột: đặt bột mì và muối vào bát rất lớn. Xén bơ và khuân vào bột thành ba đợt. Thêm dần 325 ml nước lạnh – bạn có thể không dùng hết – và khuân bằng dao chữa nhọn cho đến khi hỗn hợp vừa dính nhau. Xoa uống nhẹ bột thành một viên trên bề mặt đã bón nhẹ bột và bỏ một bên 250 g cho nắp bánh.", "Trình phần bột còn lại cho đến khi lớn hơn đĩa bạn dùng khoảng 2cm. Đệm đĩa bằng bột rồi đống nhân vào, đặt hàu vào cũng. Quét cạnh bột bằng trứng đánh tan.", "Trình phần bột còn lại cho đến khi hơi lớn hơn đĩa của bạn và nhẹ nhàng nâng lên trên nhân, bóp chặt các cạnh để kín, rồi cắt tỉa bằng dao sắc. Quét bằng trứng đánh tan để men men. Đặt đĩa lên khay nướng và nướng 25-30 phút, hoặc cho đến khi bột vàng nâu và nhân đang sôi sật."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5c44b78a-fe07-5d1c-96ad-e345697a5706', 'fda67982-c921-54e6-9568-e2184abae4d6', 900.0, 'g'::public.quantity_unit);
