INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9bf76d4f-137f-5bcf-9100-91e0a0ff12bf', 'Bánh khoai tây gà kiểu Parmentier (Chicken Parmentier)', 'man'::public.dish_category, '["Đối với phần tráng, luộc khoai tây trong nước muối cho đến khi mềm. Ráo và nghiền qua máy nghiền khoai tây, hoặc nghiền kỹ. Khuấy vào bơ, kem và lòng đỏ trứng. Nêm và đặt một bên.", "Đối với phần nhân, nung bơ trong nồi lớn. Thêm hành tím tây, cà rốt và cần tây và chiên nhẹ cho đến khi mềm, sau đó thêm tỏi. Đổ rượu vang trắng vào và nấu trong 1 phút. Khuấy vào cà chua xay nhuyễn, cà chua đã kẹo và nước dùng gà và nấu trong 10–15 phút, cho đến khi đặc. Thêm gà đã xé, quả ô liu đen và ngô tây. Nêm nếm theo khẩu vị với muối và tiêu.", "Đun lò trước đến 180°C/160°C/mức 4.", "Đặt phần nhân vào đĩa nướng 20x30cm/20x30cm và tráng bằng khoai tây nghiền. Rắc phô mai Gruyère lên trên. Nấu trong 30–35 phút, cho đến khi nóng hổi và khoai tây vàng nụi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9bf76d4f-137f-5bcf-9100-91e0a0ff12bf', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1500.0, 'g'::public.quantity_unit);
