INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b94fb645-ff38-5a1c-8965-8be905e4ee97', 'Bánh pate bò và thận (Steak and Kidney Pie)', 'man'::public.dish_category, '["Đun lò lên 220°C", "Đun nóng dầu thực vật trong chảo xào lớn, và chiên bò cho đến khi vàng khắp nơi. (Bạn có thể cần làm theo từng đợt.) Đặt riêng, rồi chiên thận cho đến khi vàng cả hai mặt trong cùng chảo. Thêm hành tây và nấu trong 3-4 phút.", "Trả bò vào chảo, rắc bột lên và phủ thịt và hành tây", "Thêm nước dùng vào chảo, khuấy tốt và đun sôi.", "Giảm lửa và ninh trong 1 giờ 30 phút không nắp. Nếu nước cốt bốc hơi quá nhiều, thêm thêm nước dùng.", "Lấy khỏi bếp. Thêm muối, tiêu và sốt Worcestershire và để nguội hoàn toàn. Đặt hỗn hợp thịt đã nấu vào chảo pate.", "Lăn bot ra dày 5mm và rộng hơn 5cm so với chảo bạn đang dùng.", "Dùng thìa cuộn, nâng bot và đặt nó lên trên chảo pate. Cắt tỉa và khép cạnh bằng ngón tay và ngón cái.", "Chải bề mặt với hỗn hợp trứng đã đánh và nướng trong 30-40 phút cho đến khi vàng và phồng.", "Phục vụ với khoai nghiền kem và rau hấp để hấp thụ sốt."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('b94fb645-ff38-5a1c-8965-8be905e4ee97', '454e13c3-f732-5ea5-9532-268e9a0fd093', 300.0, 'g'::public.quantity_unit);
