INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a38559da-e34b-5362-b14d-148a003c9915', 'Bánh pate cá ba loại', 'man'::public.dish_category, '["Đun lò 200°C.", "Cho khoai tây vào nồi nước lạnh có muối. Đun sôi và hầm sôi nhẹ cho đến khi hoàn toàn mềm. Rổ nước thật khô rồi nghiền với bơ và sữa tươi. Thêm tiêu và nếm để kiểm tra nêm nếm. Thêm muối và nhiều tiêu hơn nếu cần.", "Để làm phần nhân cá, đun bơ trong nồi, thêm tỏi tây và khuấy trên lửa. Đậy nắp và hầm sôi nhẹ 10 phút, hoặc cho đến khi mềm. Lấy bột mì đa dụng vào tô nhỏ. Thêm rượu vang trắng và đánh cho mịn.", "Thêm sữa tươi vào tỏi tây, đun sôi và sau đó thêm hỗn hợp rượu vang. Khuấy nhanh cho đến khi đặc. Nêm nếm và thêm ngô tây và cá. Khuấy trên lửa trong hai phút, rồi cho vào nồi hầm chịu nhiệt. Rắc trứng lên. Để nguội cho đến khi đặc.", "Cho khoai tây nghiền lên trên hỗn hợp cá và chấm bằng nĩa. Rắc phô mai lên.", "Nướng 30-40 phút, hoặc cho đến khi nhẹ vàng trên mặt và nổi bọt xung quanh viền."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a38559da-e34b-5362-b14d-148a003c9915', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1000.0, 'g'::public.quantity_unit);
