INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('951dc303-7852-5053-ba87-f3397891cf8f', 'Nồi hôi Lancashire (Lancashire hotpot)', 'man'::public.dish_category, '["Đầy lò 160°C. Đun nóng chờ nở hoặc bơ trong nồi đất rộng lớn, chiên thịt cừu vàng từng lượt, vớt ra đĩa, sau đó làm tương với cật cừu.", "Chiên hành tây và cà rốt trong chảo với chờ nở thêm cho đến khi vàng. Rắc bột mì, nấu vài phút, rắc sốt Worcestershire, rót nước dùng vào rồi đun sôi. Khuấy thịt cừu và lá nguyệt quế, rồi tắt bếp. Xếp lát khoai tây lên trên thịt, rồi rưới chờ nở thêm. Đậy nắp, cho vào lò khoảng một giờ nửa cho đến khi khoai chín.", "Mở nắp, sơn khoai bằng chờ nở thêm, rồi tăng nhiệt lò để nướng khoai cho vàng, hoặc hoàn thiện dưới lò nướng 5-8 phút cho đến khi vàng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('951dc303-7852-5053-ba87-f3397891cf8f', '5b335556-d749-5751-acbe-0db2ff3196c9', 100.0, 'g'::public.quantity_unit);
