INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a10bd8dc-7a64-5c0d-a83f-ba1a585b9ec2', 'Cá và gạo Nga Uy (Kedgeree)', 'man'::public.dish_category, '["1. Để làm gạo, đun dầu trong chảo lớn có nắp, thêm hành tây, rồi chiên nhẹ trong 5 phút cho đến khi mềm nhưng không đổi màu. Thêm gia vị, nêm muối, rồi tiếp tục chiên cho đến khi hỗn hợp bắt đầu chuyển thành màu nâu và thơm; khoảng 3 phút.", "2. Thêm gạo và khuấy tốt. Thêm 600 ml nước, khuấy, rồi đun sôi. Giảm xuống sôi nhẹ, rồi đậy nắp trong 10 phút. Bớt khỏi lửa và để đứng, có nắp, thêm 10-15 phút nữa. Gạo sẽ chín hoàn hảo nếu bạn không nâng nắp trước khi kết thúc nấu.", "3. Trong lúc đó, đặt cá tuyết chấm đen hun khói và lá nguyệt quế vào chảo chiên, ngâm với sữa, rồi hầm nhẹ trong 10 phút cho đến khi thịt bong tách. Lấy ra khỏi sữa, bóc da, rồi nát thịt thành các miếng bằng ngón cái. Đặt trứng vào nồi, ngâm với nước, đun sôi, rồi giảm xuống sôi nhẹ. Để trong 4½-5 phút, ngâm vào nước lạnh, rồi bóc và cắt trứng thành tư phần. Khuấy nhẹ cá, trứng, ngô tay, ngô rí và gạo cùng nhau trong nồi. Ăn nóng, rắc thêm một chút thảo mộc."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a10bd8dc-7a64-5c0d-a83f-ba1a585b9ec2', '9107935a-6de0-528d-aba7-60533d512d07', 300.0, 'g'::public.quantity_unit);
