INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a10bd8dc-7a64-5c0d-a83f-ba1a585b9ec2', '4a081187-4d43-536a-9103-19f259b0316c', 300.0, 'g'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e50c2b78-004b-58b9-aebe-1ccba2f8aae5', 'Súp hầm ba-rô Pháp (French Onion Soup)', 'canh'::public.dish_category, '["Cho bơ vào chảo lớn có đáy dày với dầu. Thêm hành tây và chiên với nắp đậy trong 10 phút cho đến khi mềm. Rắc đường vào và nấu thêm 20 phút, khuấy thường xuyên, cho đến khi caramel hóa. Hành tay nên thật vàng, đầy hương vị và mềm khi vuốt giữa các ngón tay. Lưu ý vào cuối để đảm bảo chúng không bị cháy.", "Thêm tỏi vào vài phút cuối của thời gian nấu hành, rồi rắc bột vào và khuấy tốt. Tăng lửa và tiếp tục khuấy khi bạn dần dần thêm rượu vang, theo sau là nước dùng nóng. Đậy nắp và sôi nhẹ trong 15-20 phút.", "Để ăn, bật lò nướng, nướng bánh mì. Rút súp vào bát chịu nhiệt. Đặt một hoặc hai miếng bánh mì nướng lên trên các bát súp, và nhồi phô mai Gruyère lên trên. Nướng cho đến khi tan. Hoặc, bạn có thể hoàn thành các miếng bánh nướng dưới lò nướng, rồi ăn chúng lên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('e50c2b78-004b-58b9-aebe-1ccba2f8aae5', '5b335556-d749-5751-acbe-0db2ff3196c9', 50.0, 'g'::public.quantity_unit);
