INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b583522a-5597-5f54-a9a1-3eb7c1a60274', 'Sup pistou mùa hè (Summer Pistou)', 'rau'::public.dish_category, '["Đun nóng dầu trong chảo lớn và chiên là cầu và bí ngòi trong 5 phút để mềm. Đổ nước dùng vào, thêm ba phần tư đậu trắng Cannellini với đậu que, nửa cà chua, và ninh trong 5-8 phút cho đến khi rau mềm.", "Trong khi đó, xay nhuyễn đậu trắng Cannellini và cà chua còn lại, tỏi và húng quế tây trong máy xí nhuyễn (hoặc trong bát với máy xay cầm tay) cho đến khi mịn, rồi khuấy vào phô mai Parmesan. Khuấy sốt vào sup, nấu trong 1 phút, rồi rót nửa vào tô hoặc đổ vào xốp cho bữa ăn đóng gói. Để phần còn lại trong tủ lạnh. Sử dụng được trong vài ngày."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('b583522a-5597-5f54-a9a1-3eb7c1a60274', 'cdadb656-1960-506f-b7e6-70b7cd2bb6bc', 15.0, 'ml'::public.quantity_unit);
