INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f5850f3c-6cfe-5a77-903c-b3bd341072a7', 'Bánh brie bọc presutto Pháp', 'rau'::public.dish_category, '["Trộn bột mì, 1 muỗng cà phê muối, đường cát mịn, men nở, sữa và trứng cùng nhau trong máy xay bằng máy xóc bột trong 5 phút cho đến khi hỗn hợp mịn. Thêm bơ và khuân thêm 4 phút trên mức trung bình. Kẹp bát hỗn hợp và khuân lại trong 1 phút. Đặt hỗn hợp vào bình, đậy bằng bọc thực phẩm và để trong tủ lạnh ít nhất 6 giờ trước khi dùng.", "Bọc brie bằng presutto và đặt một bên. Đổ hỗn hợp ra trên bề mặt đã bón nhẹ bột. Trình thành vòng tròn 25cm. Đặt brie đã bọc vào chính giữa vòng tròn và gấp các cạnh theo cách gọn gàng. Đặt bọc lên khay nướng đã lót giấy bếp và quét bằng trứng đánh tan. Để trong tủ lạnh trong 30 phút, rồi quét lại bằng trứng đánh tan và để trong tủ lạnh thêm 30 phút. Để nở trong 1 giờ ở nhiệt độ phòng. Đun lò đến 200°C, rồi nướng 22 phút. Phục vụ khi ấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f5850f3c-6cfe-5a77-903c-b3bd341072a7', '7d6a1f7e-745c-5cd6-af33-19568749147f', 375.0, 'g'::public.quantity_unit);
