INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4d5b47e7-e0fa-5deb-95d1-c8460fe03c00', 'Khoai tây Boulangère Pháp', 'rau'::public.dish_category, '["Đun lò đến 200°C. Xào hành và nhánh xạ hương trong dầu cho đến khi mềm và hơi vàng (khoảng 5 phút).", "Rải một lớp khoai tây lên đáy nồi gratin 1,5 lít đã dầu. Rắc vài hành (xem hình trên) và tiếp tục xếp lớp, kết thúc bằng một lớp khoai tây. Đổ nước dùng lên và nướng 50-60 phút cho đến khi khoai chín và bề mặt vàng giòn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4d5b47e7-e0fa-5deb-95d1-c8460fe03c00', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 2.0, 'piece'::public.quantity_unit);
