INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4d5b47e7-e0fa-5deb-95d1-c8460fe03c00', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1500.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4d5b47e7-e0fa-5deb-95d1-c8460fe03c00', 'f0c3f6a2-9aa3-5b12-be9e-89d92af1b483', 425.0, 'g'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('47a9457f-2088-5f29-8851-95c959412aee', 'Hầm cá sốt Rouille (Fish Stew with Rouille)', 'man'::public.dish_category, '["Xoay đầu tôm ra, rồi bóc chân và vỏ, nhưng để đuôi nguyên. Bỏ đường ruột mỗi tôm. Chiên vỏ tôm trong 1 muỗng canh dầu trong 5 phút, cho đến khi hồng đen và vàng từng chỗ. Thêm rượu vang, đun sôi cho tới khi còn một phần ba, rồi rót nước dùng vào. Rót vào bình, vớ bỏ vỏ tôm.", "Đun phần dầu còn lại trong chảo chiên sâu hoặc nồi nhồi. Thêm tiểu hồi hương, hành tây và tỏi, nêm nếm, rồi đậy nắp và nấu nhẹ trong 10 phút cho đến khi mềm. Trong lúc đó, bóc khoai tây và cắt thành miếng khoảng 2 cm. Đặt vào nồi nước lạnh, đun sôi và nấu trong 5 phút cho đến khi gần mềm. Đổ vào rổ lọc.", "Bóc một sợi vỏ chanh từ quả cam. Đặt vỏ chanh, hoa hồi, lá nguyệt quế và 1/2 muỗng cà phê harissa vào chảo. Chiên nhẹ, không đậy nắp, trong 5-10 phút, cho đến khi rau mềm, ngọt và vàng.", "Khuấy cà chua xay nhuyễn vào, nấu trong 2 phút, rồi thêm cà chua và nước dùng. Sôi nhẹ trong 10 phút cho đến khi sốt đặc một chút. Nêm nếm theo khẩu vị. Sốt có thể làm trước, rồi đun nóng lại sau trong ngày. Trong lúc đó, chùi vẹm hoặc ngao và kéo đi râu dây. Mọi con đang mở nên nhấn mạnh vào bàn làm việc – nếu chúng không đóng sau vài giây, vớ bỏ.", "Đun nóng lại sốt nếu cần, rồi khuấy nhẹ khoai tây, miếng cá và tôm vào hầm. Đun sôi trở lại, rồi đậy nắp và sôi nhẹ trong 3 phút. Rải vẹm hoặc ngao lên trên hầm, rồi đậy nắp và nấu thêm 2 phút nữa hoặc cho đến khi vỏ mở rộng. Vớ bỏ những con vẫn đóng. Các miếng cá sẽ nát dễ dàng và tôm sẽ hồng khắp. Rải lá xạ hương lên trên.", "Để làm sốt rouille nhanh, khuấy phần harissa còn lại vào sốt mayonnaise. Ăn hầm trong bát, thêm một thìa sốt rouille lên trên, sẽ hòa tan vào sốt và làm giàu hơn. Có bánh mì tốt sẵn, vì bạn chắc chắn sẽ muốn ngâm nước sốt."]'::jsonb, 4);
