INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9e62ebb6-cbe7-5739-9f29-d73420287f7f', 'Khoai tây và tiểu hồi hương nướng kem (Fennel Dauphinoise)', 'rau'::public.dish_category, '["Đun lò đến 180°C. Đặt khoai tây, tiểu hồi hương và tỏi vào chảo chống dính trung bình. Đổ sữa tươi và kem đặc, nêm nếm đậm đà và hầm nhẹ, đậy nắp, 10 phút, khuấy vào nửa đường, cho đến khi khoai tây vừa mềm.", "Chia hỗn hợp thành 2 ramekin nhỏ (khoảng 150 ml) đã bơ và rắc phô mai Parmesan ở trên. Nướng 40 phút cho đến khi khoai tây vàng và mềm khi đâm bằng dao. Cắt nhánh tiểu hồi hương dự trữ trước khi ăn."]'::jsonb, 4);
