INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9c46fc26-5c39-5472-89d2-81732f2584ad', 'Gà kiểu Marengo (Chicken Marengo)', 'man'::public.dish_category, '["Đun nóng dầu ô liu trong nồi nấu lớn và chiên nấm cho đến khi chúng bắt đầu mềm. Thêm má đùi gà và nấu ngắn trên mỗi mặt để chúng hơi vàng.", "Đổ cà chua xay mịn đóng hộp Passata vào, nghiền viên súp gà vào và khuấy vào quả ô liu đen. Nêm tiêu đen – bạn không cần muối. Đậy nắp và hầm trong 40 phút cho đến khi gà mềm. Rắc ngô tây và ăn với pasta và salad, hoặc xù xích và rau xanh, nếu muốn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9c46fc26-5c39-5472-89d2-81732f2584ad', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 15.0, 'ml'::public.quantity_unit);
