INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9ba06f9f-3bf5-5f80-928b-47089a65080f', 'Súp kem tôm hồi Pháp (Prawn & Fennel Bisque)', 'rau'::public.dish_category, '["Bóc vỏ tôm, rồi chiên vỏ tôm trong dầu trong chảo lớn khoảng 5 phút. Thêm hành tây, hồi tây và cà rốt và nấu khoảng 10 phút cho đến khi rau bắt đầu mềm. Rót rượu vang và rượu Brandy, đun sôi mãnh khoảng 1 phút để bay cồn, rồi thêm cà chua, nước dùng cá và bột ớt ngọt. Đậy nắp và hôi 30 phút. Trong lúc đó, băm tôm.", "Xay sup mịn nhất có thể bằng máy xay cầm tay hoặc máy xay thực phẩm, rồi ép qua lưới vào bát. Dùng một chút thời gian để làm việc hỗn hợp qua lưới thật kỹ vì điều này sẽ cho sup texture mịn như lụa.", "Đổ trở lại nồi sạch, thêm tôm và nấu 10 phút, rồi xay lại cho đến khi mịn. Bạn có thể làm và làm lạnh một ngày trước hoặc đông lạnh 1 tháng. Giải đông trong tủ lạnh suốt đêm. Khi dùng, hâm nóng nhẹ trong nồi với kem tươi. Nếu trang trí, nấu 8 con tôm với ít bơ. Đổ vào bát nhỏ và phủ trên cùng tôm và lá hồi tây cắt sợi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9ba06f9f-3bf5-5f80-928b-47089a65080f', '1a0a7f9b-5b1b-5750-a646-bec67383b7d3', 450.0, 'g'::public.quantity_unit);
