INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('33f6ec9c-df25-5b3f-981c-f2d96e7f1ed8', 'Sup đậu Hà Lan kiểu Canada (Split Pea Soup)', 'canh'::public.dish_category, '["Đặt giăm bông vào nồi rất lớn với 2 lít nước và đun sôi. Lấy ra khỏi bếp và rarget nước – điều này giúp loại bỏ một phần mặn. Đổ thêm 2 lít nước lạnh và đun sôi lại. Cho tất cả trừ đậu Hà Lan đông lạnh vào nồi và đun sôi. Giảm lửa về sôi nhẹ và nấu trong 1,5-2,5 giờ, thêm nước khi cần, đến mức tương tự lúc bắt đầu. Khi giăm bông mềm đủ để xé thành sợi, là xong.", "Nâng giăm bông ra, bóc vỏ và vứt vỏ. Mà nó còn nóng (đeo găng tay cao su sạch), xé thịt. Bỏ lá nguyệt quế khỏi sup và khuấy đậu Hà Lan đông lạnh vào. Ninh trong 1 phút, rồi xay nhuyễn cho mịn. Thêm một chút nước nếu quá đặc, và trả lại nồi để nóng qua nếu nó đã nguội, hoặc nếu bạn làm trước."]'::jsonb, 4);
