INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4ca03ef0-da38-5b3b-b37b-2529a81b3a49', 'Bánh pate thịt heo kiểu Canada (Tourtiere)', 'man'::public.dish_category, '["Đun lò 200°C. Luộc khoai tây cho đến khi mềm, rổ nước và nghiền, rồi để nguội. Đun nóng dầu trong chảo không dính, thêm thịt heo băm và hành tây, chiên nhanh cho đến khi vàng. Thêm tỏi, gia vị, nước dùng, nhiều tiêu và ít muối và trộn đều. Lấy khỏi lửa, khuấy vào khoai tây và để nguội.", "Lót nửa bột vào đáy khay pate 20-23 cm hoặc khay flan. Nhét hỗn hợp heo vào và chọc nước vào bên viền bột. Lót phần bột còn lại và phủ pate. Chên bên viền bột để kín, cắt bỏ phần thừa. Chọc lỗ lên trên vỏ pate để hơi nước thoát và sơn trứng đánh lên trên.", "Nướng 30 phút cho đến khi bột giòn và vàng. Dùng cắt thành miếng tam giác cùng salad xanh giòn. Còn lại ăn lạnh cho bữa trăm ngày mai, dùng với món muối chua."]'::jsonb, 4);
