INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a57d8b93-3f78-5053-b6e6-3663b10b7172', 'Thịt xông khói Montreal', 'man'::public.dish_category, '["Làm nước muối ướp: trong bát nhỏ trộn muối, muối hồng, tiêu đen, ngô rí, đường, lá nguyệt quế và đinh hương. Bọc toàn bộ gầu bò bằng nước muối và cho vào túi nhựa kín lớn. Đặt vào phần lạnh nhất của tủ lạnh và ướp 4 ngày, lật gầu bò hai lần mỗi ngày.", "Vớt gầu bò khỏi túi và rửa sạch càng nhiều nước muối càng tốt dưới vòi nước lạnh. Đặt gầu bò vào bình lớn và lấp đầy nước, để ngâm 2 giờ, thay nước mỗi 30 phút. Vớt ra khỏi nước và thấm khô bằng khăn giấy.", "Làm nước xù: trộn tiêu đen, ngô rí, bột ớt ngọt, bột tỏi, bột hành, thì là khô, mù tạt, hạt cần tây, và bột ớt đỏ nghiền trong bát nhỏ. Bọc toàn bộ gầu bò bằng nước xù.", "Khởi tạo xông khói hoặc nướng đến 105°C, thêm mảng gỗ xông khi đủ nhiệt. Khi gỗ đã cháy và khơi khói, đặt gầu bò vào, phía mỡ lên, và xông cho đến khi nhiệt kế đọc 75°C khi đâm vào phần dày nhất của gầu bò, khoảng 6 giờ.", "Chuyển gầu bò vào nồi nướng lớn có khay V. Đặt nồi nướng trên hai bếp và thêm nước 2,5 cm. Đun nước sôi trên lửa lớn, hạ lửa vừa, phủ nồi nướng bằng giấy nhôm và hấp gầu bò cho đến khi nhiệt kế đọc 82°C khi đâm vào phần dày nhất của thịt, 1 đến 2 giờ, thêm nước nóng nếu cần.", "Chuyển gầu bò vào thớ cắt và để nguội một chút. Cắt lát và dùng, thích nhất trên bánh mì lúa mạch với mù tạt."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a57d8b93-3f78-5053-b6e6-3663b10b7172', 'c9a85c2e-12a8-501d-8172-b731d9ed81b6', 1.0, 'piece'::public.quantity_unit);
