INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('656bfb96-b45f-55d8-8f1a-40f621e93210', 'Bánh pudding khoai tây Canada (Pate Chinois)', 'man'::public.dish_category, '["Trong nồi lớn nước có muối, nấu khoai cho đến khi rất mềm. Ráo.", "Dùng máy nghiền, nghiền thô khoai với ít nhất 30 ml (2 muỗng canh) bơ. Dùng máy xay điện, nghiền mịn với sữa tươi. Nems muối và tiêu. Để riêng.", "Với khay ở vị trí giữa, đậy lò 190°C.", "Trong chảo lớn, chiên hành vàng trong bơ còn lại. Thêm thịt và nấu cho đến khi vàng nâu. Nems muối và tiêu. Nới bếp.", "Nhấn nhẹ thịt ở đáy ô nướng vuông 20 cm. Phủ ngô và khoai nghiền. Rắc bột ớt ngọt và ngô tây.", "Nướng khoảng 30 phút. Hoàn thiện nấu dưới lò nướng. Để nguội 10 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('656bfb96-b45f-55d8-8f1a-40f621e93210', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 960.0, 'ml'::public.quantity_unit);
