INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f0380913-e1dd-5bc3-988c-2e15b8657413', 'Bánh Rappie Canada (Rappie Pie)', 'man'::public.dish_category, '["Đaddy lò 200°C. Mỡ khay nướng 25x35x5 cm.", "Đun chờ nở trong chảo trên lửa vừa; khuấy hành vào. Nấu và khuấy cho đến khi hành mềm và chuyển thành trong, khoảng 5 phút. Giảm nhiệt xuống thấp và tiếp tục nấu và khuấy cho đến khi hành rất mềm và màu nâu đậm, khoảng 40 phút nữa.", "Đun nước dùng gà sôi trong nồi lớn; khuấy thịt gà vào, giảm nhiệt, và hôi cho đến khi gà không còn hồng ở giữa, khoảng 20 phút. Nới bếp. Vớt thịt gà ra đĩa bằng cuch đón ráo; giữ lại nước dùng.", "Xút khoai bằng máy xút điện; đặt phần khô của khoai vào bát và đổ bỏ nước. Khuấy muối và tiêu vào khoai; khuấy đủ nước dùng đã giữ lại để hỗn hợp có độ đặc như cháo yến mạch. Để phần nước dùng còn lại riêng.", "Rải nửa hỗn hợp khoai đều vào khay đã chuẩn bị. Đặt thịt gà đã nấu đều lên khoai; rắc hành caramel hóa đều lên thịt. Rải hỗn hợp khoai còn lại lên trên hành và thịt để phủ.", "Nướng trong lò đã đaddy cho đến khi vàng nâu, khoảng 1 giờ. Đun lại nước dùng gà; rót lên từng phần dùng theo ý muốn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f0380913-e1dd-5bc3-988c-2e15b8657413', '5b335556-d749-5751-acbe-0db2ff3196c9', 30.0, 'ml'::public.quantity_unit);
