INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('38816da2-90ff-5cb4-8efb-652fedc93efe', 'Gà kiểu Basque (Chicken Basquaise)', 'man'::public.dish_category, '["Đun lò trước đến 180°C/mức 4. Chuẩn bị các miếng gà sẵn sàng nấu. Đun nóng bơ và 3 muỗng canh dầu ô liu trong nồi nấu hoặc chảo lớn. Rang miếng gà theo đợt trên cả hai mặt, nêm muối và tiêu trong quá trình đền. Không quá tải chảo – chiên gà theo đợt nhỏ, lấy các miếng ra khăn giấy khi xong.", "Thêm chút dầu ô liu hơn vào nồi và chiên hành tím tây trên lửa trung bình trong 10 phút, gọi đều cho đến khi mềm nhưng không vàng. Thêm phần dầu còn lại, sau đó ớt chuông đỏ và nấu thêm 5 phút.", "Thêm xúc xích Chorizo, cà chua khô nắng và tỏi và nấu trong 2-3 phút. Thêm gạo, khuấy để đảm bảo gạo được phủ dầu đều. Thêm cà chua xay nhuyễn, bột ớt ngọt Paprika, lá nguyệt quế và xạ hương đã kẹo. Đổ nước dùng gà và rượu vang trắng khô. Khi chất lỏng bắt đầu sôi, giảm lửa xuống hầm nhẹ. Ép gạo xuống dưới chất lỏng nếu chưa ngầm và đặt gà lên trên. Thêm vở chanh và quả ô liu đen xung quanh gà.", "Đậy nắp và nấu trong lò trong 50 phút. Gạo nên chín nhưng vẫn có chút độ dai, và gà nên có nước chảy trong khi đâm chìm vào phần dày nhất bằng dao. Nếu không, nấu thêm 5 phút và kiểm tra lại."]'::jsonb, 4);
