INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5e30ac3f-6b67-5649-8001-a302e22c5ae7', 'Bò sốt Diane (Steak Diane)', 'man'::public.dish_category, '["Đun dầu trong chảo xào lớn trên lửa vừa-cao. Nems steak với muối và tiêu, và thêm vào chảo; nấu, lật một lần, cho đến khi vàng cả hai mặt và chín theo sở thích, khoảng 4 đến 5 phút cho vừa chín, có hồng lòng. Chuyển steak sang đĩa, và để riêng.", "Trả chảo đến lửa cao, và thêm nước dùng; nấu cho đến khi giảm xuống 120 ml, khoảng 10 phút. Đổ vào bát, và để riêng. Trả chảo đến lửa, và thêm bơ; thêm tỏi và hành tím, và nấu, khuấy, cho đến khi mềm, khoảng 2 phút. Thêm nấm, và nấu, khuấy, cho đến khi chúng thả bất kỳ chất lỏng nào và nó bốc hơi và nấm bắt đầu vàng, khoảng 2 phút. Thêm coniac, và tia diêm để cháy lên; nấu cho đến khi ngọn lửa tắt dần. Khuấy vào nước dùng đã giữ, kem, Dijon, Worcestershire, và sốt nóng, và rồi trả steak vào chảo; nấu, lật trong sốt, cho đến khi nóng qua và sốt đặc, khoảng 4 phút. Chuyển steak sang đĩa phục vụ và khuấy ngô tây và cải thì là vào sốt; rót sốt lên steak để phục vụ."]'::jsonb, 4);
