INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b3ba0b39-a036-5847-8392-ab1f26374dde', 'Cá tuyết muối và trái Ackee (Saltfish and Ackee)', 'man'::public.dish_category, '["Để làm cá tuyết muối, ngâm cá tuyết muối khô qua đêm, thay nước vài lần.", "Rarget nước, rồi cho cá vào nồi lớn với nước tươi và đun sôi. Rarget lại nước, thêm nước tươi và đun sôi lại.", "Ninh khoảng năm phút, hoặc cho đến khi chín đều, rồi rarget và xẻ cá thành miếng lớn. Bỏ vỏ và cốt xương.", "Để làm bánh, trộn bột nở và mỡ thận bò với một chút muối và 250 ml nước để thành bot.", "Bọc bot bằng màng bọc và để trong tủ lạnh để nghỉ.", "Mở hộp quả Ackee, rarget nước, rửa sạch và để riêng.", "Đun nóng 1 muỗng canh dầu ô liu trong chảo và chiên hành tây cho đến khi mềm nhưng không vàng.", "Thêm gia vị, nêm nếm, sốt ớt và ớt chuông thái lát và tiếp tục chiên cho đến khi ớt chuông mềm.", "Thêm cà chua đã nghiền, rồi cá tuyết muối và trộn chung. Cuối cùng khuấy nhẹ vào quả Ackee và để ninh cho đến khi sẵn sàng phục vụ.", "Khi sắp ăn, đun khoảng 1 cm dầu thực vật trong chảo chiên và đun cho đến khi vừa khói.", "Dạng hỗn hợp bánh thành quả như mận và chiên nhẹ cho đến khi vàng. (LƯU Ý: dầu nóng có nguy hiểm. Không để chảo mà không ai coi chừng.)", "Rarget bánh trên giấy tầu và phục vụ với cá tuyết muối và quả Ackee."]'::jsonb, 4);
