INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4e3be023-e6f3-5aef-9b68-eea6ed985f3f', 'Gà nướng Jamaica với cơm và đậu (Jerk chicken with rice & peas)', 'man'::public.dish_category, '["Để làm gia vị ướp jerk, trộn tất cả nguyên liệu trong máy xay cùng với 1 muỗng cà phê muối, và xay thành puree. Nếu bạn gặp sự cố khi đánh trộn, cứ tắt máy xay liên tục, khuấy hỗn hợp, và thử lại. Cuối cùng nó sẽ bắt đầu đánh trộn – đừng thêm nước, vì bạn muốn một hỗn hợp đặc.", "Thử hỗn hợp jerk cho gia vị – nó nên khá mặn, nhưng không mặn đến mức khó chịu. Bây giờ bạn có thể ném thêm ớt nếu nó không đủ cay cho bạn. Nếu nó có vị quá mặn và chua, hãy thử thêm một chút đường nâu cho đến khi hỗn hợp có vị cân bằng tốt.", "Đặt vài vết cắt vào đùi gà và rót gia vị ướp lên thịt, chà vào tất cả các kẽ hốc. Đậy nắp và để ướp qua đêm trong tủ lạnh.", "Nếu bạn muốn nướng than gà của mình, hãy đốt than khoảng 1 tiếng trước khi bạn sẵn sàng nấu. Thịt nướng jerk thực sự không chính xác là nướng như chúng ta nghĩ về nướng, mà giống như nướng khói. Để có trải nghiệm jerk thực sự hơn, thêm một vài mảng gỗ vào nướng than của bạn, và nấu gà của bạn trên lửa chậm, nhiệt gián tiếp trong 30 phút. Để nấu trong lò, đun đến 180°C. Đặt các miếng gà vào khay nướng cùng với nửa chanh xanh và nấu trong 45 phút cho đến khi mềm và chín kỹ.", "Trong khi gà nấu, chuẩn bị cơm và đậu. Rửa gạo với nhiều nước lạnh, rồi đổ nó vào nồi lớn với tất cả các nguyên liệu còn ngoại trừ đậu đỏ Kidney. Nêm muối, thêm 300 ml nước lạnh và đặt trên lửa cao. Khi gạo bắt đầu sôi, giảm lửa xuống vừa, đậy nắp và nấu trong 10 phút.", "Thêm đậu vào gạo, rồi đậy nắp. Để rời khỏi lửa trong 5 phút cho đến khi hết chất lỏng đã được hấp thụ. Vắt chanh xanh đã nướng lên gà và ăn với cơm và đậu, và một chút sốt cay nếu bạn thích rất cay."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4e3be023-e6f3-5aef-9b68-eea6ed985f3f', '53912b45-176d-5ec9-81db-addf1adaa05f', 12.0, 'piece'::public.quantity_unit);
