INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d8a6fd97-261b-5fa5-ad28-415f4d59930c', '8a301d33-ca8b-52a8-aa71-ca6feca05e46', 1.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7ea6d407-aae7-55fb-9271-61adc49a1716', 'Gà h sốt nâu Jamaica', 'man'::public.dish_category, '["Chắt chanh xanh lên trên gà và xoa thật tốt. Xé bỏ nước chanh dư.", "Trộn cà chua, hành lá, hành, tỏi, ớt chuông đỏ, xạ hương, hạt tiêu Jamaica và nước tương trong bát lớn với các miếng gà. Đậy nắp và ướt ít nhất một giờ.", "Đun dầu trong nồi đất hoặc nồi lớn. Lắc bỏ các gia vị khi bạn lấy từng miếng gà khỏi sốt ướp. Giữ lại sốt ướp để làm sốt.", "Nhẹ vàng gà vài miếng một lúc trong dầu rất nóng. Đặt các miếng gà đã vàng lên đĩa để nghỉ trong khi bạn vàng các miếng còn lại.", "Xé bỏ dầu dư và trả gà vào chảo. Đổ sốt ướp lên trên gà và thêm cà rốt. Khuân và nấu trên lửa trung bình trong 10 phút.", "Trộn bột bắp và nước cốt dừa và thêm vào cháo hầm, khuân liên tục. Giảm lửa xuống mức thấp và nấu thêm 20 phút hoặc cho đến khi mềm."]'::jsonb, 4);
