INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('74713c6c-d71b-553a-a371-d948cf97db55', 'Sup đậu đỏ Jamaica (Red Peas Soup)', 'canh'::public.dish_category, '["Rửa và vò sạch đậu đỏ Kidney khô, rồi ngập nước trong bát lớn. Nhớ khi ngâm đậu sẽ nở ra ít nhất ba lần kích thước ban đầu nên cho nhiều nước vào bát. Ngâm qua đêm hoặc ít nhất 2 giờ để bước nấu nhanh hơn. Đổ bỏ nước ngâm sau khi đã hoàn thành nhiệm vụ.", "Nhờ thợ thủ das cắt đuôi heo muối thành miếng 5 cm vì sẽ rất khó cắt bằng dao bếp thường. Rửa, rồi cho vào nồi lớn với nước và đun sôi. Nấu 20 phút, rồi rarget nước, rửa sạch và lặp lại (đun sôi lại trong nước). Mục tiêu là làm cho các miếng đuôi heo mềm và loại bỏ phần lớn muối dùng để ức chế.", "Đến lúc nấu sup. Cho tất cả vào nồi (trừ bột mì đa dụng và khoai tây), ngập nước và đặt trên lửa lớn đun sôi. Khi sôi, vớt bọt trên mặt và vớt bỏ. Giảm lửa đun nhẹ và nấu trong 1 giờ 15 phút, cơ cho đến khi đậu mềm và bắt đầu nát.", "Đến lúc thêm khoai tây (và khoai mè… nếu thêm) cùng nước cốt dừa và tiếp tục nấu 15 phút.", "Đây là lúc thích hợp để làm bột cho bánh spinner. Trộn bột mì đa dụng và nước (thêm một chút muối biển nếu muốn) cho đến khi có bột mềm/mịn. Nghỉ 5 phút, rồi cui một muỗng canh mỗi lần và cuộn giữa tay thành hình trụ nhỏ.", "Cho chúng vào nồi, khuấy đều và tiếp tục nấu thêm 15 phút trên nước sôi dốc.", "Bạn sẽ nhận thấy tôi không thêm muối vào nồi vì muối còn lại từ đuôi heo muối đủ để nêm nếm món này đúng mức. Tuy nhiên bạn có thể nếm và điều chỉnh lại. Hãy tóm lại phần thời gian để bạn không bị nhầm. Nấu phần cơm của sup trong 1 giờ 15 phút cho đến khi mềm, rồi thêm khoai và nấu 15 phút, rồi thêm bánh và nấu thêm 15 phút. Hãy nhớ món này sẽ đặc hơn khi nguội.", "Đây không phải là công thức truyền thống của một đảo cụ thể, nhưng các phiên bản sup này (thỉnh thoảng gọi là sup đậu hầm) có thể tìm thấy khắp Caribbean, Latin Mỹ và Châu Phi. Một tô sup dạ dày chắc chắn sẽ làm bạn buồn ngủ (một số người gọi là mệt mỏi dân tộc). Bạn hoàn toàn có thể đóng băng phần còn lại và hâm nóng vào ngày khác."]'::jsonb, 4);
