INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('bebb3f15-2548-5f24-a800-c18914b273f8', 'Đuôi bò cùng đậu tằm Jamaica', 'man'::public.dish_category, '["Trộn đuôi bò với hành tây, hành lá, tỏi, gừng, ớt, xì dầu, xạ hương, muối và tiêu. Đun dầu thực vật trong chảo lớn trên lửa vừa-cao. Chiên đuôi bò trong chảo cho đến khi vàng khắp nơi, khoảng 10 phút. Đặt vào nồi áp lực và rót 375 ml nước. Nấu áp lực 25 phút, rồi nới bếp và mở nắp theo hướng dẫn của nhà sản xuất.", "Thêm đậu tằm và hạt xạ hương, và đun hôi trên lửa vừa-cao. Tan bột bắp trong 2 muỗng canh nước, và khuấy vào đuôi bò đang hôi. Nấu và khuấy vài phút cho đến khi sốt đã đặc và đậu tằm đã mềm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bebb3f15-2548-5f24-a800-c18914b273f8', '66718300-c570-5a54-a829-98bc94b48486', 450.0, 'g'::public.quantity_unit);
