INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b0c19ebf-1b3d-57af-9361-2b77a93889fe', 'Cá sốt giấm Jamaica (Escovitch Fish)', 'man'::public.dish_category, '["Rửa cá, chà nhuyễn chanh hoặc chanh xanh, nêm muối và tiêu hoặc dùng gia vị bạn thích. Để một bên hoặc để trong lò để giữ nóng cho đến khi sốt sẵn sàng.", "Đun dầu thực vật trên chảo lớn cho đến khi nóng, cho cá vào, chiên mỗi bên khoảng 5-7 phút cho đến khi chín và giòn cả hai bên. Lấy cá ra, để một bên. Đổ bỏ dầu, để lại khoảng 2-3 muỗng canh dầu.", "Cho lá nguyệt quế, tỏi và gừng vào, xào khoảng một phút, lưu ý không để tỏi cháy.", "Thêm hành tây, ớt chuông đỏ, ớt chuông vàng, xạ hương, ớt chuông siêu cay Scotch Bonnet, đường và hạt tiêu Jamaica, tiếp tục khuấy khoảng 2-3 phút. Thêm giấm mạch nha, khuấy đều và điều chỉnh muối và tiêu theo khẩu vị. Để sôi nhẹ thêm khoảng 2 phút.", "Bỏ lá nguyệt quế và nhánh xạ hương, đặt sốt lên trên cá, ăn kèm bánh bammy. Bạn có thể làm sốt trước khoảng 2 ngày."]'::jsonb, 4);
