INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c995a7e3-1920-5eb1-8e23-66de51b5c50a', 'Gà sốt Kung Pao Trung Quốc (Kung Pao Chicken)', 'man'::public.dish_category, '["Trộn rượu Sake hoặc rượu gạo, nước tương, dầu mè và bột ngô tan trong nước. Chia hỗn hợp thành nửa.", "Trong một đĩa thủy tinh hoặc bát, trộn nửa hỗn hợp rượu Sake với các miếng gà và lắc để phủ. Đậy đĩa và đặt vào tủ lạnh trong khoảng 30 phút.", "Trong một chảo chiên vừa, trộn phần còn lại của hỗn hợp rượu Sake, ớt, giấm và đường. Trộn cùng nhau và thêm hành lá, tỏi, củ năng và đậu phộng. Đun sốt chậm trên lửa vừa cho đến khi thơm.", "Trong lúc đó, lấy gà ra khỏi hỗn hợp ướp và xào trong một chảo chiên lớn cho đến khi nước cốt trong suốt. Khi sốt thơm, thêm gà đã xào và để sôi nhẹ cùng nhau cho đến khi sốt đặc."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c995a7e3-1920-5eb1-8e23-66de51b5c50a', '24baa65e-fd0f-5af3-ae1d-fa83144442ea', 30.0, 'ml'::public.quantity_unit);
