INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9886119c-6032-561c-ba1b-3762a3cd95e1', 'Tôm sốt Kung Po Trung Quốc (Kung Po Prawns)', 'man'::public.dish_category, '["Trộn bột ngô và 1 muỗng canh nước tương, lắc tôm vào và để một bên trong 10 phút. Khuấy giấm, phần nước tương còn lại, sốt cà chua, đường và 2 muỗng canh nước cùng nhau để làm sốt.", "Khi bạn sẵn sàng nấu, đun một chảo chiên lớn hoặc wok cho đến khi rất nóng, sau đó thêm 1 muỗng canh dầu. Chiên tôm cho đến khi chúng vàng ở một số nơi và đã nở ra– rồi đổ chúng ra khỏi chảo.", "Đun phần dầu còn lại và thêm đậu phộng, ớt và củ năng. Xào trong 2 phút hoặc cho đến khi đậu phộng bắt đầu đổi màu, sau đó thêm gừng và tỏi và chiên thêm 1 phút. Đổ tôm và sốt vào và hầm nhẹ trong 2 phút cho đến khi đặc một chút. Ăn với gạo."]'::jsonb, 4);
