INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9b9846c8-60b3-5a4f-98ff-8874eb1ad551', 'Hoành thánh (Wontons)', 'man'::public.dish_category, '["Trộn thịt heo, tỏi, gừng, nước tương, dầu mè và rau trong tô.", "Rách từng tờ vỏ hoành thánh.", "Đặt một muỗng cà phê đầy nhân vào giữa hoành thánh.", "Chọc nước trên 2 viền của vỏ, bao quanh 0,6 cm từ cạnh.", "Gấp vỏ thành hình tam giác, kín các cạnh.", "Cặt hai đầu dài ngoài cùng cùng nhau.", "Đun dầu đến 230 độ và chiên 4 đến 5 mỗi lần cho đến khi vàng.", "Rổ nước và dùng với sốt."]'::jsonb, 4);
