INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1efcbe1e-8eba-5dd8-b4d6-88ac342b5458', 'Heo sốt chua ngọt (Sweet and Sour Pork)', 'man'::public.dish_category, '["Chuẩn bị", "Đập trứng vào bát. Tách lòng trắng và lòng đỏ.", "Heo sốt chua ngọt", "Cắt nui heo thành sợi.", "Chuẩn bị marinade sử dụng một chút muối, một muỗng cà phê bột, hai muỗng cà phê xì dầu nhạt, và một lòng trắng trứng.", "Ướt heo sợi trong khoảng 20 phút.", "Đặt bột còn lại vào bát. Thêm một ít nước và giấm để làm sốt bột.", "Heo sốt chua ngọt", "Hướng dẫn nấu", "Đổ dầu nấu vào chảo xào và đun lên 190°C. Thêm mảnh heo đã ướt và chiên cho đến khi chúng vàng. Lấy heo đã nấu ra khỏi chảo xào và đặt trên đĩa.", "Để ít dầu trong chảo xào. Đổ sốt cà chua và đường trắng vào chảo xào, và đun cho đến khi dầu và sốt kết hợp hoàn toàn.", "Thêm một ít nước vào chảo xào và đun nóng sốt chua ngọt hoàn toàn trước khi thêm mảnh heo vào.", "Đổ sốt bột vào. Xào tất cả các thành phần cho đến khi heo và sốt được trộn kĩ.", "Phục vụ trên đĩa và thêm ngô rí để trang trí."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1efcbe1e-8eba-5dd8-b4d6-88ac342b5458', '72e52172-48ee-5eb7-b8cf-8d615540e7f1', 200.0, 'g'::public.quantity_unit);
