INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('28030d7b-0072-5050-8450-aba5038aabec', 'Bò xào kiểu Tứ Xuyên (Szechuan Beef)', 'man'::public.dish_category, '["BƯỚC 1 - ƯỚT BÒ", "Trong bát, thêm bò, muối, dầu mè, tiêu trắng, lòng trắng trứng, 2 muỗng canh bột ngô và 1 muỗng canh dầu.", "BƯỚC 2 - XÀO", "Đầu tiên nấu bò bằng cách thêm 2 muỗng canh dầu cho đến khi bò vàng.", "Đặt bò riêng", "Trong chảo xào thêm 1 muỗng canh dầu, gừng băm, tỏi băm và xào trong vài giây.", "Tiếp theo thêm tất cả các rau và sau đó thêm rượu nấu sherry và 240 ml nước.", "Để làm sốt thêm sốt hào, sốt ớt cay, và đường.", "thêm bò đã nấu và 1 muỗng canh xì dầu", "Để đặc sốt, đánh trộn 1 muỗng canh bột ngô và 2 muỗng canh nước trong bát và thêm chậm vào xào cho đến khi đủ đặc."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('28030d7b-0072-5050-8450-aba5038aabec', 'fda67982-c921-54e6-9568-e2184abae4d6', 226.8, 'g'::public.quantity_unit);
