INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b43a0903-7ab1-5615-b634-a6a2fa95b72f', 'Mì xào bò', 'man'::public.dish_category, '["BƯỚC 1 - ƯỚP THỊT BÒ", "Trong bát, thêm thịt bò, muối, 1 chút tiêu trắng, 1 muỗng cà phê dầu mè, 1/2 trứng, tinh bột, 1 muỗng canh dầu và khuân cùng.", "BƯỚC 2 - LUỘC MÌ", "Trong nồi lớn thêm mì vào nước sôi cho đến khi mì ngập và nấu trên lửa cao trong 10 giây. Sau khi mì đã nấu xong để thoát nước và làm nguội với nước lạnh.", "BƯỚC 3 - XÀO", "Thêm 2 muỗng canh dầu, thịt bò và nấu trên lửa cao cho đến khi thịt chín trung bình.", "Đặt thịt bò đã nấu một bên", "Trong wok thêm 2 muỗng canh dầu, hành, tỏi đã băm, gừng đã băm, giá đỗ, nấm, đậu lane và 360 ml nước hoặc cho đến khi các ngập trong nước.", "Thêm mì vào wok", "Để làm sốt, thêm dầu hào, 1 chút tiêu trắng, 1 muỗng cà phê dầu mè, đường, và 1 muỗng cà phê nước tương.", "Tiếp theo thêm thịt bò vào wok và xào"]'::jsonb, 4);
