INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('013ccff0-b1ff-5e83-89fd-6fa7e681a2dd', 'Mì phở xào tôm (Shrimp Chow Fun)', 'man'::public.dish_category, '["BƯỚC 1 - NGẤM MÌ", "Ngâm mì phở qua đêm cho đến khi mềm", "BƯỚC 2 - LUỘC MÌ", "Luộc mì trong 10-15 phút rồi vò dưới nước lạnh để dừng quá trình luộc mì.", "BƯỚC 3 - ƯỚT TÔM", "Trong bát thêm tôm, trứng, 1 chút tiêu trắng, 1 muỗng cà phê dầu mè, 1 muỗng canh bột ngô và 1 muỗng canh dầu", "Trộn chung tốt", "BƯỚC 4 - XÀO", "Trong chảo xào thêm 2 muỗng canh dầu, tôm và xào cho đến khi vàng", "Đặt tôm riêng", "Thêm 1 muỗng canh dầu vào chảo xào rồi thêm tỏi băm, gừng và tất cả rau.", "Thêm mì vào chảo xào.", "Tiếp theo thêm rượu nấu sherry, sốt hào, đường, giấm, dầu mè, 1 chút tiêu trắng và xì dầu.", "Thêm tôm trở lại.", "Để đặc sốt, đánh trộn 1 muỗng canh bột ngô và 2 muỗng canh nước trong bát rồi thêm chậm vào xào cho đến khi đủ đặc."]'::jsonb, 4);
