INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('430b3d7f-6598-5998-b85b-e80a258869ff', 'Sup trứng rơi (Egg Drop Soup)', 'canh'::public.dish_category, '["Trong một wok thêm nước dùng gà và đợi cho đến khi nó sôi.", "Tiếp theo thêm muối, đường, tiêu đen hạt/bột, dầu mè thơm nguyên chất.", "Khi nước dùng gà đang sôi thêm các loại rau vào wok.", "Để đặc sốt, đánh cùng nhau 1 muỗng canh bột bắp và 2 muỗng canh nước trong một bát và chậm chạp thêm vào sup của bạn cho đến khi đạt độ đặc đúng.", "Tiếp theo thêm 1 trứng gà đã đánh nhẹ bằng dao hoặc nĩa và thêm nó vào sup chậm và khuấy trong 8 giây", "Phục vụ sup trong một tách và thêm hành lá ở trên."]'::jsonb, 4);
