INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('84846148-dca5-5269-8e3f-9ed925d24e15', 'Cháo gà (Chicken Congee)', 'man'::public.dish_category, '["Bước 1 - Ướp gà", "Trong một bát, cho gà, muối, tiêu đen hạt/bột, nước cốt gừng ngọt và sau đó trộn đều.", "Để gà một bên.", "Bước 2 - Rửa gạo trắng", "Rửa gạo trong một bát kim loại hoặc nồi vài lần và sau đó ráo nước.", "Bước 3 - Nấu gạo trắng", "Tiếp theo thêm 1920 ml nước và sau đó đặt bếp trên lửa cao cho đến khi nước sôi. Khi cháo gạo bắt đầu sôi, đặt bếp trên lửa thấp và khuấy nó một lần mỗi 8-10 phút trong khoảng 20-25 phút.", "Sau 25 phút, điều này tùy chọn nhưng bạn có thể thêm chút nước hơn để làm cháo gạo ít đặc hơn hoặc theo sở thích của bạn.", "Tiếp theo thêm gà đã ướp vào cháo gạo và để bếp trên lửa thấp thêm 10 phút.", "Sau thêm 10 phút thêm hành lá, gừng đã cắt, 1 chút muối, 1 chút tiêu đen hạt/bột và khuấy trong 10 giây.", "Cho cháo gạo vào một bát", "Tùy chọn: thêm ngò rí trên cháo gạo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('84846148-dca5-5269-8e3f-9ed925d24e15', '44a6a37a-69a3-5573-9fd1-730baf90fb5b', 226.8, 'g'::public.quantity_unit);
