INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('97460b59-21df-5c20-925d-5a9544f83790', 'Cá hồi nướng với thì là và cà chua', 'man'::public.dish_category, '["Đun lò đến 180°C. Cắt cành thì là từ thì là và bỏ một bên. Cắt củ thì là nửa, rồi cắt mỗi nửa thành 3 miếng thanh. Luộc trong nước muối sôi 10 phút, rồi để thoát nước tốt. Cắt cành thì là thô, rồi trộn với ngò tây và vỏ chanh vàng nhát.", "Đổ thì đã thoát nước vào nồi ăn lò nhẹ, rồi thêm cà chua. Rưới dầu ô liu lên trên, rồi nướng 10 phút. Đặt cá hồi giữa rau, rắc nước chanh vàng, rồi nướng thêm 15 phút cho đến khi cá vừa chín. Rắc ngò tây lên trên và phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('97460b59-21df-5c20-925d-5a9544f83790', '7c7f1691-bfb1-5da4-bdbb-a53c550674d0', 2.0, 'piece'::public.quantity_unit);
