INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6ea7f1c5-1942-565d-af19-dbf1ddd32e39', 'Salad cá hồi và bơ (Salmon Avocado Salad)', 'man'::public.dish_category, '["Nems cá hồi, rồi thoa dầu. Trộn các thành phần sốt lại. Chia đôi, bóc vỏ và cắt lát bơ quả. Chia đôi và cắt dưa leo dọc rồi cắt lát. Chia salad, bơ và dưa leo vào bốn đĩa, rồi rưới nửa sốt.", "Đun nóng chảo không dính. Cho cá hồi vào và chiên 3-4 phút mỗi mặt cho đến khi giòn nhưng vẫn ẩm bên trong. Đặt một miếng cá hồi lên trên mỗi salad và rưới phần sốt còn lại. Phục vụ khi ấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6ea7f1c5-1942-565d-af19-dbf1ddd32e39', '6bc522ec-3e5d-5d16-a5c3-38f8a2849d83', 400.0, 'g'::public.quantity_unit);
