INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f53cc2fd-d950-5d1f-8760-412816dc611a', 'Trứng nấu sốt cà chua kiểu Ai Cập (Shakshuka)', 'rau'::public.dish_category, '["Đun nóng dầu trong chảo chiên có nắp, rồi làm mềm hành tây, ớt đỏ, tỏi và cuống ngô rí trong 5 phút cho đến khi mềm. Khuấy vào cà chua bi và đường cát mịn, rồi để sốt sôi trong 8-10 phút cho đến khi đặc. Có thể đóng băng trong 1 tháng.", "Dùng lưng thìa lớn, làm 4 hố trong sốt, rồi cho một quả trứng vào mỗi hố. Đậy nắp chảo, rồi nấu trên lửa nhỏ trong 6-8 phút, cho đến khi trứng chín theo sở thích. Rắc lá ngô rí và phục vụ với bánh mì vỏ giòn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f53cc2fd-d950-5d1f-8760-412816dc611a', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 15.0, 'ml'::public.quantity_unit);
