INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('84f15724-87ce-5a8b-be79-bcc6d2cc04db', 'Dê nướng Kenya (Mbuzi Choma)', 'man'::public.dish_category, '["Nướng dê trên lửa vừa 50 phút và nems muối khi lật người.", "Làm Ugali: Đun sôi nước và muối trong nồi đáy dày. Cho bột mì ngô vào chậm rãi, rônica qua ngón tay.", "Hạ lửa trung bình thấp và tiếp tục khuấy thường xuyên, đập các cơn cho đến khi kao kéo ra khỏi cạnh nồi và đặc, khoảng 10 phút.", "Nới bếp và để nguội.", "Đặt ugali vào bát lớn. Ướt tay bằng nước, tròn thành quả rồi dùng.", "Làm Kachumbari: Trộn cà chua, hành tây, ớt xanh và lá ngô rí trong một bát.", "Đặt ra và thưởng thức!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('84f15724-87ce-5a8b-be79-bcc6d2cc04db', '20dae192-f88f-59d3-8aeb-dce61b5ad94f', 1000.0, 'g'::public.quantity_unit);
