INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9b5028bd-536c-50da-bb48-f357fe6c180b', 'Canh cừu kiểu Tunisia (Tunisian Lamb Soup)', 'canh'::public.dish_category, '["Thêm cốt lết sau, 1 nửa hành tây nhỏ, nửa ớt chuông đỏ ngọt, 4 tép tỏi nguyên, lá xanh đậm của tỏi tây và nước dùng bò vào nồi nấu lớn. Nấu 45-60 phút cho đến khi thịt mềm dùng nĩa đâm được. Lưu ý: thịt có thể mất nhiều thời gian hơn để mềm dùng nĩa đâm được; điều đó ổn, chỉ cần thêm thời gian nấu nếu cần.", "Khi thịt mềm, lấy các mảnh lớn rau và xương ra. Loại bỏ.", "Thêm hành tây cắt nhỏ, 2 tỏi băm, ớt chuông ngọt nhỏ, tỏi tây cắt lát (phần xanh nhạt), hành lá, dưa cassaba và bắp ngọt; Trộn và hầm sôi nhẹ đậy nắp trên lửa vừa 5-8 phút cho đến khi dưa cassaba bắt đầu mềm. Lưu ý: dưa cassaba có thể mất nhiều thời gian hơn để bắt đầu mềm; điều đó ổn, chỉ cần thêm thời gian nấu nếu cần.", "Thêm yautia, khoai mỡ trắng và bí đỏ hồ lô vào. Trộn để trộn chung. Hầm sôi nhẹ đậy nắp trên lửa vừa 5 – 6 phút cho đến khi tất cả các loại củ raí đều mềm. Lưu ý: Đừng nấu quá nhiều, hoặc chúng sẽ vụn.", "Nếm và thêm muối theo khẩu vị, nếu cần. Thêm ngô rí và 2 tép tỏi băm còn lại. Trộn và để hầm sôi nhẹ thêm 2 phút.", "Dùng nóng trong tô canh lớn, chia thịt và rau đều. Thêm chút nước cốt chanh vàng và/hoặc sốt ớt, nếu muốn. Dùng cùng arepa và/hoặc bánh casabe (bánh cassava)."]'::jsonb, 4);
