INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('40ff19c7-25f0-5f89-b22f-7d6b108c391b', 'Súp Leblebi Tunisia (Leblebi Soup)', 'canh'::public.dish_category, '["Đun nóng dầu trong nồi lớn. Cho hành tây, nấu cho đến khi trong.", "Ráo đậu gà đã ngâm, cho vào nồi cùng nước dùng rau củ quả. Đun sôi, hạ lửa và đậy nắp. Hôi 30 phút.", "Trong khi đó, rang khô hạt thì là trong chảo nhỏ không dầu, rồi nghiền trong cối. Thêm tỏi và muối, nghiền thành hồ mịn.", "Thêm hồ và sốt harissa vào nồi súp, hôi cho đến khi đậu gà mềm, khoảng 30 phút.", "Nems muối, tiêu và nước cốt chanh vàng theo khẩu vị và dùng nóng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('40ff19c7-25f0-5f89-b22f-7d6b108c391b', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 30.0, 'ml'::public.quantity_unit);
