INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('824bb006-e4ad-593d-850f-cde05e78f2f2', 'Cừu sốt Hà Lan Tunisia (Keleya Zaara)', 'man'::public.dish_category, '["Đun dầu thực vật trong chảo chiên lớn trên lửa cao vừa. Thêm cừu và nấu cho đến khi vàng khắp mặt, khoảng 5 phút. Nêm với nghệ, muối và tiêu theo khẩu vị; khuấy tất cả ngoại trừ 4 muỗng canh hành tây vào, và rót nước vào. Đun sôi, rồi đậy nắp, giảm lửa xuống thấp vừa, và hầm nhẹ cho đến khi cừu mềm, khoảng 15 phút.", "Mở nắp chảo, khuấy bơ vào và để sốt giảm trong 5 đến 10 phút cho đến khi đạt độ đặc mong muốn. Nêm muối và tiêu theo khẩu vị, rồi rót vào đĩa ăn. Rắc hành tây đã băm và ngô tay còn lại lên trên. Rắc lát chanh lên trên để ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('824bb006-e4ad-593d-850f-cde05e78f2f2', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 60.0, 'ml'::public.quantity_unit);
