INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fbde62cf-8554-5061-8aee-5b29ea4e89db', 'Brik cá ngừ và trứng', 'man'::public.dish_category, '["Đun nóng 2 muỗng cà phê dầu trong nồi lớn và nấu hành lá trên lửa nhỏ 3 phút hoặc cho đến khi bắt đầu mềm. Thêm cải bó xôi, đậy nắp kín và nấu thêm 2-3 phút cho đến khi mềm và úa, khuấy một hoặc hai lần. Cho hỗn hợp vào lọ ráo hoặc xáo ráo và để ráo và nguội.", "Dùng đĩa nhỏ làm hướng dẫn, cắt 24 vòng tròn khoảng 12,5 cm đường kính từ bột filo, cắt 6 vòng từ mỗi tờ. Xếp các vòng filo vào một đống, rồi phủ bằng ni-lông thực phẩm để ngăn khô.", "Khi hỗn hợp cải bó xôi đã nguội, vớ lấy càng nhiều chất dư thừa có thể, rồi chuyển vào tô. Thêm cá ngừ, trứng, sốt ớt cay, muối và tiêu theo khẩu vị. Trộn đều.", "Đun lò 200°C. Lấy một vòng filo và chọc nhẹ ít dầu còn lại. Đặt một vòng thứ hai lên trên và chọc ít dầu, rồi đặt một vòng thứ ba lên trên và chọc dầu.", "Đặt một muỗng canh đầy nhân vào giữa vòng, rồi gấp bột thành hình nửa trăng. Gấp các viền, xoắn chúng để kín, và đặt lên khay nướng không dính. Làm lại với phần bột và nhân còn lại để làm 8 brik tổng cộng.", "Chọc nhẹ brik với dầu còn lại. Nướng 12-15 phút hoặc cho đến khi bột giòn và vàng nâu.", "Cùng lúc, trộn cà chua và dưa leo vào tô và rắc nước cốt chanh vàng và nêm nếm theo khẩu vị. Dùng brik nóng cùng salad này và mứt mơ."]'::jsonb, 4);
