INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('15f72cc3-cda6-547e-a606-2b31f8f7cbf7', 'Sup lente Turkey Corba (Corba)', 'rau'::public.dish_category, '["Lọc qua đậu lăng cho bất kỳ mảnh lạ nào, rửa chúng 2 hoặc 3 lần, ráo nước, và đặt một bên. Cảnh báo trước, điều này sẽ có thể biến đậu lăng của bạn thành một khối cứng mà bạn sẽ phải gãy sau này", "Trong nồi lớn trên lửa cao vừa, xào dầu ô liu và hành tây với một chút muối biển trong khoảng 3 phút, sau đó thêm cà rốt và nấu thêm 3 phút.", "Thêm cà chua xay nhuyễn và khuấy nó xung quanh trong khoảng 1 phút. Bây giờ thêm thì là Cumin, bột ớt ngọt Paprika, bạc hà, xạ hương, tiêu đen, và vụn ớt chuông đỏ càng nhanh càng có và khuấy trong 10 giây để nướng gia vị. Chúc mừng bản thân về cách nhà bạn thơm ngon bây giờ.", "Ngay lập tức thêm đậu lăng, nước lọc, nước dùng, và muối biển. Đưa sup lên sôi nhẹ.", "Sau khi nó đã sôi, giảm lửa xuống trung bình thấp, đậy nắp nồi nửa đường, và nấu trong 15-20 phút hoặc cho đến khi đậu lăng đã nát nát và cà rốt đã chín hoàn toàn.", "Sau khi sup đã nấu và đậu lăng mềm, xay sup trong máy xén hoặc đơn giản dùng máy xán tay để đạt độ đặc bạn muốn. Nếm nêm và thêm muối nếu cần.", "Phục vụ với bánh mì ng了起来, bánh mì rách, hoặc thứ gì đó để thêm đặc thêm. Bạn cũng có thể dùng đặc truyền thống (như bột bắp hoặc bột mì), nhưng tôi thích thêm bánh mì cho một chút độ dai và mặn. Làm rất nhiều phần còn lại, lưu được trong tủ lạnh trong khoảng một tuần."]'::jsonb, 4);
