INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9ca311c9-6294-5d5e-bfe8-76869ec24b0a', 'Khoai tay nướng Thổ Nhĩ Kỳ (Kumpir)', 'rau'::public.dish_category, '["Nếu bạn đặt kumpir ở Thổ Nhĩ Kỳ, nhân chuẩn là trước tiên, rất nhiều bơ nghiền vào khoai tây, tiếp theo là phô mai. Sau đó là một hàng các loại topping khác mà bạn chỉ cần chỉ vào theo ý thích – ngô ngọt, ô liu, xúc xích Salami, salad cà chua, salad Nga, v.v. – và bạn đi về với một khoai tây bị nhồi quá nhiều vì bạn quá hứng thú bởi các lựa chọn được cung cấp.", "Xay (không cần chuẩn xác – bạn có thể dùng bao nhiêu cũng được) 150g phô mai.", "Băm nhịn một củ hành tây và một ớt chuông đỏ ngọt.", "Đặt các nguyên liệu này vào một bát lớn với một lượng muối và tiêu đẹp, mảnh ớt khô (tùy chọn)."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9ca311c9-6294-5d5e-bfe8-76869ec24b0a', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 2.0, 'piece'::public.quantity_unit);
