INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('058362d9-59f9-5323-b664-587c9d1d736b', 'Bitterballen (Měl蘭)', 'man'::public.dish_category, '["Nung bơ trong chảo hoặc nồi. Khi đã nung chảy, thêm bột mì dần dần và khuân thành hỗn hợp đặc. Rồi khuân chậm nước dùng vào, đảm bảo hỗn hợp bột bơ hấp thụ chất lỏng. Hầm nhẹ trong vài phút trên lửa nhỏ trong khi bạn khuân hành, ngô tây và thịt bò xé vào. Hỗn hợp nên đặc và trở thành sốt đặc nặng.", "Đổ hỗn hợp vào bình浅, đậy nắp và để trong tủ lạnh trong vài giờ, hoặc cho đến khi sốt đã đông lại.", "Lấy một thìa lớn hỗn hợp đặc lạnh và nhanh chóng cuộn thành một viên nhỏ. Lăn nhẹ qua bột mì, rồi trứng và cuối cùng bột chiên xù. Đảm bảo trứng phủ toàn bộ bề mặt. Khi xong, để các món ăn trong tủ lạnh trong khi dầu trong nồi chiên nóng lên đến 190°C. Chiên bốn bitterballen cùng lúc cho đến khi vàng.", "Phục vụ trên đĩa với sốt mù tạt hạt hoặc cay."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('058362d9-59f9-5323-b664-587c9d1d736b', '5b335556-d749-5751-acbe-0db2ff3196c9', 100.0, 'g'::public.quantity_unit);
