INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('bb2ed664-5920-5af1-8e0b-03302d7a37fa', 'Stamppot khoai tây và rau (Stamppot)', 'man'::public.dish_category, '["Rửa và bóc khoai tây và cắt thành các mảnh tương tự để nấu đều.", "Trong nồi sup lớn, luộc khoai tây và lá nguyệt quế trong nước muối trong 20 phút. Bỏ lá nguyệt quế.", "Nếu bạn không dùng túi cải xoăn đã cắt sẵn, rửa các bó thật kỹ dưới nước lạnh chảy để loại bỏ hết đất—bạn không muốn cảm giác cát trong món hoàn thành của bạn. Cắt tỉa cuống thô và vứt lá vàng. Với dao sắc, cắt cải xoăn thành sợi mỏng.", "Bóc và cắt hành tím.", "Trong chảo xào hoặc chảo chiên, khan 1 muỗng canh bơ và xào hành tím trong vài phút trước khi thêm cải xoăn và 2 muỗng canh nước. Nems và nấu trong khoảng 10 phút, hoặc cho đến khi mềm.", "Đun nóng sữa trên bếp hoặc trong lò vi sóng.", "Rarget, lắc và làm khô khoai tây bằng khăn giấy trước khi nghiền bằng cụ nghiền hoặc máy nghiền. Làm việc nhanh, thêm sữa ấm và bơ còn lại. Nems nếm với hạt 육두구, muối, và tiêu.", "Trộn cải xoăn đã nấu qua khoai tây nghiền đã nấu.", "Đặt lát xúc xích khói lên trên và phục vụ nóng với mù tạt hoặc sốt bạn thích.", "Phục vụ và tận dụng!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bb2ed664-5920-5af1-8e0b-03302d7a37fa', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1500.0, 'g'::public.quantity_unit);
