INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4c0cc200-cda8-5709-a248-1679d1f28560', 'Sup đậu Hà Lan kiểu Hà Lan (Snert)', 'canh'::public.dish_category, '["Thu thập nguyên liệu.", "Trong nồi sup lớn, đun nước, đậu Hà Lan, bụng heo hoặc thịt xông khói, côtele heo, và viên nồng rau củ quả cho sôi. Giảm lửa về sôi nhẹ, nắp và để nấu trong 45 phút, khuấy đôi khi và vớt bọt nổi lên trên.", "Lấy côtele heo ra, cốt xương, và cắt mỏng thịt. Để riêng.", "Thêm là cầu, cà rốt, khoai tây, hành tây, là cầu tây và củ là cầu vào sup. Trả cho sôi, giảm lửa về sôi nhẹ và để nấu, không nắp, thêm 30 phút, thêm một ít nước nếu nguyên liệu bắt đầu dính đáy nồi.", "Thêm xúc xích khói trong 15 phút cuối thời gian nấu. Khi rau mềm, lấy thịt xông khói và xúc xích ra, cắt mỏng và để riêng.", "Nếu bạn thích kết cấu mịn, xay nhuyễn sup bằng máy xay cầm tay. Nems nếm lại với muối và tiêu. Thêm thịt trở lại vào sup, để lại một số lát xúc xích khói một bên.", "Phục vụ trong tô nóng hoặc đĩa sup, trang trí bằng lát xúc xích khói và lá là cầu cắt nhỏ.", "Thưởng thức!"]'::jsonb, 4);
