INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('53c3d133-b502-5ead-86af-00c4331ad307', '5b335556-d749-5751-acbe-0db2ff3196c9', 30.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0602afce-3a3f-5ee6-9405-b173cbfe9922', 'Gà sốt mật ong Balsamic với súp lơ giòn và khoai (Honey Balsamic Chicken with Crispy Broccoli & Potatoes)', 'man'::public.dish_category, '["1. 2 phần", "2. Đun lò đến 220°C. Rửa và khô tất cả nguyên liệu. Cắt khoai tây thành lát dày 1 cm. Trộn trên một bên của khay nướng với một chút dầu, muối, và tiêu. (Cho 4 phần, trải khoai tây ra toàn bộ khay.) Nướng trên kệ trên cùng trong 5 phút (chúng ta sẽ thêm súp lơ thì).", "3. Trong lúc đó, cắt bông súp lơ thành miếng vừa ăn, nếu cần. Bóc và băm nhỏ tỏi. Trong một bát nhỏ an toàn với lò vi sóng, trộn 1 muỗng canh dầu ô liu (2 muỗng canh cho 4 phần) và nửa tỏi. Đun trong lò vi sóng cho đến khi tỏi xì xì, 30 giây.", "4. Khi khoai tây đã nướng 5 phút, lấy khay khỏi lò và thêm súp lơ vào bên trống; khuấy nhẹ với dầu tỏi, muối, và tiêu. (Cho 4 phần, thêm súp lơ vào khay thứ hai.) Tiếp tục nướng cho đến khi khoai tây và súp lơ vàng và giòn, 15-20 phút nữa.", "5. Trong khi rau nướng, thấm khô gà bằng giấy bếp; nêm muối và tiêu khắp nơi. Đun một chút dầu trong chảo lớn trên lửa cao vừa. Thêm gà và nấu cho đến khi vàng và chín kỹ, 5-6 phút mỗi bên. (Nếu gà vàng quá nhanh, giảm lửa xuống vừa.) Tắt lửa; đặt gà một bên để nghỉ. Rửa sạch chảo.", "6. Đun chảo đã dùng cho gà trên lửa cao vừa. Thêm một chút dầu và tỏi còn lại; nấu cho đến khi thơm, 30 giây. Khuấy giấm, mật ong, nước dùng nồng, và 60 ml nước (80 ml cho 4 phần). Sôi nhẹ cho đến khi đặc và bóng, 2-3 phút. Bớt khỏi lửa và khuấy 1 muỗng canh bơ (2 muỗng canh cho 4). Nêm muối và tiêu.", "7. Trả gà vào chảo và lật để bọc trong men ghi. Chia gà, súp lơ, và khoai tây giữa các đĩa. Đổ phần men ghi còn lại lên gà và ăn."]'::jsonb, 4);
