INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('0602afce-3a3f-5ee6-9405-b173cbfe9922', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 15.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c0c7041d-c1ea-5ebf-a858-3535cde98fcb', 'Sườn heo nướng táo và khoai lang nướng, bí ngòi (Skillet Apple Pork Chops with Roasted Sweet Potatoes & Zucchini)', 'man'::public.dish_category, '["Dùng cho 2 người", "Điều chỉnh kệ lò ở vị trí trên và giữa và đun lò lên 230°C. Rửa và khô khô hết nông sản. Cắt khoai lang thành miếng 1,25 cm. Đậy trên khay nướng với chút dầu, muối và tiêu. Nướng trên kệ trên trong 12 phút (chúng ta sẽ nướng bí ngòi sau).", "Trong lúc đó, chia đôi và lột táo; cắt mỏng thành miếng nửa trăng. Bóc và băm mịn tỏi. Chia chanh thành tư. Cắt tỉa và chia đôi bí ngòi dọc; cắt ngang thành miếng nửa trăng dày 1,25 cm. Đậy trên khay thứ hai với chút dầu và chút muối và tiêu. Để riêng.", "Thấm khô heo bằng khăn giấy và nems muối và tiêu xung quanh. Đun chút dầu trong chảo lớn trên lửa vừa-cao. Thêm heo và nấu cho đến khi vàng và chín đều, 4-5 phút mỗi mặt. Tắt bếp; chuyển sang đĩa.", "Khi khoai lang đã nướng 12 phút, chuyển khay có bí ngòi sang kệ giữa và tiếp tục nướng cho đến khi cả hai rau đều vàng và mềm, 12-15 phút nữa.", "Trong lúc đó, nhorn 1 muỗng canh bơ (2 muỗng canh cho 4 người) trong chảo đã nấu heo trên lửa vừa-cao. Thêm táo và nems muối và tiêu. Nấu, kẹp các mảnh cháy đáy chảo, cho đến khi táo hơi mềm, 2-3 phút. Thêm tỏi; nấu cho đến khi thơm, 30 giây. Thêm 80 ml nước (180 ml cho 4), nước dùng đặc, và 1,5 muỗng cà phê đường (3 muỗng cà phê cho 4). Nấu, khuấy, cho đến khi sốt đặc và táo rất mềm, 3-5 phút. Nems muối và tiêu.", "Lấy chảo có táo khỏi bếp; khuấy vào 1 muỗng canh bơ (2 muỗng canh cho 4) và một chút nước cốt chanh. Chia heo, bí ngòi và khoai lang vào các đĩa. Đặt sốt táo lên heo. Đặt chút nước cốt chanh lên bí ngòi."]'::jsonb, 4);
