INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c0f555ec-381a-5f45-9dd2-9bd8e0e750a1', 'Bò muối và bắp cải (Corned Beef and Cabbage)', 'man'::public.dish_category, '["Đặt gầu bò vào nồi lớn hoặc nồi Holland và ngập nước lọc. Thêm túi gia vị đi kèm với gầu bò. Đậy nắp nồi và đun sôi, sau đó giảm xuống hầm nhẹ. Hầm khoảng 50 phút mỗi 450 g hoặc cho đến khi mềm.", "Thêm khoai tây bi nhỏ nguyên và cà rốt đã gọt và cắt, và nấu cho đến khi rau gần mềm. Thêm bắp cải và nấu thêm 15 phút. Lấy thịt ra và để nghỉ 15 phút.", "Đặt rau vào bát và đậy nắp. Thêm đủ nước dùng (nước nấu đã để lại trong nồi Holland hoặc nồi lớn) theo ý muốn. Cắt thịt ngang sợi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c0f555ec-381a-5f45-9dd2-9bd8e0e750a1', 'c9a85c2e-12a8-501d-8172-b731d9ed81b6', 1360.8, 'g'::public.quantity_unit);
