INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c0f555ec-381a-5f45-9dd2-9bd8e0e750a1', 'aa6aa92a-7305-56f9-a580-8185600358a5', 1.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1cda0b11-cad2-5395-8715-63940e2b9bef', 'Xúc xích chiên giòn và rau xanh (Crispy Sausages and Greens)', 'man'::public.dish_category, '["Đun lò trước đến 175°C. Bỏ cuống từ một bó cải xoăn Kale và rách lá thành các miếng 2,5cm. Kẹo nửa một cuộn bắp cải. Kết hợp các loại rau trong một đĩa nướng lớn và thêm 4 tép tỏi đã cắt mỏng. Thêm một số lát hành tây và nấm đông cô vào đây là tùy chọn, nhưng được khuyên dùng (Tôi sẽ xào hành tây và nấm trong một cái chảo nướng sắt đúc ngay trên bếp trước khi thêm vào các loại rau). Đầu các loại rau với một số dầu ô liu và đổ 120 ml nước dùng gà hoặc nước dùng vào tất cả. Đậy món ăn bằng giấy bạc và nấu cho đến khi các loại rau héo, khoảng 15 phút. Lấy giấy bạc ra và nems với muối và tiêu đen hạt/bột. Tiếp tục nấu cho đến khi bắp cải mềm, khoảng 20-25 phút hơn.", "Cùng lúc đó, đun nóng một ít dầu ô liu trong chảo lớn trên lửa cao vừa. Chọc bốn xúc xích Ý hạt tiểu hồi bằng nĩa và chiên cho đến khi vàng hết các mặt và chín qua, 10 đến 12 phút. Khi các loại rau đã xong, cắt xúc xích và nhúng vào các loại rau với một chút giấm yêu thích của bạn (Tôi thích giấm sherry hoặc rượu vang đỏ)."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1cda0b11-cad2-5395-8715-63940e2b9bef', 'a2caae43-f9d4-51e4-8790-7985f6fc2726', 1.0, 'piece'::public.quantity_unit);
