INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('45c71597-7f7c-588d-a1a7-d9496eb27d10', 'Moussaka Hy Lạp (Moussaka)', 'man'::public.dish_category, '["Núi grill cao. Chiên thịt bò vàng trong chảo chịu nhiệt lò sâu trên lửa lớn 5 phút. Trong lúc đó, chọc ảnh bằng nĩa, rồi hâm lò vi sóng cao 3-5 phút cho đến khi mềm. Trộn sữa chua Hy Lạp, trứng và phô mai Parmesan cùng nhau, rồi thêm ít nems nếm.", "Khuấy cà chua, cà chua xay nhuyễn và khoai tây cùng với thịt bò và ít nems nếm, rồi đun nóng. Lấp bề mặt hỗn hợp thịt bằng phần lưng muỗng, rồi lát ảnh đã nấu và xếp lên trên. Đổ hỗn hợp sữa chua lên ảnh, trải đều, rồi nướng cho đến khi phần phủ凝 và vàng."]'::jsonb, 4);
