INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d4365670-a34c-5a01-bd39-c84b1f8d8cfc', 'Cà chua nhồi thịt cừu kiểu Hy Lạp (Stuffed Lamb Tomatoes)', 'man'::public.dish_category, '["Đun lò lên 180°C. Cắt miếng trên cà chua và giữ lại. Lấy phần ruột đa phần bằng thìa nhỏ, cẩn thận không vỡ vỏ. Cắt nhiete ruột, và giữ bất kỳ nước cốt nào. Rắc bên trong cà chua với chút đường để loại bỏ chua, rồi đặt chúng trên khay nướng.", "Đun nóng 2 muỗng canh dầu ô liu trong chảo xào lớn, thêm hành tây và tỏi, rồi nấu nhẹ trong khoảng 10 phút cho đến khi mềm nhưng không đổi màu. Thêm cừu, quế và nét cà chua, tăng nhiệt độ, rồi chiên cho đến khi thịt vàng. Thêm ruột cà chua và nước cốt, gạo và nước dùng. Nems thật. Đun sôi, rồi ninh trong 15 phút hoặc cho đến khi gạo mềm và nước cốt đã bị hấp thụ. Để nguội một chút, rồi khuấy vào thì là, ngô tây và bạc hà.", "Nhồi cà chua đầy đến cái miệng, đặt nắp cà chua lên trên, rưới 2 muỗng canh dầu ô liu thêm, rắc 3 muỗng canh nước vào khay, rồi nướng trong 35 phút. Phục vụ với salad và bánh mì vỏ giòn, nóng hoặc lạnh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d4365670-a34c-5a01-bd39-c84b1f8d8cfc', 'de974e5e-edf0-5b8f-a7dc-f105cb93acdb', 4.0, 'piece'::public.quantity_unit);
