INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c90330be-f632-5aed-979a-cbcffa497ba4', 'Cừu nướng xích chanh Hy Lạp (Lamb and Lemon Souvlaki)', 'man'::public.dish_category, '["Nát tỏi với muối biển trong cối và xắc (hoặc dùng một máy xay nhỏ), cho đến khi tỏi tạo thành một hỗn hợp đặc. Đánh trộn dầu, nước cốt chanh, vỏ chanh, thì là và tỏi. Trộn cừu vào và kết hợp tốt. Đậy nắp và ướp ít nhất 2 tiếng hoặc qua đêm trong tủ lạnh. Nếu bạn sẽ dùng thìa tre, ngâm chúng trong nước lạnh.", "Nếu bạn đã chuẩn bị cừu hôm trước, hãy lấy nó ra khỏi tủ lạnh 30 phút trước khi nấu. Xích thịt lên các thìa đã ngâm hoặc kim loại. Đun nắp nướng cao hoặc có một chảo nướng nóng hoặc nướng than sẵn sàng. Nấu các thìa trong 2-3 phút mỗi bên, rưới với hỗn hợp ướp còn lại. Đun bánh mì pita hoặc bánh mì mỏng ngắn, rồi nhồi với souvlaki. Thêm salad Hy Lạp (xem ''Đi kèm tốt với'', bên phải) và Tzatziki (dưới đây), nếu bạn thích."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c90330be-f632-5aed-979a-cbcffa497ba4', 'a8db4b95-a126-5f43-a0b4-2c29ba37261d', 2.0, 'piece'::public.quantity_unit);
