INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a934f17f-08a3-5200-8717-7d3e3c6c0d2f', 'Burger cừu sốt Tzatziki (Lamb Tzatziki Burgers)', 'man'::public.dish_category, '["Cho lúa mì Bulgur vào nồi, ngập nước, đun sôi 10 phút. Ráo thật khô trong cái lưới, ép lấy nước thừa.", "Làm tzatziki: ép bỏ nước của dưa leo, rồi trộn vào sữa chua Hy Lạp cùng lá bạc hà đã băm và ít muối.", "Trộn lúa mì Bulgur với thịt cừu xay, gia vị, tỏi (nếu dùng) và nems nếm, rồi định hình thành 4 bánh burger. Sơn chút dầu, chiên hoặc nướng nửa chừng 5 phút mỗi mặt cho đến khi chín đều. Đặt trong bánh mì tròn (nướng nếu thích) kèm tzatziki, cà chua, hành tây và vài lá bạc hà."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a934f17f-08a3-5200-8717-7d3e3c6c0d2f', '3ead45f5-0e10-5692-9c20-74ffa09b625f', 25.0, 'g'::public.quantity_unit);
