INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7c78a687-cc85-5251-86b6-0fcd0c5ed9cb', 'Salad quinoa gà kiểu Hy Lạp (Chicken Quinoa Greek Salad)', 'man'::public.dish_category, '["Nấu quinoa theo hướng dẫn trên bao, sau đó rửa trong nước lạnh và ráo kỹ.", "Cùng lúc đó, trộn bơ, ớt đỏ và tỏi thành một hỗn hợp dán. Nhúng ngực gà vào 2 thìa cà phê dầu ô liu với một chút nêm. Đặt vào chảo nướng nóng và nấu 3-4 phút mỗi mặt hoặc cho đến khi chín qua. Chuyển ra đĩa, chấm với bơ cay và đặt một bên để nung.", "Tiếp theo, cho cà chua, quả ô liu đen, hành tím tây, phô mai Feta và bạc hà vào bát. Nhúng quinoa đã nấu vào. Khuấy phần dầu ô liu còn lại, nước cốt chanh vàng và vỏ chanh, và nêm tốt. Ăn với ngực gà ở trên, rưới thêm bất kỳ nước chảy bơ gà nào."]'::jsonb, 4);
