INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1d5390db-9810-5543-a4cf-2c156d2f34e6', 'Đậu ngự Lima nho Hy Lạp (Gigantes Plaki)', 'rau'::public.dish_category, '["Ngâm đậu qua đêm trong nhiều nước. Đổ nước, rửa, rồi đặt vào chảo ngâm nước. Đun sôi, giảm lửa, rồi sôi nhẹ khoảng 50 phút cho đến khi hơi mềm nhưng chưa nhừ. Đổ nước, rồi để một bên.", "Đun lò đến 180°C. Đun dầu ô liu trong chảo chiên lớn, đổ hành tây và tỏi, rồi nấu trên lửa vừa trong 10 phút cho đến khi mềm nhưng không vàng. Thêm cà chua xay nhuyễn, nấu thêm 1 phút, thêm các nguyên liệu còn lại, rồi sôi nhẹ trong 2-3 phút. Nêm nếm đậm đà, rồi khuấy đậu vào. Đổ vào đĩa chịu nhiệt lớn, rồi nướng khoảng 1 tiếng, không đậy nắp và không khuấy, cho đến khi đậu mềm. Đậu sẽ hấp thụ tất cả hương vị tuyệt vời và sốt sẽ đặc. Để nguội, rồi rắc ngô tây và rưới thêm một chút dầu ô liu để ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1d5390db-9810-5543-a4cf-2c156d2f34e6', '5cbe854f-8c79-5190-811b-64f865e0973c', 400.0, 'g'::public.quantity_unit);
