INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('80bef4a0-6484-5472-b1b0-656cc47521b9', 'Big Mac', 'man'::public.dish_category, '["Để làm sốt Big Mac, trộn tất cả các nguyên liệu trong bát, nems muối và để trong tủ lạnh cho đến khi dùng.", "2. Để làm bánh thịt, nems thịt băm với muối và tiêu và định hình thành 4 viên bằng khoảng 1/3 chén thịt mỗi viên. Đặt mỗi viên trên một miếng giấy bếp và ép nhẹ thành bốn vòng 15cm. Đun dầu trong chảo chiên lớn trên lửa cao. Trong 2 đợt, nấu bánh thịt bò 1-2 phút mỗi mặt cho đến khi hơi cháy và chín qua. Lấy ra khỏi bếp và giữ ấm. Làm tương tự với hai viên còn lại.", "3. Cẩn thận cắt từng bánh burger thành ba lớp theo chiều ngang, rồi nướng nhẹ.", "4. Để ghép burger, rưới một ít sốt Big Mac lên lớp dưới. Đặt hành đã cắt nhỏ, xà lách bóp, lát phô mai, bánh thịt bò và vài lát dưa muối lên trên. Đặt lớp bánh burger ở giữa, và rải thêm sốt Big Mac, hành, xà lách, dưa muối, bánh thịt bò rồi rưới thêm sốt. Đặt nắp burger lên để phục vụ.", "5. Đợi nửa giờ cho thức ăn ổn định, rồi đi chạy bộ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('80bef4a0-6484-5472-b1b0-656cc47521b9', '61b6c1bc-2369-5a04-8c51-5a4569d3d0ba', 400.0, 'g'::public.quantity_unit);
