INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5cc55978-43d8-5873-be4e-fcabb8343015', 'Bánh kẹp gà Chick-Fil-A (Chick-Fil-A Sandwich)', 'man'::public.dish_category, '["Bọc thịt gà lỏng giữa nilon bọc thực phẩm và đập nhẹ bằng mặt phẳng của bát thối thịt cho đến khi dày khoảng 1,3 cm xung quanh.", "Cắt thành hai miếng, càng đều càng tốt.", "Ngâm trong nước ngâm dưa chua trong 30 phút đến một giờ (thêm một muỗng cà phê sốt Tabasco bây giờ cho một bánh kẹp cay).", "Đánh trứng gà với sữa tươi trong một bát.", "Trộn bột mì, đường bột và gia vị trong một bát khác.", "Nhúng từng miếng thịt gà vào trứng trên cả hai mặt, rồi bóp bột mì trên cả hai mặt.", "Đun nóng dầu ô liu trong chảo chiên (sâu khoảng 1,3 cm) đến khoảng 175°C.", "Chiên mỗi miếng thịt trong 2 phút trên mỗi mặt, hoặc cho đến khi vàng và chín đều.", "Đặt trên giấy để thấm dầu và ăn trên bánh kẹp nướng với miếng dưa chua."]'::jsonb, 4);
