INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('74a741ff-f42f-56ae-8746-9f4efb6ba165', 'Bánh ngọt Paszteciki Ba Lan', 'man'::public.dish_category, '["C đường bột mì và muối vào bát trộn lớn.", "Dùng muỗng để đẩy lòng đỏ trứng qua lưới mịn vào bột mì.", "Thêm trứng生 và trộn tốt.", "Đánh bơ vào từng muỗng canh.", "Đặt bột trên bề mặt rắc bột và nhéen cho đến khi mịn và dẻo, rồi gói giấy sáp và để trong tủ lạnh cho đến khi chắc (ít nhất 30 phút).", "Trong chảo nặng, tan 2 muỗng canh bơ trên lửa vừa; xào hành tây và củ cải Thụy Điển cho đến khi hành mềm và trong (5 phút).", "Cho hành tây, củ cải Thụy Điển, và thịt bò qua máy xay thịt hai lần nếu có, nếu không chỉ cắt nhỏ càng tốt có thể.", "Tan phần 4 muỗng canh bơ còn lại trên lửa vừa, và thêm hỗn hợp thịt.", "Nấu trên lửa nhỏ, khuấy thỉnh thoảng, cho đến khi toàn bộ nước đã bay hơi và hỗn hợp đặc đủ để giữ hình dạng.", "Nới bếp và để nguội, rồi khuấy 1 quả trứng vào, và nems muối và tiêu.", "Đầy lò 175°C.", "Trên bề mặt rắc ít bột, luồn bột thành hình chữ nhật 33 x 20 cm (dày 0,3 cm).", "Đổ nhân vào giữa hình chữ nhật theo chiều dọc, để khoảng 2,5 cm khoảng trống ở mỗi đầu.", "Sơn nhẹ các cạnh dài bằng nước lạnh, rồi gấp một trong các cạnh dài lên trên nhân và bên kia lên trên của nó.", "S các đầu ngắn bằng nước lạnh và gấp chúng lên trên, bọc nhân.", "Đặt vở bánh hướng khuyết xuống trên khay nướng và sơn bề mặt đều bằng trứng đánh tan còn lại.", "Nướng trong lò đã đậy cho đến khi vàng nâu đậm (30 phút).", "Cắt vở bánh theo chéo thành các miếng dài 4 cm và dùng như món khai vị hoặc với súp."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('74a741ff-f42f-56ae-8746-9f4efb6ba165', '6511004e-c078-51d9-90e7-492186b8e9c1', 240.0, 'ml'::public.quantity_unit);
