INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9af47df6-d5c5-5f12-9840-f32a036c2c35', 'Bigos (cháo săn)', 'man'::public.dish_category, '["Đun lò đến 175°C.", "Đun nồi lớn trên lửa trung bình. Thêm xúc xích khói và kielbasa; nấu khuân cho đến khi xúc xích khói đã tan mỡ và kielbasa hơi vàng. Dùng thìa rỗng, lấy thịt ra và chuyển vào nồi hầm lớn hoặc nồi đúc.", "Lăn các khối thịt heo nhẹ trong bột mì và chiên chúng trong mỡ xúc xích khói trên lửa trung bình cao cho đến khi vàng. Dùng thìa rỗng, chuyển thịt heo vào nồi hầm. Thêm tỏi, hành tây, cà rốt, nấm tươi, lá cải và chua dền. Giảm lửa xuống trung bình; nấu khuân cho đến khi cà rốt mềm, khoảng 10 phút. Để không để rau vàng.", "Đég nồi bằng cách đổ rượu vang đỏ vào và khuân để lỏng các mảnh thức ăn và bột dính đáy nồi. Nems lá nguyệt quế, húng quế tây, kinh giới ô, paprika, muối, tiêu, hạt thì là ba tư và ớt bột cayenne; nấu 1 phút.", "Trộn nấm khô, sốt ớt cay, sốt Worcestershire, nước dùng bò, sốt cà chua đặc và cà chua vào. Đun cho đến khi sôi đót. Đổ rau và tất cả chất lỏng vào nồi hầm với thịt. Đậy nắp.", "Nướng trong lò đã đun trong 2,5 đến 3 giờ, cho đến khi thịt rất mềm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9af47df6-d5c5-5f12-9840-f32a036c2c35', '3f94e8a8-55dc-59c8-9494-12f27b6a5fb9', 2.0, 'piece'::public.quantity_unit);
