INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('15b5983c-8e5d-518c-98ff-e526bf88d8f9', 'Bánh dumpling Pierogi Ba Lan', 'rau'::public.dish_category, '["Chuẩn bị nhân chua cà:põ, tan bơ trong chảo trên lửa vừa. Khuấy hành vào, và nấu cho đến khi trong, khoảng 5 phút. Thêm chua cà:põ đã ráo và nấu thêm 5 phút. Nems theo khẩu vị với muối và tiêu trắng, rồi chuyển sang đĩa để nguội.", "Làm nhân khoai nghiền, tan bơ trong chảo trên lửa vừa. Khuấy hành vào, và nấu cho đến khi trong, khoảng 5 phút. Khuấy vào khoai nghiền, và nems muối và tiêu trắng.", "Làm bột, đánh trứng và kem chua cho đến khi mịn. C đường bột mì, muối, và bột nở cùng nhau; khuấy vào hỗn hợp kem chua cho đến khi bột kết hợp. Nhéen bột trên bề mặt rắc ít bột cho đến khi chắc và mịn. Chia bột thành nửa, rồi luồn một nửa thành độ dày 0,3 cm. Cắt thành hình tròn 7 cm bằng cutter bánh quy.", "Đặt một muỗng nhỏ nhân khoai nghiền vào giữa mỗi hình tròn. Ẩm các cạnh bằng nước, gấp lại, và nhấn bằng nĩa để kín. Làm tương với phần bột còn lại và nhân chua cà:põ.", "Đun sôi nồi lớn nước nhẹ muối. Thêm bánh dumpling và nấu 3 đến 5 phút cho đến khi chúng bơi lên trên. Vớt bằng cuch đón ráo."]'::jsonb, 4);
