INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f1bf76fc-ef4e-5eed-9cce-39d3e95deb67', 'Sup gà kiểu Ba Lan (Rosol)', 'canh'::public.dish_category, '["Cho gà vào nồi lớn hoặc nồi ninh.", "Ngập nước.", "Đun sôi và ninh trong 2 đến 2,5 giờ, vớt bọt trên mặt để đảm bảo nước dùng trong.", "Nếu nồi đủ lớn, cho rau và gia vị vào trong giờ nấu cuối cùng.", "Nồi ninh của tôi không đủ lớn để chứa tất cả, chỉ thịt gà và xương khác đầy nồi, nên tôi nấu thịt/xương trong suốt thời gian nấu, rồi lấy ra, và nấu rau và gia vị riêng lẻ.", "Vớt bỏ tất cả khỏi nước dùng.", "Cốt gà, kéo thịt thành các miếng lớn.", "Cắt cà rốt thành lát.", "Cho gà và cà rốt trở lại nước dùng.", "Nấu mì theo hướng dẫn trên bao bì nếu bạn dùng chúng.", "Cho mì vào bát và sau đó xếp nước dùng nóng lên trên."]'::jsonb, 4);
