INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a2fb58ce-f946-5674-afcb-76864a4ae902', 'Goi cuốn cải Ba Lan (Golabki)', 'man'::public.dish_category, '["Đun một nồi lớn nước có ít muối đến sôi. Đặt trái cải vào nước, đậy nắp nồi, và nấu cho đến khi lá cải hơi mềm đủ để lấy khỏi trái, 3 phút. Lấy cải khỏi nồi và để cải ngả cho đến khi lá đủ mát để bắt tay, khoảng 10 phút.", "Bóc 18 lá nguyên từ trái cải, cắt bỏ bất kỳ xương giữa dày và cứng nào. Đặt các lá nguyên một bên. Băm phần còn lại của trái cải và trải ra đáy đĩa nhồi.", "Cho bơ vào chảo lớn trên lửa cao vừa. Nấu và khuấy hành trong bơ nóng cho đến khi mềm, 5 đến 10 phút. Để nguội.", "Khuấy hành, bò, heo, gạo, tỏi, 1 muỗng cà phê muối, và 1/4 muỗng cà phê tiêu trong bát lớn.", "Đun lò đến 175°C.", "Đặt khoảng 120 ml hỗn hợp bò trên lá cải. Cuộn cải quanh hỗn hợp bò, cuộn vào hai bên để tạo một phong bì quanh thịt. Làm lại với các lá còn lại và hỗn hợp thịt. Đặt các cuộn cải thành một lớp lên trên cải đã băm trong đĩa nhồi; nêm cuộn với muối và tiêu đen.", "Trộn súp cà chua, nước cà chua, và sốt cà chua cùng nhau trong bát. Rỗ hỗn hợp súp cà chua lên cuộn cải và đậy đĩa bằng giấy bạc.", "Nướng trong lò đã đun cho đến khi cải mềm và thịt chín kỹ, khoảng 1 giờ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a2fb58ce-f946-5674-afcb-76864a4ae902', 'aa6aa92a-7305-56f9-a580-8185600358a5', 1.0, 'piece'::public.quantity_unit);
