INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('17a4550a-00f2-5dfe-a5df-c000371fe308', 'Cá trích ngâm dầu kiểu Ba Lan (Sledz w Oleju)', 'man'::public.dish_category, '["Ngâm cá trích trong nước lạnh ít nhất 1 giờ. Nếu rất mặn, lặp lại, thay nước mỗi lần.", "Rarget nước tốt và cắt cá trích thành miếng nhỏ dễ ăn.", "Đặt vào bình lớn đủ chứa các miếng và ngập dầu, hạt tiêu Jamaica, tiêu đen hạt và lá nguyệt quế. Đậy nắp bình.", "Để trong tủ lạnh 2 đến 3 ngày trước khi ăn. Món này giữ được trong tủ lạnh tối đa 2 tuần.", "Phục vụ kèm hành tây cắt nhỏ hoặc lát hành, chanh, và ngô rí hoặc thì là."]'::jsonb, 4);
