INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('488a393a-1ce6-5da1-b1eb-2ab2e56ba3eb', 'Hầm đậu tằm Ai Cập (Ful Medames)', 'rau'::public.dish_category, '["Thời gian nấu thay đổi tùy vào chất lượng và độ tuổi của đậu, vì vậy tốt là nấu trước và hâm nóng khi sẵn sàng ăn. Nấu đậu đã đổ nước trong một phần nước tươi không muối trong nồi lớn với nắp cho đến khi mềm, thêm nước để giữ đậu ngâm, và muối khi đậu đã mềm. Chúng mất 2–2 1/2 tiếng hầm nhẹ. Khi đậu đã mềm, để nước cạn. Thông thường lấy một hoặc hai choch đậu và nghiền với một chút nước nấu, rồi khuấy lại vào đậu. Đây là để đặc sốt.", "Đặt đậu vào bát súp rắc ngô tây cắt nhỏ và ăn kèm bánh mì Arab.", "Truyền các nguyên liệu sốt cho mọi người tự lấy: một chai dầu ô liu nguyên chất, chanh vàng cắt tư, muối và tiêu, một đĩa nhỏ với tỏi nát, một đĩa với vụn ớt, và một thìa với cumin xay.", "Đậu được ăn nhẹ nhàng nghiền bằng nĩa để chúng hấp thụ sốt.", "5. Trang trí tùy chọn", "Bóc trứng luộc chín—1 quả cho mỗi người—để cắt nhỏ vào bát cùng với đậu.", "Đặt lên trên đậu một salad dưa leo-cà chua cắt nhỏ và hành tây nhẹ hoặc hành lá cắt mỏng. Ngược lại, truyền một bó hành lá tốt và cà chua và dưa leo cắt tư cắt thành sợi.", "Ăn kèm sốt kem tahina (trang 65) hoặc salad (trang 67), với dưa muối và hành tây cắt ngâm trong giấm trong 30 phút.", "Cách khác để ăn ful medames là phủ bằng sốt cà chua tỏi (xem trang 464).", "Ở Syria và Lebanon, người ta ăn ful medames với sữa chua hoặc phô mai feta, ô liu, và dưa leo nhỏ.", "11. Biến thể", "Một cách truyền thống để đặc sốt là ném một nắm đậu đỏ (60 ml) vào nước khi bắt đầu nấu.", "Ở Iraq, đâu nâu lớn được dùng thay vì đậu Ai Cập nhỏ, trong một món gọi là badkila, cũng được bán cho bữa ăn sáng trên đường phố."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('488a393a-1ce6-5da1-b1eb-2ab2e56ba3eb', '37dc1c8b-c7d3-5f12-a84d-31ee91c4140a', 480.0, 'ml'::public.quantity_unit);
