INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('07d464a0-fc2d-589b-be26-b79801130b9c', 'Bánh đậu tằm kiểu Ai Cập (Tamiya)', 'rau'::public.dish_category, '["Ngâm đậu tằm trong nước ngập qua đêm. Vớ nước. Nếu không có đậu đã bóc vỏ, chà nhẹ để tháo vỏ rồi loại bỏ vỏ. Thấm khô đậu bằng khăn sạch.", "Xay nhuyễn đậu tằm bằng máy xay thịt hoặc máy xay thóc. Nếu không có máy, cho vào máy xay thực phẩm chỉ cho đến khi đậu thành bột nhão. (Nếu xay quá mịn, hỗn hợp dễ vụn khi chiên.) Thêm hành lá, tỏi, ngô tay, cumin, bột nở, ớt bột cayenne, muối, tiêu và ngô tay, nếu dùng. Để tủ lạnh ít nhất 30 phút.", "Làm tròn hỗn hợp đậu thành các viên khoảng 2,5 cm. Chạm nhẹ và tráng bột mì.", "Đun nóng ít nhất 3,8 cm dầu trên lửa vừa đến 185°C.", "Chiên các bánh đậu theo đợt, lật một lần, cho đến khi vàng đều mọi phía, khoảng 5 phút. Lấy ra bằng dùng rạch hoặc thìa có rãnh. Dùng kèm meze hoặc trong bánh pita với salad cà chua dưa leo và sốt mè tahini."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('07d464a0-fc2d-589b-be26-b79801130b9c', '37dc1c8b-c7d3-5f12-a84d-31ee91c4140a', 720.0, 'ml'::public.quantity_unit);
