INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7fa87ba3-7e7b-5b99-bb18-1d299c3a9328', 'Món Koshari Ai Cập (Koshari)', 'rau'::public.dish_category, '["Nấu đậu lăng. Đun đậu lăng và 960 ml nước đến sôi trong nồi trung bình hoặc nồi nhỏ trên lửa cao. Giảm lửa xuống thấp và nấu cho đến khi đậu lăng chỉ vừa mềm (15-17 phút). Đổ nước ra và nems một chút muối. (Lưu ý: khi đậu lăng sẵn sàng, chúng không nên chín hoàn toàn. Chúng chỉ nên được nấu một phần và vẫn còn độ dai vì chúng cần hoàn thành nấu với gạo).", "Bây giờ, đối với gạo. Đổ nước ngâm của gạo ra. Kết hợp đậu lăng đã nấu một phần và gạo trong nồi trên lửa cao vừa với 1 muỗng canh dầu nấu, muối, tiêu, và ngô rí. Nấu trong 3 phút, khuấy thường xuyên. Thêm nước ấm để ngâm hỗn hợp gạo và đậu lăng khoảng 3,5 cm (bạn có thể dùng khoảng 720 ml nước ở đây). Đun sôi; nước sẽ giảm một chút. Bây giờ đậy nắp và nấu cho đến khi hết chất lỏng đã được hấp thụ và cả gạo và đậu lăng đều chín kỹ (khoảng 20 phút). Giữ đậy nắp và không dér trong khoảng 5 phút.", "Bây giờ làm mì. Trong khi gạo và đậu lăng đang nấu, làm mì theo hướng dẫn trên bao bì bằng cách thêm Nui Macaroni vào nước sôi với một chút muối và một chút dầu. Nấu cho đến khi mì al dente. Đổ nước ra.", "Phủ đậu gà và hâm nóng trong lò vi sóng ngắn trước khi ăn.", "Làm phần hành tây giòn ở trên.", "Rắc muối lên các vòng hành tây, rồi lắc chúng trong bột mì để phủ. Lắc bỏ bột thừa.", "Trong một chảo chiên lớn, đun dầu nấu trên lửa cao vừa, nấu các vòng hành tây, khuấy thường xuyên, cho đến khi chúng chuyển thành màu nâu caramel đẹp. Hành phải giòn, nhưng không bị cháy (15-20 phút)."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7fa87ba3-7e7b-5b99-bb18-1d299c3a9328', 'fe8d0f54-08d0-5444-85d0-00057638a256', 360.0, 'ml'::public.quantity_unit);
