INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('355f6196-ce21-5fff-bac1-e259d60d80b7', 'Shawarma gà (Shawarma)', 'man'::public.dish_category, '["Trộn các thành phần nước ướp trong túi nilon khóa kín (hoặc bát).", "Thêm gà và dùng tay đảm bảo mỗi miếng được phủ đều. Nếu dùng túi nilon, tôi thấy dễ dàng khi đóng túi rồi xoa túi để phân tán gia vị lên từng miếng gà.", "Ướt qua đêm hoặc tối đa 24 giờ.", "Trộn các thành phần sốt sữa chua Hy Lạp trong bát và trộn chung. Đậy nắp và để trong tủ lạnh cho đến khi cần (sử dụng được trong 3 ngày trong tủ lạnh).", "Đun nướng/n than (hoặc chảo đáy dày lớn trên bếp) trên lửa vừa-cao. Bạn không cần bơm dầu vì nước ướp đã có dầu và cũng đùi gà có mỡ. Nhưng nếu bạn lo lắng thì bơm dầu lên bếp nóng/nướng. (Xem ghi chú cho nướng lò)", "Đặt gà lên nướng và nấu mặt đầu tiên trong 4-5 phút cho đến khi cháy đẹp, rồi lật và nấu mặt kia trong 3-4 phút (mặt thứ hai mất ít thời gian hơn).", "Lấy gà khỏi nướng và phủ lỏng bằng giấy nhôm. Để riêng để nghỉ trong 5 phút.", "ĐỂ PHỤC VỤ", "Cắt gà và xếp lên đĩa cùng bánh mì mỏng, salad và sốt sữa chua Hy Lạp.", "Để làm cuộn, lấy một miếng bánh mì mỏng và đậy sốt sữa chua Hy Lạp. Thêm một ít salad và cà chua và gà nướng. Cuộn lại và tận dụng!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('355f6196-ce21-5fff-bac1-e259d60d80b7', '53912b45-176d-5ec9-81db-addf1adaa05f', 1000.0, 'g'::public.quantity_unit);
