INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('783b7261-f013-5522-ae3f-5bf305cb8da8', 'Rau đay Ai Cập (Mulukhiyah)', 'man'::public.dish_category, '["Xào hành trong 3-4 muỗng canh dầu ô liu.", "Thêm khối thịt bò hoặc miếng thịt gà, chiên nửa chừng 3-4 phút mỗi mặt.", "Thêm 1 lít nước hoặc đủ ngập thịt.", "Nấu trên lửa vừa cho đến khi thịt chín (thường tôi nấu trong nồi áp lực và nén 5 phút).", "Thêm rau đay đông lạnh và khuấy cho đến khi tan hoàn toàn và sôi.", "Trong chảo khác, thêm 1/4 đến 1/2 chén dầu ô liu và tép tỏi, nấu trên lửa trung bình thấp cho đến khi ngửi được mùi tỏi (đừng chiên vàng, sẽ cay đắng).", "Cho dầu và tỏi vào rau đay, hạ lửa và hôi 5-10 phút.", "Thêm muối theo khẩu vị.", "Dùng với nhiều nước cốt chanh vàng.", "Có thể ăn kèm với gạo hạt ngắn hoặc bánh mì pita."]'::jsonb, 4);
