INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6f662be8-d74c-5260-ab24-2178b397e9f3', 'Bánh lớp Ai Cập (Feteer Meshaltet)', 'rau'::public.dish_category, '["Trộn bột mì và muối rồi đổ một cốc nước và bắt đầu nghiền.", "Nếu bạn cảm thấy bột vẫn chưa kết hợp hoặc quá khô, hãy thêm dần phần nước còn lại cho đến khi có một bột dẻo rất mịn sao khi kéo nó sẽ không bị rách.", "Để bột nghỉ 10 phút rồi chia thành 6-8 viên tùy theo kích thước bạn muốn cho feteer.", "Đun nóng bơ lạt hoặc dầu bạn sử dụng và đổ vào bát sâu.", "Ngâm các viên bột vào bơ ấm. Để nghỉ 15 đến 20 phút.", "Đun lò đến 290°C.", "Keo giãn viên đầu tiên bằng tay trên bàn làm việc sạch. Keo giãn mỏng nhất có thể, mục tiêu là có thể nhìn thấy bàn làm việc qua bột.", "Gấp bột lên trên chính nó để tạo hình vuông, rải hỗn hợp bơ giữa các lớp gấp.", "Để một bên và bắt đầu làm viên tiếp theo.", "Keo giãn viên thứ hai mỏng như đã làm với viên đầu tiên.", "Đặt viên trước đó ở giữa, mặt keo xuống dưới. Gấp lớp ngoài lên, rải thêm hỗn hợp bơ khi gấp. Để một bên.", "Làm như vậy với viên thứ ba và thứ tư. Bây giờ chúng ta có một viên sẵn sàng, đặt vào đĩa nướng 25 cm, mặt keo xuống dưới và rải bơ lên trên.", "Lặp lại với 4 viên còn lại để làm cái thứ hai. Bằng tay nhẹ nhàng bấm feteer đã gấp để trải ra trên đĩa nướng.", "Đặt vào lò đã nóng 10 phút khi feteer bắt đầu nở, bật lò nướng trên để vàng mặt trên.", "Khi hoàn thành, thêm một chút bơ lên trên và phăng để không bị khô."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6f662be8-d74c-5260-ab24-2178b397e9f3', '6511004e-c078-51d9-90e7-492186b8e9c1', 960.0, 'ml'::public.quantity_unit);
