INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('cab26270-7e87-5592-bde2-664f0328d3e2', 'Heo nướng bơm giòn kiểu Nhật', 'man'::public.dish_category, '["Bỏ miếng mỡ lớn trên cạnh từng lát sườn heo, rồi đập từng lát giữa hai tờ giấy nướng cho dày khoảng 1 cm – có thể dùng công cụ mềm thịt hoặc láp cuộn bột. Sau khi đập, dùng tay định hình lại thịt về hình dạng và độ dày ban đầu – bước này đảm bảo thịt ngon nhất có thể.", "Cho bột mì, trứng và bột chiên xù vào ba tô rộng riêng biệt. Nêm thịt, rồi nhúng trước vào bột mì, tiếp theo là trứng, sau đó là bột chiên xù.", "Trong chảo chiên lớn, thêm đủ dầu cao 2cm lên bên chảo. Đun dầu đến 180°C – nếu không có nhiệt kế, cho một ít bột chiên xù vào dầu và nếu chìm một chút rồi bắt đầu chiên thì dầu đã sẵn sàng. Thêm hai lát heo chiên và nấu 1 phút 30 giây mỗi bên, rồi lấy ra và để nghỉ 5 phút. Làm lại với phần heo còn lại.", "Trong khi heo nghỉ, làm sốt bằng cách đánh trộn các nguyên liệu, thêm chút nước nếu đặc quá. Lát tonkatsu và dùng chọc sốt lên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('cab26270-7e87-5592-bde2-664f0328d3e2', '277679d9-8810-544e-aa68-7703e85c1a4d', 4.0, 'piece'::public.quantity_unit);
