INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c6e02396-9d94-56e2-88b7-cea6582d52fa', 'Cơm gạo Nhật (Japanese gohan rice)', 'rau'::public.dish_category, '["Việc rửa và ngâm gạo là chìa khóa để đạt được kết cấu hoàn hảo. Đo gạo vào bát, ngâm với nước lạnh, sau đó dùng ngón tay massage các hạt gạo – nước sẽ trở nên đục. Ráo và rửa lại với nước tươi. Lặp lại năm lần nữa cho đến khi nước trong suốt.", "Đổ gạo đã rửa vào nồi với 400 ml nước, hoặc 200 ml dashi và 200 ml nước, đun sôi, rồi giảm lửa xuống sôi nhẹ, đậy nắp kín có lỗ hơi và nấu trong 15 phút. Bớt khỏi lửa và để ngả thêm 15 phút, rồi khuấy mirin vào. Mở nắp và khuấy tốt. Ăn kèm với bất kỳ hoặc tất cả các loại topping tùy chọn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c6e02396-9d94-56e2-88b7-cea6582d52fa', 'd5c5fc5e-590e-54b3-8052-74f87ef0a7eb', 300.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c6e02396-9d94-56e2-88b7-cea6582d52fa', 'abeb68bb-cab5-5e4f-a7cf-264c717edc6a', 15.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f5e87392-0d81-52bd-acd8-0bb331d9e684', 'Cơm cá heo chiên Nhật (Japanese Katsudon)', 'man'::public.dish_category, '["Đun dầu trong chảo, chiên hành tây đã cắt cho đến khi vàng nâu, rồi thêm tonkatsu (xem công thức tại đây), đặt nó ở giữa chảo. Trộn dashi, nước tương, mirin và đường cùng nhau và đổ ba phần tư hỗn hợp xung quanh tonkatsu. Xì xì trong vài phút cho đến khi sốt đặc một chút và tonkatsu được hâm nóng lại.", "Đổ trứng đánh tan xung quanh tonkatsu và nấu trong 2-3 phút cho đến khi trứng chín nhưng vẫn hơi đặc. Chia gạo giữa hai bát, rồi đặt mỗi bát với nửa trứng và hỗn hợp tonkatsu, rắc hẹ lên trên và ăn ngay, rưới thêm một chút nước tương nếu bạn muốn thêm vị umami."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f5e87392-0d81-52bd-acd8-0bb331d9e684', '41e2849c-302d-5cf6-9f07-ca579b4604a3', 15.0, 'ml'::public.quantity_unit);
