INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f5e87392-0d81-52bd-acd8-0bb331d9e684', 'd5c5fc5e-590e-54b3-8052-74f87ef0a7eb', 200.0, 'g'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2f0fdb71-5149-5a06-aafc-16232bb3342d', 'Khoai nghiền giò heo Ba Lan (Ham hock colcannon)', 'man'::public.dish_category, '["Bóc và cắt khoai tây thành các miếng vừa vặn, vừa phải. Đặt vào chảo lớn đầy nước lạnh có muối, đun sôi và nấu trong 10-15 phút cho đến khi dao có thể đâm vào khoai tây dễ dàng.", "Trong lúc đó, cho bơ vào chảo xào lớn trên lửa vừa. Thêm tỏi, cải, hành lá và một chút gia vị. Khuấy thỉnh thoảng cho đến khi cải úng nhưng vẫn còn một chút đều, rồi để một bên.", "Đổ nước khoai tay, để khô hơi vài phút, rồi nghiền với kem, mù tạt và gia vị trong cùng nồi. Khuấy cải và giò heo vào. Giữ nóng trên lửa thấp.", "Đun lại chảo bạn đã dùng để nấu cải (không cần rửa trước), thêm một chút dầu, đập trứng vào và chiên theo ý thích. Để ăn, chia colcannon giữa các bát và đặt một quả trứng chiên lên mỗi bát."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2f0fdb71-5149-5a06-aafc-16232bb3342d', '904f767e-d4d3-5f96-9210-b4177d71c452', 800.0, 'g'::public.quantity_unit);
