INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ef7e7179-bf6c-50e7-b1a9-12a21b76c095', 'Boxty ăn sáng Irland', 'man'::public.dish_category, '["Trước khi bắt đầu, đặt lò ở mức thấp nhất, sẵn sàng giữ nóng. Bóc vỏ khoai tây, bào 2 cái, rồi đặt một bên. Cắt 2 cái khác thành các khối lớn, rồi luộc 10-15 phút cho đến khi mềm. Cùng lúc đó, vắt càng nhiều nước từ khoai đã bào bằng khăn bếp sạch. Nghiền khoai đã luộc, rồi trộn với khoai đã bào, hành lá và bột mì.", "Khuôn lòng trắng trứng trong bát lớn cho đến khi giữ được đỉnh mềm. Khuân sữa chua vào, rồi thêm bột nở soda. Khuân vào hỗn hợp khoai.", "Đun chảo không dính lớn trên lửa trung bình, rồi thêm 1 muỗng canh bơ và một ít dầu. Thả 3-4 thìa hỗn hợp khoai vào chảo, rồi nấu nhẹ 3-5 phút mỗi mặt cho đến khi vàng và giòn. Giữ ấm trên đĩa trong lò trong khi bạn nấu đợt tiếp theo, thêm thêm bơ và dầu vào chảo trước khi làm vậy. Bạn sẽ có 16 boxty kích thước bánh mặn từ hỗn hợp. Có thể làm trước ngày hôm trước, để thoát dầu trên giấy bếp, rồi hâm nóng lại trong lò thấp trong 20 phút.", "Đun nồi nướng ở mức trung bình và đặt cà chua vào nồi nặng. Thêm một đống bơ và ít dầu, rồi chiên khoảng 5 phút cho đến khi mềm. Nướng xúc xích khói, rồi xếp lên đĩa và giữ ấm. Xếp boxty, xúc xích khói và trứng, và phục vụ cà chua ở bên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('ef7e7179-bf6c-50e7-b1a9-12a21b76c095', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 4.0, 'piece'::public.quantity_unit);
