INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6a07ac56-9e49-5f49-a395-ffb9a111c2f0', 'Heo hầm với rượu táo (Coddled pork with cider)', 'man'::public.dish_category, '["Nung bơ trong nồi nấu cho đến khi xì xì, sau đó chiên heo trong 2-3 phút mỗi mặt cho đến khi nâu. Lấy ra khỏi chảo.", "Đổ xông khói, cà rốt, khoai tây và sắn tây vào chảo, sau đó chiên nhẹ cho đến khi hơi màu nâu. Khuấy vào bắp cải, đặt sườn heo trở lên trên, thêm lá nguyệt quế, sau đó đổ rượu táo lên men và nước dùng gà. Đậy nắp, sau đó để mọi thứ hầm nhẹ trong 20 phút cho đến khi heo chín qua và rau mềm.", "Phục vụ tại bàn cham trực tiếp từ món ăn."]'::jsonb, 4);
