INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d7e3ef32-b5dc-5e4c-8618-039d5aec0583', 'Khoai nghiền mù tạt Ireland (Mustard champ)', 'rau'::public.dish_category, '["Luộc khoai tây 15 phút hoặc cho đến khi mềm. Ráo, rồi nghiền.", "Đun nóng sữa và nửa bơ ở góc nồi, rồi đánh vào khoai nghiền, cùng với mù tạt ganze.", "Chiên nhẹ hành lá trong phần bơ còn lại 2 phút cho đến khi vừa mềm nhưng vẫn xanh tươi. Gộp vào khoai nghiền và dùng. Ngon với gammon hoặc để phủ lên bánh pudding cá."]'::jsonb, 4);
