INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('80e81699-652b-5d8d-9cc0-13167bf5d0f9', 'Gà nướng Piri-piri với salad', 'man'::public.dish_category, '["Xay cùng tất cả nguyên liệu nước ướp trong máy xay nhỏ. Xoát nước ướp lên gà và để 1 giờ ở nhiệt độ phòng.", "Đậy lò 190°C. Đặt gà vào khay nướng và nấu 1 giờ 20 phút. Nghỉ dưới lớp giấy nhôm lỏng 20 phút. Trong khi gà đang nghỉ, trộn các nguyên liệu salad và nems. Dùng gà với salad, khoai tây chiên và các loại sốt chấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('80e81699-652b-5d8d-9cc0-13167bf5d0f9', '44a6a37a-69a3-5573-9fd1-730baf90fb5b', 1500.0, 'g'::public.quantity_unit);
