INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ae4eaa92-49c2-551b-b3d7-93808d070825', 'Cá mòi nồ Thụy Điển nướng (Grilled Portuguese sardines)', 'man'::public.dish_category, '["Đặt tất cả nguyên liệu, ngoại trừ cá mòi, vào bát và trộn cùng với một chút gia vị. Đổ vào đĩa nướng, thêm cá mòi và lắc thật tốt. Đậy nắp và để trong tủ lạnh vài giờ.", "Đun nướng than hoặc chảo nướng cho đến khi nóng. Nấu cá mòi 4-5 phút mỗi bên hoặc cho đến khi thật caramel hóa và cháy đen. Đặt lên đĩa ăn, rưới dầu, rắc thêm một chút paprika và vắt lát chanh lên trên."]'::jsonb, 4);
