INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5a96ee69-6004-5db8-86c3-8f67dbf268a3', 'Bánh mì Prego sốt Piri-piri xanh (Portuguese prego with green piri-piri)', 'man'::public.dish_category, '["Chà tỏi lên các miếng thịt rồi cho vào túi bánh mì và rót dầu ô liu, giấm rượu Sherry và cuống ngô tây vào. Nén mọi thứ với nhau, rồi dùng cylindrical để đập các miếng thịt vài lần. Để 1-2 giờ.", "Làm sốt, cho tất cả nguyên liệu vào máy xay cùng 1 muỗng canh nước và xay cho đến khi mịn nhất có thể. Điều này sẽ làm nhiều hơn quanto cần cho công thức nhưng sẽ giữ được một tuần trong lọ kín.", "Đun nồi nướng hoặc chảo đến mức cao. Chải bỏ tỏi và cuống ngô tây khỏi các miếng thịt và nems tốt. Chiên nửa chừng các miếng thịt 2 phút mỗi mặt rồi nghỉ trên đĩa. Đặt các nửa bánh mì Ciabatta lên đĩa, phần nướng xuống, để hấp thụ nước mát.", "Lát các miếng thịt rồi nhét vào các bánh mì với sốt xanh và Rau Rocket."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5a96ee69-6004-5db8-86c3-8f67dbf268a3', 'a8db4b95-a126-5f43-a0b4-2c29ba37261d', 1.0, 'piece'::public.quantity_unit);
