INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4a2e0bb7-a1ca-50b5-be2d-2be37705756c', 'Bánh cá fofo (Fish fofos)', 'man'::public.dish_category, '["Đặt cá vào chảo có nắp và rót đủ nước để ngâm cá. Đun sôi nhẹ và luộc nhẹ trong 10 phút trên lửa nhỏ với nắp. Đổ nước và nát cá thành sợi.", "Cho cá, khoai tây, ớt xanh, ngô rí, hạt thì là, tiêu đen, tỏi và gừng vào bát lớn. Nêm nếm, thêm bột gạo, trộn tốt và đổ 1 trứng vào. Khuấy hỗn hợp và chia thành 15 phần, rồi hình thành các bánh dài nhỏ. Gói các trứng còn lại vào một bát và đánh nhẹ. Đặt bột chiên xù vào một bát khác. Trám mỗi bánh fofo vào trứng đánh tan rồi vào hỗn hợp bột chiên xù. Để trong tủ lạnh 20 phút.", "Đun 1 cm dầu trong chảo chiên lớn trên lửa vừa. Chiên các bánh fofo theo lượt, 2 phút mỗi bên, lật nhẹ cho đến khi vàng đều khắp mặt. Để ráo trên giấy bếp và làm lại với các bánh fofo còn lại.", "Làm salad hành: trộn đều hành tây, ngô rí và nước cốt chanh với một chút muối. Ăn kèm với bánh fofo và chutney xoài."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4a2e0bb7-a1ca-50b5-be2d-2be37705756c', '59634a7a-dde6-505c-a6c4-3b42fbed82dc', 600.0, 'g'::public.quantity_unit);
