INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fa923337-5f19-51ae-a0a1-e7a5484b13bc', 'Heo nướng Febras assadas (Portugal)', 'man'::public.dish_category, '["Cắt các mích thành 5 miếng bằng nhau để phần đuôi hơi dài hơn. Túi nhựa trong suốt và trượt một miếng vào. Đập thành mảnh mỏng kích thước đĩa phụ bằng cylindrical và làm tương với các miếng còn lại.", "Cho rượu vang, bột ớt ngọt, chút muối và tiêu và nước cốt nửa quả chanh vàng vào bát và thêm thịt heo. Để ướp 20-30 phút, trong khi bạn chuẩn bị nướng than cho đến khi than đang hồng rực nhưng không có lửa.", "Làm khoai chiên, lấp bát bằng nước mát và cắt khoai thành khoai chiên dày 3cm. Ngâm chúng trong nước 5 phút và rồi thay nước. Để thêm 5 phút. Ráo và sau đó thấm khô bằng khăn hoặc khăn bếp giấy.", "Đun dầu trong máy chiên sâu hoặc nồi sâu có nắp đến 130C và thả khoai chiên vào dầu (từng đợt). Luộc sơ 8-10 phút. Vớt ra khỏi dầu và ráo tốt. Đặt trên khay để nguội. Đun lại dầu đến 180C (đảm bảo nóng hoặc khoai chiên của bạn sẽ nhuyễn) và thả rổ khoai chiên vào dầu (làm tương từng đợt). Để nấu 2 phút rồi lắc nhẹ. Nấu thêm một phút hoặc cho đến khi chúng có màu tốt và giòn khi chạm. Ráo tốt vài phút, đổ vào bát và rắc muối biển.", "Thịt heo sẽ nấu nhanh nên làm 2 đợt. Lấy các miếng ra khỏi nước ướp, xát chúng với dầu, và thả chúng lên nướng than (bạn cũng có thể dùng nướng than). Nấu 1 phút mỗi mặt – chúng có thể bùng cháy khi bạn làm như vậy. Thời gian này thực sự nên đủ vì chúng sẽ tiếp tục nấu. Lấy chúng ra khỏi nướng than và đống lên đĩa. Làm tương với đợt còn lại.", "Dùng bằng cách đống đĩa với khoai chiên, thả thịt heo lên trên mỗi đống và rót nước mát từ đĩa qua sao cho khoai hấp thụ vị. Trangs trí bằng một muỗng sốt Mayonnaise và một miếng chanh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('fa923337-5f19-51ae-a0a1-e7a5484b13bc', '72e52172-48ee-5eb7-b8cf-8d615540e7f1', 2.0, 'piece'::public.quantity_unit);
