INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('fa923337-5f19-51ae-a0a1-e7a5484b13bc', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1000.0, 'g'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('32ab3e9d-ed51-55b0-82b3-a7267a1f01af', 'Súp cá Cao Lãnh (Caldeirada de peixe)', 'man'::public.dish_category, '["Đun chút dầu trong chảo sâu lớn, và chiên hành và ớt chuông trên lửa trung bình cho đến khi mềm nhưng không vàng. Băm mịn cuống ngô rí (giữ lá cho sau), và thêm vào chảo với ớt và tỏi đã băm. Chiên thêm vài phút. Thêm rượu vang, nhụy hoa nghệ tây và lá nguyệt quế và để hôi cho đến khi còn một nửa.", "Thêm khoai tây, cà chua, và 300 ml nước và đun sôi nhẹ. Giổi ca chua bằng muỗng trên cạnh chảo và hôi 20-25 phút cho đến khi khoai vừa mềm và cà chua đã tan ra.", "Nems tốt, rồi nhẹ nhàng đẩy cá vào sốt, và sắp xếp mực, tôm sú, nghêu và âme trên bề mặt. Đậy nắp và nấu 6-8 phút cho đến khi vỏ nghêu và âme đã mở, tôm đã chín và cá xơ. Nướng bánh mì, chà nhẹ với nửa tép tỏi và rưới dầu ô liu. Dùng súp rắc lá ngô rí băm, và các miếng bánh nướng để nhúng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('32ab3e9d-ed51-55b0-82b3-a7267a1f01af', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 2.0, 'piece'::public.quantity_unit);
