INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f09ffa3d-610d-5632-ae94-30dcb53066c1', 'Súp cà rốt Maroc', 'canh'::public.dish_category, '["Đầy lò 180°C.", "Trộn cà rốt, hành tây, tỏi, hạt thì là, hạt ngô rí, muối và dầu ô liu trong bát và trộn đều. Đổ ra khay nướng.", "Đặt khay vào lò đã đậy và nướng 10-12 phút cho đến khi cà rốt mềm. Vớt ra và để nguội.", "Nghiền hỗn hợp cà rốt đã nướng cùng chút nước thành hồ mịn và lọc vào bát.", "Đun hỗn hợp cà rốt trong chảo không dính. Thêm 2 chén nước và đun sôi. Thêm bột garam masala và trộn. Thêm muối và trộn kỹ.", "Nới bếp, thêm nước cốt chanh vàng và trộn kỹ.", "Dùng nóng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f09ffa3d-610d-5632-ae94-30dcb53066c1', '43dc47ee-00be-5d33-80aa-80f11053db4f', 6.0, 'piece'::public.quantity_unit);
