INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('81d8e98f-0156-576f-82d4-132e2a867096', 'Mì xào Mee goreng mamak', 'man'::public.dish_category, '["Đun dầu trong chảo trên lửa vừa. Rồi cho đậu phộng, ớt khô, tôm khô và đậu vào. Xào mùi cho đến khi thơm. Vớt ra khỏi chảo và để riêng.", "Xay nhuyễn các nguyên liệu đã chiên với cốt me và nước cho đến khi mịn. Rồi xào hỗn hợp đã xay trong dầu đun trên lửa nhỏ. Tiếp tục nấu cho đến khi dầu tách khỏi hồ và tối màu hơn.", "Bóc vỏ và cắt khoai tây thành từng khối nhỏ và luộc trong nồi nước cho đến khi dao đâm được mềm. Khi sẵn sàng, vớt ra khỏi nồi và để riêng. Đổ bỏ nước.", "Cắt lát hành tây và đậu hũ chiên, băm tỏi, cắt chút bắp cải và cải làn. Chuẩn bị bánh tôm chiên và cắt chúng. Luộc mì sợi cho mềm nếu mua khô. Cũng trộn xì dầu đen với nước.", "Để chiên một phần Mee goreng mamak, đun dầu và thêm 1/4 các nguyên liệu sau theo thứ tự: tỏi, hành tây, hồ. Xào cho đến khi thơm. Tuỳ chọn, thêm tôm sú.", "Thêm 1/4 lượng đậu hũ, khoai đã luộc, bắp cải, cải làn và bánh tôm chiên. Xào thêm 30 giây.", "Cho mì sợi vào wok. Thêm 3 muỗng canh hỗn hợp xì dầu đen. Trộn đều trong 1 phút. Rồi dồn mì sang một bên wok. Đập một quả trứng vào. Trangs trí với lát chanh xanh và lát ớt xanh. Để nấu thêm đĩa mì khác, lặp lại từ bước 5 trở đi."]'::jsonb, 4);
