INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3434abdc-3fb8-55c2-bfbb-13d6f6899588', 'Gà nướng percik (ayam percik)', 'man'::public.dish_category, '["Trong máy xay, thêm các nguyên liệu làm sốt gia vị và xay cho mịn.", "Trên lửa trung bình, đổ sốt gia vị vào chảo và chiên 10 phút cho đến khi thơm. Thêm nước hoặc dầu từng muỗng canh nếu sốt quá khô. Đừng cháy sốt. Giảm lửa nhẹ nếu cần.", "Thêm đinh hương, thảo quả, nhục me, nước cốt dừa, nước, đường và muối. Bật lửa lớn và đun hỗn hợp đến sôi. Giảm lửa xuống trung bình thấp và hầm nhẹ 10 phút. Khuân đôi khi. Sốt sẽ đặc lên một chút. Đây là sốt ướp, nên nếm và điều chỉnh gia vị nếu cần. Đừng lo nếu hơi đắng. Hương vị sẽ mất đi khi nướng.", "Khi sốt đã nguội, đổ hết lên gà và ướt một đêm đến hai ngày.", "Đun lò đến 220°C.", "Lấy gà ra khỏi sốt ướp. Đổ sốt lên khay nướng đã bơ (hoặc giấy bạc). Đặt gà lên trên sốt (đảm bảo gà che hết sốt và sốt không bị lộ ra hoặc sẽ cháy) và khuân sốt ướp còn lại lên gà. Nướng 35-45 phút hoặc cho đến khi nhiệt độ bên trong phần dày nhất của gà ít nhất 80°C.", "Để gà nghỉ 5 phút. Quét gà bằng ít dầu. Phục vụ gà với sốt lên trên cơm hấp (hoặc cơm dừa)."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3434abdc-3fb8-55c2-bfbb-13d6f6899588', '53912b45-176d-5ec9-81db-addf1adaa05f', 6.0, 'piece'::public.quantity_unit);
