INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('dd178538-1ac2-53f3-acd6-e1b382abccef', 'Cơm Nasi lemak Malaysia (Nasi lemak)', 'man'::public.dish_category, '["Trong nồi vừa trên lửa vừa, trộn kem dừa, nước, bột gừng, rễ gừng, muối, lá nguyệt quế và gạo. Đậy nắp và đun sôi. Hạ lửa và hôi 20 đến 30 phút, hoặc cho đến khi chín.", "Cho trứng vào nồi, ngập nước lạnh. Đun nước sôi, ngay lập tức nới bếp. Đậy nắp và để trứng trong nước nóng 10 đến 12 phút. Vớt trứng ra khỏi nước nóng, để nguội, bóc vỏ và cắt nửa. Cắt dưa leo.", "Trong lúc đó, trong chảo lớn hoặc wok, đun 240 ml dầu ăn trên lửa vừa-cao. Khuấy đậu phộng và nấu ngắn cho đến khi nhẹ vàng. Vớt đậu bằng cuch đón ráo và đặt lên khăn giấy để thấm dầu thừa. Trả chảo lên bếp. Khuấy nội dung một gói cá muối; nấu ngắn, lật, cho đến khi giòn. Vớt ra và đặt lên khăn giấy. Đổ bỏ dầu. Lau sạch chảo.", "Đun 2 muỗng canh dầu trong chảo. Khuấy hành tây, tỏi và hành tím; nấu cho đến khi thơm, khoảng 1 hoặc 2 phút. Trộn sốt ớt vào và nấu 10 phút, khuấy thỉnh thoảng. Nếu sốt ớt quá khô, thêm ít nước. Khuấy cá muối còn lại; nấu 5 phút. Khuấy muối, đường và nước cốt me vào; hôi cho đến khi sốt đặc, khoảng 5 phút.", "Đổ sốt hành và tỏi lên gạo nóng, và phủ với đậu phộng, cá muối chiên, dưa leo và trứng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('dd178538-1ac2-53f3-acd6-e1b382abccef', 'e8f63dcb-a381-5607-baca-4d3a9368853f', 480.0, 'ml'::public.quantity_unit);
