INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4de23045-2f06-5e11-8d41-8b2e31d044f4', 'Bánh mì baguette Roti John (Roti john)', 'man'::public.dish_category, '["Trộn tất cả nguyên liệu trong bát.", "Đun nóng chảo hoặc nếp nướng với một ít dầu thực vật.", "Đổ hỗn hợp lên chảo và đặt một miếng bánh mì baguette mở mặt lên trên.", "Bấm bánh mì bằng muỗng nhôm và nướng trong 2 phút.", "Lật bánh mì ngược lại để làm cho hơi giòn.", "Lấy khỏi chảo và cắt bánh mì thành các phần nhỏ.", "Thêm sốt Mayonnaise và/hoặc Sambal trước khi cắt sandwich (tùy chọn)."]'::jsonb, 4);
