INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2e83a95a-e22d-550d-aa4d-83067783128a', 'Rendang bò', 'man'::public.dish_category, '["Cắt nhỏ các nguyên liệu sốt gia vị rồi xay trong máy xay thực phẩm cho đến khi mịn.", "Đun dầu trong nồi hầm, thêm sốt gia vị, quế, đinh hương, hồi, thảo quả và xào cho đến khi thơm. Thêm thịt bò và sả đã xoa uống và khuân trong 1 phút. Thêm nước cốt dừa, nước me, nước và hầm nhẹ trên lửa trung bình, khuân thường xuyên cho đến khi thịt gần chín. Thêm lá chanh thái, kerisik (dừa rang), đường hoặc đường thốt nốt, khuân để trộn tốt với thịt.", "Giảm lửa xuống thấp, đậy nắp và hầm nhẹ trong 1 đến 1,5 giờ hoặc cho đến khi thịt rất mềm và sốt đã khô. Thêm thêm muối và đường vừa đủ. Phục vụ ngay với cơm hấp và lưu lại một ít cho đêm sau."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2e83a95a-e22d-550d-aa4d-83067783128a', 'fda67982-c921-54e6-9568-e2184abae4d6', 453.6, 'g'::public.quantity_unit);
