INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7faba7d9-be42-5f09-9eec-1059b1531e1e', 'Xúc xích Cevapi (Cevapi Sausages)', 'man'::public.dish_category, '["Cho thịt băm vào bát. Cắt hành tây rất nhỏ và xén tỏi. Thêm vào bát. Thêm ngò tây, bột ớt ngọt Paprika, bột nở, bột chiên xù, nước lọc, viên súp rau củ quả, muối và tiêu đen hạt/bột.", "Trộn kỹ với máy trộn tay có móc xên. Đậy bát với nilon bọc thực phẩm và để nguội trong tủ lạnh 1 hoặc 2 giờ.", "Lấy phần hỗn hợp thịt, khoảng 50-55 g (khoảng 60 ml), và hình thành cevapi. Các cuộn nên bằng ngón tay cái và dài khoảng 7-10 cm. Tôi có 18 xúc xích. Công thức có thể gấp đôi dễ dàng.", "Nướng cevapi trên chảo nướng nóng hoặc trên nướng than trong khoảng 12-14 phút, lật vài lần ở giữa, hoặc cho đến khi vàng và chín đều. Tôi kiểm tra bằng cách cắt một cái vào giữa rồi nướng các đợt sau trong cùng khoảng thời gian.", "Ăn nóng như đã gợi ý ở trên. Cevapi có thể hâm nóng trong lò ở 180°C trong khoảng 10 phút hoặc cho đến khi nóng qua. Kiểm tra một cái, nếu chưa nóng đủ, cho xúc xích thêm vài phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7faba7d9-be42-5f09-9eec-1059b1531e1e', '61b6c1bc-2369-5a04-8c51-5a4569d3d0ba', 500.0, 'g'::public.quantity_unit);
