INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3ca2c7bb-4522-513b-bfdb-c407f3769e8e', 'Cừu nướng peka Croatia (Croatian lamb peka)', 'man'::public.dish_category, '["Đun lò trước đến 200°C / 220°C / 220°C / mức 7", "Nếu bạn chưa mua thịt cừu đã cắt, cắt vai cừu hoặc chân cừu thành các mẩu lớn và đặt một bên.", "Các mẩu thịt cừu đã cắt trên một cái thớ cắt màu đỏ", "Làm marinade dầu -", "Trộn 80ml dầu ô liu trong một bát với mù tạt xay, cà chua khô nắng xay, tiêu đen và muối.", "dầu ô liu, gia cà chua khô nắng xay và gia tỏi xay và tiêu đen được trộn cùng nhau trong một cái bạc bạc để làm Croatian peka", "Thêm khoai tây và rau vào một nồi nấu lớn có nắp.", "Các loại rau đã cắt bao gồm hành tím đỏ đã cắt, bí ngòi xanh, khoai tây ớt chuông đỏ trong một cái chảo sắt đúc", "Đặt diced lamb lên trên các loại rau, rót marinade và rượu vang trắng lên trên.", "Các mẩu thịt cừu được phủ trong sốt cà chua khô nắng xay và được phủ với xạ hương, romarin và ngò gai который ở trên trên hành tím đỏ, cà tím, bí ngòi xanh và khoai tây trong một cái chảo sắt đúc", "Thêm lá nguyệt quế, xạ hương và ngò gai, cố gắng giữ các loại thảo mộc ở trên.", "Để bạn có thể dễ dàng lấy cuống thảo mộc ra sau khi nấu.", "Các mẩu thịt cừu được phủ trong sốt cà chua khô nắng xay và được phủ với xạ hương, romarin và ngò gai ở trên trên hành tím đỏ, cà tím, bí ngòi xanh và khoai tây trong một cái chảo sắt đúc", "Đậy nắp nồi nấu và nấu trong 1 tiếng 30 phút", "Nếu bạn không có nắp đậy rất tốt bằng giấy bạc", "Chảo sắt đúc với nắp lên trong lò", "Lấy nắp ra, loại bỏ các cuống thảo mộc dày. Khuấy vào 2 thìa soupe dầu ô liu.", "Nấu thêm 20-30 phút.", "Cừu nướng peka Croatia đã nấu trong một cái chảo sắt đúc trong lò", "Phục vụ với bánh mì tươi làm ở nhà để nhúng vào nước cốt."]'::jsonb, 4);
