INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d826ec01-87fe-51f6-9564-1d010420dd6e', 'Goulash bò kiểu Croatia truyền thống', 'man'::public.dish_category, '["Làm sạch thịt bò từ các mạch nếu có và cắt thành các mảnh nhỏ hơn, 3 × 3 cm. Ngâm thịt trong mù tạt và gia vị và để trong tủ lạnh một giờ.", "Đun nóng một muỗng canh mỡ heo hoặc dầu thực vật trong nồi và chiên thịt mọi mặt cho đến khi vàng. Khi thịt đã chín, chuyển vào đĩa và thêm một muỗng canh mỡ khác vào nồi.", "Cắt hành tây rất mịn, bóc cà rốt và xén bằng cạo. Nấu hành tây và cà rốt trên lửa nhỏ 15 phút. Có thể nêm ít muối vào rau để chúng mềm nhanh hơn.", "Khi rau đã vàng và hơi nhừ, thêm thịt, lá nguyệt quế và tỏi. Đổ rượu vang đỏ vào và hầm sôi nhẹ 10-15 phút cho cồn bốc hết. Đây là lúc thích hợp để thêm 2/3 lượng chất lỏng.", "Đậy nắp và nấu trên lửa nhỏ trong một tiếng, khuấy thỉnh thoảng. Sau tiếng đầu tiên, đổ phần còn lại của nước hoặc nước dùng và nấu thêm 30-45 phút.", "Để hầm nguội hơi và dùng cùng chút ngô tay cắt nhỏ và một vài lát ớt tươi cay nếu muốn thêm cay.", "Lát bánh mì tươi, nêm nếm salad và đơn giản thưởng thức những hương vị tuyệt vời này."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d826ec01-87fe-51f6-9564-1d010420dd6e', 'fda67982-c921-54e6-9568-e2184abae4d6', 500.0, 'g'::public.quantity_unit);
