INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3c8eeccf-754f-55f1-827c-550f7bfab444', 'Hầm đậu Croatia (Croatian Bean Stew)', 'man'::public.dish_category, '["Đun nóng dầu thực vật trong chảo. Thêm các loại rau đã kẹo và xào cho đến khi mềm. Lấy một nồi, trống đậu trắng Cannellini cùng với các loại rau vào đó, đặt xúc xích Chorizo bên trong và nấu thêm 20 phút trên lửa thấp. Hoặc, đặt nó vào lò và nướng ở nhiệt độ 180°C/175°C trong 30 phút. Món ăn này ngon hơn khi hâm nóng vào ngày hôm sau."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3c8eeccf-754f-55f1-827c-550f7bfab444', '408d726e-6ef4-593c-a77b-e4481c2da478', 2.0, 'piece'::public.quantity_unit);
