INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a759dac5-177b-5375-a50a-68450731977d', 'Súp nấm kiều mạch Croatia', 'canh'::public.dish_category, '["Băm hành tây và tỏi, lát nấm và rửa hạt kiều mạch. Đun dầu và xào nhẹ hành. Thêm nấm và tỏi và tiếp tục xào. Thêm muối, gia vị súp rau củ quả, hạt kiều mạch và lá nguyệt quế và ngập nước. Hôi nhẹ và ngay trước khi chín hoàn toàn, thêm tiêu, kem chua trộn bột mì, lá ngô tây băm và giấm theo khẩu vị."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a759dac5-177b-5375-a50a-68450731977d', 'e5d6f15f-da22-5023-a84c-79eba0d033e4', 150.0, 'g'::public.quantity_unit);
