INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fcd08fb6-a16a-5294-b439-5385cd201ffb', 'Burek Croatia', 'rau'::public.dish_category, '["Chiên hành đã cắt nhuyễn và thịt băm trong dầu. Thêm muối và tiêu. Nhớ bơ khay nướng tròn và đặt một lớp bột filo vào. Phủ một lớp nhân mỏng và phủ bằng một lớp bột filo khác phải được phủ dầu tốt. Đặt một lớp nhân khác và phủ với bột filo. Khi bạn có năm hoặc sáu lớp, phủ bằng bột filo, nướng ở 200°C trong nửa giờ và cắt thành tư phần và phục vụ."]'::jsonb, 4);
