INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6a873ec6-513a-58cc-860b-3638f86057e0', 'Cá mòi tươi chiên (Fresh sardines)', 'rau'::public.dish_category, '["Rửa cá dưới vòi nước lạnh. Lăn trong bột mì và chiên sâu trong dầu cho đến khi giòn. Đặt lên khăn giấy bếp để loại bỏ dầu thừa và ăn nóng hoặc lạnh với một lát chanh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6a873ec6-513a-58cc-860b-3638f86057e0', 'caeaaeb4-b6e5-56da-abc8-c1df64860f6c', 500.0, 'g'::public.quantity_unit);
