INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('32dce439-1e37-5749-9a3f-490f99e2ef3f', 'Chivito Uruguay (Chivito uruguayo)', 'man'::public.dish_category, '["Nén thịt bò cho đến khi mịn và chúng ta đặt nó lên chảo nướng để nướng. Đặt trứng, xông khói và giăm bông để chiên.", "Cắt bánh mì nửa, đặt thịt bò, trứng đã chiên, xông khói, giăm bông, phô mai Mozzarella, cà chua và xà lách. Đậy với nửa còn lại của bánh mì và phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('32dce439-1e37-5749-9a3f-490f99e2ef3f', 'c9a85c2e-12a8-501d-8172-b731d9ed81b6', 2.0, 'piece'::public.quantity_unit);
