INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1c5bae59-dd83-5a2b-8ace-aed1a40e96ad', 'Sushi (Sushi)', 'man'::public.dish_category, '["ĐỂ LÀM CUỘN SUSHI: Đắp gạo. Đặt tờ nori trên bàn cuộn, mặt bóng xuống dưới. Ngâm tay vào nước cốt giấm, rồi đắp nắm gạo lên trên thành lớp dày 1cm, để lề xa bạn trống.", "Đắp đều sốt mayonnaise Nhật. Dùng thìa để đắp một lớp mỏng mayonnaise xuống giữa gạo.", "Thêm nhân. Hãy để con bạn đặt các lớp nhân yêu thích lên trên mayonnaise – ở đây chúng tôi đã dùng cá ngừ và dưa leo.", "Cuộn nó lên. Nâng lề của bàn cuộn lên trên gạo, áp lực ít để giữ mọi thứ trong cuộn chặt.", "Dán các bên như tem. Khi bạn đến lề không có gạo, chải với chút nước và tiếp tục cuộn thành cuộn chặt.", "Bọc bằng màng bọc. Lấy bàn cuộn ra và cuộn chặt trong màng bọc trước khi người lớn cắt sushi thành lát dày, rồi bóc màng bọc ra.", "ĐỂ LÀM SUSHI ÉP: Đặt lớp cá xông khói lên.", "Lót khay nướng bánh bằng màng bọc, rồi đặt một lớp mỏng cá xông khói vào trong trên màng bọc.", "Đậy bằng gạo và ép xuống. Ép khoảng 3cm gạo lên trên cá, gấp màng bọc lên và ép xuống càng nhiều có thể, dùng khay khác nếu bạn có.", "Đảo nó ra như lâu cát. Đổ khối sushi lên thớ cắt. Hãy cho người lớn cắt thành ngón tay, rồi lấy màng bọc ra.", "ĐỂ LÀM SUSHI QUYÊN: Chọn nhân của bạn. Lấy một vuông màng bọc nhỏ và đặt một nhân, như nửa tôm hoặc một miếng cá xông khói nhỏ, lên nó. Dùng tay ẩm để cuộn viên gạo kích thước hạt óc chó và đặt lên trên nhân.", "Làm thành quy chặt. Kéo các góc của màng bọc lại và chặt thành quy bằng cách xoắn nó lên, rồi bóc và phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1c5bae59-dd83-5a2b-8ace-aed1a40e96ad', 'd5c5fc5e-590e-54b3-8052-74f87ef0a7eb', 300.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1c5bae59-dd83-5a2b-8ace-aed1a40e96ad', 'd1e8d19d-1545-589f-87b4-7c6128fa50ef', 100.0, 'ml'::public.quantity_unit);
