INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1c5bae59-dd83-5a2b-8ace-aed1a40e96ad', 'e420f419-4a1c-5433-b888-e18247cb20b9', 15.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1c5bae59-dd83-5a2b-8ace-aed1a40e96ad', '1f704316-5b7b-55b1-a19d-9f908816a5af', 1.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4b33a272-4557-56c0-b41d-d8c7af4a4d20', 'Ớt chuông nhồi quinoa và đậu đen (Stuffed Bell Peppers with Quinoa and Black Beans)', 'rau'::public.dish_category, '["Đun lò lên 190°C. Lát nhẹ một chiếc khay nướng lớn.", "Đặt nửa ớt chuông vào khay nướng đã chuẩn bị, phần cắt lên trên. Nướng trong 15-20 phút, hoặc cho đến khi hơi mềm.", "Trong khi ớt chuông đang nướng, chuẩn bị nhân. Trong chảo xào lớn, đun nóng dầu ô liu trên lửa vừa. Thêm hành tây đã cắt, và nấu trong 3-4 phút, cho đến khi mềm. Thêm tỏi, và nấu thêm 1 phút, cho đến khi thơm.", "Khuấy vào quinoa đã nấu, đậu đen, ngô, cà chua đã cắt, cumin, bột ớt, bột ớt ngọt Paprika hun khói, muối, và tiêu. Nấu trong 5-7 phút, cho đến khi nóng qua. Bớt bấm chảo từ lửa, và khuấy vào 240 ml phô mai đã xé, nếu dùng.", "Lấy ớt chuông khỏi lò, và cẩn thận nhồi mỗi nửa ớt chuông với hỗn hợp quinoa và đậu đen. Đặt 120 ml phô mai đã xé còn lại lên trên ớt chuông đã nhồi, nếu dùng.", "Trả ớt chuông đã nhồi vào lò, và nướng thêm 15-20 phút, cho đến khi phô mai tan và ớt chuông mềm.", "Lấy khỏi lò, và để ớt chuông nguội trong 5 phút trước khi phục vụ. Trang trí bằng ngô rí đã cắt tươi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4b33a272-4557-56c0-b41d-d8c7af4a4d20', '70a26f29-1bba-53d9-a9ec-db932fdcb327', 4.0, 'piece'::public.quantity_unit);
