INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('775ba99c-101b-5cd0-a3b4-6079a001d234', 'Bò mechado', 'man'::public.dish_category, '["0. Làm sốt ướp thăn nội bò bằng cách trộn nước tương, giấm, gừng, tỏi, dầu mè, dầu ô liu, đường, muối và tiêu đen xay trong bát lớn. Khuân tốt.", "1. Thêm các khối thăn nội bò vào bát với sốt ướp thăn nội bò. Khuân nhẹ cho đến khi thịt được phủ. Để trong 1 giờ.", "2. Dùng xiên kim hoặc tre, ghép bánh bò kebob bằng cách xiên rau và thăn nội bò đã ướp.", "3. Đun nồi nướng và bắt đầu nướng các xiên bò 3 phút mỗi bên. Điều này sẽ cho bạn thịt bò trung bình, nhiều nước và mềm bên trong. Thêm thêm thời gian nếu bạn muốn thịt bò chín kỹ, nhưng nó sẽ ít mềm hơn.", "4. Chuyển sang đĩa phục vụ. Phục vụ với cơm saffron.", "5. Chia sẻ và ăn ngon!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('775ba99c-101b-5cd0-a3b4-6079a001d234', 'a8db4b95-a126-5f43-a0b4-2c29ba37261d', 3.0, 'piece'::public.quantity_unit);
