INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('982382d2-cbda-5544-bfce-d45b80311a00', 'Bistek', 'man'::public.dish_category, '["0. Ướp thịt bò trong nước tương, chanh vàng (hoặc calamansi), và tiêu đen xay ít nhất 1 giờ. Lưu ý: ướp qua đêm để có kết quả tốt nhất", "1. Đun dầu nấu trong chảo rồi chiên nửa lượng hành trên cùng cho đến khi kết cấu mềm. Đặt một bên", "2. Xé bỏ sốt ướp từ thịt bò. Đặt một bên. Chiên thịt bò trên cùng chảo nơi hành đã chiên trong 1 phút mỗi mặt. Lấy ra khỏi chảo. Đặt một bên", "3. Thêm dầu nếu cần. Xào tỏi và hành còn lại cho đến khi hành mềm.", "4. Đổ sốt ướp còn lại và nước vào. Đun đến sôi.", "5. Thêm thịt bò. Đậy nắp chảo và hầm cho đến khi thịt mềm. Lưu ý: Thêm nước nếu cần.", "6. Nems tiêu đen xay và muối nếu cần. Đặt hành chiên lên trên.", "7. Chuyển sang đĩa phục vụ. Phục vụ nóng. Chia sẻ và ăn ngon!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('982382d2-cbda-5544-bfce-d45b80311a00', 'fda67982-c921-54e6-9568-e2184abae4d6', 453.6, 'g'::public.quantity_unit);
