INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0250b974-aed5-5374-8cfe-321e030acbd1', 'Cháo bò caldereta', 'man'::public.dish_category, '["0. Đun dầu trong nồi nấu. Xào hành và tỏi cho đến khi hành mềm", "1. Thêm thịt bò. Xào cho đến khi phần bên ngoài hơi vàng.", "2. Thêm nước tương. Đổ sốt cà chua và nước. Đun sôi.", "3. Thêm viên Knorr Bò. Đậy nắp nồi áp lực. Nấu 30 phút.", "4. Chiên chảo cà rốt và khoai tây cho đến khi vàng. Đặt một bên.", "5. Thêm ớt, pate gan và bơ đậu phộng. Khuân.", "6. Thêm ớt chuông, khoai tây chiên và cà rốt. Đậy nắp nồi. Tiếp tục nấu 5 đến 7 phút.", "7. Nems muối và tiêu đen xay. Phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('0250b974-aed5-5374-8cfe-321e030acbd1', 'fda67982-c921-54e6-9568-e2184abae4d6', 2000.0, 'g'::public.quantity_unit);
