INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ea8e1473-8eef-543f-874a-8861eeae612f', 'Bò asado Philippines', 'man'::public.dish_category, '["Trộn thịt bò, tiêu đen đã nghiền, nước tương, giấm, lá nguyệt quế khô, chanh vàng và sốt cà chua. Khuân tốt. Ướp thịt bò ít nhất 30 phút.", "Đặt thịt bò đã ướp vào nồi nấu cùng sốt ướp còn lại. Thêm nước. Đun đến sôi.", "Thêm viên Knorr Bò. Khuân. Đậy nắp nồi và nấu 40 phút trên lửa nhỏ.", "Lật thịt bò ngược lại. Thêm sốt cà chua đặc. Tiếp tục nấu cho đến khi thịt bò mềm. Đặt một bên.", "Đun dầu trong chảo. Chiên khoai tây cho đến khi vàng. Lật lại và tiếp tục chiên mặt kia. Lấy ra khỏi chảo và đặt trên đĩa sạch. Làm tương tự với cà rốt.", "Giữ 3 muỗng canh dầu nấu từ chảo nơi khoai đã chiên. Xào hành và tỏi cho đến khi hành mềm.", "Đổ sốt từ cháo bò vào. Đun sôi. Thêm thịt bò. Nấu 2 phút.", "Thêm bơ và để nung chảy. Tiếp tục nấu cho đến khi sốt cạn một nửa."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('ea8e1473-8eef-543f-874a-8861eeae612f', 'fda67982-c921-54e6-9568-e2184abae4d6', 1500.0, 'g'::public.quantity_unit);
