INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('edc71525-9eaf-51e2-a99e-1ee187c42bb4', 'Cà tím chiên giòn (Crispy Eggplant)', 'rau'::public.dish_category, '["Cắt cà tím thành lát dày 1 cm. Đặt chúng vào bát và rắc muối. Để chúng nằm trong 30 phút để thoát một số chất liquid và đắng.", "Sau 30 phút rửa lát cà tím khỏi muối và thấm khô bằng khăn bếp.", "Trong một bát/đĩa lớn đặt bột chiên xù và hạt mè. Trong một bát khác đánh 2 trứng gà với chút muối và tiêu đen hạt/bột.", "Đun nóng dầu trong chảo lớn trên lửa cao.", "Ngâm lát cà tím vào trứng, sau đó vào bột chiên xù, và đặt vào dầu nóng. Chiên 2 đến 3 phút mỗi mặt, hoặc cho đến khi vàng nụi. Ráo lên khăn giấy."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('edc71525-9eaf-51e2-a99e-1ee187c42bb4', '1d49713a-73c2-5b5c-aaea-110ec71ca040', 1.0, 'piece'::public.quantity_unit);
