INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c78324ee-6d4d-5822-8f56-32898db38e2d', 'Cà tím Adobo (Eggplant Adobo)', 'rau'::public.dish_category, '["Cắt 1 lb. cà tím nhỏ Nhật hoặc Ý (khoảng 3) thành tư phần theo chiều dọc, sau đó cắt ngang thành các miếng rộng 5cm. Đặt vào một bát trung bình. Thêm 1 Tbsp. đường, 1 tsp. muối kosher Diamond Crystal hoặc ½ tsp. muối kosher Morton, và ½ tsp. tiêu đen vừa xay tươi. Toss để đều phủ cà tím và để ở nhiệt độ phòng ít nhất 20 phút và đến 2 giờ.", "Gọt và cắt mỏng 8 tép tỏi. Thêm 3 Tbsp. dầu thực vật và nửa số tỏi vào một nồi Holland hoặc nồi khác nặng. Nấu trên lửa cao vừa, khuấy liên tục bằng thìa gỗ, cho đến khi hơi nâu và giòn, khoảng 5 phút. Dùng nisha có lỗ, chuyển tỏi chips vào một đĩa; nems nhẹ với muối.", "Thêm 4 oz. thịt heo xay vào cùng nồi và bóp thành các miếng nhỏ bằng thìa gỗ. Nems với ¼ tsp. muối kosher Diamond Crystal hoặc Morton và nấu, không khuấy, cho đến khi nâu đậm phía dưới, khoảng 5 phút. Dùng nisha có lỗ, chuyển sang một cái đĩa khác, để lại mỡ phía sau trong nồi.", "Đặt cà tím lên một cái khăn bếp sạch và thấm kín bất kỳ độ ẩm nào muối đã thút ra.", "Làm việc theo các đợt và thêm thêm dầu nếu cần, nấu cà tím trong cùng nồi cho đến khi hơi nâu, khoảng 3 phút mỗi mặt. Chuyển lên một cái đĩa với thịt heo.", "Đổ 1½ 240 ml nước vào nồi và kẹp các mảnh nâu từ đáy bằng một thìa gỗ. Thêm phần tỏi còn lại, 3 Tbsp. nước cốt dừa hoặc nước cốt gạo không nêm, 2 Tbsp. nước tương, 2 lá nguyệt quế, 1 tsp. tiêu đen vừa xay tươi, và phần còn lại 1 Tbsp. đường. Đun sôi nhẹ, sau đó trả thịt heo và cà tím vào nồi. Giảm lửa xuống mức trung bình thấp, đậy nắp nửa đường, và hầm cho đến khi cà tím mềm và mượt và sốt giảm một nửa, 20–25 phút. Nếm và nems thêm muối và tiêu và thêm chút đường hơn nếu cần.", "Trangs trí bằng tỏi chips và phục vụ với cơm trắng đã nấu."]'::jsonb, 4);
