INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2f8dd88c-c592-5e36-a785-699e1303caf0', 'Cà tím nướng với nước cốt dừa (Grilled eggplant with coconut milk)', 'rau'::public.dish_category, '["Chuẩn bị cà tím cho nướng bằng cách chọc chúng khắp người bằng nĩa. Điều này để nó không phát nổ trong quá trình nướng khi nước tự nhiên trong nó nóng lên.", "Nướng cà tím, lật chúng thường xuyên để đảm bảo chín đều. Nướng cho đến khi vỏ màu nâu đậm, thậm chí đen và cà tím mềm khi bạn chạm vào.", "Ngâm cà tím đã nướng trong một bát nước để nguội nóng. Bóc vỏ cà tím. Đặt các cà tím nguyên vào một đĩa nông (mẹ tôi thực sự cắt cà tím thành những miếng nhỏ vừa ăn).", "Trong một bát trộn nhỏ, trộn nước cốt dừa hoặc kem, bột chanh vàng, muối và ớt cay. Trộn cho đến khi bột chanh vàng và muối tan. Thử, rồi điều chỉnh lượng bột chanh vàng, muối và ớt cay theo khẩu vị của bạn. Đổ hỗn hợp lên cà tím. Rắc hành tây lên cà tim và nước cốt dừa. Khuấy nhẹ để trộn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2f8dd88c-c592-5e36-a785-699e1303caf0', '1d49713a-73c2-5b5c-aaea-110ec71ca040', 6.0, 'piece'::public.quantity_unit);
