INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8fd941e9-061d-5ab8-9403-4aab7c2b8098', 'Cà tím chiên trứng kiểu Philippines (Tortang Talong)', 'rau'::public.dish_category, '["Nướng cà tím cho đến khi màu vỏ gần đen.", "Để cà tím nguội vài phút rồi bóc vỏ. Để một bên.", "Đập trứng vào tô.", "Thêm muối và đánh.", "Đặt cà tím trên bề mặt phẳng và dẹp bằng nĩa.", "Nhúng cà tím đã dẹp vào hỗn hợp trứng đã đánh.", "Đun nóng chảo và dầu nấu.", "Chiên cà tím (đã nhúng vào hỗn hợp trứng). Đảm bảo cả hai mặt đều chín. Thời gian chiên khoảng 3 đến 4 phút mỗi mặt trên lửa vừa."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8fd941e9-061d-5ab8-9403-4aab7c2b8098', '1d49713a-73c2-5b5c-aaea-110ec71ca040', 4.0, 'piece'::public.quantity_unit);
