INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2785a891-ddb0-54a1-8422-f52cec56a8e3', 'Súp lá cải Nga (Shchi)', 'canh'::public.dish_category, '["Thêm bơ vào nồi hầm lớn hoặc nồi nặng khác trên lửa trung bình. Khi bơ đã nung chảy, thêm hành và xào cho đến khi trong suốt.", "Thêm lá cải, cà rốt và cần tây. Xào cho đến khi các rau bắt đầu mềm, khuân thường xuyên, khoảng 3 phút.", "Thêm lá nguyệt quế và nước dùng rau và đun đến sôi trên lửa cao. Giảm lửa xuống thấp và hầm nhẹ, đậy nắp, cho đến khi các rau vừa chín còn giòn, khoảng 15 phút.", "Thêm khoai tây và đun sôi lại trên lửa cao. Giảm lửa xuống thấp và hầm nhẹ, đậy nắp, cho đến khi khoai mềm, khoảng 10 phút.", "Thêm cà chua (hoặc cà chua hộp không lọc) và đun sôi lại súp trên lửa cao. Giảm lửa xuống thấp và hầm nhẹ, không đậy nắp, trong 5 phút. Nems muối và tiêu vừa đủ.", "Bớp và vứt lá nguyệt quế khỏi nồi.", "Phục vụ với kem chua tươi và thì là tươi bên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2785a891-ddb0-54a1-8422-f52cec56a8e3', '5a79c587-c78a-529c-b4ea-eb619d193848', 45.0, 'ml'::public.quantity_unit);
