INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ea6d9b35-dd1c-5a0d-aeee-b8445b729cb2', 'Súp củ dền borscht', 'canh'::public.dish_category, '["Cắt củ dền, thêm nước và viên nuso dùng và nấu 15 phút. Thêm các nguyên liệu khác và đun sôi cho đến khi mềm. Cuối cùng thêm đậu và nấu 5 phút. Phục vụ trong nồi súp."]'::jsonb, 4);
