INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0fc584a7-626b-5558-8023-2171c49e41cd', 'Súp cá Nga (Ukha)', 'canh'::public.dish_category, '["Trong nồi vừa, đun dầu ô liu trên lửa vừa đến lớn. Thêm hành tây và nấu, thỉnh thoảng khuấy cho đến khi hành bắt đầu vàng caramel. Thêm cà rốt và nấu cho đến khi cà rốt bắt đầu mềm, khoảng 4 phút nữa.", "Thêm nước dùng cá, nước, khoai tây, lá nguyệt quế và hạt tiêu đen. Nêm muối và đun sôi. Hạ lửa, đậy nắp và nấu trong 10 phút. Thêm gạo mì và nấu thêm 15 phút cho đến khi gạo mì và khoai tây chín.", "Thêm nhẹ các miếng cá vào. Khuấy và để súp sôi nhẹ. Cá sẽ chín rất nhanh, vì vậy hãy chắc chắn không nấu quá chín. Cá chín khi thịt trong suốt và nát dễ dàng.", "Rắc thì là hoặc ngô tay cắt nhỏ lên súp trước khi ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('0fc584a7-626b-5558-8023-2171c49e41cd', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 30.0, 'ml'::public.quantity_unit);
