INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('86d7b809-f181-5c60-a44c-c31340adf42c', 'Bánh blini Nga', 'rau'::public.dish_category, '["Trong bát lớn, khuôn cùng 120 ml bột kiều mạch, 160 ml bột mì đa dụng, 1/2 muỗng cà phê muối và 1 muỗng cà phê men nở.", "Làm một hố ở chính giữa và đổ vào 240 ml sữa ấm, khuôn cho đến khi hỗn hợp mịn.", "Đậy nắp bát và để hỗn hợp nở cho đến khi dội đôi, khoảng 1 giờ.", "Làm giàu và nghỉ hỗn hợp", "Khuân 2 muỗng canh bơ đã nung chảy và 1 lòng đỏ trứng vào hỗn hợp.", "Trong bát riêng, khuôn 1 trứng gà cho đến khi ngắc, nhưng không khô.", "Khuân trứng gà đã khuôn vào hỗn hợp.", "Đậy nắp bát và để hỗn hợp nghỉ 20 phút.", "Chiên blini trong chảo", "Đun bơ trong chảo không dính lớn trên lửa trung bình.", "Thả một chút hỗn hợp kích thước đồng xu vào chảo, cẩn thận không quá đông chảo. Nấu khoảng 1 phút hoặc cho đến khi có bọt tạo thành.", "Lật và nấu thêm khoảng 30 giây.", "Lấy blini hoàn tất ra đĩa và che bằng khăn bếp sạch để giữ ấm. Thêm thêm bơ vào chảo và lặp lại quá trình chiên với hỗn hợp còn lại."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('86d7b809-f181-5c60-a44c-c31340adf42c', 'ecb91f6a-1942-55f6-905b-82549f751c6f', 120.0, 'ml'::public.quantity_unit);
