INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d65e03c4-008d-5609-aadd-457c0a847f51', 'Salad khoai tây Olivier Nga', 'rau'::public.dish_category, '["Cắt khoai tây và cà rốt thành các khối vuông nhỏ đồng đều.", "Đặt chúng vào nồi lớn và lấp đầy nước.", "Thêm muối và giấm rượu vang trắng. Đun sôi trên lửa trung bình cao, rồi giảm nhiệt xuống trung bình và tiếp tục nấu cho đến khi khoai chín đều, khoảng 15 phút. Ráo khoai và để nguội đến nhiệt độ phòng.", "Trong lúc đó, cắt xúc xích và dưa muối thành các khối nhỏ, và băm hành lá.", "Cắt trứng luộc thành các khối nhỏ cũng.", "Nếu dùng thì là tươi, băm chúng cũng.", "Trong bát lớn, trộn khoai, cà rốt, xúc xích, dưa muối, đậu Hà Lan và hành lá.", "Thêm sốt Mayonnaise và thì là và trộn cho đến khi hòa hợp tốt.", "Nems muối và tiêu theo khẩu vị. Bọc bằng ni-lông và để trong tủ lạnh ít nhất 1 giờ trước khi dùng."]'::jsonb, 4);
