INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('851c3b95-9ba6-574d-963e-f711f3cde779', 'Cơm nạo cừu Nga (Plov)', 'man'::public.dish_category, '["Cho nho khô và mận khô vào cái bát nhỏ, rót đủ nước ngập. Thêm nước cốt chanh vàng, ngâm ít nhất một giờ. Ráo. Băm thô mận khô.", "Trong lúc đó, đun nóng bơ trong chảo lớn, cho hành tây, nấu 5 phút. Cho thịt cừu thái khối, thịt cừu xay và tép tỏi nghiền, chiên 5 phút, khuấy liên tục cho vàng.", "Rót 2/3 chén (150 ml) nước dùng vào chảo. Đun sôi, hạ lửa, đậy nắp, hôi một giờ hoặc cho đến khi thịt cừu mềm.", "Thêm nước dùng còn lại và đun sôi. Cho gạo nếp dài trắng đã rửa và một chút lớn nhụy hoa nghệ tây. Khuấy, đậy nắp, hôi 15 phút hoặc cho đến khi gạo mềm.", "Thêm nho khô đã ráo, mận khô băm đã ráo, muối và tiêu theo khẩu vị. Đun nóng vài phút, rồi đổ lên đĩa dùng nóng đã ấm, trang trí bằng cành ngò tây lá phẳng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('851c3b95-9ba6-574d-963e-f711f3cde779', '53d68eb2-9589-5956-abbd-25c77ed291c9', 50.0, 'g'::public.quantity_unit);
