INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4eaf03f7-466c-5d06-9b63-a68e2a81715c', 'Bánh gà và phô mai halloumi 15 phút', 'man'::public.dish_category, '["Đặt miếng gà giữa hai tờ giấy nướng và dùng láp cuộn bột để nhẹ nhàng đập chúng cho đến khi dày khoảng 1 cm. Cắt từng miếng gà thành hai miếng đều.", "Nếu bạn dùng chảo chiên, đun nóng hai chảo trên lửa cao vừa, trong đó một chảo có dầu. Chiên gà trong chảo có dầu 3-4 phút mỗi mặt cho đến khi chúng chín qua. Nêm gà, giảm lửa, chọc sốt ớt cay và nửa nước cốt chanh vàng vào, và nấu thêm 1-2 phút cho đến khi sốt giảm bớt. Lấy gà khỏi bếp.", "Nếu bạn dùng ném không dầu, đun lò nóng 180°C trong 4 phút. Thêm gà vào ném không dầu và nấu 12 phút. Chọc sốt ớt cay và nửa nước cốt chanh vàng lên và nấu thêm 1-2 phút cho đến khi gà chín qua và sốt giảm bớt. Lấy gà ra và giữ ấm.", "Trong khi gà đang nấu, nướng bún trong chảo khô 30 giây. Chuyển chúng vào đĩa. Nếu bạn dùng ném không dầu, đặt bún vào ném không dầu 1-2 phút cho đến khi chúng ấm. Tăng nhiệt độ ném không dầu lên 200°C. Thêm phô mai vào giỏ ném không dầu và nấu 10 phút, lật giữa đường, cho đến khi chúng vàng. Trộn bắp cải với sốt mayonnaise và phần nước cốt chanh vàng còn lại.", "Cho hummus (hoặc sốt chấm bạn chọn) vào bún đã nướng, rồi đặt rau rocket, gà ớt, phô mai và ớt chuông đỏ lên trên. Chọc thêm ít sốt ớt cay hơn, rót bắp cải lên, nêm tiêu đen, và đặt nắp bún lên trên. Dùng với bắp cải thừa ở bên hoặc salad xanh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4eaf03f7-466c-5d06-9b63-a68e2a81715c', '7c9a15f2-fae9-5394-bcbb-9bbae8011db7', 2.0, 'piece'::public.quantity_unit);
