INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('42eccc60-9a04-5588-bca3-c62911858ed1', 'Bánh mì Pita chả đậu gà sốt Tahini (Falafel Pita Sandwich with Tahini Sauce)', 'rau'::public.dish_category, '["Đun nóng lò đến 230°C. Đặt bánh chả đậu gà lên khay nướng.", "Nướng trong lò đã nóng cho đến khi nóng quanh, 8 đến 10 phút.", "Trong khi chả đậu gà nướng, trộn đều sốt tahini, nước lọc, nước cốt chanh vàng, tỏi và bột ớt ngọt Paprika trong một bát.", "Cắt khoảng 2,5 cm từ trên cùng mỗi bánh mì pita để tạo túi. Thêm 2 chả đậu gà vào mỗi bánh pita cùng cùng lượng xà lách, cà chua, dưa leo, dưa leo muối và hành tím tây. Rưới mỗi bánh khoảng 1 muỗng canh sốt tahini và một chút harissa."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('42eccc60-9a04-5588-bca3-c62911858ed1', '91ec91e1-9866-5ac2-bf66-618b05f1f72c', 12.0, 'piece'::public.quantity_unit);
