INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('96dcd920-b07c-5570-8f51-7a239466303f', 'Đậu que xào dầu ô liu Syria (Fasoliyyeh Bi Z-Zayt)', 'rau'::public.dish_category, '["Đặt đậu que vào nồi lớn, rưới dầu ô liu. Nêm muối theo khẩu vị, đậy nắp. Nấu trên lửa vừa đến lớn, thỉnh thoảng khuấy, cho đến khi đậu chín theo ý bạn. Người Syria thích nấu cho đến khi đậu que chuyển thành màu nhạt vàng. Ý tưởng không phải xào, mà để đậu hơi trong lượng nước tự thoát ra.", "Thêm ngô rí và tỏi vào đậu, tiếp tục nấu cho đến khi ngô rí bắt đầu úng. Ăn như món chính bằng cách gắp với bánh mì pita nóng hoặc ăn như món phụ."]'::jsonb, 4);
