INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('312efc15-a1f7-5cec-a8c2-968b2594e209', 'Xào hash bò muối (Corned Beef Hash)', 'man'::public.dish_category, '["Xào hành tây:", "Nung bơ lạt trong chảo lớn (th hoped là chảo sắt đúc) trên lửa trung bình. Thêm hành tây và nấu vài phút, cho đến khi nhờn.", "Thêm khoai tây và Thịt bò muối đóng hộp bò muối:", "Trộn Thịt bò muối đóng hộp bò muối đã kẹo và khoai tây. Trải đều trên chảo. Tăng lửa lên cao hoặc trung bình cao và nhấn xuống hỗn hợp bằng espátula kim loại.", "Nấu cho đến khi vàng sau đó lật:", "Đ khuấy khoai tây và Thịt bò muối đóng hộp bò muối, nhưng để chúng nướng. Nếu bạn nghe chúng xì xì, điều đó tốt.", "Dùng espátula kim loại để ngắm bên dưới và xem liệu chúng có đang nướng không. Nếu đã nướng tốt, dùng espátula để lật các phần trên chảo để chúng nướng ở mặt khác. Nhấn xuống lại với espátula.", "Nếu có quá nhiều dính, bạn có thể thêm chút bơ lạt hơn vào chảo. Tiếp tục nấu theo cách này cho đến khi khoai tây và Thịt bò muối đóng hộp bò muối đều nướng tốt.", "Khuấy vào ngô tây tươi và nems:", "Nâng khỏi lửa, khuấy vào ngô tây tươi đã kẹo. Thêm nhiều tiêu đen vừa xay tươi, và thêm muối theo khẩu vị."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('312efc15-a1f7-5cec-a8c2-968b2594e209', '5a79c587-c78a-529c-b4ea-eb619d193848', 45.0, 'ml'::public.quantity_unit);
