INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c3960f8d-2e9b-5aae-8651-dc804a559849', 'Burger Úc (Aussie Burgers)', 'man'::public.dish_category, '["Làm burger: Đổ thịt vào bát và rắc 1 muỗng cà phê muối và hạt tiêu đen xay nhẹn. Tay ướt, khuân trộn gia vị vào. Chia thành 4 phần bằng tay và định hình thành các miếng burger. (Có thể đóng băng ở giai đoạn này.)", "Chuẩn bị nguyên liệu: Cắt lát củ dền chín và chia đôi bánh mì naan.", "Nướng naan: Đun nồi nướng đá hoặc nướng than. Nướng naan hai mặt cho đến khi nhẹ vàng rồi để một bên. Thêm burger vào nồi nướng hoặc nướng than và nấu 2-3 phút, rồi lật và nấu mặt kia thêm 2-3 phút.", "Ghép món: Đặt nửa miếng naan đã nướng trên mỗi đĩa phục vụ và đặt một đống rau rocket lên mỗi chiếc. Đặt burger lên trên, rồi vài lát củ dền chín và một chút kem chua. Rắc muối và tiêu đen xay tươi và ăn ngay với salad xanh lớn và khoai chips. Một ly rượu đỏ cũng không hề sai."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c3960f8d-2e9b-5aae-8651-dc804a559849', '39fb3f05-ea65-5925-ba66-5507beaa02c1', 500.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c3960f8d-2e9b-5aae-8651-dc804a559849', 'd6cd5910-011f-5588-ac85-d2ae49a7e24f', 100.0, 'g'::public.quantity_unit);
