INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('46fd9ae2-efab-51b7-8175-5c0bce2df3be', 'Salad mực, đậu gà và xúc xích (Squid, chickpea & chorizo salad)', 'man'::public.dish_category, '["Nấu ớt chuông nguyên dưới nồi nướng, trên n than hoặc chảo nướng, cho đến khi cháy khét hoàn toàn. Đặt ớt chuông vào bát, phủ bằng đĩa cho đến khi đủ mát để bắt tay, rồi bóc vỏ, lấy hạt và cắt mỏng. Trong bát lớn trộn ớt chuông và bất kỳ nước cốt nào với đậu gà, ngô tây, ớt và tỏi. Để riêng.", "Đun chảo xào lớn cho đến khi khói. Làm việc nhanh và cẩn thận, thêm chút dầu vào chảo, rồi mực. Xào trong khoảng 30 giây. Rắc xúc xích Chorizo lên trên mực, tiếp tục nấu thêm 30 giây nữa, rồi đổ vào bát với ớt chuông. Nems mọi thứ với muối và tiêu, rồi đậy với dầu còn lại, nước cốt chanh và vỏ chanh. Trộn chung, đống lên đĩa và để mọi người tự lấy."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('46fd9ae2-efab-51b7-8175-5c0bce2df3be', '1464765e-f3b9-52a0-9ee3-27e1a66845a3', 4.0, 'piece'::public.quantity_unit);
