INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('491260ba-4b21-54ae-8790-1cff95584d1f', 'Gà nướng n than khói gia vị (Spiced smoky barbecued chicken)', 'man'::public.dish_category, '["Làm nước ướp. Nát tỏi với một ít muối bằng cối và chùy. Thêm vỏ và nước cốt chanh, hỗn hợp gia vị, ớt, dầu và một ít tiêu đen nghiền. Trộn thành bot. Có thể làm trong máy xí nhuyễn nhỏ.", "Trộn gà trong nước ướp và để riêng trong khi bạn đốt n than. Khi n than nóng, đặt các bó thảo mộc trên lưới và đặt gà, phần da lên trên, trên đó. Đậy nắp, nếu n than của bạn có nắp, và nấu gà trên các thảo mộc khói trong khoảng 10 phút cho đến khi thịt bắt đầu đổi màu. Lật gà và tiếp tục nấu thêm 20-30 phút, lật nếu cần, cho đến khi hơi cháy từ thảo mộc bị cháy và chín đến xương."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('491260ba-4b21-54ae-8790-1cff95584d1f', 'a8db4b95-a126-5f43-a0b4-2c29ba37261d', 2.0, 'piece'::public.quantity_unit);
