INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6c84cb51-4b6f-5a34-b7a1-97c8dd2d4f2d', 'Salad măng tây nướng ấm (Warm roast asparagus salad)', 'man'::public.dish_category, '["Đun lò 200°C. Gãy các đầu măng tây gỗ vớt và loại bỏ. Sắp xếp măng tây thành một lớp trong khay nướng có viền. Cắt cà chua thành nửa theo chiều ngang, nhét chúng vào với măng tây, nêm muối biển và tiêu và chọc dầu ô liu nguyên chất. Cuộn từng lát xông khói thành một cuốn chặt (nếu lớn, trước tiên cắt nửa theo chiều ngang), và sắp xếp trong khay. Chọc các cuốn xông khói với mật ong và nướng 20 phút cho đến khi cà chua mềm và xông khói giòn.", "Trong khoảng thời gian này, luộc khoai tây cho đến khi mềm. Đánh trộn giấm rượu vang đỏ, dầu ô liu nguyên chất, mù tạt Dijon, ít muối biển và tiêu trong tô lớn cho đến khi trộn đều. Trộn lá rocket hoặc rau chân vịt trong nửa sốt, và sắp xếp trên đĩa dùng lớn.", "Rổ khoai tây và cắt nửa. Trộn nhẹ chúng trong phần sốt còn lại, và sắp xếp trên đĩa cùng với măng tây. Xếp cà chua và xông khói vào."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6c84cb51-4b6f-5a34-b7a1-97c8dd2d4f2d', 'd752330f-fc8d-529d-98a9-252fff3c7e9c', 500.0, 'g'::public.quantity_unit);
