INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('258abd74-06e2-5b8c-aeea-40a633e5acbe', 'Sốt bơ quả khoai non', 'rau'::public.dish_category, '["Xay nửa thịt bơ quả với sữa chua, nước chanh xanh và chanh vàng cùng gia vị. Cắt bơ quả còn lại thành các khối nhỏ, rồi nhẹ nhàng khuân vào hỗn hợp đã xay với phần lớn vỏ chanh xanh nhát. Đậy nắp, rồi để trong tủ lạnh cho đến khi sẵn sàng phục vụ.", "Luộc khoai non 6 phút, rồi để thoát nước và trộn với dầu ô liu, bột ớt cay và hạt cumin. Để một bên cho đến nửa giờ trước khi khách đến.", "Đun lò đến 200°C, rồi nướng khoai khoảng 30 phút, lắc khay ở giữa, cho đến khi vàng và mềm. Chuyển sốt vào một hoặc hai bát, rắc vỏ chanh xanh còn lại và phục vụ với khoai nóng, và bánh tortilla để chấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('258abd74-06e2-5b8c-aeea-40a633e5acbe', '3aee4899-cf28-5fd7-8902-263b783b7669', 3.0, 'piece'::public.quantity_unit);
