INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6a4eead1-4ba2-57f2-8578-8f425eb48ab9', 'Mực muối tiêu nhanh Úc', 'man'::public.dish_category, '["Hỏi người bán cá làm sạch mực; những con nhỏ thường đã được làm sẵn. Dùng kéo bếp, cắt mở thân và trải ra. Rửa sạch, rồi thấm khô. Nếu bạn có con mực lớn, cắt thân thành bốn phần, hình vuông roughly. Mực nhỏ có thể chỉ trải ra.", "Dùng đầu dao rất nhọn, chéo gicanos trên mặt trên thành hình vuông chéo gọn. Sơn dầu và để riêng trong khi bạn đun nướng than hoặc nồi nướng cho đến khi sẵn sàng nấu.", "Trộn cùng 2 muỗng cà phê muối biển, bột ngũ vị hương và 1 muỗng cà phê tiêu đen xay tươi. Rắc lên cả hai mặt của mực ngay trước khi nấu, theo khẩu vị. Bạn có thể không dùng hết. Đun nồi nướng cho đến khi nóng và nấu khoảng 1 phút mỗi mặt, cho đến khi nó bắt đầu cuộn. Vớt bằng kẹp vào đĩa dùng và rưới chút dầu mè. Khi dùng, trang trí với lá ngô rí và dùng với các bát nhỏ sốt ớt ngọt để nhúng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6a4eead1-4ba2-57f2-8578-8f425eb48ab9', '5faff7d3-f5be-5380-b3ef-afaf04a882ee', 400.0, 'g'::public.quantity_unit);
