INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('13322895-58be-5c25-afc7-682db40b1aed', 'Bánh pudding cay bò mini', 'man'::public.dish_category, '["Làm sốt cay: đun dầu trong chảo và chiên hành 5 phút cho mềm. Thêm gia vị; chiên 1 phút. Khuấy thịt bò xay vào và nấu vài phút. Thêm cà chua xay nhuyễn, nước dùng và quế. Khuấy, đun sôi rồi hôi 15-20 phút cho đến khi còn ít nước. Thêm đậu đỏ trước 5 phút cuối nấu. Kiểm tra nems nếm và để nguội.", "Đậy lò 200°C. Dùng cutter đường kính 7 cm, cắt ra 12 vòng tròn từ vở bánh. Dùng để đựm khay muffin mini 12 lỗ, chọc lỗ đáy vở bằng nĩa, và nướng 10 phút. Vớt ra khỏi lò để nguội trên khay thép. Làm tương với phần vở còn lại.", "Trong lúc đó, luộc khoai trong nước sôi cho đến khi mềm. Ráo, nghiền với kem chua và nems nếm, rồi khuấy hành tỉa. Cho 1-2 muỗng cà phê hỗn hợp cay vào các khay vở và phủ một muỗng cà phê khoai nghiền. Khuấy khoai bằng nĩa; trả lại lò 15 phút hoặc cho đến khi vàng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('13322895-58be-5c25-afc7-682db40b1aed', 'abf28cb9-6b57-51e1-afcd-16e32ca2cb8b', 450.0, 'g'::public.quantity_unit);
