INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('34c4a30d-f09b-5d88-981e-12da4508bdaa', 'Gà dính ngọt (Sticky Chicken)', 'man'::public.dish_category, '["Làm 3 vết chọc trên mỗi miếng gà. Trộn xì dầu, mật ong, dầu, sốt cà chua xay nhuyễn và mù tạt. Đổ hỗn hợp này lên gà và phủ kỹ. Để ướt trong 30 phút ở nhiệt độ phòng hoặc qua đêm trong tủ lạnh. Đun lò lên 200°C.", "Đổ gà vào khay nướng và nướng trong 35 phút, lật đôi khi, cho đến khi gà mềm và bóng nhánh với nước ướp."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('34c4a30d-f09b-5d88-981e-12da4508bdaa', '992be00b-b0c9-5ba3-abe8-c9cb5823b5e3', 8.0, 'piece'::public.quantity_unit);
