INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e91eeb2e-9fae-5ae3-a8bd-e235ed4e8d44', 'Cà ri bò Kenya (Kenyan Beef Curry)', 'man'::public.dish_category, '["Đun 960 ml nước đến sôi trong nồi Hà Lan hoặc nồi súp. Thêm bò, tỏi, và gừng, và khuấy tốt. Đun sôi nhẹ, đậy nắp, và nấu, khuấy thỉnh thoảng, trong 20 phút. Nếu bạn có bất kỳ bọt nhựa nào trên đầu, không sao, chỉ cần dùng muỗng lấy nó đi hoặc khuấy nó trở lại.", "Bớt khỏi lửa, và ráo, nhưng giữ lại lượng nước thừa sau này.", "Trả nồi hoặc nồi Hà Lan trở lại lửa vừa với 2 muỗng canh dầu nấu. Khi dầu bắt đầu i nhú, thêm hành tây và nấu, khuấy thỉnh thoảng, cho đến khi mềm, 5 đến 7 phút.", "Thêm cà chua vào hành tây, và tiếp tục nấu, khuấy thỉnh thoảng, cho đến khi cà chua đang rã, 3 đến 5 phút.", "Thêm bò đã ráo vào hỗn hợp cà chua và hành tây, và khuấy tốt. Tiếp tục nấu trên lửa vừa trong 5 phút, khuấy thỉnh thoảng.", "Thêm paprika, tiêu, bột cà ri, sốt cà chua, và muối theo khẩu vị, và khuấy tốt.", "Thêm trở lại lượng nước thừa đã được dùng để nấu bò, cùng với đủ nước thêm để ngâm. Đun sôi, giảm lửa, và hầm nhẹ, không đậy nắp, khuấy thỉnh thoảng, trong khoảng 1 giờ, hoặc cho đến khi thịt mềm và sốt đã đặc. Thêm nước thêm nếu cà ri bò của bạn bắt đầu khô và dính, hoặc nếu bạn muốn cà ri của bạn có tính chất súp hơn.", "Khi cà ri bò đã sẵn sàng, bớt khỏi lửa, thử một chút, và điều chỉnh gia vị theo ý thích. Rắc ớt tươi và ngô rí lên trên."]'::jsonb, 4);
