INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('25a80ffa-99a1-5ec6-a3b5-949dc8f93e29', 'Cải xoăn xào hành kiểu Kenya (Sukuma Wiki)', 'rau'::public.dish_category, '["Đun nóng 2 muỗng canh dầu trong chảo xào lớn hoặc nồi trên lửa vừa cho đến khi rọi. Thêm hành tây và nấu, khuấy đôi khi, cho đến khi mềm, 5 đến 7 phút.", "Thêm cải xoăn đã xé vào hành tây và trộn tốt. Xoay lửa về vừa-thấp, nắp và nấu trong 5 phút.", "Sau 5 phút, mở nắp, thêm muối theo khẩu vị, và khuấy vào kem. Tiếp tục nấu thêm 5 phút, không nắp, khuấy đôi khi. Kem sẽ đặc hơi, tạo ra cải xoăn kem và hành ngon quá!", "Phục vụ nó với món hầm Kenya yêu thích của bạn, và một bên ugali!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('25a80ffa-99a1-5ec6-a3b5-949dc8f93e29', 'f9ef1ba9-7da5-599e-ad08-11ab8b7e76d9', 30.0, 'ml'::public.quantity_unit);
