INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e8edecec-525d-5aba-9491-dd8dc24db9e6', 'Hành tím ngâm chua (Red onion pickle)', 'rau'::public.dish_category, '["Bỏ vỏ hành tím tây, c đôi theo chiều từ trên xuống dưới rồi cắt mỏng thành miếng nửa bulan. Cho vào lá rổ đặt trên bát, rắc muối biển, lắc nhẹ nhàng miếng hành bằng tay cho bề mặt đều được phủ. Để riêng khoảng một giờ để muối ngâm.", "Trong lúc đó, cho giấm táo, 50 ml nước và đường cát trắng vào một nồi. Đun sôi nhỏ lửa, khuấy cho đường tan, sau đó nấu vài phút. Để riêng.", "Đổ hành tím tây vào bình đã khuẩn trùng, rắc một ít tiêu đen khi đổ. Phủ bằng giấm táo ấm, chèn vài lá nguyệt quế vào bên trong bình. Đóng nắp. Hành ngâm ngon nhất khi để trong tủ lạnh và dùng trong vòng 4 tuần."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('e8edecec-525d-5aba-9491-dd8dc24db9e6', 'caf82c3b-825a-5c73-bf1b-e7186bcd700b', 3.0, 'piece'::public.quantity_unit);
