INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('dbdc7ac6-f2ca-55a4-9902-016daa4ea1fb', 'Smørrebrød măng tây sốt cren (Nordic smørrebrød)', 'rau'::public.dish_category, '["Làm sốt cren: trộn kem tươi Crème Fraîche, cren bào, nước cốt chanh, muối và tiêu trắng trong bát. Để trong tủ lạnh đến khi dùng.", "Làm hành tím giòn: đun ít dầu ăn trong chảo trên lửa vừa. Cho hành tím lát vào và chiên cho đến khi vàng và giòn.", "Vớt bằng cuch đón ráo và để ráo trên đĩa đựng khăn giấy giấy bếp. Nems một chút muối.", "Làm bánh mở: đun sôi nồi lớn nước có muối, rồi luộc nửa số măng tây (bốn trắng và bốn xanh) cho đến khi vừa nhừ giòn, khoảng 2-3 phút.", "Thêm đá vào bát nước lạnh. Dùng cuch đón ráo để lấy măng từ nước sôi và ngay lập tức chuyển vào nước đá để dừng nấu. Lát mỏng phần măng còn lại theo chiều dọc để dùng sống.", "Đ予 grill cho đến khi nóng. Đổ bơ lên bánh mì đen lúa mạch Rye và nướng cho đến khi vàng và giòn.", "Khi dùng, đặt lát bánh nướng lên đĩa dùng. Xếp cả măng đã luộc và sống lên bánh. Rưới sốt cren, rồi rắc phô mai bào lên trên. Trangs trí với hành tím giòn và chút thì là tươi để hoàn thành."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('dbdc7ac6-f2ca-55a4-9902-016daa4ea1fb', '9cd7e8b2-0290-5c07-9703-780a26a7ad15', 150.0, 'ml'::public.quantity_unit);
