INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('bde47c0e-f777-5d50-b5e9-6746e8ba3937', 'Bánh mì khoai tây Luệp Na Uy (Norwegian Potato Lefse)', 'rau'::public.dish_category, '["Luộc khoai tây. Bóc vỏ khoai khi còn ấm và qua máy nghiền khoai hai lần.", "Để khoai nguội trong bát không nắp trong tủ lạnh.", "Trộn muối, đường, bơ chảy và kem vào khoai nghiền.", "Thêm bột chậm rãi và nhéen bằng tay cho đến khi được độ stabilize. Không thêm nhiều bột hơn cần thiết! Cuộn bột thành xúc xích dài và chia thành khoảng 7 hoặc 8 miếng nếu dùng nướng 18 inch. Nếu dùng nướng nhỏ hơn hoặc chảo chiên, chia bột thành 10 – 12 miếng.", "Cuộn từng miếng thành quả rồi nhấn thành hình tròn, dùng cạnh tay để tạo bột thành hình tròn không nứt. Điều này quan trọng, nếu không bạn sẽ không có lefser tròn.", "Đun nướng lên lửa vừa/cao.", "Rắc bột lên bề mặt làm việc và luồn bột lefse thành hình tròn lớn hơi nhỏ hơn nướng hoặc chảo chiên của bạn. Bắt đầu luồn với quello trơn nhẵn, rồi chuyển sang quello xiệp khi lefse mỏng hơn. Đừng dùng quá nhiều bột, nếu không cạnh có thể cứng.", "Cuộn lefse lên que lefse rồi nhẹ nhàng desembalo nó lên nướng. Sau một hai phút kiểm tra mặt dưới lefse cho điểm nâu rồi dùng que lefse để lật lefse và nấu mặt kia.", "Dùng que lefse để lấy lefse khỏi nướng và đặt nó lên khăn hoặc khăn bếp ẩm gấp lại."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bde47c0e-f777-5d50-b5e9-6746e8ba3937', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1360.8, 'g'::public.quantity_unit);
