INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c708bc45-8ad7-53f7-beb5-748b8bdc49f0', 'Súp cá kem Na Uy (Fiskesuppe)', 'canh'::public.dish_category, '["Cắt filê cá thành khối hoặc sợi. Nát hoặc băm tỏi. Rửa rau và cắt thành sợi mỏng.", "Cho bơ vào nồi và thêm tỏi. Khi tỏi bắt đầu vàng, thêm bột mì, đánh trộn tốt.", "Thêm nước dùng cá và tiếp tục đánh trộn cho đến khi không còn cục.", "Thêm rau và sữa và đun sôi. Nấu khoảng 10 phút.", "Thêm kem tươi Crème Fraîche (hoặc kem chua). Đun súp trở lại sôi nhẹ và khi súp bắt đầu nôi trở lại tắt lửa. Giữ súp trên bếp và thêm cá. Để cá nấu trong súp nóng trong 5 phút. Nếu dùng tôm, thêm ngay trước khi ăn.", "Rắc hẹ (hoặc thì là hoặc ngô tay) trước khi ăn."]'::jsonb, 4);
