INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('49427124-0717-56b5-82a2-98d45383d284', 'Món hầm cừu cải trắng Na Uy (Fårikål)', 'man'::public.dish_category, '["Cắt thịt cừu thành miếng lớn.", "Cắt cải trắng thành lát lớn, giữ gốc cải.", "Đặt một lớp thịt cừu vào đáy nồi lớn, phần mỡ xuống dưới. Rắc hạt tiêu đen và muối. Đặt một lớp cải trắng lên trên. Lặp lại với thêm lớp thịt cừu, hạt tiêu và cải, kết thúc với lớp cải ở trên cùng.", "Tùy chọn: Rắc một vài muỗng canh bột mì lên trên thịt cừu để súp đặc hơn.", "Thêm nước vào nồi và đun sôi. Đậy nắp và hạ lửa. Hầm trên lửa nhẹ 2 – 3 tiếng, cho đến khi thịt cừu tự rời xương.", "Ăn với khoai tây luộc và ngô tay tươi, rót nước dùng fårikål lên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('49427124-0717-56b5-82a2-98d45383d284', '53d68eb2-9589-5956-abbd-25c77ed291c9', 1360.8, 'g'::public.quantity_unit);
