INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('039d6ca2-6efa-54cf-8ba4-9798e1b75c57', 'Bánh dumpling Raspeballer Na Uy', 'man'::public.dish_category, '["Raspeballer & (Tuỳ chọn) Thịt muối", "Nếu bạn làm giò heo, nấu trong nước hôi khoảng 3 giờ, cho đến khi thịt rụng từ xương. Vớt heo ra và giữ lại nước dùng để nấu raspeballer.", "Luộc khoai đã luộc và bóc vỏ khi đã nguội. Cũng bóc vỏ khoai sống, rồi bào hoặc xay qua máy xay thực phẩm. Dùng khăn giấy để loại bỏ một số độ ẩm từ khoai đã bào.", "Nghiền khoai đã luộc bằng máy nghiền khoai hoặc máy nghiền. Đảm bảo không còn cục. Thêm khoai sống đã bào vào khoai nghiền trong bát trộn lớn và khuấy cùng nhau. Thêm bột lúa mạch, bột mì đa dụng, và muối và trộn bằng tay cho đến khi hỗn hợp hoàn toàn hòa quyện.", "Bạn có thể nấu raspeballer trong nước dùng rau hoặc bò, hoặc nếu bạn làm giò heo, nấu chúng trong nước dùng từ giò heo. Đun nước dùng lên hơi hơi rất nhẹ – bạn không muốn nó sôi đầy đủ vì thì raspeballer có thể b vỡ.", "Dùng muỗng canh nhúng vào nước lạnh để định hình mỗi raspeball trong tay bạn. Cố gắng làm chúng mịn nhất có thể rồi nhẹ nhàng thả chúng vào nước dùng đang hôi. Nhúng muỗng canh vào bát nước lạnh giữa mỗi raspeball.", "Để raspeballer hôi khoảng 30 phút. Nếu bạn làm xúc xích hun khói, bạn có thể đun nóng xúc xích trong cùng nồi với raspeballer. Trangs trí với ngô tây tươi đã băm.", "Khoai nghiền củ cải Thụy Điển", "Bóc vỏ củ cải Thụy Điển và cà rốt và cắt thành các miếng nhỏ. Luộc trong nước khoảng 30 phút, hoặc cho đến khi mềm. Rồi ráo nước, thêm kem/sữa, bơ và nhục đậu khấu và nghiền cho đến khi mịn.", "Dùng kèm với raspeballer và thịt."]'::jsonb, 4);
