INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fc7c0370-9d73-524e-930c-db7a27473b7a', 'Bánh nướng bò gầy Đan Mạch với hành tây caramel (Karbonader (Lean Beef Patties) with Caramelized Onions)', 'man'::public.dish_category, '["Xay nửa một củ hành và để một bên. Cắt phần hành còn lại thành lát và chiên trong bơ trên lửa thấp/vừa cho đến khi caramel hóa.", "Trong bát, trộn thịt bò xay, hành đã xay, muối, tiêu, nhục đậu khấu, bột bắp/nước cất khoai, và nước.", "Hình thành một xúc xích và cắt 6 bánh. Dùng dao làm một dạng lưới nhẹ trên mỗi bánh.", "Chiên cả hai bên của bánh nướng bò trong bơ trên lửa cao, rồi giảm lửa xuống thấp và chiên thêm 2 – 3 phút.", "Ăn bánh nướng bò và hành với khoai tây, đậu Hà Lan hầm, và sốt nâu cho bữa tối, hoặc trên một lát bánh mì cho trưa hoặc ăn vặt."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('fc7c0370-9d73-524e-930c-db7a27473b7a', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 2.0, 'piece'::public.quantity_unit);
