INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('acc374c0-c0e4-5b3b-947f-cd68cff64109', 'Cháo bò rau giá Norway (Brun Lapskaus)', 'man'::public.dish_category, '["▢", "Đun dầu ô liu trong nồi lớn. Cắt thịt bò thành các khối 2,5 cm và rang trong dầu.", "▢", "Cắt hành thành khối và thêm vào thịt đang rang. Thêm nước dùng và đun đến sôi, rồi giảm lửa, đậy nắp, và để hầm trong khoảng 30 phút.", "▢", "Bóc và cắt cải Thụy Điển và cần tây thành các khối 2,5 cm. Thêm vào nồi, đậy nắp, và tiếp tục hầm thêm 30 phút.", "▢", "Bóc và cắt các rau còn lại thành các khối 2,5 cm và thêm vào nồi. Cắt hành lá thành các vòng. Đậy nắp và tiếp tục hầm khoảng 20 phút. Khuân ít càng tốt.", "▢", "Trang trí bằng ngô tây tươi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('acc374c0-c0e4-5b3b-947f-cd68cff64109', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 30.0, 'ml'::public.quantity_unit);
