INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8baf1a1e-1553-57c8-a5c5-a5b1b843d677', 'Bò nướng asado (Asado)', 'man'::public.dish_category, '["Chuẩn bị lửa: Bật lửa củi trong nồi nướng và để cháy xuống thành than.", "Nêm thịt: Nems muối nhiều cho các lát thịt bò.", "Nướng thịt: Đặt thịt bò lên nồi nướng, bắt đầu với các miếng dày nhất xa than nhất. Thêm chorizo và morcilla sau khi thịt bò đã nướng một thời gian.", "Nấu cho đến khi hoàn hảo: Nấu thịt, quay đôi khi, cho đến khi đạt độ chín mong muốn. Thông thường, xương sườn có thể mất tới 2 giờ; các miếng mỏng sẽ nấu nhanh hơn.", "Nghỉ và phục vụ: Để thịt nghỉ khoảng 10 phút trước khi cắt lát. Phục vụ kèm sốt chimichurri và rau nướng.", "Mẹo:", "Dùng hỗn hợp củi và than làm nguồn nhiệt ổn định. Củi tạo hương vị, còn than duy trì nhiệt độ.", "Nems thịt ngay trước khi nướng để giữ độ ẩm và hương vị.", "Gợi ý phục vụ:", "Phục vụ kèm sốt chimichurri, salad cà chua tươi và bánh mì vỏ giòn. Kết hợp với rượu vang Malbec đậm đà để hoàn thiện hương vị thịt."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8baf1a1e-1553-57c8-a5c5-a5b1b843d677', 'b3c6a234-3ea3-55d4-9399-17088507c3f9', 2000.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8baf1a1e-1553-57c8-a5c5-a5b1b843d677', '95b2c047-4a6d-559d-8b89-d93b756d6ad4', 4.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8baf1a1e-1553-57c8-a5c5-a5b1b843d677', '51ae486d-889a-5f8c-8c00-cf81185e06da', 2.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('884805c3-025a-508f-aad7-7e546d624123', 'Empanadas Argentina (Empanadas)', 'man'::public.dish_category, '["Làm vở bánh: Trộn bột mì và muối trong một bát lớn. Thêm bơ, dùng ngón tay của bạn để nhuyễn thành một hỗn hợp vụn. Dần dần thêm nước, trộn cho đến khi tạo thành bột. Bọc và để trong tủ lạnh trong 30 phút.", "Chuẩn bị phần nhân: Nấu hành tây trong chảo cho đến khi nhờn. Thêm thịt bò xay, nấu cho đến khi nâu. Khuấy vào gia vị, sau đó nâng khỏi lửa. Khi đã nguội, trộn vào trứng gà và quả ô liu xanh.", "Lắp ráp: Lăn vở bánh ra và cắt thành các vòng. Đặt một thìa soupe của phần nhân vào mỗi cái, gấp lại, và kín các cạnh.", "Nấu: Nướng ở 200°C trong 20-25 phút, hoặc cho đến khi vàng.", "Mẹo:", "Đối với vở bánh giòn hơn, thêm một thìa soupe giấm vào hỗn hợp vở bánh. Điều này giúp ngăn hình thành gluten.", "Kín các cạnh của empanadas bằng một cái nĩa để đảm bảo chúng không mở trong quá trình nướng hoặc chiên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('884805c3-025a-508f-aad7-7e546d624123', '7d6a1f7e-745c-5cd6-af33-19568749147f', 500.0, 'g'::public.quantity_unit);
