INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('dd9533d3-eb40-525e-b809-b17a68b18cfd', 'Milanesa', 'man'::public.dish_category, '["Nems miếng cốt lết: muối và tiêu.", "Bám bánh mì: nhúng mỗi miếng vào trứng, rồi phủ với hỗn hợp bột chiên xù, ngô tây và tỏi.", "Chiên: Đun dầu trong chảo lớn trên lửa vừa. Chiên cốt lết cho đến khi vàng và chín đều, khoảng 3-4 phút mỗi mặt.", "Đặt ra: Dùng nóng với lát chanh hoặc salad phụ.", "Mẹo:", "Để lớp vỏ giòn thêm, dùng bột chiên xù panko trộn phô mai Parmesan đã bào mịn.", "Đánh nhẹ cốt lết cho độ dày đều để nấu đồng đều."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('dd9533d3-eb40-525e-b809-b17a68b18cfd', 'b0eb7e79-b177-570c-8769-655f9bbb837a', 4.0, 'piece'::public.quantity_unit);
