INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('dd9533d3-eb40-525e-b809-b17a68b18cfd', 'a8db4b95-a126-5f43-a0b4-2c29ba37261d', 2.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c0f2be5e-3c2e-55a4-b68f-886c4b0e0753', 'Choripán (Choripán)', 'man'::public.dish_category, '["Nướng xúc xích Chorizo: Nấu xúc xích Chorizo trên nướng hoặc chảo cho đến khi chín qua, khoảng 10-15 phút.", "Chuẩn bị bánh: Cắt các bánh và nướng nhẹ trên nướng hoặc trong chảo.", "Lắp ráp: Cắt mỗi xúc xích Chorizo theo chiều dài và đặt vào bánh. Phủ một lượng lớn sốt Chimichurri.", "Phục vụ: Thưởng thức ngay khi nóng.", "Mẹo: Nướng xúc xích Chorizo chậm trên lửa trung bình để ngăn vỡ da và đảm bảo nó chín đều khắp nơi.", "Nướng bánh trên nướng để hấp thụ một số hương vị từ xúc xích Chorizo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c0f2be5e-3c2e-55a4-b68f-886c4b0e0753', '95b2c047-4a6d-559d-8b89-d93b756d6ad4', 4.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c0f2be5e-3c2e-55a4-b68f-886c4b0e0753', 'c4d71647-7464-582d-9444-ccd7c98202a8', 4.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c0f2be5e-3c2e-55a4-b68f-886c4b0e0753', 'df25f695-5e0b-5f1b-b35b-9c36d7a1c708', 5.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a992fadd-3927-586a-8a42-d1a35f8bc1de', 'Bánh bột đậu gà Argentina (Fainá)', 'rau'::public.dish_category, '["Chuẩn bị hỗn hợp bột: Trộn đều bột đậu gà, nước lọc, muối và tiêu đen. Để ít nhất 4 tiếng.", "Nướng: Đun nóng lò đến 220°C. Đổ dầu ô liu vào đĩa nướng tròn và đun nóng trong lò. Đổ hỗn hợp bột vào và nướng 25-30 phút, cho đến khi vàng.", "Pha vụn: Cắt lát và ăn nóng, có thể thêm tiêu đen ở trên.", "Mẹo: Để hỗn hợp bột nghỉ ít nhất 2 tiếng, hoặc qua đêm trong tủ lạnh, để đảm bảo bột đậu gà hấp thụ nước đủ và hương vị hòa quyện.", "Để viền giòn, đun nóng khay nướng với dầu trong lò trước khi thêm hỗn hợp bột."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a992fadd-3927-586a-8a42-d1a35f8bc1de', 'a17ac7a3-9fdb-5ddd-9dd9-b64bd91b98d8', 200.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a992fadd-3927-586a-8a42-d1a35f8bc1de', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 600.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a992fadd-3927-586a-8a42-d1a35f8bc1de', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 60.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d3fa2459-d8c0-547a-bbeb-05b7ded6e026', 'Matambre nướng phô mai (Matambre a la Pizza)', 'man'::public.dish_category, '["Chuẩn bị miếng thịt: Nems muối tiêu. Nướng một mặt cho đến khi chín nửa.", "Thêm phần tráng: Rải sốt cà chua lên mặt đã nướng, rồi thêm phô mai, hoặc hy lạp và ô liu xanh.", "Hoàn thiện nướng: Nướng cho đến khi phô mai tan và nổi bọt.", "Đặt ra: Cắt lát và dùng nóng.", "Mẹo nấu:", "Làm mềm matambre bằng cách rạch nhẹ hai mặt. Điều này giúp nấu đều và thấm vị hơn.", "Nướng nửa chín matambre trên lò nướng trước khi thêm phần tráng để đảm bảo chín đều mà không cháy phô mai."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d3fa2459-d8c0-547a-bbeb-05b7ded6e026', '23d8e1a8-6a9c-56ff-851f-6ff8e6f1198d', 1000.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d3fa2459-d8c0-547a-bbeb-05b7ded6e026', 'b9dcd0e0-435c-580c-a424-d8c84834901e', 200.0, 'g'::public.quantity_unit);
