INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d3fa2459-d8c0-547a-bbeb-05b7ded6e026', '0ad607e1-23a9-52d9-a46c-544fd5376e56', 100.0, 'g'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6d2d716d-55f6-5d8d-961b-357a119d187e', 'Bò hầm rau quả kiểu Argentina (Carbonada Criolla)', 'man'::public.dish_category, '["Đun ninh thịt bò: Trong nồi lớn, cho thịt bò cắt khối rang cho vàng đều. Lấy ra, để một bên.", "Xào rau: Trong cùng nồi, cho hành tây vào xào cho đến khi nhờn. Thêm cà rốt, khoai tây và bí đỏ, xào vài phút.", "Hầm: Cho thịt bò trở lại nồi. Thêm nước dùng bò và quả mơ sấy khô. Nêm muối và tiêu đen hạt/bột. Hầm 1-2 giờ cho đến khi thịt bò mềm.", "Ăn: Thưởng thức nóng, với một miếng bánh mì vỏ giòn.", "Mẹo: Rang thịt bò từng đợt để có lớp vỏ vàng nụi, tạo hương vị đậm đặn cho món hầm.", "Thêm quả vào phần cuối quá trình nấu giúp giữ độ dai dẻo của quả và tạo vị ngọt nhẹ cho món ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6d2d716d-55f6-5d8d-961b-357a119d187e', 'fda67982-c921-54e6-9568-e2184abae4d6', 500.0, 'g'::public.quantity_unit);
