INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('605ffe43-6d0f-5092-aaaa-4b350c511f5d', 'Trứng om gia vị (Spiced tortilla)', 'rau'::public.dish_category, '["Đun nóng dầu trong chảo xào lớn. Chiên hành tây và nửa ớt đỏ trong 5 phút cho đến khi mềm. Đôme gia vị vào, chiên thêm 1 phút nữa, rồi thêm cà chua bi, khoai tây và cuống ngô rí vào chảo. Nems trứng tốt, rót lên trên rau và để nấu nhẹ trong 8-10 phút cho đến khi gần kết.", "Đun nồi nướng và châm tortilla dưới trong 1-2 phút cho đến khi phần trên kết. Rắc lá ngô rí và ớt đỏ còn lại lên trên, cắt thành miếng và phục vụ với salad xanh."]'::jsonb, 4);
