INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4f538c41-c092-53ae-b253-68c7a6eb0d68', 'Gà Spain đơn giản (Easy Spanish chicken)', 'man'::public.dish_category, '["Đun lò đến 200°C/180°C/mức 6. Đun nóng dầu ô liu nguyên chất trong một cái chảo nướng lớn trên lửa vừa và chiên hành tây, xúc xích Chorizo và ớt chuông cùng với một chút muối và tiêu đen trong 15 phút cho đến khi rau đã mềm và xúc xích Chorizo đã nhờn. Thêm bột ớt ngọt Paprika hun khói ngọt và tỏi, và nấu thêm vài phút cho đến khi thơm.", "Đổ cà chua đóng hộp, quả ô liu xanh và đậu ngự Lima vào, khuấy kết hợp và nems. Đặt vào các đùi gà và nems tốt. Chuyển vào lò và nướng trong 40 phút cho đến khi da gà giòn và thịt chín qua và mềm. Rắc ngô tây và phục vụ.", "Xem sau quảng cáo", "3 ý kiến trứng ngân sách"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4f538c41-c092-53ae-b253-68c7a6eb0d68', '77fb1c7e-c873-50e7-b08f-9c13fc312719', 30.0, 'ml'::public.quantity_unit);
