INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6b2bf5dd-e017-5824-a0c9-0c5ce0f54ba5', 'Tôm nướng tỏi Tây Ban Nha (Gambas al ajillo)', 'man'::public.dish_category, '["Bóc tôm, để đuôi nguyên, và dùng que cocktail để bỏ đường ruột. Hoặc, nếu bạn sử dụng chảo chiên thay vì nồi gốm, bạn có thể nấu tôm với vỏ. Nêm một chút muối biển.", "Đặt tỏi, dầu ô liu và ớt Cayenne vào nồi gốm chống cháy hoặc chảo chiên và đặt trên lửa lớn. Khi tỏi bắt đầu vàng, thêm tôm và nấu 1-2 phút mỗi bên cho đến khi hồng. Rắc ngô tây cắt nhỏ và tiêu đen xay tươi lên trên, và ăn ngay. Nếu sử dụng nồi gốm, bạn có thể đưa trực tiếp lên bàn, nhưng cẩn thận vì dầu và gốm sẽ còn nóng trong vài phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6b2bf5dd-e017-5824-a0c9-0c5ce0f54ba5', '0b3c601a-12db-550f-ac0a-3c1b3c7410c5', 12.0, 'piece'::public.quantity_unit);
