INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6b2bf5dd-e017-5824-a0c9-0c5ce0f54ba5', '957d3bfc-d01e-55b9-ad73-d2ee0794f45a', 3.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6b2bf5dd-e017-5824-a0c9-0c5ce0f54ba5', 'dda12c43-6125-554d-9644-0c26114cca9a', 15.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('797b829e-163b-5d15-8214-85cf977b4dc9', 'Bánh nướng jambon và tỏi rừng Tây Ban Nha (Jamon & wild garlic croquetas)', 'man'::public.dish_category, '["Rửa các lá tỏi rừng tốt trong rổ lọc, rồi rót nước sôi từ ấm vào cho đến khi chỉ úng. Ngay lập tức rửa dưới nước lạnh chảy, rồi vắt bỏ lượng nước thừa và băm nhịn.", "Đun sữa trong nồi trên lửa thấp cho đến khi chỉ hơi nóng. Đun dầu hoặc bơ trong nồi thứ hai và, khi ấm hoặc đã tan, khuấy bột vào trong vài phút cho đến khi bắt đầu hơi vàng. Dần dần thêm sữa ấm, một ít một lần, cho đến khi có một sốt đặc và mịn. Nôi trong một hoặc hai phút, khuấy để đảm bảo tất cả bột đã chín. Nêm nếm.", "Thêm phô mai Manchego, jambon và tỏi rừng vào nồi, và đánh để kết hợp. Đổ lên khay nướng hoặc đĩa đã bớt dầu, trải ra rồi đậy nắp và để lạnh ít nhất 1 giờ. Có thể giữ lạnh trong 24 giờ.", "Bớt dầu lên tay và hình thành hỗn hợp thành 18-20 viên bằng nhau. Sắp xếp lên khay nướng và đông lạnh trong 30 phút để chắc.", "Đánh trứng trong một đĩa nông với một chút gia vị. Đổ panko vào một đĩa thứ hai. Trám mỗi bánh nướng jambon vào trứng, rồi lật để bọc trong bột chiên xù. Đến lúc này, các bánh nướng jambon chưa nấu có thể đông lạnh trong ba tháng.", "Đổ dầu vào chảo lớn, sâu, đảm bảo không đầy hơn một phần ba và đun đến 170°C, hoặc cho đến khi một khối bánh mì vàng nhẹ trong 30 giây. Chiên các bánh nướng jambon theo lượt trong 2-3 phút cho đến khi vàng đậm. Để nấu từ trạng thái đông lạnh, chiên ở 160°C trong vài phút lâu hơn cho đến khi chúng nóng hổi bên trong. Lấy ra bằng thìa có lỗ lên một tấm giấy bếp và để ráo. Ăn nóng với một ly rượu Sherry."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('797b829e-163b-5d15-8214-85cf977b4dc9', 'd2db3aee-8976-5205-b659-e3a82ae73c4d', 150.0, 'g'::public.quantity_unit);
