INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('06def1d4-d435-5774-8adb-7155f6d5c459', 'Cơm tôm mực kiểu Tây Ban Nha (arroz con gambas y calamar)', 'man'::public.dish_category, '["Bóc vỏ và bỏ sã hầu hết tôm sống (ngư viên có thể làm việc này cho bạn), giữ lại vài con nguyên vẹn để trang trí, nếu thích. Đun nóng dầu ô liu trong chảo chiên lớn hoặc nồi đất chạy lò trên lửa trung bình thấp và chiên hành tây 5 phút cho đến khi mềm. Thêm lá nguyệt quế, saffron, gạo và cà chua xay nhuyễn, nấu thêm 1-2 phút, khuân đều.", "Đổ rượu vang trắng vào và để nấu sôi nhỏ 1-2 phút, rồi đổ nước dùng hầm hải sản và 150 ml nước. Nấu 5 phút, rồi thêm mực, nems vừa đủ và khuân trộn. Đun đến sôi, rồi đậy nắp và giảm lửa xuống đun sôi nhẹ. Nấu thêm 12 phút, thêm ít nước nữa nếu hỗn hợp bắt đầu khô.", "Mở nắp chảo và khuân qua các tôm đã bóc vỏ, rồi sắp xếp các tôm nguyên vẹn trên hỗn hợp cơm. Đậy nắp lại và đun sôi nhẹ thêm 5-6 phút cho đến khi tôm hồng và chín hết. Để nghỉ vài phút trước khi ăn trực tiếp từ chảo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('06def1d4-d435-5774-8adb-7155f6d5c459', '0b3c601a-12db-550f-ac0a-3c1b3c7410c5', 24.0, 'piece'::public.quantity_unit);
