INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('42fdcca0-5f0c-594f-838b-45193423c22d', 'Ớt Padrón nướng (Padron peppers)', 'rau'::public.dish_category, '["Đun dầu ô liu trong chảo lớn trên lửa lớn, hoặc nếu dùng máy nướng không dầu, đậy đến 205C trong 3 phút. Chiên ớt, khuấy thường xuyên, 5 phút cho đến khi bọng và héo. Các ớt nên mềm và hơi cháy.", "Chuyển ớt lên đĩa dùng và nems chút muối biển. Dùng kèm sốt chấm hoặc như một phần bữa tapas, nếu thích."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('42fdcca0-5f0c-594f-838b-45193423c22d', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 15.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('42fdcca0-5f0c-594f-838b-45193423c22d', '6ea4f353-52b5-5953-abcd-94887c1d9964', 500.0, 'g'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('99999fd8-66d9-5870-950e-d1869d2bb0d8', 'Paella Tây Ban Nha (Paella)', 'man'::public.dish_category, '["Đun 1 muỗng canh dầu trong chảo rộng nông. Cho đầu tôm và cuống ngô tây vào và chiên cho đến khi đầu chuyển sang hồng, rồi nghiền bằng máy nghiền khoai. Rót rượu Sherry hoặc rượu vang và 300 ml nước, nems muối và hôi 10 phút để làm nước dùng, nghiền đầu tôm khi chúng nấu.", "Rắc nghêu vào chảo, phủ lỏng nắp chảo hoặc khăn bếp, rồi đặt lên lửa lớn 3-4 phút cho đến khi nghêu vừa mở. Khuấy để thả nước nghêu, rồi đổ nội dung chảo vào cái rổ đặt trên bát lớn chứa nhụy hoa nghệ tây. Để nhụy ngâm trong nước dùng – tổng cộng cần 700 ml, nên thêm nước nếu cần và khuấy mọi thứ kỹ. Lấy nghêu ra khỏi cái rổ, rồi để riêng.", "Lau sạch chảo và thêm phần dầu ô liu còn lại. Xào xúc xích Chorizo cho đến khi thả dầu, rồi thêm hành tây và tỏi và nấu cho đến khi mềm. Thêm mực và lật cho đến khi trắng. Thêm cà chua và nấu một phút, rồi rót phần lớn nước dùng, khuấy mọi thứ kỹ và đun sôi. Rải gạo lên nước dùng, khuấy tốt một lần, rồi đun sôi mãnh 5 phút. Giảm nhiệt xuống mức thấp nhất và hôi chậm 10 phút không khuấy cho đến khi gạo đã hấp thụ hầu hết nước.", "Chèn đuôi tôm vào gạo và hôi 5 phút, lật cho đến khi chín đều. Khuấy nghêu và đậu tằm hoặc đậu Hà Lan vào. Nếm gạo – nếu vẫn hơi chín nhưng chảo khô, thêm chút nước dùng hơn và tiếp tục nấu; nếu quá nước, tăng lửa để nấu bỏ phần nước còn lại.", "Khi gạo vừa chín, tắt bếp và phủ khăn bếp vài phút. Rắc lá ngô tây và vỏ chanh, rồi nems muối hun khói nếu thích. Khuấy mọi thứ một lần, rồi dùng ngay từ chảo, với lát chanh ở bên cạnh."]'::jsonb, 4);
