INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ef0227cc-ffc2-5176-a60b-12b2aafd2c12', 'Cá hake chiên sốt đậu trắng Chorizo', 'canh'::public.dish_category, '["Ráo đậu, rồi đổ vào nồi lớn với 2 lít nước. Hôi với tép tỏi nguyên bản, lá nguyệt quế và thì là 30 phút cho đến khi chín và mềm. Nới bếp và để riêng.", "Trong lúc đó, đun 2 muỗng canh dầu trong chảo. Chiên bánh mì với tép tỏi còn lại. Khi vàng và giòn, vớt ra và ráo trên khăn bếp giấy. Thêm xúc xích Chorizo vào chảo, chiên cho đến khi giòn, đổ ra và giữ nóng cùng với bánh mì.", "Thêm thêm 2 muỗng canh dầu và hành tây vào chảo, và nấu 5 phút cho đến khi mềm. Khuấy bột ớt ngọt vào. Ráo đậu và thêm vào hành với nước dùng gà và 2 muỗng cà phê muối. Nấu 5-10 phút. Khuấy ngô tây vào và giữ nóng.", "Nems cá hake và đun phần dầu 2 muỗng canh còn lại trong chảo. Đặt cá hake, phần da xuống, vào chảo và nấu 3-5 phút trên lửa vừa-cao để da giòn. Lật cá ra và nấu thêm 3-5 phút cho đến khi chín đều. Cho hỗn hợp đậu trắng vào bát, đặt cá hake lên trên và hoàn thiện với bánh mì chiên, xúc xích Chorizo và chút thì là hơn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('ef0227cc-ffc2-5176-a60b-12b2aafd2c12', '7f4625bd-5655-5ee6-9427-323f53d13fd7', 450.0, 'g'::public.quantity_unit);
