INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c82b93a8-8e5a-515e-8f95-fb69fa92785c', 'Hầm nghêu, xúc xích Chorizo và đậu trắng (Clam, chorizo & white bean stew)', 'man'::public.dish_category, '["Chiên xúc xích Chorizo trong chảo lớn có nắp trên lửa trung bình cho đến khi bắt đầu giòn và nhờn dầu. Thêm hành tây và nấu trong 5 phút cho đến khi bắt đầu mềm. Sau đó thêm tép tỏi và ngô tây đã kẹo nhỏ, và chiên thêm 1 phút.", "Đổ nước dùng và cà chua đóng hộp vào. Đun sôi, giảm lửa, sau đó thêm đậu ngự Lima và giấm rượu vang sherry. Hầm trong 10 phút cho đến khi chất lỏng hơi giảm.", "Rắc nghêu lên trên, đậy nắp và hấp trong 2-4 phút, lắc chảo đôi khi cho đến khi nghêu mở. Nếm trước khi nêm, vì nghêu có thể khá mặn. Sau đó rắc ngô tây đã kẹo. Ăn với nhiều bánh mì vỏ giòn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c82b93a8-8e5a-515e-8f95-fb69fa92785c', '95b2c047-4a6d-559d-8b89-d93b756d6ad4', 50.0, 'g'::public.quantity_unit);
