INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('22c38376-fdba-5d64-a79b-6077434a860d', 'Bánh pate gà kiểu Tây Ban Nha (Spanish chicken pie)', 'man'::public.dish_category, '["Đun lò lên 200°C. Luộc khoai tây trong 15-20 phút cho đến khi mềm. Rarget nước, trả vào chảo, rồi nghiền với một ít nems và 2 muỗng cà phê bột ớt ngọt Paprika.", "Trong lúc đó, đun nóng dầu trong chảo lớn, rồi chiên hành tây và tỏi trong vài phút cho đến khi mềm. Khuấy vào phần bột ớt ngọt Paprika còn lại trong 1 phút, thêm cà chua, rồi đun sôi nhỏ lửa. Đổ vào đĩa chống nồi lớn, rồi khuấy vào gà, ớt chuông nướng thơm, oliu xanh và một ít nems.", "Đổ hỗn hợp nghiền lên trên, rồi nướng trong 15 phút cho đến khi hỗn hợp nghiền vàng trên bề mặt và sốt sôi phao phao."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('22c38376-fdba-5d64-a79b-6077434a860d', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1000.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('22c38376-fdba-5d64-a79b-6077434a860d', 'cf5b26eb-334e-52dc-9958-4665a1bf178e', 15.0, 'ml'::public.quantity_unit);
