INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('22c38376-fdba-5d64-a79b-6077434a860d', '44a6a37a-69a3-5573-9fd1-730baf90fb5b', 300.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('22c38376-fdba-5d64-a79b-6077434a860d', '4a47824f-b1cf-5c63-be11-b000573f3d1b', 140.0, 'g'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2b276a7f-e021-5775-a7dd-39c21d1b1d5e', 'Cơm nướng kiểu Tây Ban Nha (arroz al horno)', 'man'::public.dish_category, '["Đun lò đến 200°C. Đun nửa lượng dầu trong chảo sâu hoặc chảo xào (hoặc nồi ăn lò nhẹ) khoảng 30cm đường kính. Trên lửa lớn, vàng hai mặt từng đợt lát thịt ba chỉ heo, rồi chuyển ra bát. Thêm dầu còn lại vào chảo, giảm lửa xuống trung bình, thêm dồi huyết kiểu Anh và xúc xích khói, chiên cho vàng hết mọi bên. Lấy ra bằng thìa rỗng. Chiên hành tây và ớt chuông khoảng 10 phút cho đến khi mềm và vàng nhạt, rồi thêm cà chua và nấu cho đến khi mềm. Thêm tỏi, paprika khói và ớt khô dạng vảy, nấu thêm 2 phút, rồi trả thịt heo, dồi huyết kiểu Anh và xúc xích khói vào chảo. Thêm đậu trắng, nước dùng và gia vị lá bạn dùng, đun hỗn hợp đến khi sôi.", "Rắc cơm xung quanh thịt ba chỉ, đìm qua phía dưới nước dùng. Để nước dùng sôi lại, nems vừa đủ, rồi để vào lò (không đậy nắp). Nấu 20 phút không khuân, rồi kiểm tra cơm đã như thế nào. Cơm nên mềm và nước dùng được hấp thụ hết. Nếu chưa chín, để lại trong lò thêm 5 phút, rồi kiểm tra lại. Nếm và nems lại.", "Chắt nước chanh vàng lên trên và rưới dầu ô liu nguyên chất thêm vào trước khi ăn, nếu thích."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2b276a7f-e021-5775-a7dd-39c21d1b1d5e', '77fb1c7e-c873-50e7-b08f-9c13fc312719', 30.0, 'ml'::public.quantity_unit);
