INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('170a4b9b-193f-5dac-9039-21b156f154a1', 'Salad xúc xích Chorizo và trứng luộc mềm (Chorizo & soft-boiled egg salad)', 'man'::public.dish_category, '["Luộc khoai tây non baby trong nồi lớn nước muối sôi trong 12 phút, thêm trứng sau 6 phút, và đậu que trong 2 phút cuối. Ráo tất cả và để trứng nguội dưới nước lạnh chảy.", "Cùng lúc đó chiên miếng xúc xích Chorizo trong 1-2 phút, cho đến khi bắt đầu giòn. Lấy ra khỏi chảo bằng nisha có lỗ và đặt một bên, để lại dầu từ xúc xích Chorizo trong chảo. Thêm tép tỏi vào chảo và nấu nhẹ trong 1 phút.", "Nâng chảo khỏi lửa, khuấy vào giấm rượu vang sherry và ngô tây, sau đó trộn với khoai tây, đậu que, xúc xích Chorizo và nêm nếm. Bóc trứng, cắt thành tư phần và thêm vào salad."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('170a4b9b-193f-5dac-9039-21b156f154a1', '70c5869e-01e1-5e36-aa93-f0c5330edec8', 500.0, 'g'::public.quantity_unit);
