INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('458e6b60-953e-5070-8fa5-8336e17a93f6', 'Khoai tây sốt cay (patatas bravas)', 'rau'::public.dish_category, '["Ngâm khoai tây trong nước vừa sôi 30 phút, rồi để thoát nước và khô tự nhiên 5 phút. Đun nồi không khói đến 200°C. Đổ khoai vào bát và đổ 1 muỗng canh dầu ô liu lên trên, thêm 1/2 muỗng cà phê muối và tiêu đen xay tươi. Trộn đều cho khoai phủ đều, rồi đổ vào rổ nồi không khói và nấu 20-30 phút cho đến khi giòn và vàng.", "Cùng lúc đó, đun nóng dầu còn lại trong chảo nhỏ trên lửa trung bình thấp và chiên hành tây 8-10 phút cho đến khi mềm nhưng không vàng. Thêm tỏi vào và nấu một phút trước khi thêm sốt ớt ngọt paprika, nấu thêm 30 giây. Thêm cà chua xay nhuyễn vào, nấu 1 phút, rồi đổ cà chua đóng hộp vào. Nấu 5-10 phút trên lửa trung bình cho đến khi sốt đặc lên một chút.", "Khi khoai đã chín, đổ lên đĩa lớn và phủ sốt cà chua lên trên. Rắc lá húng quế, rồi ăn ngay."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('458e6b60-953e-5070-8fa5-8336e17a93f6', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 900.0, 'g'::public.quantity_unit);
