INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7bb945d4-7fb4-5fb8-a061-576bd922786f', 'Trứng chảo xúc xích Chorizo, khoai tây và phô mai (Chorizo, potato & cheese omelette)', 'man'::public.dish_category, '["Luộc khoai tây trong nước sôi trong 8-10 phút cho đến khi mềm. Ráo và để khô. Đun nóng dầu ô liu trong chảo trứng chảo, thêm xúc xích Chorizo và nấu trong 2 phút. Thêm khoai tây và nấu thêm 5 phút cho đến khi khoai tây bắt đầu giòn. Lấy phần trong chảo ra, lau chảo và nấu một chảo trứng 2 hoặc 3 trứng trong cùng chảo. Khi gần chín, rắc xúc xích Chorizo và khoai tây, ngô tây và phô mai Cheddar. Gấp chảo trứng trong chảo và nấu thêm 1 phút nữa để nung phô mai."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7bb945d4-7fb4-5fb8-a061-576bd922786f', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1.0, 'piece'::public.quantity_unit);
