INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7bb945d4-7fb4-5fb8-a061-576bd922786f', '8a301d33-ca8b-52a8-aa71-ca6feca05e46', 3.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7bb945d4-7fb4-5fb8-a061-576bd922786f', 'c97c5682-6dfa-53cd-bcf5-2be89afd7e38', 25.0, 'g'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c6293afe-7743-5521-98d2-3b800f6c5e71', 'Rau xào trứng Tây Ban Nha (Pisto con huevos)', 'rau'::public.dish_category, '["Đun dầu trong nồi đất chịu nhiệt lớn hoặc chảo gang trên lửa nhỏ. Cho hành và một chút muối vào, đậy nắp và nấu nhẹ 15 phút, khuấy thỉnh thoảng. Thêm tỏi và nấu thêm 2 phút.", "Tiếp theo, ném ớt chuông vào và nấu trên lửa trung bình, đậy nắp, khoảng 5 phút, khuấy thỉnh thoảng, cho đến khi ớt vừa mềm.", "Trộn hoặc hy lạp, thì là, lá nguyệt quế, chút tiêu đen và ít muối, nếu cần. Đổ cà tím và cải vào, trộn kỹ, và nấu trên lửa trung bình, đậy nắp, 10 phút. Khuấy cà chua vào, đậy nắp và nấu 20 phút, khuấy thỉnh thoảng.", "Cẩn thận đập trứng lên trên pisto – cố gắng không vỡ lòng đỏ. Nấu trong sốt trên lửa trung bình 5-6 phút cho đến khi trứng chín nhưng vẫn hơi mềm, rồi rắc ngô tây trước khi dùng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c6293afe-7743-5521-98d2-3b800f6c5e71', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 30.0, 'ml'::public.quantity_unit);
