INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('11064a41-8df9-518a-9b20-ba823f9c762a', 'Nồi gà xúc xích Chorizo với cơm (Chicken & chorizo rice pot)', 'man'::public.dish_category, '["Đun nóng dầu ăn trong nồi lớn, rang miếng gà cho vàng hết các mặt – có thể phải làm từng đợt. Lấy ra khỏi nồi và đặt một bên.", "Giảm lửa, cho hành tây và ớt chuông đỏ vào, ninh nhẹ trong 10 phút cho đến khi mềm. Thêm tỏi và xúc xích Chorizo, ninh thêm 2 phút cho đến khi xúc xích Chorizo nhờn vào nồi. Cho cà chua xay nhuyễn vào và ninh thêm 1 phút.", "Trả miếng gà vào nồi cùng với xạ hương, rượu vang trắng và nước dùng gà. Đun sôi nồi, đậy nắp kín và giảm lửa. Nấu trong 30 phút.", "Đổ gạo vào và trộn đều tất cả. Đậy nắp, đặt trên lửa nhỏ và nấu thêm 15 phút, hoặc cho đến khi gạo chín và hấp thụ hầu hết nước nấu. Tắt lửa và để nồi ngâm trong 10 phút để hấp thụ phần nước còn lại. Nêm nếm theo khẩu vị và rắc ngò tây để ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('11064a41-8df9-518a-9b20-ba823f9c762a', 'f9ef1ba9-7da5-599e-ad08-11ab8b7e76d9', 15.0, 'ml'::public.quantity_unit);
