INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('203d6bc0-862e-59a4-89a8-48a8cc1d980f', 'Gà kiểu Tây Ban Nha (Spanish Chicken)', 'man'::public.dish_category, '["Đun lò lên 190°C. Đặt tất cả thành phần vào đĩa chống nồi lớn. Trộn mọi thứ bằng tay và nems.", "Nướng trong 45 phút, khuấy hành tây sau 20 phút, cho đến khi gà vàng và hành tây mềm. Phục vụ với cơm."]'::jsonb, 4);
