INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4ae2d458-5dd1-58b8-aaf8-10f0c3b75cc4', 'Hầm đậu gà, xúc xích Chorizo và cải bó xôi (Chickpea, chorizo & spinach stew)', 'man'::public.dish_category, '["Đun nóng dầu ô liu nguyên chất trong nồi lớn, sau đó chiên nhẹ hành tây trong 3-4 phút cho đến khi bắt đầu mềm. Khuấy vào cà rốt, cần tây, xạ hương và lá nguyệt quế. Nêm, sau đó nấu trong 2-3 phút, gọi đôi khi. Thêm tỏi, xúc xích Chorizo, quế và bột ớt ngọt Paprika. Chiên nhẹ cho đến khi rau mềm và xúc xích Chorizo bắt đầu nhờn và giòn lên.", "Khuấy vào đậu gà Chickpeas, giấm rượu vang sherry và 150ml nước, sau đó đun sôi nhẹ trong 1-2 phút cho đến khi đậu gà đã nóng qua. Thêm cải bó xôi, rồi khuấy qua đậu gà cho đến khi nó hơi héo. Nâng khỏi lửa, nems nếm theo khẩu vị, sau đó ăn nóng với bánh mì vỏ giòn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4ae2d458-5dd1-58b8-aaf8-10f0c3b75cc4', '77fb1c7e-c873-50e7-b08f-9c13fc312719', 60.0, 'ml'::public.quantity_unit);
