INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('30fcae42-0645-58bd-ac81-1fb451fbae11', 'Cơm hải sản (Seafood rice)', 'man'::public.dish_category, '["Đun nóng dầu trong chảo đậm, rồi làm mềm tỏi tây trong 5 phút không vàng. Thêm xúc xích Chorizo và chiên cho đến khi thả dầu. Khuấy vào nghệ và gạo cho đến khi được phủ dầu, rồi đổ nước dùng vào. Đun sôi, rồi ninh trong 15 phút, khuấy đôi khi.", "Đổ đậu Hà Lan vào và nấu trong 5 phút, rồi khuấy vào hải sản để nóng qua trong 1-2 phút nấu cuối cùng hoặc cho đến khi gạo chín. Kiểm tra nems và phục vụ ngay với lát chanh."]'::jsonb, 4);
