INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('57a49c3a-01f4-564e-8a1f-7b51da12da96', 'Sup xúc xích Chorizo và đậu gà (Chorizo & chickpea soup)', 'canh'::public.dish_category, '["Đặt nồi vừa trên lửa và cho cà chua đóng hộp vào, sau đó thêm một chén nước. Khi cà chua đang nóng, cắt nhanh xúc xích Chorizo thành các miếng dày (bỏ vỏ nếu có) và bào bắp cải Savoy.", "Nhét xúc xích Chorizo và bắp cải vào nồi cùng với vụn ớt khô và đậu gà Chickpeas, sau đó nghiền viên súp gà vào. Khuấy tốt, đậy nắp và để sôi trên lửa cao trong 6 phút hoặc cho đến khi bắp cải vừa mềm. Chia vào tách ăn với bánh mì vỏ giòn hoặc bánh mì tỏi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('57a49c3a-01f4-564e-8a1f-7b51da12da96', '7c3030a0-3c6a-55ff-9ca4-37783b1c53e8', 400.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('57a49c3a-01f4-564e-8a1f-7b51da12da96', '95b2c047-4a6d-559d-8b89-d93b756d6ad4', 110.0, 'g'::public.quantity_unit);
