INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('57a49c3a-01f4-564e-8a1f-7b51da12da96', '1ac9b5a0-35d1-5a93-9209-0239e87084f0', 400.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('57a49c3a-01f4-564e-8a1f-7b51da12da96', 'bda8c5ec-94c7-50c4-8658-919b21da2e28', 1.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e78ccbb5-be42-5b1c-b8e4-cc935faf09ed', 'Trứng om cá tuyết muối (Salt cod tortilla)', 'man'::public.dish_category, '["Đun nửa dầu trong chảo chiên, và xào hành tây trên lửa vừa cho đến khi mềm và hơi vàng – sẽ mất khoảng 8 phút. Lấy khỏi chảo, để riêng, và thêm khoai tây vào chảo. Nấu cho đến khi mềm nhưng không nát, cẩn thận lật đôi khi. Phủ nắp chảo một thời gian để giúp các lát chín đều. Cho hành trở lại chảo cùng với tỏi và nấu thêm 4 phút. Cho vào bát với trứng, ngô tây và một ít nems và trộn chung. Để ngâm nửa tiếng.", "Trong lúc đó, cho cá tuyết muối vào nồi nhỏ và ngập nước. Đun cho sôi nhỏ lửa. Bớt bấm, nắp lại và để 10 phút. Rarget, để nguội và bóc vỏ và cốt xương. Làm thành miếng lớn và thêm vào hỗn hợp khoai tây và trứng.", "Đun nóng phần dầu còn lại trong chảo không dính. Đổ hỗn hợp trứng vào và nấu trên lửa vừa-thấp cho đến khi vừa kết và tách khỏi cạnh chảo. Bạn có thể cần nắp để giúp phần trung tâm kết. Cẩn thận không nấu quá. Đặt muỗng nhôm dưới trứng om đôi khi để đảm bảo nó không dính. Trượt trứng om lên đĩa, rồi đặt chảo lên trên và lật trứng om vào, mặt chưa chín xuống dưới. Nấu trên lửa thấp cho đến khi vàng, hoặc nướng cho đến khi vừa kết. Để nguội một chút trước khi phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('e78ccbb5-be42-5b1c-b8e4-cc935faf09ed', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 60.0, 'ml'::public.quantity_unit);
