INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6a9f93a0-c186-54fa-9165-3d7b5a5b6639', 'Khoai tây nướng sốt Bravas Tây Ban Nha (Patatas bravas)', 'rau'::public.dish_category, '["Đun dầu trong chảo và chiên hành khoảng 5 phút cho đến khi mềm. Thêm tỏi, cà chua đã băm, cà chua xay nhuyễn, bột ớt ngọt, bột ớt, đường và một chút muối, rồi đun sôi, khuấy thỉnh thoảng. Hạ lửa hôi và nấu 10 phút cho đến khi nhừ. Có thể bảo quản trong tủ lạnh tối đa 24 giờ.", "Đậy lò 200°C. Thấm khô khoai bằng khăn bếp giấy, rồi đổ vào khay nướng và trộn với dầu ô liu và chút nems nếm. Nướng 40-50 phút cho đến khi giòn và vàng. Đổ khoai vào đĩa dùng và đỗn sốt cà chua lên trên. Rắc chút ngô tây tươi khi dùng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6a9f93a0-c186-54fa-9165-3d7b5a5b6639', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 45.0, 'ml'::public.quantity_unit);
