INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9a9ed347-0238-5a1a-a371-dd770b19a414', 'Tôm sốt Romesco Tây Ban Nha', 'man'::public.dish_category, '["Chuẩn bị trước - cắt ớt thành nửa theo chiều dọc và lấy bỏ hạt và cuống. Đổ giấy nhôm lên khay nướng và đặt các nửa ớt, mặt da lên, trên khay cùng với tép tỏi nguyên bản, ớt và cà chua. Nướng 2 phút, lật cà chua, rồi nướng thêm 2 phút. Vớt cà chua với muỗng lớn, rồi bóc vỏ, chia tư và lấy bỏ hạt. Sau đó băm thô cà chua.", "Tiếp tục nướng ớt, ớt cay và tỏi 4-5 phút, cho đến khi vỏ ớt và ớt cay đã đen và tỏi bắt đầu mềm (vỏ tỏi sẽ bắt đầu chia khi sẵn sàng). Khi nguội nắm tay được, bóc vỏ và chia nửa ớt, và khiêu bỏ hạt và vứt đi. Bóc vỏ ớt chuông và băm thô cả ớt chuông và ớt cay.", "Rắc hạt lên giấy nhôm và nướng cho đến khi thơm. Băm mịn hạt và ngô tây trong máy xay thực phẩm. Đổ vào bát nhỏ.", "Đun 3 muỗng canh dầu trong chảo, thêm ớt chuông, tỏi và ớt cay và chiên 3 phút. Xé bánh mì thành mảnh và thêm vào chảo, lật trong dầu cho đến khi nhẹ vàng. Xay nhẹ trong máy xay thực phẩm với cà chua, muối, giấm và dầu cho đến khi cắt thô. Đổ vào bát. Để nguội và bảo quản trong tủ lạnh tối đa 3 ngày.", "Vào ngày dùng thêm hạt và ngô tây vào sốt và trộn. Dùng trong bát nhỏ trên đĩa với tôm đã bóc vỏ. Cung cấp que cocktail để đâm tôm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9a9ed347-0238-5a1a-a371-dd770b19a414', '1464765e-f3b9-52a0-9ee3-27e1a66845a3', 1.0, 'piece'::public.quantity_unit);
