INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('91a969b9-670d-5844-a258-fec653c8a6c3', 'Vai cừu nấu chậm kiểu Tây Ban Nha với đậu (Spanish-style slow-cooked lamb shoulder & beans)', 'man'::public.dish_category, '["Để làm hỗn hợp gia vị, trộn tất cả thành phần cùng một nắm lớn muối. Chọc vai cừu khắp nơi bằng dao sắc và chà vào. Nếu bạn có thời gian, ướt trong 24 giờ, nhưng không cần thiết.", "Đun lò lên 150°C. Đun nóng dầu trong nồi chống cháy lớn hoặc khay nướng trên lửa vừa-cao, thêm hành tây, cà rốt và tỏi và chiên trong 5 phút cho đến khi hành tây và cà rốt mềm. Rưới nước dùng vào, rồi đun sôi. Đặt cừu vào nồi và nắp, rồi chuyển vào lò và nướng trong 2 giờ.", "Mở nắp và dùng kìm chuyển cừu sang đĩa. Khuấy đậu, ớt chuông nướng thơm và oliu qua nước dùng trong nồi, đặt cừu lại lên trên và trở lại lò, không nắp, trong 1 giờ 30 phút cho đến khi cừu chín hoàn toàn. Chuyển cừu sang tấm và xé bằng 2 nĩa. Khuấy ngô tây qua đậu nướng trước khi phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('91a969b9-670d-5844-a258-fec653c8a6c3', '183f4755-c7d4-5017-9d66-3e0028f10788', 2500.0, 'g'::public.quantity_unit);
