INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9fc068b2-79b1-545c-afbd-588448a41bea', 'Bánh mì cà chua kiểu Tây Ban Nha với giăm bông Serrano (Spanish tomato bread with jamón Serrano)', 'man'::public.dish_category, '["Trộn cà chua đã nghiền, tép tỏi, dầu ô liu, muối và tiêu. Giữ trong tủ lạnh cho đến khi cần.", "Để phục vụ, nướng 20 lát bánh mì baguette. Đổ một ít topping cà chua lên mỗi miếng bánh nướng. Rách 5-6 lát giăm bông Serrano thành miếng và đặt một miếng trên mỗi lát bánh."]'::jsonb, 4);
