INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a430e22d-5fc1-5f50-a250-d355a3b57b76', 'Mì Ý hương Tây Ban Nha (Spaghetti with Spanish flavours)', 'man'::public.dish_category, '["Đặt nồi nước lên trên lửa cao để sôi. Trong lúc đó, cắt xúc xích Chorizo thành miếng bằng kéo, và cắt ngô tây và ớt chuông (kiểm tra hạt dại trước).", "Khi nước sôi sôi thật, thêm mì Ý với một ít muối tốt, khuấy và trả cho sôi. Nấu trong 3 phút.", "Trong chảo xào lớn, đun nóng dầu, thêm xúc xích Chorizo và ớt chuông và nhiều tiêu đen. Nấu trong khoảng một phút, cho đến khi nóng qua và nước cốt bị nhuộm đỏ từ bột ớt ngọt Paprika trong xúc xích. Lấy nửa tách nước luộc mì từ chảo, rarget nước còn lại và trả mì Ý vào chảo xào.", "Thêm ngô tây và parmesan, trộn tốt và rưới chút nước luộc mì, để ẩm. Truyền parmesan thêm trên bàn ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a430e22d-5fc1-5f50-a250-d355a3b57b76', '95b2c047-4a6d-559d-8b89-d93b756d6ad4', 80.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a430e22d-5fc1-5f50-a250-d355a3b57b76', 'db78e4d5-0324-5573-8ad7-382fb3a1caea', 300.0, 'g'::public.quantity_unit);
