INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('cfcefc9a-e5a3-522d-9374-c5145e05820c', 'Mực chiên giòn (Fried calamari)', 'man'::public.dish_category, '["Cắt mực thành các vòng dày khoảng 0,5 cm. Đổ bột mì vào túi đóng băng và nêm nếm đậm đà. Thêm nụ bạch hoa, rồi lắc đều để trộn. Đổ mực vào túi, rồi lắc lại cho đến khi tất cả các vòng đều được bọc. Trộn tỏi và sốt mayonnaise, rồi đặt vào bát ăn.", "Đổ dầu vào chảo lớn cho đến khi dầu cao khoảng 7 cm lên bên ngoài, nhưng chảo không đầy hơn một phần ba. Đặt trên lửa vừa và để dầu ấm lên. Để kiểm tra dầu đã sẵn sàng, đặt một miếng bánh mì nhỏ vào chảo – nó sẽ xì xì khi chạm dầu.", "Lấy một nắm mực từ bột mì và lắc bỏ bột thừa. Nhẹ nhàng thả vào dầu, rồi nấu khoảng 3 phút cho đến khi giòn. Lấy ra bằng thìa có lỗ và đặt lên giấy bếp. Làm lại với phần mực còn lại. Ăn ngay với sốt mayonnaise và lát chanh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('cfcefc9a-e5a3-522d-9374-c5145e05820c', '5faff7d3-f5be-5380-b3ef-afaf04a882ee', 300.0, 'g'::public.quantity_unit);
