INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('68c20829-8147-5e5e-a3c9-4282c9f26fa7', 'Bánh nướng jambon Tây Ban Nha (Ham croquetas)', 'man'::public.dish_category, '["Để làm nhân, đun dầu ô liu trong chảo cho đến khi bắt đầu i nhúe. Thêm ba-rô và xào cho đến khi mềm nhưng không thay đổi màu. Khuấy jambon bằng thìa gỗ, chiên trong 1 phút, rồi khuấy bột mì vào và chiên trên lửa vừa, thỉnh thoảng khuấy, cho đến khi hỗn hợp vàng nhưng không cháy – điều này sẽ mất khoảng 5 phút.", "Trong lúc đó, trộn nước dùng và sữa trong một nồi nhỏ và đun cho đến khi hơi nóng nhưng không sôi. Nêm với một ít nhục đậu khấu. Dần dần thêm chất lỏng, vài muỗng canh một lần, khuấy liên tục.", "Khi bạn đã hòa quyện hết hỗn hợp sữa và nước dùng, tiếp tục nấu nhân trên lửa vừa trong khoảng 10 phút hoặc cho đến khi nó đặc và rời khỏi bên chảo khi bạn khuấy.", "Nêm tiêu đen, thử và điều chỉnh muối nếu cần – jambon có thể rất mặn ở đầu. Nhân hiện đã xong: nó phải thật đặc vì bạn không muốn các bánh nướng jambon biến thành bánh xèo.", "Lấy nhẵn hỗn hợp lên khay nướng (30 x 20 cm là ổn). Khi nó đã ngừng hơi nóng, phủ bằng ni-lông thực phẩm để ngăn khô. Để nguội trước khi đựng vào tủ lạnh trong 1 giờ.", "Khi bạn sẵn sàng cho giai đoạn tiếp theo, xếp ba bát: bát đầu đầy bột mì, bát thứ hai với trứng đánh tan và bát thứ ba với bột chiên xù. Lấy hỗn hợp jambon khỏi tủ lạnh. Đặt một chút dầu ô liu lên tay của bạn để dễ cuộn các bánh nướng jambon hơn.", "Cuộn một thìa hỗn hợp giữa lòng bàn tay. Kích thước và hình dạng của các bánh nướng jambon tùy bạn, nhưng cách dễ nhất là một viên bằng quả óc chó. Sau đó bắt đầu bọc như sau.", "Trám các bánh nướng jambon vào bột mì – bạn muốn một lớp bột mỏng – rồi trứng, sau đó bột chiên xù. Đặt chúng trên khay và, khi bạn đã dùng hết hỗn hợp, đựng vào tủ lạnh trong 30 phút.", "Nếu bạn có chiên nồi, đun dầu đến 180°C và chiên vài phút. Nếu không, đun dầu trong nồi sâu đáy dày cho đến khi bắt đầu i nhúe. Sau đó thêm 5-6 bánh nướng jambon một lần và chiên cho đến khi vàng khắp mặt. Khi đã chín, để ráo trên giấy bếp và ăn ngay.", "Ăn nóng với một ly rượu Sherry."]'::jsonb, 4);
