INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('91fb2641-3a89-5005-bb6b-712ad5f6fdc3', 'Tôm sốt rượu Sherry Tây Ban Nha (Garlicky prawns with sherry)', 'man'::public.dish_category, '["Đun dầu ô liu trong chảo chiên lớn. Đổ các lát tỏi vào và nấu vài giây. Sau đó khuấy tôm vào và nấu vài phút cho đến khi bắt đầu hồng.", "Rưới rượu Sherry và nấu thêm vài phút, chỉ đến khi tôm chín kỹ. Rắc ngô tây trước khi ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('91fb2641-3a89-5005-bb6b-712ad5f6fdc3', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 45.0, 'ml'::public.quantity_unit);
