INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c1a41ba9-3e9c-5b94-830a-57a5c08b27cb', 'Đậu Pinto với gà và xúc xích Tây Ban Nha (Spanish beans with chicken & chorizo)', 'man'::public.dish_category, '["Ngâm đậu ít nhất 4 giờ hoặc qua đêm trong bát lớn với đủ nước ngập. Ngày hôm sau, rửa và rarget, rồi cho vào nồi đáy dày lớn cùng hành tây, bột ớt ngọt Paprika, gói lá thơm và gà. Đổ đủ nước hoặc nước dùng để ngập, đun sôi, rồi giảm lửa, nắp và ninh trong 45 phút.", "Lấy gà ra đĩa, rồi thêm khoai tây và xúc xích Chorizo vào nồi. Tiếp tục nấu trong 30 phút cho đến khi đậu và khoai tây mềm.", "Bỏ da và xương từ gà và xé thành các mảnh lớn. Trả gà vào nồi cùng cải bó xôi và ninh trong 5 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c1a41ba9-3e9c-5b94-830a-57a5c08b27cb', 'df3cc328-b377-56cb-8607-7a6d89e2830c', 300.0, 'g'::public.quantity_unit);
