INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3c68ae95-6abb-539a-98cc-7dd50e2b2cd4', 'Cơm hải sản kiểu Tây Ban Nha (Spanish seafood rice)', 'man'::public.dish_category, '["Đun nóng dầu trong nồi lớn và làm mềm hành tây trong 6-7 phút. Thêm ớt chuông và tỏi, nấu thêm 2 phút nữa, rồi khuấy vào gạo paella và nấu trong 1 phút, khuấy để phủ.", "Đổ nước dùng vào, thêm nhụy hoa nghệ tây và đun sôi. Nấu, không nắp, ở hơi sôi, trong 20 phút, khuấy đôi khi cho đến khi gạo mềm.", "Khuấy vào hải sản và nước cốt chanh và nấu trong 2 phút hoặc cho đến khi nóng rất và chín hoàn toàn. Phục vụ trong tô ấm rắc ngô tây."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3c68ae95-6abb-539a-98cc-7dd50e2b2cd4', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 15.0, 'ml'::public.quantity_unit);
