INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('576486f4-b1bb-575c-9e44-f0ed8f43a966', 'Cơm tôm một nồi kiểu Tây Ban Nha (Spanish rice & prawn one-pot)', 'man'::public.dish_category, '["Sôi bình nước. Trong chảo xào không dính có nắp, chiên hành tây, ớt chuông, xúc xích Chorizo và tỏi trong dầu trên lửa cao trong 3 phút. Khuấy vào gạo và cà chua đã nghiền với 500 ml nước sôi, nắp, rồi nấu trên lửa cao trong 12 phút.", "Mở nắp, rồi khuấy – gạo nên gần mềm. Khuấy vào tôm, với chút nước thêm nếu gạo trông khô, rồi nấu thêm một phút cho đến khi tôm vừa hồng và gạo mềm."]'::jsonb, 4);
