INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c526c447-5b65-5639-98e7-d5dd70322715', 'Salad xúc xích Chorizo và cà chua (Chorizo & tomato salad)', 'man'::public.dish_category, '["Đặt cà chua bò vào bát cùng với hành tím tây và xạ hương. Nêm, sau đó rắc giấm rượu vang sherry và dầu ô liu nguyên chất. Để hương vị trộn lẫn trong khi bạn chiên xúc xích Chorizo.", "Trong chảo nóng khô, chiên miếng xúc xích Chorizo cho đến khi vàng cả hai mặt. Phục vụ cà chua với xúc xích Chorizo đã chiên, rắc chút dầu từ chảo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c526c447-5b65-5639-98e7-d5dd70322715', 'd08e04ea-20bc-5d83-b858-9d8476d96cd0', 3.0, 'piece'::public.quantity_unit);
