INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b2541ad3-c0d2-50cd-9367-92111e833a94', 'Bánh nướng thịt heo (Fašírky)', 'man'::public.dish_category, '["1. Chuẩn bị hỗn hợp bánh mì", "Ngâm miếng bánh mì trong sữa hoặc nước cho đến khi mềm.", "Vắt bỏ chất thải và nghiền thành bột nhỏ.", "2. Trộn các nguyên liệu", "Trong bát lớn, trộn thịt heo xay, hành tây băm, tỏi, bánh mì đã ngâm, trứng và gia vị. Trộn đều cho đến khi kết hợp đều.", "3. Hình thành bánh thịt", "Lấy phần hỗn hợp và hình thành các bánh bằng lòng bàn tay. Dập nhẹ để giúp chín đều.", "4. Bóc bột cho bánh", "Phớt nhẹ bột mì lên mỗi bánh. Trám vào trứng đánh tan, rồi bọc bột chiên xù để có bề mặt giòn.", "5. Chiên Fašírky", "Đun dầu thực vật trong chảo trên lửa vừa. Chiên bánh 4-5 phút mỗi bên cho đến khi vàng và chín kỹ.", "Chuyển sang đĩa lót giấy để ráo dầu thừa.", "6. Ăn và thưởng thức", "Ăn Fašírky nóng với khoai tây nghiền, salad cải, hoặc bánh mì tươi.", "Ăn kèm mù tạt, dưa muối, hoặc sốt tỏi để tăng hương vị."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('b2541ad3-c0d2-50cd-9367-92111e833a94', '5e2f9050-b7fc-59c7-b3b5-04d1d825ee50', 500.0, 'g'::public.quantity_unit);
