INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d403d26c-298f-57cb-9ca2-1d8c4872ce1b', 'Bánh khoai tây kiểu Slovakia (Zemiakové Placky)', 'rau'::public.dish_category, '["1. Chuẩn bị khoai tây:", "Bắt đầu bằng cách bóc và xén mịn khoai tây. Để đảm bảo giòn đặc, dùng khăn bếp sạch để vớ càng nhiều độ ẩm có thể.", "2. Trộn các nguyên liệu:", "Trong tô trộn lớn, trộn khoai tây đã xén, hành tây cắt nhỏ, tỏi băm, trứng, bột mì, kinh giới ô, muối và tiêu đen. Khuấy tốt cho đến khi hỗn hợp tạo thành hỗn hợp đặc, đồng nhất.", "3. Đun dầu:", "Trong chảo chiên lớn, đun nóng lượng dầu nhiều trên lửa vừa. Dầu nên nóng nhưng không khói.", "4. Chiên bánh:", "Cho phần hỗn hợp vào chảo, dẹp mỗi phần thành bánh mỏng. Chiên cho đến khi vàng và giòn trên một mặt, rồi lật và nấu mặt bên kia cho đến khi cùng vàng và giòn.", "5. Rổ nước & dùng:", "Chuyển các bánh đã chiên vào đĩa lót khăn giấy để bỏ dầu thừa. Dùng ngay khi nóng, cùng kem chua hoặc sốt tỏi, hoặc làm món ăn kèm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d403d26c-298f-57cb-9ca2-1d8c4872ce1b', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1000.0, 'g'::public.quantity_unit);
