INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ec8d6f87-3cff-57a3-8dd8-1efc000dcdf1', 'Halušky phô mai cừu Bryndza Slovakia', 'man'::public.dish_category, '["1. Chuẩn bị bột", "Bào khoai tây mịn bằng máy bào tay hoặc máy xay thực phẩm. Đặt khoai đã bào vào bát và trộn với bột, trứng và muối cho đến khi tạo thành hỗn hợp dính. Độ đặc nên đặc nhưng có thể uốn được.", "2. Nấu bánh chín", "Đun nồi lớn nước muối đến sôi. Dùng máy làm halušky (tương tự máy làm spaetzle), đùn hỗn hợp trực tiếp vào nước sôi. Nếu bạn không có, dùng khía cắt nghiêng và dao để cạo các mảnh nhỏ hỗn hợp vào nước.", "Để bánh chín cho đến khi chúng nổi lên bề mặt, thường trong vòng 2-3 phút. Lấy chúng ra bằng thìa rỗng và đặt vào một bát lớn.", "3. Chuẩn bị các lát đánh trên", "Cắt xúc xích khói thành các mảnh nhỏ và chiên trong chảo trên lửa trung bình cho đến khi giòn. Nếu dùng bryndza thay thế, trộn feta đập nhuyễn với một chút kem chua để mô phỏng hương vị chua của phô dai cừu truyền thống Slovakia.", "4. Ghép món", "Trộn bánh đã nấu với phô mai bryndza (hoặc thay thế) cho đến khi chúng được phủ tốt và mềm mịn. Đặt xúc xích khói giòn và nước mỡ của nó lên trên. Trang trí bằng ngô tây hoặc ngô tây đã cắt nhỏ cho thêm màu sắc và hương vị."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('ec8d6f87-3cff-57a3-8dd8-1efc000dcdf1', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 500.0, 'g'::public.quantity_unit);
