INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7d592f8e-9c95-52c8-b9b9-9b356c06b28a', 'Mì xào Pad Thái (Pad Thai)', 'man'::public.dish_category, '["Cho mì vào bát lớn chịu nhiệt, rót nước sôi qua và để 4 phút, rồi ráo và làm lạnh dưới vòi nước lạnh chảy.", "Cho nước cốt chanh, bột ớt Cayenne, đường và nước mắm vào bát và trộn kỹ. Chuẩn bị tất cả nguyên liệu khác bên cạnh bếp.", "Đun dầu và chiên tôm cho đến khi nóng qua. Thêm hành lá và mì và dao động. Đổ hỗn hợp nước cốt chanh vào, rồi khuấy giá đỗ và nửa số đậu phộng và ngô rí. Nấu 1 phút cho đến khi mọi thứ nóng qua.", "Đổ vào đĩa lớn, rắc phần còn lại của đậu phộng và ngô rí, và dùng với lát chanh xanh và sốt ớt ngọt."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7d592f8e-9c95-52c8-b9b9-9b356c06b28a', '65d41c7d-edba-590e-b675-fa4c8dfc2930', 125.0, 'g'::public.quantity_unit);
