INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c1191d56-f5f8-5720-9de6-642640c25ba8', 'Mì rượu Thai (Drunken noodles (pad kee mao))', 'man'::public.dish_category, '["Chuẩn bị bánh phở tươi theo hướng dẫn trên bao, sau đó ráo nước và đặt một bên. Kết hợp tất cả nguyên liệu cho sốt trong một cái bát nhỏ hoặc bình, và đặt một bên.", "Đun nóng dầu trong một chảo lớn hoặc chảo chiên trên lửa cao và xào tỏi và ớt trong 20 giây cho đến khi bắt đầu chuyển sang vàng. Thêm thịt bò Sirloin Steak và xào trong 1 phút cho đến khi nghén và bắt đầu nâu. Thêm bông cải xanh và xào thêm một phút, sau đó đổ bánh phở tươi vào và thêm sốt. Xào thêm 1-2 phút cho đến khi kết hợp tốt và nóng hổi.", "Khuấy qua lá húng quế và tắt lửa. Phục vụ ngay để tránh nấu quá chín."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c1191d56-f5f8-5720-9de6-642640c25ba8', 'f6887277-9882-5cb5-806b-e775f7cb0214', 200.0, 'g'::public.quantity_unit);
