INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f6c19b00-0ed1-572c-ab20-e4c124ea15ce', 'Canh tom yum với tôm', 'canh'::public.dish_category, '["Đổ 1,3 lít nước vào nồi lớn trên lửa cao. Thêm hành tây, cà chua, ớt đỏ, củ riềng, sả tươi, đầu tôm và viên súp gà vào. Khuấy và đun sôi, rồi giảm nhiệt xuống mức vừa và hầm sôi nhẹ 20 phút cho đến khi nước cạn lại.", "Lọc kỹ canh nóng vào tô hoặc bình chịu nhiệt lớn, rồi loại bỏ đầu tôm.", "Cho hỗn hợp rau và thảo mộc đã lọc lại vào nồi và đổ canh lên. Khuấy nấm bào ngư và lá chanh Thái Makrut vào, rồi nấu 3 phút cho đến khi nấm mềm.", "Thêm 1 muỗng canh đường, nước mắm, nước cốt chanh xanh, nước cốt dừa và tôm sống vào. Đun sôi và nấu cho đến khi tôm chín hết, khoảng 1-2 phút. Lấy khỏi lửa. Lấy sả ra, rồi khuấy sa tế tương ớt Thái Nam Prik Pao vào nếu dùng. Rắc ngô rí lên trên để hoàn tất, nếu thích, và dùng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f6c19b00-0ed1-572c-ab20-e4c124ea15ce', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 200.0, 'g'::public.quantity_unit);
