INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4e5f9138-20a0-5848-9b7a-3ec9e9402b9b', 'Canh mì cà ri kiểu Thái', 'canh'::public.dish_category, '["Đun nóng dầu trong nồi trên lửa vừa và nấu sốt cà ri xanh kiểu Thái 1 phút trước khi thêm rau xào và tôm. Nấu 3 phút cho đến khi tôm hơi hồng, rồi thêm nước cốt dừa, nước dùng hầm rau củ quả và mì Udon.", "Đun sôi, rồi giảm lửa và hầm sôi nhẹ 5 phút cho đến khi mì chín và rau mềm nhưng còn giòn. Chia thành hai tô và rắc ngô rí, ớt đỏ và hành lá lên trên."]'::jsonb, 4);
