INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7ba19f38-9360-5fa2-b430-8134a4b8b668', 'Canh tom yum chua cay với tôm (Tom yum soup)', 'canh'::public.dish_category, '["Đun nước dùng gà sôi trong nồi vừa. Cho sả, củ riềng, rễ ngô rí và lá chanh Thái Makrut vào, rồi hầm sôi nhẹ 2 phút.", "Thêm tôm càng, nước mắm, ớt xanh và nước cốt chanh xanh vào, rồi đun sôi lại. Nếm và điều chỉnh nêm nếm bằng thêm nước cốt chanh xanh hoặc nước mắm, rồi trang trí với lá ngô rí và dùng."]'::jsonb, 4);
