INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2394055b-4578-52b6-96c5-a992fe9599f0', 'Cơm chiên tôm và đậu Hà Lan kiểu Thái', 'man'::public.dish_category, '["Đun nóng 1 muỗng canh dầu trong wok, thêm hành tím, tỏi và ớt, nấu 2-3 phút cho đến khi vàng. Thêm tôm và nấu 1 phút. Cho gạo lứt và đậu Hà Lan đông lạnh vào, khuấy liên tục cho đến khi nóng bỏng. Thêm nước tương và nước mắm, rồi khuấy với ngô rí cắt nhỏ. Giữ ấm trong khi chiên trứng.", "Đun nóng dầu còn lại trong chảo và chiên trứng với ít nêm nếp. Chia hỗn hợp gạo chiên thành 4 tô và đặt một trứng chiên lên mỗi tô. Dùng rắc ngô rí lên trên, kèm tương ớt cay nếu thích."]'::jsonb, 4);
