INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d8d02ab6-1d6f-5757-86b1-93cd41abfce8', 'Bò xào kiểu Thái', 'man'::public.dish_category, '["Đun nóng wok hoặc chảo lớn cho đến khi nóng bốc khói. Đổ dầu vào và lăn quanh chảo, rồi cho thịt bò lát và ớt đỏ vào. Nấu, khuấy đều liên tục, cho đến khi thịt nhẹ vàng, khoảng 3 phút, rồi đổ dầu hào vào. Nấu cho đến khi nóng đều và sốt phủ thịt. Thêm lá húng quế khuấy rồi phục vụ với cơm trắng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d8d02ab6-1d6f-5757-86b1-93cd41abfce8', '41e2849c-302d-5cf6-9f07-ca579b4604a3', 30.0, 'ml'::public.quantity_unit);
