INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d53491bd-3b80-5a6b-99b0-c30ba335e4cb', 'Tôm xào Thái (Prawn stir-fry)', 'man'::public.dish_category, '["Thả tôm vào bát. Cho ớt, tỏi, cuống ngô rí (cắt nhỏ bằng kéo trước) và đường caster vào máy nghiền gia vị hoặc máy xay nhỏ và xay cùng. Thêm nửa nước cốt chanh xanh và nước mắm, rồi rót hỗn hợp này qua tôm.", "Đun 1 muỗng canh dầu trong wok, thêm gừng và hành lá và chiên 1 phút. Thêm ớt chuông đỏ và chiên 1 phút, cho đến khi ớt bắt đầu mềm. Thêm củ năng và giá đỗ, và trộn cùng cho đến khi giá đỗ bắt đầu héo. Thêm xì dầu và chút tiêu đen xay nhè, rồi đổ hết vào đĩa dùng.", "Đun phần dầu còn lại trong wok và thêm tôm, nâng chúng ra khỏi nước mát. Trộn 1-2 phút cho đến khi chúng chuyển hồng, thêm nước ướp và xoay wok nhanh, rồi đổ hết lên rau. Cắt ngô rí lên trên và vắt phần chanh còn lại. Dùng trên mì với chanh thêm để vắt qua."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d53491bd-3b80-5a6b-99b0-c30ba335e4cb', '0a250acb-4cd5-5414-b289-aa75f40bd26b', 200.0, 'g'::public.quantity_unit);
