INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2de59df0-876d-5dab-b69c-593f1bc83793', 'Gà xào ớt và húng quế kiểu Thái (Stir-fried chicken with chillies & basil)', 'man'::public.dish_category, '["Đun chảo xào hoặc chảo xào lớn cho đến khi rất nóng, rồi thêm 1 muỗng canh dầu. Khi rất nóng, thêm gà và xào trên lửa cao trong 8-10 phút, cho đến khi vàng khắp nơi. Dùng thìa có lỗ, lấy gà ra khỏi chảo và để riêng.", "Đun lại chảo xào và thêm dầu còn lại. Ném tỏi và hành tím vào và xào trong 3 phút, cho đến khi vàng.", "Trả gà vào chảo xào và thêm ớt, nước mắm, xì dầu đen và đường. Xào trên lửa cao thêm 8-10 phút hoặc cho đến khi gà chín qua. Khuấy vào lá húng quế và phục vụ ngay lập tức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2de59df0-876d-5dab-b69c-593f1bc83793', '41e2849c-302d-5cf6-9f07-ca579b4604a3', 30.0, 'ml'::public.quantity_unit);
