INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5ae4345d-d9cf-5399-a5a0-9a4769ad140f', 'Cá hấp kiểu Thái', 'man'::public.dish_category, '["Đặt lát cá hồi chấm bên nhau trên một miếng giấy bạc lớn và rắc gừng, tỏi, ớt đỏ và vỏ chanh xanh lên trên. Chọc nước cốt chanh xanh lên trên và rồi rắc lát cải thìa baby xung quanh và lên trên cá. Đổ nước tương lên cải thìa baby và khép giấy bạc lỏng để tạo thành một gói, đảm bảo để khoảng trắng ở trên cho hơi nước tuần hoàn khi cá chín.", "Hấp 15 phút. (Nếu không có nồi hấp, đặt gói trên đĩa chịu nhiệt qua nồi nước sôi nhẹ, đậy nắp và hấp.)"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5ae4345d-d9cf-5399-a5a0-9a4769ad140f', '461d8354-778b-55a2-9342-e4f10b1b6c97', 2.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5ae4345d-d9cf-5399-a5a0-9a4769ad140f', '9a6647ac-a227-585b-a175-0314f34cf87f', 1.0, 'piece'::public.quantity_unit);
