INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5ae4345d-d9cf-5399-a5a0-9a4769ad140f', 'e420f419-4a1c-5433-b888-e18247cb20b9', 30.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7d0eaf5f-274f-55e0-bc85-15a40bd4951c', 'Salad bún gạo kiểu Thái', 'rau'::public.dish_category, '["Cho bún và giá đỗ vào tô chịu nhiệt và ngập nước sôi. Để 4 phút, hoặc cho đến khi bún mềm. Rổ nước, rồi để nguội dưới nước lạnh chảy và rổ nước lại. Cho vào tô.", "Trộn vỏ và nước cốt chanh xanh, nước mắm hoặc nước tương và đường vào. Khuấy vào bún cùng hành tím tây và xà lách.", "Làm với thịt băm, đun ít dầu trong chảo không dính và xào 500g thịt heo băm, một chút gừng xay và một chút ớt bột cayenne hoặc ớt bột cayenne trong 10 phút cho đến khi thịt băm vàng và chín hết. Trộn vào bún, chia thành bốn tô và dùng nóng.", "Làm với steak, làm salad bún gạo. Đun 1 muỗng cà phê dầu hoa hướng dương trong chảo. Cho 2 muỗng canh hạt mè (vừng) vào đĩa. Chà 1 muỗng cà phê dầu vào 4 lát steak 175g và nhấn vào hạt mè. Chiên 5 phút cho đến khi chín vừa, lật giữa đường. Để nghỉ 5 phút, rồi lát mỏng. Trộn 1 ớt đỏ đã bỏ hạt và thái sợi, cùng một nắm lá bạc hà vào bún. Đặt steak lên trên để dùng."]'::jsonb, 4);
