INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('bcc31dd3-0d84-5f45-8190-edc3af905c9e', 'Kebab gà sốt cà ri đỏ (Red curry chicken kebabs)', 'man'::public.dish_category, '["Nung n than hoặc đun nếp nướng đến nhiệt độ cao. Cho thịt gà, sốt cà ri đỏ kiểu Thái và nước cốt dừa vào một bát, trộn đều cho đến khi thịt gà được phủ đều. Xiên bí ngòi xanh, ớt chuông đỏ, hành tím tây và thịt gà vào xiên nướng. Nướng xiên trên n than hoặc nếp nướng trong 5-8 phút, quay liên tục cho đến khi thịt gà chín đều và cháy khét. Ăn kèm cơm thơm, salad và nửa chanh xanh để vắt lên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bcc31dd3-0d84-5f45-8190-edc3af905c9e', '7c9a15f2-fae9-5394-bcbb-9bbae8011db7', 2.0, 'piece'::public.quantity_unit);
