INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c1f16f77-91c7-5ee6-be7d-6d37509ee196', 'Cà ri tôm kiểu Thái', 'man'::public.dish_category, '["Đun nóng dầu trong nồi vừa. Cho hành tây và gừng vào, nấu vài phút cho đến khi mềm. Khuấy sốt cà ri đỏ kiểu Thái vào, rồi nấu thêm 1 phút. Đổ cà chua đóng hộp và kem dừa vào. Đun sôi, rồi hầm sôi nhẹ 5 phút, thêm ít nước sôi nếu hỗn hợp quá đặc.", "Cho tôm sống đông lạnh vào, rồi nấu thêm 5-10 phút tùy theo kích thước. Dùng kèm cơm trắng và rắc ít ngô rí cắt nhỏ nếu thích."]'::jsonb, 4);
