INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4e388961-72f7-5592-b805-47fb5271967a', 'Bánh gà kiểu Thái sốt chilli ngọt', 'man'::public.dish_category, '["Cho thịt gà, tỏi, gừng, hành tây, ngô rí và ớt vào máy xay thực phẩm và nêm nếp đặn. Xay cho đến khi thịt gà được xay nhuyễn và mọi thứ trộn đều. Dùng tay tạo thành sáu bánh nhỏ.", "Đun nóng dầu trong chảo, rồi chiên bánh trên lửa vừa khoảng 6-8 phút, lật một lần. Dùng nóng kèm tương ớt ngọt, lát chanh xanh, ngô rí, hành lá bào sợi và ớt đỏ."]'::jsonb, 4);
