INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('63d2877b-2b4a-5853-9721-aef84bd9132d', 'Sup gà nước cốt dừa kiểu Thái (Tom kha gai)', 'man'::public.dish_category, '["Đổ nước dùng gà và nước cốt dừa vào nồi lớn trên lửa vừa. Cho củ riềng, sả tươi và lá chanh vào, rồi đun sôi nhẹ nhàng khoảng 6-8 phút. Giữ ở mức sôi nhẹ nhàng, thêm gà vào. Nấu 8-10 phút cho đến khi mềm và chín hết.", "Khuấy nấm bào ngư và ớt cima vào, rồi hầm sôi nhẹ thêm 3-5 phút cho đến khi tất cả chín hết. Rắc đường cát mịn và 3 muỗng canh mỗi loại nước mắm và nước cốt chanh xanh vào. Nếm và thêm phần còn lại nếu cần.", "Lấy củ riềng, sả tươi và lá chanh ra trước khi dùng bằng thìa có rãnh. Cho vào tô và dùng với lá ngô rí rắc lên trên và cơm hấp ở bên cạnh. Có thể bảo quản trong tủ lạnh tới ba ngày. Để nguội trước."]'::jsonb, 4);
