INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f2f99855-7e9e-584c-942f-1700a3dbcbf8', 'Canh nước cốt dừa rau quả kiểu Thái', 'canh'::public.dish_category, '["Cho sốt cà ri đỏ kiểu Thái vào nồi lớn hoặc wok cùng dầu. Chiên 1 phút cho đến khi thơm. Cho nước dùng hầm rau củ quả, nước cốt dừa và đường nâu vào. Hầm sôi nhẹ 3 phút.", "Thêm mì trứng, cà rốt và cải thảo vào. Hầm sôi nhẹ 4-6 phút cho đến khi tất cả đều mềm. Cho giá đỗ và cà chua bi vào. Thêm nước cốt chanh xanh theo khẩu vị và nêm thêm nếu thích. Cho vào tô và rải hành lá và ngô rí lên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f2f99855-7e9e-584c-942f-1700a3dbcbf8', '68f0a453-5b0c-5cc6-9066-5ae4344996de', 22.5, 'ml'::public.quantity_unit);
