INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b7fa7a93-55f0-5a55-bf5d-80d3e9cafb59', 'Mì xào tôm cay kiểu Thái (Spicy Thai prawn noodles)', 'man'::public.dish_category, '["Nấu mì theo hướng dẫn trên bao bì, rarget nước và để riêng cho sau. Đun nóng dầu trong chảo xào lớn và rót trứng đã đánh vào. Quay quanh chảo để làm chảo mỏng, nấu trong 1-2 phút, rồi lật ngược và nấu mặt khác trong 1 phút. Đảo ra và cắt thành sợi mỏng.", "Thêm ớt và gừng vào chảo, chiên trong 1-2 phút rồi đổ mì, tôm và trứng vào. Rổt xì dầu vào và xào thêm 1 phút nữa. Ném rau thơm đã cắt vào và rót nước cốt chanh và vỏ chanh, rồi rắc lạc đã cắt vào và phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('b7fa7a93-55f0-5a55-bf5d-80d3e9cafb59', '65d41c7d-edba-590e-b675-fa4c8dfc2930', 200.0, 'g'::public.quantity_unit);
