INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('888048e1-ab26-5571-95ac-d8636c7fe120', 'Canh bí đỏ kiểu Thái', 'canh'::public.dish_category, '["Đun lò 200°C. Trộn bí đỏ hoặc quả bí trong khay nướng với nửa dầu và nêm nếm, rồi nướng 30 phút cho đến khi vàng và mềm.", "Cùng lúc, cho dầu còn lại vào chảo với hành tây, gừng và sả. Nấu nhẹ 8-10 phút cho đến khi mềm. Khuấy sốt cà ri đỏ kiểu Thái vào 1 phút, rồi bí đỏ đã nướng, hầu hết nước cốt dừa trừ 3 muỗng canh và nước dùng. Đun sôi nhẹ, nấu 5 phút, rồi lấy sả ra. Để nguội vài phút, rồi xay cho mịn bằng máy xay tay, hoặc trong máy xay lớn theo đợt. Đưa lại vào chảo để nóng đều, nêm muối, tiêu, nước cốt chanh xanh và đường nếu cần. Dùng chọc nước cốt dừa còn lại và rắc ớt đỏ nếu thích."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('888048e1-ab26-5571-95ac-d8636c7fe120', 'd92c1f73-564a-5fda-8a71-464baefa051d', 1500.0, 'g'::public.quantity_unit);
