INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8d73fb2f-28ef-52cf-8e28-37d7a5facb91', 'Bò kho sả mì', 'man'::public.dish_category, '["Cho gừng, tỏi, sả, ngò rí và 1 ớt đỏ vào máy xay, nhuyễn thành tếm. Đun nóng dầu trong chảo trên lửa nhẹ. Cho tếm vào, nấu 5 phút. Khuấy thêm thịt bò, xì dầu, bột ngũ vị hương, đường và nước dùng. Đậy nắp, đun sôi, hạ lửa hôi 1 giờ 15 phút. Mở nắp, nấu thêm 15 phút cho đến khi thịt bò mềm.", "Trước khi ăn vài phút, luộc mì theo hướng dẫn trên bao bì. Ráo khô, chia ra 2 bát và đỗn bò kho lên trên. Trangs trí với ớt và lá ngò rí còn lại, kèm củ chanh xanh vắt thêm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8d73fb2f-28ef-52cf-8e28-37d7a5facb91', 'd53f6c80-8c7e-50fb-a58e-500d1e4e01c8', 15.0, 'ml'::public.quantity_unit);
