INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5dcce98e-f61f-5592-be37-4304469949ed', 'Đùi gà nướng kiểu Thái', 'man'::public.dish_category, '["Đun lò 200°C và khay nướng giấy bạc. Trộn tương ớt ngọt với vỏ và nước cốt cam, tỏi, sốt cà ri đỏ kiểu Thái và ¼ muỗng cà phê muối. Thêm gà và trộn đều đến khi gà được phủ đều.", "Xếp đùi gà trên giấy bạc, cách đều nhau. Phủ gà với sốt ngâm còn lại trong tô, rồi nướng 35-40 phút cho đến khi mềm. Bọc giấy bạc hoặc đóng vào hộp thực phẩm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5dcce98e-f61f-5592-be37-4304469949ed', 'd0a8068f-35c0-532c-b763-a52679d3a0d2', 30.0, 'ml'::public.quantity_unit);
