INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9573b680-a063-5a3d-a376-9acecb478d3a', 'Canh cá kiểu Thái với rau xanh', 'canh'::public.dish_category, '["Nấu bún theo hướng dẫn trên bao bì. Để nguội trong nước lạnh và rổ nước thật khô.", "Cho nước dùng gà vào nồi lớn và khuấy sốt cà ri đỏ kiểu Thái, lá chanh, nước mắm và 250 ml nước lạnh vào. Đun sôi nhẹ và nấu 5 phút.", "Cắt cá trắng thành các khối khoảng 3 cm và cho vào chảo. Đun sôi nhẹ lại, rồi nấu 2 phút không đậy nắp.", "Khuấy bún, tôm sống và cải thìa vào, và hầm sôi nhẹ 2-3 phút cho đến khi cá và tôm vừa chín. Dùng trong tô rắc ngô rí lên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9573b680-a063-5a3d-a376-9acecb478d3a', 'a745398d-2950-5108-a37f-1f8fd2dae007', 100.0, 'g'::public.quantity_unit);
