INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c0edb2ae-22d8-5572-b904-4dfcee5e24ef', 'Canh gà sốt cà ri xanh kiểu Thái', 'canh'::public.dish_category, '["Đun nóng dầu trong chảo lớn nhất, thêm hành tây và chiên 3 phút cho đến khi mềm. Thêm gà và tỏi, nấu cho đến khi gà đổi màu.", "Thêm sốt cà ri xanh kiểu Thái, nước cốt dừa, nước dùng gà, lá chanh và nước mắm, rồi hầm sôi nhẹ 12 phút. Thêm hành lá cắt nhỏ, đậu que và măng tre, nấu 4-6 phút cho đến khi đậu vừa mềm.", "Cùng lúc, cho nước cốt chanh xanh và húng quế tây vào bình nhỏ và xay bằng máy xay tay thành dền xanh mịn. Đổ vào canh cùng hành lá thái sợi và đun nóng. Dùng kèm lát chanh xanh cho bữa trưa hoặc tối nhẹ, hoặc làm món khai vị trước."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c0edb2ae-22d8-5572-b904-4dfcee5e24ef', '72c039b3-d84c-5d79-bf87-f4b61d743072', 30.0, 'ml'::public.quantity_unit);
