INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7b722aaa-ed7c-5f72-80e9-3d0a72bb904f', 'Cuộn bánh mì shawarma và vai bò hầm (Shawarma chuck roast wrap)', 'man'::public.dish_category, '["Trong nồi ninh hoặc nồi nấu chậm, thêm tất cả gia vị, nước dùng bò và nước cốt chanh. Trộn chung.", "Thêm bò và lật để phủ, chút sốt lên trên.", "Đậy nắp và nấu trên lửa thấp trong 8-10 giờ.", "Sau khi nấu, lấy bò ra và xé bằng 2 nĩa. Bỏ mỡ thừa.", "Vớt mỡ trên mặt nước cốt còn lại.", "Trộn bò xé vào sốt. Giữ nóng cho đến khi sẵn sàng phục vụ.", "Xây cuộn bằng cách đậy sốt tỏi lên bánh mì mỏng. Thêm bò và thêm trang trí theo sở thích.", "Gấp kiểu burrito.", "Đun chảo nướng và nướng cuộn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7b722aaa-ed7c-5f72-80e9-3d0a72bb904f', '5b58f364-1c8c-56e8-99d9-18ded842f1ae', 1000.0, 'g'::public.quantity_unit);
