INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fdc66770-6386-5ef3-94e5-e46c9aba5072', 'Cơm Kabsa Ả Rập (kabse)', 'man'::public.dish_category, '["Chiên cho vàng caramel gà với dầu ô liu rồi thêm một viên Maggi và luộc trong khoảng 30 phút.", "Trong nồi khác, thêm tất cả rau và caramel hóa cho đến khi chúng mềm.", "Khi tất cả đã xong, thêm gạo, nho khô và gia vị vào rau và thêm 600 ml nước cho gạo nấu.", "Khi gạo đã xong đặt tất cả vào lò."]'::jsonb, 4);
