INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3c7e5965-e7c1-56b3-84df-a6664dfef480', 'Shakshuka chay', 'rau'::public.dish_category, '["Chiên hành tím và ớt chuông đỏ cùng nhau trên lửa vừa cho đến khi hành mềm.", "Thêm tỏi sấy dạng hạt nhỏ, nấu một phút.", "Thêm cà chua băm và các gia vị còn lại, khuấy đều.", "Hầm sôi nhẹ khoảng 20 phút.", "Tạo các hố trong sốt và đập một trứng vào mỗi hố.", "Khi trứng trắng đã chín hết, trang trí và dùng với bánh mì nướng lát."]'::jsonb, 4);
