INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c1a464d5-5a35-5c13-b979-05debbd662cb', 'Bánh mì shawarma (Shawarma bread)', 'rau'::public.dish_category, '["Rây bột và thêm bột nở, muối, đường, dầu và trộn chung.", "Thêm nước và nhuyễn bot trong khoảng 10 phút.", "Đậy hỗn hợp và để bot nở.", "Sau khi bot nở, chuyển lên bề mặt làm việc và làm tròn (bạn có thể dùng đĩa hoặc nắp nồi).", "Đun nóng chảo và đặt nó vào.", "Nó sẽ bắt đầu nổi rồi bạn lật nó.", "Cuối cùng đặt nó trong nơi ấm, rồi bạn sẽ thấy nó có túi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c1a464d5-5a35-5c13-b979-05debbd662cb', '6511004e-c078-51d9-90e7-492186b8e9c1', 240.0, 'ml'::public.quantity_unit);
