INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c1a464d5-5a35-5c13-b979-05debbd662cb', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 5.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('700df217-fddf-552f-aa1d-14ab23e0ddbe', 'Bánh tráng cuốn nhân chiên (Rice paper dumplings)', 'man'::public.dish_category, '["Cho bắp cải trắng vào máy xí nhuyễn và xay cho đến khi nhỏ nhặt. Nêm nửa muỗng cà phê muối, trộn tốt và để riêng 15 phút. Cho vào khăn sạch và vắt lấy càng nhiều nước càng tốt. Cho vào bát cùng cà rốt, nấm đông cô, thịt heo xay, tỏi, gừng, xì dầu, dầu mè và hành lá. Nêm tiêu đen. Nhuyễn tất cả bằng tay, trộn đều cho đến khi mọi thứ kết hợp.", "Ngâm vở bánh tráng cuốn gỏi trong vài giây trong đĩa nước ấm, rồi chuyển lên thớ đã phơi dầu. Làm việc với một tờ mỗi lần, cho một muỗng canh đầy nhân vào giữa, rồi gấp phần dưới lên và phủ nhân. Gấp phần trên của tờ bánh, rồi hai bên để hoàn toàn bao bọc và thành hình vuông đều. Nếu bánh cảm giác hơi dễ vỡ, ngâm thêm một tờ và bọc lại. Làm tương tự với các tờ bánh và nhân còn lại, chuyển các bánh lên đĩa đã phơi dầu khi bạn làm.", "Đun nóng dầu thực vật trong chảo không dính lớn (đảm bảo không quá một phần ba chảo) trên lửa vừa-cao và chiên các bánh trong 3-5 phút cho đến khi vàng. Dùng thìa có lỗ để lật chúng, rồi nắp nắp lên và nấu thêm 3-4 phút cho đến khi vàng. Mở nắp và nấu thêm 1-2 phút.", "Trong lúc đó, trộn hết các thành phần sốt chấm trong bát nhỏ. Phục vụ các bánh với sốt chấm ở một bên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('700df217-fddf-552f-aa1d-14ab23e0ddbe', '2ec75171-2e76-59e4-a1e6-e35ad57bcbc1', 0.25, 'piece'::public.quantity_unit);
