INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('26cde5b0-1403-52bd-acbf-9d9cc814c1c9', 'Cá hồi caramel kiểu Việt Nam', 'man'::public.dish_category, '["Cho đường vào chảo lớn thấp, cùng một chút nước. Đun nhẹ, xoay chảo, cho đến khi đường tan. Tăng lửa và đun sốt cho đến khi chuyển màu vàng đậm. Thêm nước mắm, phần lớn ớt đỏ và gừng, rồi chọc 1 muỗng canh nước vào để loãng. Đun sôi lại cho đến khi đặc loãng, rồi thêm lát cá hồi, phía da xuống, và cải thìa, phía cắt xuống.", "Đậy nắp chảo và hầm sôi nhẹ 4-5 phút cho đến khi cá chín và cải thìa đã úa. Tắt bếp, chọc nước cốt chanh vàng lên và rắc phần ớt đỏ, gừng và nhánh ngô rí còn lại. Dùng với gạo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('26cde5b0-1403-52bd-acbf-9d9cc814c1c9', '17ed562f-6ab8-5a78-94a2-83654dacd0c6', 50.0, 'g'::public.quantity_unit);
