INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('49c4c11c-f846-59eb-aaa4-8ebcb107e4f1', 'Salad mì bò nướng kiểu Việt Nam (Steak & Vietnamese noodle salad)', 'man'::public.dish_category, '["Trộn tất cả thành phần sốt trong bát với 1 muỗng canh nước cho đến khi đường tan.", "Nấu mì theo hướng dẫn trên bao bì, rồi ngâm vào bát nước lạnh để nguội hoàn toàn. Rarget nước mì, rồi thêm cà rốt, cải, hành lá và sốt, và khuấy để trộn.", "Đun nóng dầu trong chảo xào trên lửa cao. Nems steak, rồi nấu theo sở thích; 2-3 phút mỗi mặt cho vừa chín, có hồng lòng. Để nghỉ trong 5 phút, rồi cắt lát. Chia salad và lát steak vào các bát và rắc ngô rí lên trên để phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('49c4c11c-f846-59eb-aaa4-8ebcb107e4f1', 'a745398d-2950-5108-a37f-1f8fd2dae007', 85.0, 'g'::public.quantity_unit);
