INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8e860e03-d217-55b1-b29c-54d734d16d66', 'Cốt lết cừu nấu khoai lang kiểu Việt Nam', 'man'::public.dish_category, '["Đun lò 160°C. Đun 1 muỗng canh dầu trong nồi hầm đáy dày, nêm cốt lết cừu, rồi vàng chúng 2 lát một lần mọi mặt, thêm dầu còn lại cho lần thứ hai. Lấy cừu ra và thêm hành tây. Chiên chúng khá nhanh, khoảng 30 giây, thêm gừng, tỏi và ớt đỏ băm, rồi giảm lửa và nấu 1 phút. Thêm 1 muỗng canh đường, khuấy, rồi thêm hoa hồi, sả tươi, nước hầm thịt cừu, cà chua xay nhuyễn và gia vị. Đun sôi.", "Đậy nắp và nấu trong lò 1,5 giờ, rồi thêm khoai lang và nấu thêm 1 giờ. Cừu nên hoàn toàn mềm và gần như rụng xương. Khuấy nước mắm, nước cốt chanh xanh và 1 muỗng cà phê đường vào để nâng vị, rồi rắc bạc hà, húng quế tây và ớt đỏ lát để dùng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8e860e03-d217-55b1-b29c-54d734d16d66', '517c3f35-996d-5157-a620-45cafd626c06', 30.0, 'ml'::public.quantity_unit);
