INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c4a7bb39-4900-5f3d-a0d6-09606616d85b', 'Salad gà kiểu Việt Nam', 'man'::public.dish_category, '["Để làm sốt, đánh trộn tất cả nguyên liệu vào tô dùng lớn. Nấu bún theo hướng dẫn trên bao bì, rồi rổ nước và thêm vào tô cùng sốt.", "Bóc cà rốt thành sợi dài bằng lóc rau. Làm tương tự với dưa leo, cho đến khi đạt đến hạt (loại bỏ chúng). Thêm cà rốt và dưa leo vào hỗn hợp bún cùng với thịt gà xé, củ cải đỏ, hành tím tây và bạc hà. Trộn tốt để đậy trong sốt, rắc đậu phộng lên trên và dùng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c4a7bb39-4900-5f3d-a0d6-09606616d85b', '65d41c7d-edba-590e-b675-fa4c8dfc2930', 140.0, 'g'::public.quantity_unit);
