INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('947d8a90-9bf1-54c6-8b99-f925f8381ac1', 'Mực chiên muối tiêu (Salt & pepper squid)', 'man'::public.dish_category, '["Để làm sốt chấm, trộn tất cả nguyên liệu trong bát nhỏ cho đến khi đường tan, rồi để riêng. Trộn bột mì ngô và bột mì đa dụng với cả hai loại ớt và 2 muỗng cà phê muối biển trong bát lớn, rồi để riêng. Lót khay bằng giấy tầu và đảm bảo bạn có thêm muối để rắc.", "Đun khoảng 7 cm dầu lên 180°C trong chiên xả, wok hoặc chảo đậm. Nếu bạn không có nhiệt kế, bạn có thể kiểm tra bằng một khối bánh mì – nó nên vàng trong 20 giây. Bọc mực tốt với hỗn hợp bột và chiên theo từng đợt khoảng 2 phút mỗi lần cho đến khi giòn. Dùng thìa có lỗ để nâng mực ra, rồi rarget trên giấy tầu và rắc một ít muối thêm. Phục vụ mực rắc hành lá và ớt, với sốt chấm ở một bên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('947d8a90-9bf1-54c6-8b99-f925f8381ac1', '12fe5889-1eaf-59e9-b1ea-7748e8c37010', 85.0, 'g'::public.quantity_unit);
