INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e3961a8e-6d7b-5495-a52e-801fd7974f6e', 'Sup mì cá hồi (Salmon noodle soup)', 'canh'::public.dish_category, '["Đổ nước dùng vào chảo lớn, đun sôi, rồi khuấy vào sốt cà ri đỏ kiểu Thái. Thêm mì và nấu trong 8 phút. Cho nấm đông cô và ngô vào và nấu thêm 2 phút.", "Thêm cá hồi vào chảo và nấu trong 3 phút cho đến khi chín đều. Bớt bấm và khuấy vào nước chanh, xì dầu và một chút đường. Đổ vào 4 tô và rắc ngô rí ngay trước khi phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('e3961a8e-6d7b-5495-a52e-801fd7974f6e', 'bda8c5ec-94c7-50c4-8658-919b21da2e28', 1000.0, 'ml'::public.quantity_unit);
