INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5d26405a-ddea-5657-9a5f-65a2d8c87edb', 'Heo caramel kiểu Việt Nam', 'man'::public.dish_category, '["Đun nóng 1 muỗng canh dầu trong wok trên lửa cao và xào thịt heo theo đợt cho đến khi vàng mọi mặt. Lấy ra bằng thìa có rãnh và để một bên.", "Giảm lửa xuống thấp nhất và thêm dầu còn lại, rồi khuấy hành tím, gừng và ớt vào. Nấu trên lửa thấp vài phút cho đến khi bắt đầu mềm. Thêm đường, nước mắm và 200 ml nước vào chảo và khuấy tất cả cùng nhau. Đun sôi, khuấy, cho đến khi đường tan, rồi trả thịt heo vào chảo. Đun sôi mạnh 8-10 phút cho đến khi sốt đặc để phủ thịt và trở nên bóng. Nếm và khuấy thêm ít nước mắm hơn nếu cần, cùng với sốt ớt. Rắc hành lá lên và dùng với cơm hấp và cải thìa."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5d26405a-ddea-5657-9a5f-65a2d8c87edb', '517c3f35-996d-5157-a620-45cafd626c06', 22.5, 'ml'::public.quantity_unit);
