INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f49b4239-812b-5790-9a4a-a81a6958664b', 'Lẩu rau kiểu Việt Nam', 'rau'::public.dish_category, '["Đun nóng dầu trong nồi vừa có nắp. Thêm gừng và tỏi, rồi xào khoảng 5 phút. Thêm bí đỏ hồ lô, nước tương, đường và nước dùng. Đậy nắp, rồi hầm sôi nhẹ 10 phút. Mở nắp, thêm đậu que, rồi nấu thêm 3 phút cho đến khi bí đỏ hồ lô và đậu que đều mềm. Khuấy hành lá vào ở phút cuối, rồi rắc ngô rí và dùng với gạo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f49b4239-812b-5790-9a4a-a81a6958664b', '41e2849c-302d-5cf6-9f07-ca579b4604a3', 10.0, 'ml'::public.quantity_unit);
