INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2a8f1266-664b-5231-a9b8-b3e7eacce583', 'Salad heo kiểu Việt Nam', 'man'::public.dish_category, '["Ngày hôm trước: làm sốt. Cho đường và nước cốt chanh xanh vào nồi với 1 muỗng canh nước và đun sôi để tan đường. Thêm ớt đỏ và ngô rí và khuấy đều, rồi xay nhuyễn trong máy xay cho đến khi mịn. Đổ vào tô, rồi khuấy dầu mè thơm nguyên chất, nước mắm, nước tương và hạt mè vào để làm sốt. Đậy và để tủ lạnh cho đến khi cần.", "Hai giờ trước khi dùng: đun nóng chảo nướng. Đun lò 200°C. Chọc dầu vào thịt heo và nướng mọi mặt vài phút cho đến khi cháy nhẹ. Chuyển vào khay nướng và cho vào lò khoảng 10-12 phút cho đến khi chín hết. Để nguội, lát mỏng ngang với xơ thịt. Đổ vào tô và rót nửa sốt lên.", "Để dùng: trộn các nguyên liệu salad còn lại trong tô với sốt còn lại. Đống lên đĩa lớn, đặt lát heo lên trên và châm chút nước dùng lên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2a8f1266-664b-5231-a9b8-b3e7eacce583', '17ed562f-6ab8-5a78-94a2-83654dacd0c6', 5.0, 'ml'::public.quantity_unit);
