INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fb03d45d-cea0-5ef9-a758-50890e8b9740', 'Phở bò', 'man'::public.dish_category, '["Đổ nước dùng bò cùng 500 ml nước vào nồi lớn. Đặt hành tây và gừng trong chảo chiên trên lửa cao và rang cho đến khi cháy từng bên, khoảng 3-5 phút (bạn cũng có thể làm điều này dưới nồi nướng). Sau khi đã cháy, thêm vào nước dùng bò. Trong cùng chảo, rang gia vị trong 2-3 phút và khi chúng bắt đầu thơm, thêm chúng vào nước dùng bò cũng như vậy. Đun nước dùng đến sôi, rồi chuyển sang hầm nhẹ và nấu trong 30 phút trước khi lọc.", "Cùng lúc đó, cắt phần béo từ thăn và bao bọc bằng bọc thực phẩm, rồi đặt vào tủ lạnh đá trong 15 phút – điều này sẽ làm cho thăn của bạn rất dễ cắt lát! Cắt lát mỏng, rồi bao bọc bằng bọc thực phẩm lại và đặt vào tủ lạnh.", "Nếm nước dùng bò và dùng đường thốt nốt, nước mắm và nước tương để nems. Nấu mì theo hướng dẫn trên bao bì và chia cho hai bát, đặt lát thịt bò lên trên mỗi bát. Đun nước dùng đến sôi rồi đổ vào các bát (nóng sẽ chín thịt bò). Đặt hành lá, lát ớt và thảo mộc lên trên mỗi bát. Phục vụ với các miếng chanh xanh để chắt lên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('fb03d45d-cea0-5ef9-a758-50890e8b9740', '93d0e445-664f-5c28-833d-04e493515d3c', 1000.0, 'ml'::public.quantity_unit);
