INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('236a598b-47b8-58ad-adfe-1177cf641576', 'Salad tôm bang bang', 'man'::public.dish_category, '["Nấu mì theo hướng dẫn trên bao bì, rồi rửa dưới nước lạnh và để thoát nước hoàn toàn. Trong nồi nhỏ, nung chảy cùng bơ đậu phộng, nước cốt dừa, tương ớt ngọt và nửa hành lá, thêm 1-2 muỗng canh nước để làm loãng hỗn hợp cho đến khi vừa đủ để rưới.", "Trộn mì, dưa leo và giá đỗ trong đĩa phục vụ. Đặt tôm lên trên, rưới sốt đậu phộng và rắc hành lá còn lại."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('236a598b-47b8-58ad-adfe-1177cf641576', '65d41c7d-edba-590e-b675-fa4c8dfc2930', 140.0, 'g'::public.quantity_unit);
