INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c002f95c-40c9-529a-af09-465d4e3bf015', 'Đậu hũ xào rau và hạt điều', 'rau'::public.dish_category, '["Đun nóng dầu trong wok không dính. Thêm bông cải xanh, rồi chiên trên lửa cao 5 phút hoặc cho đến khi vừa mềm, thêm ít nước nếu bắt đầu dính. Thêm tỏi và ớt, chiên 1 phút, rồi khuấy với hành lá, hạt đậu nành, cải thìa và đậu hũ tẩm gia vị. Xào 2-3 phút. Thêm sốt tương đen Hoisin, nước tương và hạt điều để nóng qua."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c002f95c-40c9-529a-af09-465d4e3bf015', '41e2849c-302d-5cf6-9f07-ca579b4604a3', 15.0, 'ml'::public.quantity_unit);
