INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('96c9c0bf-eacc-54dd-a75f-d766fc368a91', 'Cuốn rau chế biến kiểu Việt Nam', 'rau'::public.dish_category, '["Ngâm bánh xèo bột gạo theo hướng dẫn trên bao bì hoặc trong nước sôi 30 giây. Lấy ra và để nguội trên giấy bếp. Ngâm bún gạo theo hướng dẫn trên bao bì, rồi rổ nước và cắt chúng thành sợi 2cm.", "Đặt một bánh xèo bột gạo trên mặt bằng và sắp xếp bún gạo, gà, rau và lá thảo mộc khoảng một phần ba chiều cao, để một cạnh 1cm ở bên. Gấp các cạnh qua rau rồi cuốn dài. Lưu trong tủ lạnh, phủ bằng giấy bếp ẩm cho tới 1 ngày.", "Trộn cùng các nguyên liệu cho sốt chấm và cho vào tô. Để dùng, sắp xếp các cuốn trên đĩa cùng lá và thảo mộc. Để ăn, gói từng cuốn vào một miếng xà lách với nhánh thảo mộc và nhúng vào sốt."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('96c9c0bf-eacc-54dd-a75f-d766fc368a91', '2b970252-5ac1-5f7f-b26d-4d4b2c524c4f', 100.0, 'g'::public.quantity_unit);
