INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7ab58c3c-98e4-515f-9696-9907c116ded5', 'Bánh bao heo nướng', 'man'::public.dish_category, '["Đun lò đến 200°C. Trộn đường vào hỗn hợp bánh mì trong bát lớn, rồi thêm nước theo hướng dẫn trên bao bì. Tập hợp bột bằng muỗng gỗ, rồi xoa uống trên bề mặt đã bón nhẹ bột trong 5 phút cho đến khi mịn. Đặt vào bát lớn, đậy bằng bọc thực phẩm đã dầu rồi để ở nơi ấm cho đến khi dội đôi.", "Cùng lúc đó, đun dầu trong chảo, rồi chiên xúc xích khói cho đến khi giòn, khoảng 5 phút. Thêm gừng và tỏi và chiên 1 phút cho đến khi mềm, rồi đổ nước tương, mật ong và cà chua xay nhuyễn vào và khuân tốt. Có thể làm trước tối đa 3 ngày.", "Đổ bột ra và xoa uống ngắn, rồi kéo thành 12 viên bằng nhau. Úp nhẹ bằng tay, rồi đặt một poi nhân lớn như một muỗng cà phê ở giữa. Kéo bột lên và kín lại như một bao, rồi lật bánh lên và đặt nó trên khay nướng lớn. Đậy bằng bọc thực phẩm đã dầu và để nở khoảng 30 phút cho đến khi bột mềm như gối. Quét trứng và nướng 20 phút cho đến khi vàng. Phục vụ khi ấm với sốt chấm. Có thể đóng băng sau lần nở thứ hai trong tối đa 1 tháng hoặc nướng trước tối đa một ngày và hâm nóng lại."]'::jsonb, 4);
