INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('bceb69b6-425d-5404-a52f-cb6ea59bc00c', 'Gỏi cuốn tôm rau củ xoắn sợi kiểu Việt Nam', 'man'::public.dish_category, '["Trộn tất cả nguyên liệu cho sốt chấm cùng 50 ml nước vào tô và để một bên để đường tan và hương thấm.", "Để cuốn, đổ nước ấm vào tô rộng và lấy khăn ẩm sạch để làm việc trên. Nhúng bánh tráng vào nước vài giây cho đến khi mềm rồi cẩn thận đặt lên khăn ẩm.", "Đặt một vài lá bạc hà và ngô rí vào giữa bánh tráng rồi đặt hai tôm và một nắm nhỏ rau củ xoắn sợi, có thể cần cắt nếu các xoắn quá dài.", "Gấp các cạnh bánh tráng vào giữa, bên trên nhân, rồi gấp các viền vào, để nhân được bao bọc hoàn toàn, rồi cuốn chặt. Làm lại cho đến khi tất cả bánh tráng và nhân đã được dùng. Để dùng, lát chéo và ăn với sốt chấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bceb69b6-425d-5404-a52f-cb6ea59bc00c', '6f3e8a07-5496-5e41-94db-a34866afbff5', 30.0, 'ml'::public.quantity_unit);
