INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bceb69b6-425d-5404-a52f-cb6ea59bc00c', '07b31e21-696b-5e81-8f6e-995a8c8fe4af', 1.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3b80f0f0-1923-5f63-a50d-cb7309b228c9', 'Salad tôm mì với hành tím giòn Việt Nam', 'man'::public.dish_category, '["Làm hành tím giòn, đun 5 cm dầu cho đến khi nóng trong wok. Bạn sẽ biết dầu đủ nóng khi một miếng hành ch是吗 sizzles ngay khi thả vào. Trộn lát hành với bột mì, lắc dớt bột thừa và chiên trong dầu cho đến khi vàng. Chúng chiên nhanh, khoảng 1 phút. Ráo trên khăn bếp giấy, rắc muối và để riêng.", "Làm sốt, trộn nước cốt chanh xanh, đường, nước mắm và tỏi và để riêng. Trong bát trộn lớn, rót nước sôi qua mì. Để chúng 2 phút hoặc cho đến khi vừa chín, rồi rửa dưới nước lạnh. Ráo tốt, lắc lưới nhiều lần để loại bỏ nước thừa, rồi đặt trở lại bát. Thêm tôm, hành, ớt, dưa leo và thảo mộc. Rót sốt qua, trộn, rồi rắc hành tím và đậu phộng lên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3b80f0f0-1923-5f63-a50d-cb7309b228c9', '65d41c7d-edba-590e-b675-fa4c8dfc2930', 200.0, 'g'::public.quantity_unit);
