INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3768c19f-37c6-5828-98ae-aaaff8b57e01', 'Salad bát mì Việt Nam (Noodle bowl salad)', 'man'::public.dish_category, '["Cho mì vào bát lớn, rồi rót đủ nước sôi ngập. Thêm đậu ngọt đã thái và để 4 phút. Ráo trong cái rổ, đặt dưới vòi nước lạnh chạy cho nguội, rồi ráo lại. Đổ vào bát và trộn với dầu mè.", "Trộn các nguyên liệu sốt. Đống hành lá, ngô rí và cá hồi hun khói lên mì, rót sốt qua và trộn tất cả với nhau. Dùng kèm bánh xoắn mặn Pretzels hoặc bánh mì ổ nhỏ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3768c19f-37c6-5828-98ae-aaaff8b57e01', '65d41c7d-edba-590e-b675-fa4c8dfc2930', 125.0, 'g'::public.quantity_unit);
