INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('11ca9364-65d8-566b-8438-df843bf9edec', 'Salad cà rốt, bắp cải tím và hành tím chua ngọt', 'rau'::public.dish_category, '["Cho cà rốt, bắp cải tím và hành tím vào tô. Làm sốt bằng cách trộn đều các nguyên liệu cho đến khi đường tan. Đổ lên salad, khuấy rau trong sốt. Thêm bạc hà và lá ngô rí, khuấy lại, rồi rải đậu phộng rang lên trên."]'::jsonb, 4);
