INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('518ff025-7172-5da1-95fe-fff01e3cb68b', 'Cá chẽm nướng thenh gừng, ớt và hành lá (Sea bass with sizzled ginger, chilli & spring onions)', 'man'::public.dish_category, '["Nems muối và tiêu cho 6 fillet cá chẽm, rồi chọc da 3 lần.", "Đun nóng chảo đáy dày và thêm 1 muỗng canh dầu hoa hướng dương.", "Khi nóng, chiên fillet cá chẽm, mặt da xuống, trong 5 phút cho đến khi da rất giòn và vàng. Cá sẽ gần như chín đều.", "Lật ngược lại, nấu thêm 30 giây - 1 phút, rồi chuyển sang đĩa phục vụ và giữ nóng. Bạn sẽ cần chiên các fillet cá chẽm trong 2 đợt.", "Đun nóng 2 muỗng canh dầu hoa hướng dương, rồi chiên cả củ gừng đã bóc và cắt thành găm nhỏ, 3 tép tỏi thái mỏng và 3 ớt đỏ thái sợi mỏng trong khoảng 2 phút cho đến khi vàng.", "Bớt bấm và ném vào nhiều hành lá thái sợi. Rưới 1 muỗng canh xì dầu lên cá và đảo lên trên nội dung chảo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('518ff025-7172-5da1-95fe-fff01e3cb68b', 'cbfa6358-8309-5939-85d6-3bb02535cc62', 6.0, 'piece'::public.quantity_unit);
