INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('eb0c973a-de40-57ba-b9b5-d40d2ef6b531', 'Gói mì cá hồi (Salmon noodle wraps)', 'man'::public.dish_category, '["Đun lò lên 200°C. Đặt mì vào bát và đổ đủ nước sôi chỉ ngập chúng. Để trong 2 phút, cho đến khi uốn được nhưng không quá mềm, rồi rarget nước tốt. Trả vào bát với hành lá, đậu Hà Lan hạt nhỏ ngọt, muối và tiêu và một phần ba bơ. Trộn tốt cho đến khi bơ đã tan.", "Xếp mì và rau lên hai tô giấy nướng lớn, rồi đặt cá hồi lên trên. Cắt bơ còn lại thành lát và xếp lên trên cá hồi. Đưa đầu giấy qua trên cá, gấp chúng lại để kín, rồi cuộn đầu giấy xuống dưới để không có kẽ. Đặt các gói trên khay nướng và nướng trong 15-20 phút. Chuyển vào đĩa ăn và phục vụ ngay lập tức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('eb0c973a-de40-57ba-b9b5-d40d2ef6b531', '65d41c7d-edba-590e-b675-fa4c8dfc2930', 100.0, 'g'::public.quantity_unit);
