INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('491106fb-7e0e-5a9f-8091-48a7ebc468b2', 'Bánh mì chay kiểu Việt Nam', 'rau'::public.dish_category, '["Cho rau củ thái sợi vào tô và thêm giấm, đường và 1 muỗng cà phê muối. Trộn mọi thứ cùng nhau, rồi để một bên để muối chua nhanh trong khi bạn chuẩn bị phần còn lại của bánh sandwich.", "Đun lò 180°C. Cắt bánh mì baguette thành bốn, rồi cắt mỗi miếng theo chiều ngang thành nửa. Đặt các miếng bánh mì vào lò 5 phút cho đến khi nhẹ nướng và nóng. Bớt một lớp hummus lên mỗi miếng, rồi đặt lát tempeh lên bốn miếng và xếp rau củ đã muối chua lên trên. Để dùng, rắc thảo mộc lên và chọc sốt ớt cay lên, rồi đặt các miếng bánh mì còn lại lên trên để làm sandwich."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('491106fb-7e0e-5a9f-8091-48a7ebc468b2', '77e4b1d5-633e-5975-92b3-4054ab94d7ca', 150.0, 'g'::public.quantity_unit);
