INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('78b09509-5782-5a28-93e1-9975d45f40d3', 'Bánh mì mỏng thịt bò kiểu Thổ Nhĩ Kỳ (lahmacun)', 'man'::public.dish_category, '["Cho bột mì số 13 chuyên dụng bánh mì vào tô lớn, làm một hốc ở giữa và rắc men vào. Đổ 125 ml nước lên men, rồi rắc bột lên trên dịch để tạo một lớp. Đậy và để men nở ở nơi ấm 15 phút cho đến khi nứt xuất hiện trên bề mặt lớp đó.", "Dùng tay trộn thêm 250 ml nước cùng 1 muỗng cà phê muối và cuộn bột khoảng 10 phút cho đến khi co giãn và không còn dính. Thêm ít bột mì hơn nếu cần. Đậy và để men nở lại ở nơi ấm 30 phút cho đến khi tăng gấp đôi.", "Đun lò đến mức cao nhất có thể (khoảng 240°C) và rắc một hoặc hai khay nướng mỏng bột ngô.", "Đổ nước sôi từ ấm vào cà chua, để đứng ngắn, rồi rổ nước và bóc vỏ. Cắt cà chua thành nửa, cắt cuống, lấy hạt ra và loại bỏ, rồi cắt nhừ thịt.", "Cắt ớt xanh dọc theo chiều dài, cắt cuống, hạt và màng trắng bên trong, rồi xả. Cắt dọc thành sợi mịn, rồi ngang thành khối nhỏ.", "Cho cà chua, ớt xanh, hành lá, ngô tây cắt nhỏ, thịt bò xay, gia vị, 1 muỗng cà phê muối và ½ muỗng cà phê tiêu đen recién xay vào tô và trộn đều.", "Lấy bột và cuộn ngắn, rồi chia thành bốn miếng và định hình mỗi miếng thành viên. Cuộn từng viên thành hình tròn mỏng, đặt lên các khay nướng đã chuẩn bị. Bớt một lớp mỏng của hỗn hợp thịt lên trên.", "Nướng từng bánh mì phẳng 10-15 phút cho đến khi viền bắt đầu tối. Sau khi lấy khỏi lò, rắc lahmacun với ngô tây cắt không đều và hành tây lát, rồi chọc vài giọt nước cốt chanh vàng lên. Dùng ngay lập tức."]'::jsonb, 4);
