INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('99826e23-a90f-550b-be84-a4ef03b0330f', 'Salad cà chua ớt Thổ Nhĩ Kỳ (Ezme)', 'rau'::public.dish_category, '["Cho cà chua và ớt sừng ngọt vào máy xay, xay nhuyễn. Đặt trên rổ lọc đặt trên bát để rót nước. Cho hành tây, tỏi và ngô tay vào máy xay, xay nhuyễn, sau đó để một bên.", "Cho sốt đặc ớt chuông đỏ, cà chua xay nhuyễn, mật lựu cô đặc, ớt vảy Thổ Nhĩ Kỳ, bột sumac, bạc hà khô và phần lớn dầu ô liu nguyên chất vào bát ăn, trộn đều cho mọi thứ hòa thành sốt. Đổ hỗn hợp hành tây đã xay và hỗn hợp ớt đã rót nước cùng 1 muỗng cà phê muối biển mảnh vào, khuấy đều, rồi rưới phần dầu ô liu còn lại để ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('99826e23-a90f-550b-be84-a4ef03b0330f', 'de974e5e-edf0-5b8f-a7dc-f105cb93acdb', 3.0, 'piece'::public.quantity_unit);
