INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e8b94a6a-2451-564c-b9f1-b2c1df35272f', 'Cà tím nướng với đậu gà cay sốt óc chó (Grilled aubergines with spicy chickpeas & walnut sauce)', 'rau'::public.dish_category, '["Đun 2 muỗng canh dầu trong chảo, thêm hành tây và chiên cho đến khi mềm và hơi vàng, khoảng 10 phút. Thêm ớt, gừng và gia vị rồi trộn tốt. Khuấy đậu gà, cà chua và 5 muỗng canh nước vào, đun sôi, rồi sôi nhẹ trong 10 phút. Thêm một chút muối và tiêu và nước cốt chanh.", "Sắp xếp cà tím lên chảo nướng. Mở nhẹ dầu, rắc muối và tiêu, rồi nướng cho đến khi vàng. Lật chúng qua, mở lại dầu, nêm nếm và nướng tiếp cho đến khi mềm và vàng.", "Trộn sữa chua với tỏi, phần lớn óc chó và ngô rí và một chút muối và tiêu. Sắp xếp lát cà tím lên đĩa nóng và gắp hỗn hợp đậu gà lên trên. Rưới sốt óc chó và rắc óc chó và ngô rí còn lại."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('e8b94a6a-2451-564c-b9f1-b2c1df35272f', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 60.0, 'ml'::public.quantity_unit);
