INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7a6fe565-7360-5aea-9d6c-b2f080595f08', 'Cacik Thổ Nhĩ Kỳ', 'rau'::public.dish_category, '["Đặt một rason lên bát lớn, lót nó bằng một tờ khăn giấy không nhuộm dày hoặc một tấm vải muslin sạch, và thìa sữa chua vào. Đậy bằng một tờ khăn giấy khác và để lọc trong tủ lạnh ít nhất 12 giờ.", "Thêm nước chanh vàng, phần lớn dầu ô liu và bạc hà khô vào bát và khuân tốt cho đến khi bạc hà khô mềm và hấp thụ nước cất. Khuân sữa chua đã lọc vào, rồi xé bỏ nước sữa chua đã lọc và để bát đó một bên.", "Cắt dưa leo thành hai theo chiều dọc và loại bỏ hạt bằng cách chạy một thìa cà phê từ trên xuống dưới của thịt, cắt dưa leo thành hai theo chiều ngang để chúng ngắn hơn và dễ xử lý, rồi bào thô mỗi cái vào bát sữa chua đang lọc qua. Dùng tay sạch (hoặc một tấm vải muslin sạch), nén càng nhiều nước từ dưa leo có thể.", "Thêm dưa leo đã lọc và bào, tỏi và 3/4 muỗng cà phê muối hạt vào phần còn lại của các nguyên liệu và khuân tốt. Trang trí bằng dầu ô liu nguyên chất thêm một chút và một chút bạc hà khô rắc lên trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7a6fe565-7360-5aea-9d6c-b2f080595f08', 'd8147e12-2f16-5df9-bdd6-16ba54f8c8c1', 500.0, 'g'::public.quantity_unit);
