INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f9e5b967-9500-5a6f-80ef-53d5c1e04804', 'Burger kofta Thổ Nhĩ Kỳ (kofta burgers)', 'man'::public.dish_category, '["Đổ thịt xay vào một bát lớn (dùng một cái bát rửa bát sạch nếu bạn không có gì đủ lớn) với tất cả các nguyên liệu burger khác và một nắm muối đẹp. Cuộn tay áo lên, đặt tay vào hỗn hợp và nghiền hết mọi thứ cùng nhau qua ngón tay cho đến khi trộn hoàn toàn. Dập hỗn hợp thành 16 bánh burger nhỏ. Những bánh này có thể được đông lạnh trong tối đa 1 tháng hoặc bảo quản trong tủ lạnh đến một ngày trước.", "Để nấu, đun nắp nướng đến chế độ cao nhất và đặt các bánh burger thành một lớp trên khay nướng (bạn có thể cần làm theo lượt, tùy theo kích thước khay của bạn). Nướng trên kệ cao nhất trong 5-6 phút mỗi bên cho đến khi vàng và chín kỹ. Đống các bánh burger lên đĩa và ăn với tất cả các món kèm, để mọi người có thể tự làm sandwich của mình."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f9e5b967-9500-5a6f-80ef-53d5c1e04804', '53d68eb2-9589-5956-abbd-25c77ed291c9', 1000.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f9e5b967-9500-5a6f-80ef-53d5c1e04804', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 2.0, 'piece'::public.quantity_unit);
