INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f21c3ffd-368c-524b-bde4-f435649044af', 'Gói cừu sốt cumin nóng với salad giòn và sốt mayonnaise cay (Hot cumin lamb wrap with crunchy slaw & spicy mayo)', 'man'::public.dish_category, '["Đun chảo nướng. Chà các lát cừu với dầu, cumin và một chút gia vị. Nướng khoảng 3-4 phút mỗi bên hoặc cho đến khi chín theo ý thích. Đặt về một bên trên đĩa để nghỉ.", "Trong bát lớn, khuấy đường vào giấm cho đến khi tan. Thêm cà rốt, hành lá, cải và một chút gia vị, rồi trộn cùng nhau.", "Xay nhuyễn các ớt nguyên và sốt mayonnaise trong máy xay. Thêm một đống salad vào mỗi bánh mì mỏng. Cắt cừu, cắt bỏ chất béo thừa và đặt lên trên salad, rưới nước thịt. Đổ sốt mayonnaise lên và rắc vài lát ớt đã cắt. Cuộn lại và ăn. Nếu sử dụng pita, cắt thành hai và nhồi. Ăn salad thừa ở bên cạnh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f21c3ffd-368c-524b-bde4-f435649044af', 'ddb7bb27-1d6e-5063-a720-1d7dfbb8f6e6', 4.0, 'piece'::public.quantity_unit);
