INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8b6ae7a8-6976-5e6d-bad7-e5b512caa00b', 'Cà tím xông khói nghiền (Smoked aubergine purée)', 'rau'::public.dish_category, '["Đun nồi nướng đến rất nóng. Cắt cà tím thành hai ngang theo chiều dọc, rồi nướng trong 25 phút, lật đôi khi, cho đến khi mềm – da vẫn còn chắc, nhưng thịt sẽ mềm. Lấy cà tím khỏi nồi nướng và để cho đến khi đủ mát để bắt tay.", "Dùng dao sắc, chọc thịt đã nướng và lấy thịt bằng thìa. Đổ vào bát và nghiền bằng nĩa cho đến khi có hỗn hợp đặc. Khuấy vào nước cốt chanh và tỏi. Thêm sữa chua và thì là, và nems. Phục vụ trong khi còn ấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8b6ae7a8-6976-5e6d-bad7-e5b512caa00b', '1d49713a-73c2-5b5c-aaea-110ec71ca040', 2.0, 'piece'::public.quantity_unit);
