INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8b6ae7a8-6976-5e6d-bad7-e5b512caa00b', 'dacc6771-1bda-5efb-b3d1-4cc3cb8ed886', 150.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('597ae074-7126-5ee3-b206-bb5c5255aee9', 'Cừu nướng chậm quế, thì là và trái cây họ cam chanh (Slow-roast lamb with cinnamon, fennel & citrus)', 'man'::public.dish_category, '["Đặt cừu vào túi thực phẩm lớn với tất cả nước cốt và ướt qua đêm.", "Ngày hôm sau, lấy cừu khỏi tủ lạnh 1 giờ trước khi bạn muốn nấu. Đun lò lên 220°C. Lấy cừu khỏi nước ướp (giữ phần nước ướp còn lại) và thấm khô. Chà nửa dầu và nướng trong 15-20 phút cho đến khi vàng. Lấy cừu ra và giảm lò xuống 160°C.", "Trộn vỏ chanh, dầu còn lại, mật ong, gia vị và tỏi với nhiều nêm nếm. Đạt tờ giấy nướng lớn lên tờ giấy nhôm lớn. Đặt chân cừu lên trên, chà hỗn hợp khắp nơi và kéo các bên của giấy nhôm lên. Rưới nước ướp vào đáy, và vứn giấy nhôm để kín.", "Nướng trong 4 giờ, cho đến khi rất mềm. Nghỉ, vẫn được gói, trong 30 phút. Mở gói và phục vụ với nước cốt."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('597ae074-7126-5ee3-b206-bb5c5255aee9', 'ddb7bb27-1d6e-5063-a720-1d7dfbb8f6e6', 1.0, 'piece'::public.quantity_unit);
