INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('080fde2c-520d-524b-a1e8-34701fc34f65', 'Cánh gà thì là, chanh và tỏi (Chicken wings with cumin, lemon & garlic)', 'man'::public.dish_category, '["Dùng cặp kéo bếp nhọn, cắt mỗi cánh gà ở khớp thành hai phần. Trộn tỏi, vỏ chanh vàng và nước cốt, thì là Cumin và dầu ô liu với nhiều nêm, rồi đổ vào đĩa với cánh gà và lắc để đều. Đậy nắp và đặt vào tủ lạnh để ướp ít nhất 1 giờ, hoặc qua đêm nếu bạn có thời gian.", "Đun lò đến 200°C/180°C/mức 6, hoặc đun nướng ngoài trời. Nướng cánh gà trên khay nướng trong 45-50 phút cho đến khi giòn, hoặc nướng than trong 20 phút, rưới mật ong vào 10 phút cuối mỗi phương pháp. Ăn trên đĩa lớn với nhiều khăn giấy. Đặt chén nhỏ với quả ô liu, hạt pistas hoặc hạnh nhân, kh ô và ớt chuông đã muối và bánh mì mỏng để ăn cùng, cùng với các món bên dưới."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('080fde2c-520d-524b-a1e8-34701fc34f65', '66b61f6c-7c68-5e55-b396-5d180c2b96be', 12.0, 'piece'::public.quantity_unit);
