INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('81849b97-c387-55ff-a2d6-885b9faf4261', 'Kebab Adana (Adana kebab)', 'man'::public.dish_category, '["Cắt nhuyễn ớt chuông Romano trong máy xay thực phẩm, rồi cho vào lưới lọc và ép cho ớt thoát hết nước cất. Đổ vào bát cùng thịt cừu xay, sốt đặc ớt chuông đỏ, pul biber, 1,5 muỗng cà phê muối biển và 2 muỗng canh dầu hoa hướng dương. Trộn đều và xoa uống kỹ ít nhất 2-3 phút. Nếu cần, ướt tay bằng nước lạnh để hỗn hợp không dính tay. Khi dùng, hỗn hợp phải có độ dính. Bao bọc và để trong tủ lạnh ít nhất 2 giờ, hoặc tối đa 12 giờ.", "Khi sẵn sàng nướng, bật nồi nướng ở mức cao hoặc lò ở 220°C. Chia hỗn hợp thành 12 phần bằng nhau, mỗi phần khoảng 85 g. Nếu muốn xiên, chia thành 8 phần bằng nhau và cuộn thành viên. Tay ướt, xiên các viên vào đầu xiên, xoa uống hỗn hợp xuống xiên bằng lòng bàn tay cho đều. Đảm bảo hỗn hợp được quấn chặt quanh xiên, không để kim loại lộ ra. Hoặc đặt trên khay nướng lớn giấy bếp nếu nướng trong lò, hoặc giấy bạc nếu nướng dưới nồi nướng. Hình thành các köfte dài 20 cm. Ngón tay ướt bằng ít nước lạnh và tạo vết lún dọc trên các köfte để có hình dạng truyền thống.", "Lăn nhẹ mỗi köfte bằng 1 muỗng canh dầu còn lại và nướng dưới nồi nướng trên kệ trên cùng 10-12 phút, quay đều, hoặc nướng trong lò 16-18 phút cho đến khi ngoài giòn và trong nhiều nước."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('81849b97-c387-55ff-a2d6-885b9faf4261', 'b688d856-a4a3-52c2-b39b-262d71a1f321', 2.0, 'piece'::public.quantity_unit);
