INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('45dbd8be-80e9-52aa-a43e-0569775d2aef', 'Cơm cừu kiểu Thổ Nhĩ Kỳ (Turkish lamb pilau)', 'man'::public.dish_category, '["Chiên khô hạt thông hoặc hạnh nhân trong chảo lớn cho đến khi nhẹ nướng, rồi đổ vào đĩa. Thêm dầu vào chảo, rồi chiên hành tây và quế cùng nhau cho đến khi bắt đầu vàng. Tăng lửa, khuấy cừu vào, chiên cho đến khi thịt đổi màu, rồi đổ gạo Basmati vào và nấu 1 phút, khuấy liên tục.", "Đổ 500 ml nước sôi vào, nghiền viên súp vào, thêm quả mơ sấy khô, rồi nêm nếm theo khẩu vị. Giảm lửa, đậy nắp và hầm sôi nhẹ 12 phút cho đến khi gạo mềm và nước dùng đã bị hấp thụ. Cho hạt thông và bạc hà vào và dùng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('45dbd8be-80e9-52aa-a43e-0569775d2aef', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 15.0, 'ml'::public.quantity_unit);
