INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4652d3b5-f4d0-5505-8829-1cc4796a0db5', 'Xiên gà nướng khói (Smoky chicken skewers)', 'man'::public.dish_category, '["Bạn cần 15 xiên: nếu xiên gỗ, ngâm trong nước trong 10 phút. Cắt gà thành miếng 3cm và đặt vào bát. Thêm 1 muỗng canh dầu ô liu, các gia vị, tỏi và giấm, trộn tốt và nems. Bạn có thể làm điều này trước một ngày và để trong tủ lạnh.", "Xiên 2-3 miếng trên mỗi xiên. Đổ dầu còn lại vào chảo chiên hoặc chà lên chảo nướng. Đun chảo cho nóng và chiên gà trong 3-4 phút mỗi mặt – bạn có thể phải làm theo từng đợt, giữ các xiên đã chín ấm trong lò ở nhiệt độ thấp. Phục vụ với sốt tỏi aïoli vị khói nếu bạn thích."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4652d3b5-f4d0-5505-8829-1cc4796a0db5', '53912b45-176d-5ec9-81db-addf1adaa05f', 6.0, 'piece'::public.quantity_unit);
