INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b85461ca-2363-5de3-a4fe-8341cf2d173f', 'Sườn cừu ớt gừng (Chilli ginger lamb chops)', 'man'::public.dish_category, '["Cho tỏi vào bát với gừng, nước cốt chanh vàng, dầu ô liu, gia vị và nêm. Xay nhuyễn bằng máy xén tay cho đến khi mịn, sau đó dùng để phủ sườn cừu trên cả hai mặt. Để ướp trong tủ lạnh trong vài giờ hoặc qua đêm.", "Đun nướng than cho đến khi nóng. Nướng sườn cừu trên than trong 3 phút mỗi mặt cho đến khi chín nhưng vẫn hồng và nh đào ở chính giữa."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('b85461ca-2363-5de3-a4fe-8341cf2d173f', 'a8db4b95-a126-5f43-a0b4-2c29ba37261d', 4.0, 'piece'::public.quantity_unit);
