INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('55373a11-bf38-536d-82b3-927d2a5e143f', 'Bánh chả đậu gà (Falafel)', 'rau'::public.dish_category, '["Đun 1 muỗng canh dầu hoa hướng dương trong chảo lớn, rồi chiên hành tây và tỏi trên lửa nhẹ 5 phút cho đến khi mềm. Đổ vào bát trộn lớn với đậu gà và gia vị, rồi nghiền nhuyễn bằng bấm nhẹ hoặc bấm nhẹ khoai tây cho đến khi đậu gà bị nghiền hoàn toàn. Thêm ngô tay hoặc thảo mốc khô, nêm nếm theo khẩu vị. Thêm trứng gà, rồi dùng tay áp thành hỗn hợp.", "Cuộn hỗn hợp thành 6 viên, rồi dập nhẹ thành bánh. Đun phần dầu còn lại trong chảo, rồi chiên bánh chả đậu gà trên lửa vừa 3 phút mỗi bên, cho đến khi vàng và chắc. Ăn nóng hoặc lạnh với cús cús, bánh mì pita hoặc salad."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('55373a11-bf38-536d-82b3-927d2a5e143f', '72c039b3-d84c-5d79-bf87-f4b61d743072', 30.0, 'ml'::public.quantity_unit);
