INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f8b9d4f1-6015-5f3d-b097-81d60a3345cc', 'Salad cà tím couscous', 'rau'::public.dish_category, '["Đun nồi nướng ở mức cao. Đặt cà tím lên khay nướng, quét dầu và nems. Nướng khoảng 15 phút, quay và quét thêm dầu ở giữa, cho đến khi vàng và mềm.", "Cùng lúc đó, đổ couscous vào bát lớn, đun nước dùng qua, rồi đậy nắp và để 10 phút. Trộn cà chua, bạc hà, phô mai sữa dê và dầu còn lại với nhau. Dùng nĩa lả couscous cho đều, rồi khuân cà tím, hỗn hợp cà chua và nước chanh vàng vào."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f8b9d4f1-6015-5f3d-b097-81d60a3345cc', '1d49713a-73c2-5b5c-aaea-110ec71ca040', 1.0, 'piece'::public.quantity_unit);
