INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('71af2828-2a07-5252-ab27-aee02db565ba', 'Gà nướng sốt óc chó kem (Roasted chicken with creamy walnut sauce)', 'man'::public.dish_category, '["Đun lò lên 200°C. Trong khay nướng, trộn thịt gà, thì là Ai Cập, bột ớt ngọt Paprika, 1 muỗng canh dầu ô liu và nems nếm. Nấu trong 40 phút cho đến khi gà giòn và chín đều.", "Trong lúc đó, chẻ 1 chiếc bánh mì baguette thành miếng và đặt vào bát nhỏ. Rưới một vài muỗng canh nước dùng gà và để ngâm. Rang khô hạt óc chó trong chảo chiên trong khoảng 3 phút cho đến khi vàng và thơm. Để riêng. Đun nóng dầu còn lại trong chảo và nấu hành tây và tỏi cho đến khi mềm. Cho bánh mì baguette đã ngâm, hỗn hợp hành và hầu hết hạt óc chó vào máy xay. Rồi phần còn lại của nước dùng gà vào và xay cho đến khi tạo thành hỗn hợp thô. Trả hỗn hợp vào chảo. Thêm kem sữa và nước chanh, nems nếm và giữ ấm.", "Khi gà đã chín, xếp lên đĩa. Khuấy ngô rí vào sốt và cho vào bát. Cắt quả óc chó còn lại thành miếng nhỏ và rắc lên trên gà. Nướng bánh mì baguette, cắt thành miếng và phục vụ bên cạnh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('71af2828-2a07-5252-ab27-aee02db565ba', '53912b45-176d-5ec9-81db-addf1adaa05f', 8.0, 'piece'::public.quantity_unit);
