INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1a2927f0-6404-5981-abb0-420d3d93e4da', 'Súp đậu gà xay (Hummus)', 'rau'::public.dish_category, '["Đổ đậu gà vào rổ lọc đặt trên bát hoặc bình để giữ nước. Đổ đậu gà, tahini, tỏi và sữa chua vào máy xay hoặc máy đánh trộn và xay đến khi mịn.", "Xay một muỗng canh nước đậu gà một lần cho đến khi bạn có độ đặc tốt, rồi đổ vào bát.", "Khuấy một chút nước cốt chanh và nêm theo khẩu vị."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1a2927f0-6404-5981-abb0-420d3d93e4da', '1ac9b5a0-35d1-5a93-9209-0239e87084f0', 400.0, 'g'::public.quantity_unit);
