INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b8ac3289-493e-5a95-89c6-d2b1d768ade1', 'Cừu nướng kiểu Thổ Nhĩ Kỳ (Turkish-style lamb)', 'man'::public.dish_category, '["Đun nướng cao. Nêm cừu, rồi nướng 2 phút mỗi mặt cho đến khi vàng, nhưng vẫn rất nhẹ. Cùng lúc, trộn gia vị nêm, hoặc oregano và nửa bạc hà vào một thùng sữa chua, đắp này lên cừu, rồi trả lại nướng thêm 2-3 phút hoặc cho đến khi sữa chua bong ra và thịt chín theo ý bạn.", "Để thịt nghỉ trên ván vài phút trong khi bạn nướng bánh pita, xé xà lách và lát mỏng hành tím. Khuấy phần bạc hà còn lại vào thùng sữa chua thứ hai. Lát dày thịt và nhét vào bánh pita cùng salad và sữa chua bạc hà. Chọc nước cốt chanh vàng lên trước khi ăn, nếu thích."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('b8ac3289-493e-5a95-89c6-d2b1d768ade1', 'ddb7bb27-1d6e-5063-a720-1d7dfbb8f6e6', 4.0, 'piece'::public.quantity_unit);
