INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('051a3920-66eb-5075-9a2f-f4be1c1c11b5', 'Bánh mì mỏng nướng (Griddled flatbreads)', 'rau'::public.dish_category, '["Đổ các loại bột vào máy xay. Thêm men nở, đường và 1 muỗng cà phê muối, rồi trộn tốt. Đổ 350 ml nước ấm và dầu, rồi xay thành bột nhăn dẻo. Trộn trong 1 phút, rồi để đến khi tăng gấp đôi kích thước, khoảng 1 tiếng.", "Nhấn nhẹ bột vài lần để hô hơi ra, rồi đặt trên bề mặt đã rắc bột. Cắt bột thành nửa và keo giãn một nửa thành hình chữ nhật khoảng 20 x 40 cm. Cắt viền bằng dao sắc lớn, rồi cắt thành tám vuông 10 cm. Lót khay lớn hoặc hai khay nướng bằng giấy không dính và sắp xếp các hình chữ nhật bánh mì lên khay trong một lớp. Làm lại với nửa còn lại của bột. Để trong nơi ấm trong khoảng 30 phút cho đến khi bột bắt đầu nở.", "Đặt bánh trực tiếp lên giá nướng và nấu vài phút cho đến khi nở lên, rồi lật ngược và nấu do bên kia. Đổ vào giỏ và ăn với các loại sốt chấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('051a3920-66eb-5075-9a2f-f4be1c1c11b5', 'ed8b10ac-54f4-5485-8c0c-86ffa5c1d582', 250.0, 'g'::public.quantity_unit);
