INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b708ef5b-198c-50de-b070-74041675f4c8', 'Cà tím nướng phô mai dê và bánh mì mỏng rang (Roast aubergine with goat''s cheese & toasted flatbread)', 'rau'::public.dish_category, '["Đun lò lên 200°C. Nhúng lát cà tím với 1 muỗng canh dầu ô liu nguyên chất, rồi nems. Xếp trên khay nướng hoặc khay tô và nướng trong 20 phút cho đến khi vàng, thêm cà chua bi vào khay trong 5 phút cuối. Chẻ bánh mì baguette thành miếng và đặt trên khay tô riêng. Nướng trong lò trong 8 phút cho đến khi giòn, rồi lấy ra.", "Để làm sốt, trong bát nhỏ, trộn giấm Balsamic, bạc hà, hành tím thái nhễn, ớt đỏ, dầu còn lại và một ít muối và tiêu.", "Rải lát cà tím, cà chua, hành tím thái lát và bánh mì giòn vào tô phục vụ. Rưới sốt lên, rắc phô mai sữa dê và rải một ít rau Rocket."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('b708ef5b-198c-50de-b070-74041675f4c8', '1d49713a-73c2-5b5c-aaea-110ec71ca040', 2.0, 'piece'::public.quantity_unit);
