INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6112c3de-c21e-5857-802e-60d58a003e07', 'Cà tím nướng sốt mè (Griddled aubergines with sesame dressing)', 'rau'::public.dish_category, '["Mở dầu lên mỗi lát cà tím, rồi nêm nếm. Đun chảo nướng hoặc nướng than. Khi nóng, nướng lát cà tím 2-3 phút mỗi bên cho đến khi vàng và mềm.", "Trộn sữa chua với tahini, tỏi, nước cốt chanh và thảo mộc, rồi nêm nếm. Đặt sốt lên cà tím và rắc thêm lá thảo mộc ở trên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6112c3de-c21e-5857-802e-60d58a003e07', '1d49713a-73c2-5b5c-aaea-110ec71ca040', 2.0, 'piece'::public.quantity_unit);
