INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('78d32d36-000d-5646-ab2b-7e76826ea129', 'Salad khoai lang (Sweet potato salad)', 'rau'::public.dish_category, '["Đun lò lên 200°C. Trộn các mảnh khoai lang với dầu ô liu và một ít nems, và rải trên khay đã lát giấy nướng. Nướng trong 30 - 35 phút cho đến khi mềm và vàng. Để nguội ở nhiệt độ phòng.", "Khi vừa về mát, đánh trộn cùng tất cả thành phần sốt với một ít nems nữa và khuấy nhẹ qua các mảnh khoai lang – dùng tay để tránh phá vỡ chúng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('78d32d36-000d-5646-ab2b-7e76826ea129', 'fcba46e6-4e6d-58e5-baf3-23ca0e2a2786', 1200.0, 'g'::public.quantity_unit);
