INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('78d32d36-000d-5646-ab2b-7e76826ea129', 'c1c28930-9c6a-5f3c-b209-743f51bf317a', 30.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5a8bd55c-8535-5eb5-b2fa-4fd677ed99fc', 'Burger thịt cừu và mơ Thổ Nhĩ Kỳ (Lamb & apricot meatballs)', 'man'::public.dish_category, '["Đun 2 muỗng cà phê dầu trong chảo và làm mềm hành tây trong 5 phút. Thêm tỏi và gia vị và nấu thêm vài phút. Lấy nửa hỗn hợp hành vào bát và để một bên để nguội. Thêm cà chua, đường và gia vị vào phần hành còn lại trong chảo và hầm nhẹ trong khoảng 10 phút cho đến khi giảm.", "Trong lúc đó, thêm bạc hà, cừu, mơ sấy khô và bột chiên xù vào hành đã nguội, nems nếm và trộn tốt bằng tay của bạn. Hình thành các bánh thịt nhỏ.", "Đun phần dầu còn lại trong chảo không dính và chiên các bánh thịt cho đến khi vàng (theo lượt nếu cần). Khuấy sốt với một chút nước và nấu nhẹ tất cả trong vài phút cho đến khi các bánh thịt chín kỹ. Ăn với bánh mì pita và salad."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5a8bd55c-8535-5eb5-b2fa-4fd677ed99fc', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 30.0, 'ml'::public.quantity_unit);
