INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5604c978-460d-5fa8-a37a-5e5e612e33dd', 'Cà tím nướng hummus (aubergine & hummus grills)', 'rau'::public.dish_category, '["Đặt cà tím thành một lớp trên khay nướng lớn. Quét ít dầu thực vật, rồi nems nhiều. Nướng 15 phút, quay hai lần và quét dầu cho đến khi các lát mềm và chín hết. Cùng lúc đó, xay bánh mì thành bột mì. Thêm 2 muỗng cà phê dầu và xay nhanh lần nữa để bột mì bám vào.", "Lăn một chút hummus lên trên mỗi lát cà tím. Đổ bột mì bánh mì lên đĩa lớn, rồi ép mặt hummus của cà tím vào bột mì để bám. Nướng lại, mặt bột mì lên trên, khoảng 3 phút cho đến khi vàng.", "Trộn hạt óc chó, ngò tây và cà chua bi trong bát, nems nếm, rồi thêm nước chanh vàng và dầu ô liu và trộn lại. Phục vụ các món nướng kèm salad, một chút hummus thêm và một số bánh mì pitta."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5604c978-460d-5fa8-a37a-5e5e612e33dd', '1d49713a-73c2-5b5c-aaea-110ec71ca040', 2.0, 'piece'::public.quantity_unit);
