INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8513b064-d9b9-51e5-8366-4ad48d184874', 'Gà nướng Algeria (Poulet Roti a l''Algerienne)', 'man'::public.dish_category, '["Đậy lò 175°C.", "Trộn nước, hành tây, dầu ô liu, giấm Balsamic, mù tạt Dijon, tỏi, tiêu đen, bột ớt Cayenne, và muối cùng nhau trong khay nướng. Thêm gà; lật cho đến khi được phủ đều với hỗn hợp.", "Nướng trong lò đã đậy cho đến khi nhiệt kế tiêm vào phần dày nhất của đùi, gần xương, đọc 75°C, khoảng 1 giờ 30 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8513b064-d9b9-51e5-8366-4ad48d184874', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 240.0, 'ml'::public.quantity_unit);
