INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2e530e4d-3558-587d-8b3c-fb6653bd6794', 'Kefta bò xay sốt cà chua kiểu Algeria', 'man'::public.dish_category, '["Trộn thịt bò xay với nửa lượng tỏi đã băm và 1 muỗng canh hành tây đã cắt nhỏ trong bát lớn. Trộn bằng tay cho đến khi kết hợp hoàn toàn. Định hình hỗn hợp thịt thành các bánh oval dài 1,5 inch. Sẽ có 12 đến 14 viên thịt viên.", "Đun chảo lớn trên lửa trung bình cao. Chiên các bánh theo từng đợt trong chảo nóng cho đến khi vàng giòn hai mặt và không còn màu hồng ở giữa, khoảng 10 phút. Đặt viên thịt vào đĩa phục vụ có lề.", "Giảm lửa xuống trung bình và thêm hành tây đã cắt nhỏ còn lại vào nước mỡ trong chảo. Nems muối và tiêu. Nấu, khuân liên tục, cho đến khi hành mềm và trong suốt, khoảng 5 phút. Thêm tỏi còn lại và nấu 30 giây. Thêm cà chua quả mận, ngò tây khô và ras el hanout. Đổ nước vào. Nấu cho đến khi cà chua mềm, khoảng 5 phút.", "Đổ sốt cà chua lên trên viên thịt để ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2e530e4d-3558-587d-8b3c-fb6653bd6794', '0225f57d-a713-5fb1-be5b-d262b636e2c3', 453.6, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2e530e4d-3558-587d-8b3c-fb6653bd6794', 'a8db4b95-a126-5f43-a0b4-2c29ba37261d', 4.0, 'piece'::public.quantity_unit);
