INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2e530e4d-3558-587d-8b3c-fb6653bd6794', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 120.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c8a916fa-ab6a-5292-b25e-72ec2d0b2932', 'Cà rốt kiểu Algeria', 'rau'::public.dish_category, '["Đặt luồng hấp vào nồi và đổ 360 ml nước, hoặc ngay dưới đáy luồng hấp. Đậy nắp và đun nước sôi trên lửa lớn. Thêm cà rốt đã cắt lát, giảm lửa xuống trung bình và đậy nắp nồi lại. Hấp cho đến khi mềm nhưng không nhừ, 4 đến 6 phút tùy độ dày lát cà rốt. Giữ lại 120 ml nước dùng.", "Đun nóng dầu ô liu trong chảo trên lửa trung bình. Giảm lửa xuống nhỏ và thêm muối, tiêu, quế, cumin, tỏi và xạ hương. Nấu gia vị và tỏi, khuân đều, cho đến khi thơm, khoảng 10 phút. Thêm 120 ml nước dùng đã giữ lại và lá nguyệt quế, đậy nấp và hầm nhẹ 20 phút.", "Thêm cà rốt vào, trộn đều để được phủ bởi hỗn hợp gia vị, và nấu cho đến khi nóng đều, khoảng 2 đến 3 phút. Rắc nước cốt chanh vàng và bỏ lá nguyệt quế trước khi ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c8a916fa-ab6a-5292-b25e-72ec2d0b2932', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 360.0, 'ml'::public.quantity_unit);
