INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('47333451-ff9d-534b-92d9-333c188a5696', 'Hầm khoai tây Algeria Chtitha Batata (Chtitha Batata)', 'rau'::public.dish_category, '["Kết hợp tỏi, ớt đỏ, bột thì là Cumin, bột ớt ngọt Paprika, tiêu đen, ớt bột Cayenne và muối trong cối nhỏ; nghiền bằng cối cho đến khi tạo thành hỗn hợp dán. Thêm dầu ô liu và trộn hỗn hợp dán tốt.", "Đun nồi lớn trên lửa trung bình và xào hỗn hợp dán cho đến khi thơm, 2 đến 4 phút. Thêm nửa khoai tây và khuấy kết hợp với hỗn hợp dán. Khuấy vào cà chua xay nhuyễn. Đổ đủ nước để ngập nửa khoai tây và đun sôi. Giảm lửa và hầm cho đến khi nửa khoai tây mềm, khoảng 40 phút.", "Đổ nửa khoai tây vào tách ăn. Roph bất kỳ sốt còn lại lên trên nửa khoai tây."]'::jsonb, 4);
