INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9af29ab9-4c51-5f6e-9b11-01010e903c8e', 'Bánh mì Bouzgene Berber sốt ớt chuông rang (Bouzgene)', 'rau'::public.dish_category, '["Bật chức năng nướng của lò. Đặt ớt chuông đỏ và cà chua trên khay nướng, nướng dưới lò khoảng 8 phút, quay đôi khi cho đến khi vỏ đen và bóc dễ dàng. Để nguội, rồi bóc vỏ cà chua và ớt, đặt vào bát lớn. Bớp cuống và hạt của ớt chuông.", "Đun nóng 1 muỗng canh dầu ô liu trong chảo trên lửa trung bình. Thêm ớt jalapeño và tỏi, nấu cho đến khi mềm, khuân đều. Tắt bếp, rồi chuyển tỏi và ớt jalapeño vào bát với cà chua và ớt chuông đỏ. Dùng hai dao cắt steak sắc (một dao trong mỗi tay), cắt cà chua và ớt thành kiểu sền sệt loãng. Trộn và để sốt một bên.", "Đặt bột mì semolina vào bát lớn, thêm muối và 4 muỗng canh dầu ô liu. Thêm nước dần dần trong khi trộn và nặn bằng tay cho đến khi hỗn hợp bám nhau, không dính hay khô, và dễ định hình bằng tay. Chia thành 6 phần và tròn thành viên.", "Với mỗi viên, đun nóng 1 muỗng canh dầu ô liu trong chảo sắc lớn trên lửa trung bình. Trình bột mỏng từng viên một, không dày quá 1/4 inch. Chiên trong chảo nóng cho đến khi có đốm đen nâu trên bề mặt và chúng giòn. Lấy ra khỏi chảo và gói trong khăn sạch khi chuẩn bị các bánh mì phẳng còn lại.", "Để ăn bánh mì và sốt, bẻ các miếng bánh mì và nhúng vào sốt. Miếng bánh sẽ trượt xuống, nhưng cứ tiếp tục nhúng vào!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('9af29ab9-4c51-5f6e-9b11-01010e903c8e', '1464765e-f3b9-52a0-9ee3-27e1a66845a3', 2.0, 'piece'::public.quantity_unit);
