INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ea384fac-188b-53da-b7ff-a53c2c48f9be', 'Bánh mì Algeria (Khobz el Dar (Algerian Semolina Bread))', 'rau'::public.dish_category, '["Trộn 1/2 cốc cộng 2 muỗng canh bột mì semolina, 2 muỗng canh hạt mè, đường, men nở, và muối cùng nhau trong một bát lớn. Đánh vào dầu, trứng, và lòng trắng trứng. Khuấy sữa ấm chậm chạp cho đến khi một hỗn hợp bột lỏng tạo thành.", "Đậy bát bằng một đĩa hoặc ni-lông thực phẩm; để đứng ở nhiệt độ phòng cho đến khi nổi bọt, khoảng 1 giờ.", "Khuấy 2 3/4 cốc bột mì với một thìa gỗ cho đến khi một hỗn hợp bột nhớt tạo thành. Đậy nắp lại và để nghỉ trong 30 phút.", "Lót khay nướng bằng giấy nướng hoặc một tấm đế nướng.", "Rắc 1 muỗng canh bột mì lên bột và tay của bạn. Trộn bột, thêm bột mì nếu cần, 1 muỗng canh một lần, cho đến khi nó rời khỏi các bên của bát. Hình thành một bánh tròn và đặt lên khay nướng đã chuẩn bị. Đậy nắp lỏng bằng một chiếc khăn và để nở trong 1 giờ trong một nơi ấm cho đến khi bánh tăng gấp đôi thể tích.", "Đun lò đến 200°C.", "Đánh lòng đỏ trứng và nước trong một bát với một nĩa; mở lên toàn bề mặt của bánh. Rắc 1 muỗng canh hạt mè lên trên.", "Nướng trong lò đã đun cho đến khi bánh vàng nâu, khoảng 20 đến 25 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('ea384fac-188b-53da-b7ff-a53c2c48f9be', 'f0953817-f7d6-543f-ad92-6bbd11417434', 120.0, 'ml'::public.quantity_unit);
