INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7814312f-5666-5212-9ee3-7affc3c8fdf6', 'Gà hầm tagine cà rốt và khoai lang (Tajine de Poulet aux Carottes et Patates Douces)', 'man'::public.dish_category, '["Trộn hành tây, cần tây, ngô rí và ngô tây trong nồi lớn. Khuấy thêm nghệ, cumin, paprika, gừng, ớt bột cayenne, muối và tiêu. Đặt đùi gà lên trên. Chọc dầu ô liu lên gà. Đậy nồi và hầm lửa nhỏ cho đến khi gà mềm, khoảng 40 phút.", "Cho nho khô vào tô nhỏ, ngập bằng nước nóng; ngâm 10 phút. Vớ nước.", "Đun lò trước 200°C.", "Chuyển hỗn hợp gà vào nồi tagine hoặc nồi hầm đựng trong lò. Thêm khoai lang và cà rốt. Đậy nắp hoặc giấy bạc.", "Nướng trong lò đã đun cho đến khi khoai lang mềm, khoảng 40 phút. Thêm nho khô và mận sấy khô đã vớ nước. Tiếp tục nướng, đậy nắp, cho đến khi nho khô và mận sấy khô nóng đều, khoảng 10 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7814312f-5666-5212-9ee3-7affc3c8fdf6', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 2.0, 'piece'::public.quantity_unit);
