INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6589abe2-e47c-5112-8922-5e5c6b523c49', 'Salad ớt chuông (flafla)', 'rau'::public.dish_category, '["Đun lò đến 230°C. Đặt ớt chuông nguyên quả trên giấy bạc. Nướng cho đến khi vỏ có đốm đen và ớt mềm, 30 đến 45 phút, quay ớt một lần nếu cần.", "Lấy ớt ra khỏi lò và để nguội 10 phút. Bóc vỏ, bớp cuống và hạt. Cắt ớt đã nướng thành từng miếng 1/2 inch.", "Đun nóng dầu ô liu trong chảo trên lửa trung bình. Thêm hành tím tây vào và nấu, khuân đều, cho đến khi hành mềm và trong suốt, khoảng 5 phút. Thêm tỏi, muối và tiêu; thêm ớt đã cắt và cà chua quả mận vào. Nấu trên lửa trung bình, khuân đôi khi, cho đến khi cà chua mềm và hỗn hợp trộn đều, khoảng 5 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6589abe2-e47c-5112-8922-5e5c6b523c49', '70a26f29-1bba-53d9-a9ec-db932fdcb327', 3.0, 'piece'::public.quantity_unit);
