INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d21c89cb-2fb6-56b2-a4ab-5abe3db92caf', 'Sup cừu, cà chua và freekeh Algeria (Chorba Hamra bel Frik)', 'canh'::public.dish_category, '["Đặt freekeh vào một bát nhỏ và ngập nước lạnh. Đặt một bên.", "Kết hợp thịt cừu, hành tây, tiêu đen, bột ớt ngọt Paprika, bột quế và muối trong một nồi. Khuấy dầu ô liu, ½ ngò rí, ½ bạc hà và cần tây stalk cho đến khi kết hợp. Hầm trên lửa thấp trong 15 phút. Khuấy vào đậu gà Chickpeas; rót đủ nước để ngập, và quay lại sôi nhẹ. Khuấy vào bí ngòi xanh, cà rốt và cà chua xay nhuyễn.", "Đặt một cái hấp trên nồi; thêm cà chua. Đậy nắp và hấp cà chua cho đến khi mềm, khoảng 5 phút. Nén cà chua bằng thìa gỗ, để thịt nhừ chảy vào sup. Lấy hấp ra và vỏ cà chua thải bỏ.", "Thêm khoai tây vào sup và đủ nước để ngập. Hầm cho đến khi khoai tây mềm, khoảng 10 phút.", "Ráo freekeh và thêm vào sup. Hầm cho đến khi mềm, khoảng 15 phút. Lấy cần tay ra và thải bỏ. Rắc sup với phần ngò rí còn lại và phần bạc hà còn lại trước khi phục vụ."]'::jsonb, 4);
