INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6e18739f-565a-5a63-a804-f68e29c78de9', 'Bánh borek phô mai (Cheese Borek)', 'rau'::public.dish_category, '["Trong một bát vừa, đánh chung trứng gà, ngò tây, tỏi và ớt chuông đỏ nghiền. Trộn phô mai Gouda và phô mai Thụy Sĩ Emmentaler.", "Mỗi lần một tờ, đặt bột phyllo trên bề mặt phẳng và chà khoảng 1 muỗng canh bơ lạt. Cắt dọc thành 4 sợi. Đặt một muỗng cà phê đầy của hỗn hợp trứng ở một đầu của mỗi sợi. Gấp góc của sợi lên phía trên nhân, tạo thành tấm gấp tam giác. Tiếp tục gấp chiều dài của sợi bằng các tấm gấp tam giác để tạo thành tam giác nhỏ nhồi nhân. Lặp lại với phần bột phyllo còn lại.", "Đun lò trước đến 175°C. Nhớt nhẹ một khay nướng lớn.", "Sắp xếp các tam giác bột phyllo nhồi nhân thành một lớp trên khay nướng đã chuẩn bị. Nướng trong lò đã đun trước trong 30 phút, hoặc cho đến khi nhẹ vàng. Ăn khi ấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6e18739f-565a-5a63-a804-f68e29c78de9', '8a301d33-ca8b-52a8-aa71-ca6feca05e46', 1.0, 'piece'::public.quantity_unit);
