INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f50453e7-038e-5413-b7f2-e27dbd08dd11', 'Zapiekanki Ba Lan', 'man'::public.dish_category, '["Đun lò 200°C. Nướng bánh mì baguette trên khay nướng 8-10 phút, rồi để nguội.", "Đun nóng 2 muỗng cà phê bơ và 1 muỗng cà phê dầu trong chảo trên lửa nhỏ và nấu hành tây cắt nhỏ 5 phút cho đến khi mềm. Khuấy nấm vào, tăng lửa vừa và nấu thêm 5-10 phút cho đến khi rau mềm và dịch nấm đã bốc hơi. Khuấy tỏi vào và nấu 1-2 phút cho đến khi mềm. Nêm nếm, rồi khuấy sốt mayonnaise vào và lấy khỏi lửa.", "Cắt bánh mì baguette thành nửa theo chiều dọc, rồi đưa trở lại khay nướng, mặt cắt lên và bớt hỗn hợp nấm lên, rồi rắc phô mai cheddar, giăm bông, xúc xích cay Ba Lan Kabanos và phô mai mozzarella lên. Nướng 8-10 phút, hoặc cho đến khi phô mai đã nung và đã vàng.", "Cùng lúc, đun nóng bơ và dầu còn lại trong chảo trên lửa vừa và chiên hành tây lát 5 phút cho đến khi vàng và mềm. Lấy khỏi lửa và để một bên. Khi các bánh pizza đã chín, đặt hành tây caramelized, dưa chuột thì là (nếu dùng), tỏi lá và chút sốt ketchup chéo lên."]'::jsonb, 4);
