INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f2405a19-b29a-5917-9fb1-08a09a97f135', 'Bánh pierogi chua cà (Sauerkraut pierogi)', 'rau'::public.dish_category, '["Đầu tiên, làm hành tím giòn. Đun dầu trong nồi nhỏ lên 180°C (một khối bánh mì sẽ vàng trong 15 giây). Trộn hành tím vào ít bột và chiên đậm trong 1 phút cho đến khi vàng nhạt và giòn. Rarget trên giấy tầu. Có thể làm trước hai ngày và để trong bao kín khí.", "Để làm nhân, đun dầu trong chảo không dính vừa và chiên nhẹ hành tím trong 10 phút cho đến khi bắt đầu vàng.", "Thêm chua cà và cải, nấu trong 5-10 phút cho đến khi cải mềm. Nếm và thêm một ít muối nếu chưa đủ nêm, hoặc đường nếu chát. Đổ vào bát và để nguội hoàn toàn.", "Để làm bot, trộn trứng và dầu với 125 ml nước, rồi dần dần thêm bột, trộn tốt bằng tay. Nhuyễn bot trên bề mặt đã rắc bột cho đến khi bot không dính tay nữa. Bạn sẽ có bot dẻo, co giãn. Bọc bot bằng màng bọc và để trong tủ lạnh ít nhất 30 phút, hoặc qua đêm.", "Rắc bột dày lên bề mặt làm việc. Lăn bot thành vòng tròn 40 cm hoặc cho đến khi bot dày như một đồng xu.", "Dùng dụng cụ cắt bánh 9 cm, cắt các vòng tròn từ bot – bạn sẽ có khoảng 25 vòng. Không vứt phần còn lại – chúng ta ném vào bánh pierogi khi luộc để hạn chế lãng phí.", "Sẵn sàng đĩa đã rắc bột. Cho 1 muỗng cà phê nhân vào giữa mỗi vòng. Trong tay, gấp đôi xung quanh nhân và kín để tạo hình nửa trăng. Đặt trên đĩa đã rắc bột, đảm bảo chúng không chạm nhau.", "Đun nồi lớn nước muối cho sôi và nhẹ nhàng hạ pierogi vào. Luộc trong 2 phút cho đến khi chúng nổi lên bề mặt.", "Rarget nước và phục vụ với một miếng bơ và một ít kem chua. Trang trí bằng hành tím giòn rắc trên lên khi phục vụ."]'::jsonb, 4);
