INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('99eb0585-c67e-5879-89ed-982d45c5e4da', 'Salad lựu Ba Lan (Pomegranate salad)', 'rau'::public.dish_category, '["Trộn dầu ô liu, nước cốt chanh vàng, mật ong và lá thì là trong bát lớn. Nems kỹ, rồi đổ xà lách, cà chua, hành lá và ớt vào, và trộn để kết hợp.", "Lấy hạt lựu qua một bát và loại bỏ các màng trắng. Xếp salad đã sốt trên đĩa lớn, rồi rắc hạt lựu và phô mai Feta lên trên."]'::jsonb, 4);
