INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4c0236f4-c10c-58f0-947d-441f02e0db77', 'Kotlety Ba Lan (Polish patties (kotlety))', 'rau'::public.dish_category, '["Ngâm bánh mì ổ nhỏ trong sữa cho đến khi mềm hoàn toàn. Trong lúc đó, chiên hành trong dầu khoảng 8 phút hoặc cho đến khi mềm và vàng. Thêm hành đã chiên vào thịt bò xay cùng với trứng, tỏi, kinh giới ô và chút nems nếm. Vắt sữa thừa từ bánh mì và thêm vào hỗn hợp thịt. Trộn mọi thứ với nhau và nems tốt.", "Chia thịt thành 8 bánh. Đổ bột chiên xù khô vào bát浅 và phủ bánh ở khắp nơi. Đun ít dầu trong chảo sâu và chiên bánh từng lượt trên cả hai mặt cho đến khi vàng và chín đều, khoảng 6-7 phút mỗi mặt."]'::jsonb, 4);
