INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7e939329-943e-55c0-93f3-e2ae639533f0', 'Bigos (cháo săn Ba Lan)', 'man'::public.dish_category, '["Đặt lá cải vào nồi hầm nặng, thêm nước dùng và nấu trên lửa nhỏ khoảng 50 phút, cho đến khi lá cải mềm.", "Cắt nấm đã ngâm thành sợi và giữ nước ngâm. Nung mỡ heo và chiên xúc xích Đức và xúc xích khói, rồi lấy ra, để lại mỡ trong chảo. Xào hành trong cùng chảo trong 5-8 phút cho đến khi hơi vàng.", "Thêm nấm và nước ngâm cùng với tất cả thịt đã nấu, hành và mận sấy, rồi đậy nắp và nấu 20 phút. Thêm các gia vị, rượu vang đỏ và sốt cà chua đặc và đun đến sôi nhẹ, rồi đậy nắp và nấu 1 giờ. Nems rất tốt và để nguội. Cháo sẽ giữ được trong tủ lạnh tối đa hai ngày nếu đậy nắp. Bigos ngon hơn sau mấy ngày. Để nguội trước. Đun nóng lại cho đến khi nóng hổi trước khi phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7e939329-943e-55c0-93f3-e2ae639533f0', '2ec75171-2e76-59e4-a1e6-e35ad57bcbc1', 1.0, 'piece'::public.quantity_unit);
