INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4ab47214-48d4-5906-95b7-e4099e929e73', 'Goulash heo và chua cà:põ Ba Lan', 'man'::public.dish_category, '["Đun mỡ heo nước trong nồi trên lửa vừa và chiên hành băm nhẹ cho đến khi vàng, khoảng 5-8 phút. Thả thì là và thịt heo vào, và chiên 10 phút khắp nơi cho đến khi vàng. Thêm tỏi, nems tốt và rắc bột mì qua. Nấu khoảng một phút, rồi thêm bột ớt ngọt và nấu thêm 1 phút.", "Rót nửa nước dùng, thêm lá nguyệt quế, và hôi với nắp đậy trên lửa nhỏ 30 phút.", "Thêm chua cà:põ, nước dùng còn lại và một giọt nước muối chua cà:põ. Hôi với nắp 30 phút, khuấy thỉnh thoảng, cho đến khi thịt mềm. Khuấy kem tươi đánh bông vào và hôi 5 phút để hòa kết vị. Nems theo khẩu vị, rồi dùng trang trí bằng một muỗng kem chua.", "Công thức này được cung cấp bởi Apetit Online và chưa được chúng ta kiểm tra lại."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4ab47214-48d4-5906-95b7-e4099e929e73', 'd71c389a-dea9-5ae9-9304-e575538d3451', 45.0, 'ml'::public.quantity_unit);
