INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('265de5b5-a8d8-5dcb-91a9-49e5f4d0a7e5', 'Thịt vai heo nướng chậm chanh, tỏi và húng lùi (Slow-roasted ham with lemon, garlic & sage)', 'man'::public.dish_category, '["Đun lò lên 200°C. Đập tỏi, húng lùi, vỏ chanh, muối và tiêu bằng cối và chùy cho đến khi hỗn hợp trở thành bot. Khuấy vào dầu, rồi trộn hỗn hợp lên vai heo, tránh da phía trên. Chọc da bằng dao sắc, rồi chà một nắm lớn muối vào da. Chặt heo bằng dây bếp.", "Lát khay nướng lớn bằng hai lớp giấy nhôm và đặt heo lên trên, phần da lên trên. Kéo các bên giấy nhôm lên xung quanh heo để tạo gói, rồi rót rượu vang vào khay quanh các bên. Chuyển vào lò và giảm nhiệt độ xuống 140°C. Nướng trong 4-5 giờ, hoặc cho đến khi nhiệt kế thịt châm vào phần dày nhất của heo chỉ 70°C.", "Tăng lò lên 240°C. Cẩn thận cham nước cốt nướng heo từ chảo vào nồi nhỏ và nấu trên lửa vừa trong 10-15 phút, hoặc cho đến khi giảm một phần ba. Nems nếm lại.", "Trong lúc đó, sắp xếp giấy nhôm xung quanh heo để chỉ da bị lộ, rồi trả lại lò trong 10-15 phút cho đến khi da phồng lên và vàng khắp nơi. Để nghỉ trong 20 phút trước khi cắt lát. Phục vụ với sốt rưới lên."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('265de5b5-a8d8-5dcb-91a9-49e5f4d0a7e5', 'a8db4b95-a126-5f43-a0b4-2c29ba37261d', 5.0, 'piece'::public.quantity_unit);
