INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('265de5b5-a8d8-5dcb-91a9-49e5f4d0a7e5', '41e2849c-302d-5cf6-9f07-ca579b4604a3', 50.0, 'ml'::public.quantity_unit);
