INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('265de5b5-a8d8-5dcb-91a9-49e5f4d0a7e5', 'cdf4f7d7-8a4d-5c25-b1b0-e5384598b1f8', 500.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('80ddbd30-87c8-5b66-911b-b42c120f93f9', 'Lá cải nhồi nướng Ba Lan', 'rau'::public.dish_category, '["Đun lò đến 180°C. Bớp cuống giữa cứng của lá cải. Đun nồi lớn nước muối đến sôi, thêm lá cải, rồi nấu chỉ 1-2 phút cho đến khi các lá bắt đầu ngả. Lọc và làm mát dưới nước lạnh chảy. Lọc tốt, rồi thấm khô bằng khăn bếp.", "Đun dầu trong chảo, thêm hành, rồi chiên 5 phút cho đến khi hơi vàng. Thêm hương thảo và cần tây, rồi nấu thêm 8 phút. Khuân gạo vào, rồi nấu khoảng một phút cho đến khi các hạt bóng nhánh. Lấy ra khỏi bếp, khuân hạt dẻ luộc chín và nam việt quất vào, rồi nems.", "Đổ một chút nhân lên lá cuộn cuống, cuộn lên và gấp các bên để bao bọc nhân. Đặt thành một lớp trong nồi ăn lò nhẹ lớn đã dầu với phần keo dưới. Đặt các lá còn lại theo cùng cách. Trộn nước dùng, giấm và mật ong, rồi đổ lên trên lá cải. Đậy nắp nồi chặt bằng giấy bạc, nướng trong 1 giờ, mở nắp, rồi nấu thêm 15 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('80ddbd30-87c8-5b66-911b-b42c120f93f9', 'f79597bc-a2a7-55e7-a432-27df4f5d3792', 6.0, 'piece'::public.quantity_unit);
