INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('387ecca5-c9ab-5403-b347-a9cd9ee95299', 'Súp sườn heo bortsch Ba Lan', 'man'::public.dish_category, '["Cắt thịt thành các khối lớn, đặt vào nồi lớn nhất và ngập 5 lít nước. Đun sôi trên lửa lớn, vớt bọt nổi lên bề mặt. Thêm lá nguyệt quế. Nems. Hạ lửa xuống hôi và nấu 1 giờ, hoặc cho đến khi thịt mềm và rụng từ xương. Thêm đậu nếu dùng khô.", "Tăng lửa lên. Đun sôi lại, rồi giảm nhiệt và hôi thêm 20 phút – đậu vẫn nên hơi sống. Thêm cà rốt, hành tây, tỏi và tiêu. Khuấy tốt, rồi thêm ớt, nếu dùng. Nấu thêm 15 phút.", "Khuấy củ dền vào và nấu 10 phút trước khi thêm khoai tây. Sau 15 phút, thêm cà chua xay nhuyễn theo khẩu vị và đậu, nếu dùng hộp, và đun sôi. Nấu 5 phút, thêm cải bắp và nấu thêm 5 phút. Nems, rồi trang trí với ngô tây và thì là. Tắt bếp và để nghỉ 5 phút. Dùng với kem chua ở bên cạnh."]'::jsonb, 4);
