INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('439bc9fa-75dc-5788-9370-116e639915c5', 'Chua dền bắp cải tím', 'rau'::public.dish_category, '["Đổ tất cả nguyên liệu vào bát lớn, thêm 1-1,5 muỗng cà phê tiêu đen xay tươi, rồi xoa nặn tất cả cùng nhau bằng tay trong 5 phút. Bạn có thể muốn đeo găng tay để tránh nhuớm da bằng nước củ dền.", "Nén rau xuống trong bát bằng tay, rồi phủ bề mặt và lên bên cạnh bát bằng một tờ bọc thực phẩm phân hủy được hoặc thứ có thể tái sử dụng như bọc mật ong. Bây giờ đặt một bát kích thước tương tự lên trên. Nén xuống mạnh và thêm mọi thứ nặng (bao gạo hoặc lon) để nén sao cho nước cất lên phủ bề mặt. Đậy nắp lại.", "Để lên men ở nhiệt độ phòng trong ít nhất 5 ngày, nhưng để có hương vị tối đa, để trong 1-5 tuần (cho đến khi tiếng néu giảm bớt).", "Kiểm tra chua dền. Sau vài ngày, bạn sẽ thấy bọt khí đã tích tụ khi nó lên men. Khuân một lần, rồi đậy nắp và nén xuống lần nữa như trước. Bắp cải sẽ càng chua theo thời gian nó lên men, nên nếm thử đôi khi. Khi bạn thích hương vị, chuyển nó vào các chai đã khuẩn trùng và giữ lạnh. Nó sẽ giữ lạnh trong tối đa sáu tháng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('439bc9fa-75dc-5788-9370-116e639915c5', '0f0c3d76-0473-5e78-b623-43c0ac7ea356', 320.0, 'g'::public.quantity_unit);
