INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('44d44da9-42c1-5513-a749-ef35f83f5f91', 'Bánh mì lúa mạch đen (Rye bread)', 'rau'::public.dish_category, '["Đổ bột, men nở và muối vào bát. Trong xén, trộn mật ong với 250 ml nước ấm, đổ chất lỏng vào bát và trộn thành bot. Bột lúa mạch đen có thể khá khô và hấp thụ nhiều nước, nếu bot trông quá khô hãy thêm thêm nước ấm cho đến khi có bot mềm. Đổ bot lên bề mặt làm việc và nhuyễn trong 10 phút cho đến khi mịn. Lúa mạch đen chứa ít gluten hơn bột trắng nên bot sẽ không mềm như bánh mì trắng thông thường.", "Đặt bot vào bát đã phơi dầu, phủ màng bọc và để bot nở trong nơi ấm trong 1-2 giờ, cho đến khi tăng gấp đôi kích thước. Rắc bột lên khay nướng bánh 900 g.", "Đổ bot lại lên bề mặt làm việc và nhuyễn ngắn để loại bỏ các bật khí. Nếu dùng hạt thì là Ba Tư, nhầm chúng vào bot. Dạng thành bánh mì hình oval mịn và đặt vào khay. Phủ khay với màng bọc đã phơi dầu và để nở ở nơi ấm thêm 1 – 1,5 giờ, cho đến khi tăng gấp đôi kích thước.", "Đun lò lên 220°C. Bóc màng bọc và rắc bột lúa mạch đen lên bề mặt bánh. Chạo vài vết chéo nghiêng rồi nướng trong 30 phút cho đến khi vàng đen và vang vồ khi gõ. Chuyển đến giá làm nguội và để nguội ít nhất 20 phút trước khi phục vụ."]'::jsonb, 4);
