INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('85c2275c-3cde-50fe-94c7-c46e2952f319', 'Salad dưa leo và thì là (Cucumber & fennel salad)', 'rau'::public.dish_category, '["Đặt dưa leo vào một cái rổ ráo. Rắc 1 muỗng cà phê muối và đường, sau đó để trong 10 phút. Thêm thì là.", "Trộn kem chua, nước cốt chanh vàng, giấm rượu vang trắng và thì là, sau đó nems với tiêu đen và thêm vào hỗn hợp thì là."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('85c2275c-3cde-50fe-94c7-c46e2952f319', '1f704316-5b7b-55b1-a19d-9f908816a5af', 1.0, 'piece'::public.quantity_unit);
