INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4abe3a08-357e-542a-ac60-3be90c72c2eb', 'Bánh mì challah (Challah)', 'rau'::public.dish_category, '["Trộn men nở, một chút đường cát mịn và 2 muỗng canh nước ấm trong một bát nhỏ. Khuấy để tan men, rồi để trong 10 phút cho đến khi bọt nở.", "Cùng lúc đó, trộn bột mì số 13 chuyên dụng bánh mì, phần đường còn lại và 2 muỗng cà phê muối mịn trong một bát lớn. Làm hốc ở chính giữa, sau đó thêm nửa trứng gà đã đánh, hỗn hợp men và dầu hoa hướng dương. Đổ vào 200ml nước ấm (nên cảm giác ấm nhẹ khi xúc vào) và khuấy bằng muỗng, sau đó trộn bằng một tay, giữ tay kia sạch trong khi kết hợp bột thành khối. Nếu có quá nhiều phần khô, thêm dần ít nước cho đến khi kết hợp – bạn không muốn nó quá ướt và dính. Bột nguội nên ẩm, nhưng không ướt nhờn.", "Khi bột đã kết hợp, đổ ra lên bề mặt đã rắc bột nhẹ. Xên bằng hai tay trong 10 phút cho đến khi mịn và hơi dẻo. Nếu rất dính, thêm rất ít bột mì – càng ít càng tốt. Keo các bên của bột xuống và kéo lại để tạo hình cầu. Nhớt nhẹ một bát, sau đó lăn nhẹ quả bột quanh bát để bọc dầu. Đậy bằng khăn sạch và để trong một nơi ấm trong 1 giờ, hoặc cho đến khi bột nở gấp đôi kích thước.", "Lót khay nướng bằng giấy nướng. Đổ bột ra trên bề mặt làm việc sạch và chia thành ba phần bằng nhau, cân chính xác nếu thích. Cuộn mỗi phần thành hình xúc xích dài khoảng 25cm, làm nhọn nhẹ ở cả hai đầu. Đặt các phần trước bạn, song song với nhau cách nhau vài centimet. Kết nối các xúc xích ở đầu trên, rồi xên chúng dọc xuống chiều dài, cuộn các đầu khi đạt đáy. Cẩn thận chuyển bánh lên khay nướng đã chuẩn bị và đậy lỏng bằng khăn sạch. Để nở cho đến khi phồng và mềm, khoảng 40 phút.", "Cùng lúc đó, đun lò đến 200°C. Chà nhẹ phần trứng gà đã đánh còn lại trên toàn bộ challah, đưa vào mọi khe hẽ, và rắc hạt anh túc hoặc hạt mè, nếu sử dụng. Nướng trên kệ giữa của lò trong 25-30 phút, cho đến khi bánh vàng nụi bên dưới và nghe trống khi gõ. Kiểm tra sau khoảng 15 phút – nếu phần trên của bánh bắt đầu quá đen, phủ bằng giấy bạc. Để nguội trên giá sắt, rồi ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4abe3a08-357e-542a-ac60-3be90c72c2eb', '24a43e24-1e07-57f8-b964-71cf3302a770', 500.0, 'g'::public.quantity_unit);
