INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9d4cee06-21a5-5c73-9c3d-38f7e353834d', 'Borscht Ukraina', 'man'::public.dish_category, '["Để làm nước dùng, đặt thịt, hành nguyên quả, lá nguyệt quế và 2 lít nước lạnh nhẹ muối vào nồi lớn. Nấu trên lửa rất thấp trong 1 giờ 30 phút hoặc cho đến khi gầu bò mềm và rã dễ dàng – có thể mất tới 3 giờ. Bớp bọt bằng thìa theo thời gian. Nhúc bất kỳ mảnh lớn hơn của thịt bò vào nước dùng, lấy hành nguyên quả ra và vứt bỏ.", "Thêm khoai tây vào borscht, nems muối và tiêu rất tốt và nấu 10-15 phút cho đến khi mềm. Cùng lúc đó, đun dầu hướng dương trong chảo lớn sâu. Thêm hành đã cắt khối và cà rốt, và nấu trên lửa trung bình, khuân, cho đến khi cà rốt mềm và sắp bắt đầu caramel hóa.", "Thêm củ dền và nấu khoảng 5 phút, khuân đôi khi. Thêm ớt chuông đỏ, nếu dùng, và nấu thêm 2 phút, rồi thêm cà chua và mận sấy, khuân, rồi tăng lửa và đun sôi để đặc hơi, trước khi thêm tất cả vào borscht.", "Thêm lá cải đã xé và đậu kidney, và nấu 7-10 phút cho đến khi mềm. Phục vụ với một chút kem sữa hoặc crème fraîche, rất nhiều thì là đã cắt nhỏ và một số bánh mì vỏ giòn."]'::jsonb, 4);
