INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('16ad7c36-e6df-597c-b8fa-2125a6c5f8bb', 'Salad bắp cải chua ngọt', 'rau'::public.dish_category, '["Trộn đều sốt mayonnaise, vỏ và nước cốt chanh, giấm, mù tạt và muối cần tây trong tô nhỏ, rồi nêm nếp nhiều.", "Thêm bắp cải trắng, cà rốt, hành tím và cần tây. Trộn đều và để tủ lạnh. Có thể làm trước tới 1 ngày."]'::jsonb, 4);
