INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('189fcee5-00bb-5fb8-82f3-247d5989fe89', 'Bánh latke củ dền', 'rau'::public.dish_category, '["Đun lò đến 180°C. Làm bánh latke bằng cách trộn tất cả các nguyên liệu.", "Đun dầu trong chảo không dính lớn. Cho hỗn hợp bằng thìa để làm sáu bánh latke tròn. Chiên 4-5 phút mỗi bên, rồi chuyển lên khay nướng và nướng 10 phút.", "Trộn sữa chua và bạc hà trong bát nhỏ. Trộn các lá salad và cà chua cùng nhau, rồi phục vụ bánh latke với sữa chua bạc hà và salad."]'::jsonb, 4);
