INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ce1c56e3-791b-5ae3-917d-2d0262bf03d7', 'Bắp cải tím hầm thenh cùng xúc xích khói thenh (Rosemary braised red cabbage with kabanos)', 'man'::public.dish_category, '["Chia đôi bắp cải tím, bỏ cuống cứng và cắt mỏng. Đặt vào chảo lớn cùng tất cả các nguyên liệu khác trừ xúc xích, rồi trộn vào 300 ml nước và một ít muối và tiêu.", "Đun sôi nhỏ lửa, rồi giảm lửa, nắp nắp khít và nấu nhẹ trong 1,5 giờ, khuấy thường xuyên. Nếu quá khô, bạn có thể thêm một ít nước.", "Thêm xúc xích xông khói Kabanos vào hỗn hợp bắp cải, nắp nắp lên chảo và ninh nhẹ trong 20 phút. Mở nắp và nấu thêm 10 phút. Phục vụ kèm một ít khoai nghiền hoặc khoai luộc."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('ce1c56e3-791b-5ae3-917d-2d0262bf03d7', 'b41f9ce0-9530-5db2-b4c0-4f3a1bb9e57f', 0.5, 'piece'::public.quantity_unit);
