INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('51b94e1f-d11f-5d8a-b24d-75a44b413ede', 'Bánh empanadas bò', 'man'::public.dish_category, '["Với bột đặt mỡ heo, nước ấm và muối vào bát xoa uống lớn và khuân. Thêm bột mì và oregano và xoa uống 5 phút bằng tay hoặc bằng chức năng xoa uống của máy. Để nghỉ đậy nắp ít nhất 30 phút hoặc cả đêm trong tủ lạnh.", "Với nhân đặt cà chua trong nước sôi khoảng 30 giây, rồi làm nguội bằng nước lạnh và bóc vỏ và cắt thành các khối. Ép tỏi qua máy ép tỏi, cắt hành thành các khối. Hầm nhẹ tỏi và hành trong ít dầu ô liu cho đến khi trong suốt. Lấy hành và tỏi ra và rang thịt ở nhiệt độ cao từ mọi phía. Nems với tất cả các thảo mộc và thêm hành, tỏi và cà chua. Để hầm nhẹ vài phút, thêm muối, tiêu và gia vị bổ sung vừa đủ. Bạn có thể chuẩn bị thịt đêm trước, để trong tủ lạnh nếu làm vậy. Luộc trứng và cũng cắt thành các khối và trộn với thịt đã chuẩn bị.", "Cắt bột thành nửa và trình một nửa mỏng trên bề mặt đã bón bột. Cắt các hình tròn khoảng 12-15cm đường kính. Cái của tôi có đường kính 12,5 cm. Đặt khoảng 2-4 muỗng cà phê nhân trên một hình tròn, đặt một ít nước xung quanh các cạnh và gấp nửa kia thành nửa trăng. Đảm bảo kín các cạnh bằng nĩa. Làm tương tự cho đến khi hết bột và nhân.", "Cùng lúc đó đun lò đến 200°C. Quét empanadas bằng trứng đánh tan và nướng khoảng 8 empanadas trên khay nướng đã lót giấy bếp trong khoảng 25 phút hoặc cho đến khi vàng. Phục vụ khi ấm với sốt chimichurri."]'::jsonb, 4);
