INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3f21687e-f860-58fe-9bc6-8de2320a9e15', 'Bánh nướng giăm bông phô mai (Torta de fiambre)', 'man'::public.dish_category, '["Lót đáy khay removable 20-2 cm (8-9 inch) bằng giấy nướng, tôi thường để phần thừa vì bột rất loãng và có thể tràn. Đun lò 220°C.", "Xay phô mai ra và lấy giăm bông ra.", "Trộn tất cả nguyên liệu còn lại trong tô lớn khoảng một đến hai phút.", "Đổ nửa bột vào khay đã chuẩn bị, bột sẽ rất loãng. Rồi đặt giăm bông và phô mai lên trên và đổ phần bột còn lại lên trên.", "Nướng khoảng 20-25 phút hoặc cho đến khi mặt vàng. Đợi vài phút trước khi lấy khỏi khay và dùng nóng hoặc lạnh cùng thảo mộc tươi."]'::jsonb, 4);
