INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9f2d7f5a-4a42-56db-b911-182ce0152fb1', 'Sandwich Chivito (Chivito sandwich)', 'man'::public.dish_category, '["Đối với bánh brioche hâm nóng sữa với bơ và mật mía cho đến khi bơ đã nung. Thêm nước lạnh và trứng vào hỗn hợp này.", "Trong một bát lớn đặt bột mì làm bánh mì, muối và men nở và trộn. Sau đó thêm hỗn hợp sữa và nước và khuấy bằng khiên gỗ cho đến khi kết hợp. Bạn không cần xên bột, hoàn toàn ổn để làm điều này bằng tay với khiên gỗ, điều này không cần phải rất cẩn thận. Đậy bằng khăn ẩm và đựng vào tủ lạnh qua đêm.", "Sáng hôm sau xên bột trên bề mặt đã rắc bột nhẹ một chút và cắt thành tám phần bằng nhau. Hình thành những cái bóng và đặt trên khay nauvais đã lót giấy nướng. Đậy lại bằng khăn ẩm và để nở khoảng một giờ hoặc cho đến khi gấp đôi kích thước.", "Đun lò đến 220 °C. Chà bánh với sữa, kem béo hoặc trứng đánh và rắc hạt mè, nếu muốn. Nấu trong khoảng 15-20 phút hoặc cho đến khi vàng. Để nguội.", "Đối với phần phủ kẹo hành tây và chiên trong chút bơ, để caramelize, điều này có thể mất mười đến mười lăm phút, gọi đôi khi. Chà các miếng thịt bò với chút tỏi sau đó chiên hoặc nướng các miếng thịt bò, xông khói, và trứng với muối và tiêu, nướng bánh sau khi đã cắt nửa. Lát mù tạt lên một nửa bánh, xếp mỗi chivito với một lát thịt bò, một lát xông khói, một lát phô mai, một sợi xông khói, một lát cà chua, và một ít xà lách. Đặt trứng chiên lên trên và rắc سخونة với sốt Chimichurri và một ít hành tây ngay trước khi phục vụ."]'::jsonb, 4);
