INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5a60c6df-93db-5d3e-9310-09936892b9e8', 'Arepas Venezuela', 'rau'::public.dish_category, '["Đun lò 210°C.", "Đổ nước vào tô lớn. Đảm bảo nước ở nhiệt độ phòng.", "Thêm muối. Trộn đều bằng máy xay, nĩa hoặc lát nhựa để đảm bảo muối tan tốt.", "Trong khi bạn tiếp tục đánh hỗn hợp, thêm bột ngô hạt thô chậm rãi—một chút một lúc.", "Khi tất cả bột đã thêm, tiếp tục trộn cho đến khi bột ngô, nước và muối được trộn và tan hoàn toàn.", "Đặt bột ngô (masa) vào tô một bên. Để nghỉ 5 phút để bột được thấm nước hoàn toàn. Loại bột ngô này không có gluten, vì vậy không cần uốn. Masa nên mịn, cứng nhưng có thể co uốn.", "Trong khi chờ 5 phút nghỉ, đun nóng budare (hoặc comal, chảo nướng, chảo t''ep sắt hoặc chảo không dính) trên lửa vừa. Bớt ít dầu.", "Đổ nước vào tô nhỏ để ướt tay khi làm arepa.", "Lấy khoảng 2 muỗng canh masa trong tay ẩm. Masa nên vừa vặn trong lòng bàn tay để dễ tạo thành viên nhỏ.", "Chéo tay, một tay đặt lên tay kia, với viên masa ở giữa. Xoay tay phải theo vòng tròn, để bạn đồng thời nhấn masa thành đĩa phẳng và giữ hình tròn.", "Làm arepa:", "Bước cuối trong việc định hình arepa là đưa và nhẹ nhàng nhấn đĩa masa từ tay này sang tay khác cho đến khi dày khoảng 1,9 cm và rộng 10 cm. Làm mịn các cạnh bằng đầu ngón tay (nhúng nhanh vào tô nước trước) để chúng giữ hình tròn nhất có thể và không nứt.", "Làm arepa:", "Đặt arepa theo đợt trên bề mặt budare hoặc chảo không dính đã đun trước. Để mỗi bên vàng, khoảng 4 đến 5 phút mỗi bên. Kiểm tra thường xuyên để chúng không bị cháy.", "Khi chúng đã vàng đều trên hai mặt, đặt arepa lên khay nướng trong lò đã đun trước trong 10 phút. Chúng nên hơi phồng, để nếu bạn nhẹ nhàng gõ lên trên một arepa, nó sẽ nghe như đang gõ vào hộp rỗng.", "Dùng arepa nóng, dù bạn nhồi chúng với nhân tùy chọn hoặc dùng đơn riêng để đi kèm guiso hoặc hầm Venezuela."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5a60c6df-93db-5d3e-9310-09936892b9e8', 'fa3ab68d-fab5-5968-91fc-66dbe30c41eb', 480.0, 'ml'::public.quantity_unit);
