INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('dde61361-0fb2-51cc-b19d-45dc81980c78', 'Gà nấu nước cốt dừa kiểu Venezuela', 'man'::public.dish_category, '["Cắt gà thành các miếng cắn vừa. Bóc và cắt hành tây, băm tỏi.", "Chuẩn bị các nguyên liệu còn lại và bạn đã sẵn sàng bắt đầu nấu.", "Làm món:", "Đun nóng chảo chiên trên lửa vừa. Thêm dầu và khi nóng, hẹn hành tây cho đến khi trong suốt. Lấy khỏi chảo và chuyển vào máy xay hoặc máy xay thực phẩm.", "Thêm cà chua, tỏi, nghệ, cumin, đường, sốt đặc gừng, nước cốt dừa và nước vào, xay mịn.", "Trong cùng chảo bạn đã nấu hành, thêm gà và vàng mọi mặt. Nên mất khoảng 3 phút.", "Thêm thành phần từ máy xay và lá nguyệt quế vào chảo, đun sôi nhẹ và nấu cho đến khi gà trắng bên trong và chất lỏng kem. (15 đến 20 phút)", "Bỏ lá nguyệt quế ra và dùng với cơm trắng."]'::jsonb, 4);
