INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('740077f6-0324-589f-8218-6e04328e87f1', 'Bò xé kiểu Venezuela', 'man'::public.dish_category, '["Nêm bò với muối, tiêu và tỏi băm.", "Cắt 1 hành tây thành 4 lát lớn.", "Đặt vào nồi áp lực bò với 4 lát hành tây và nước dùng.", "Nấu áp lực 20 phút.", "Giả áp lực và mở nắp.", "Lấy bò ra và lưu 2 chén nước dùng vào hộp khác.", "Với 2 nĩa, xé bò. Bò nên mềm đủ để xé dễ dàng. Nếu không, nấu thêm 10 phút.", "Bấm nút xào của nồi Instant. Thêm dầu ô liu.", "Khi máy bíp, thêm hành tây lát, ớt chuông đỏ và cà chua. Nấu cho đến khi mềm.", "Thêm bò đã xé trở lại nồi và trộn.", "Đổ 1,5 chén nước dùng đã lưu, sốt Worcestershire, cà chua xay nhuyễn, ketchup và cumin vào. Trộn.", "Nếu sốt vơi khô, thêm chút nước dùng nữa.", "Nêm muối và tiêu.", "Dùng!"]'::jsonb, 4);
