INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b63a866e-6179-5842-bc04-21fb81701200', 'Arepa pelua', 'man'::public.dish_category, '["Nấu thịt: Đặt bắp bò vào nồi với nước dùng hoặc nước và muối. Nấu trên lửa nhỏ khoảng 2 giờ cho đến khi mềm và xé được sợi.", "Xé thịt: Khi chín đã, lọc nước và xé thịt sợi bằng hai nĩa.", "Chuẩn bị rau: Cho hành tây cắt nhỏ, ớt chuông đỏ và tỏi vào chảo với ít dầu, xào. Thêm cumin, oregano, paprika và muối. Cho thịt vào, khuân và nấu vài phút cho đến khi hương vị trộn đều.", "Làm bột: Trong bát, trộn bột ngô với nước ấm và muối cho đến khi tạo thành bột mềm. Để nghỉ 5 phút.", "Hình thành arepa: Chia bột thành 6 phần, tròn thành viên và úp nhẹ thành các bánh dày.", "Nướng: Nướng arepa trên nồi nướng hoặc chảo trên lửa trung bình 2-3 phút mỗi bên cho đến khi vàng. Có thể nướng thêm vài phút trong lò nếu thích giòn hơn.", "Nhân: Mở arepa ra một bên, nhét thịt bò xé sợi nóng vào và rồi phô mai bào lên trên."]'::jsonb, 4);
