INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6da68a97-fb70-56a8-abbb-09ce5d2f2d7d', 'Pizza bánh khoai mì (Cassava pizza)', 'man'::public.dish_category, '["Đun lò trước đến 200°C.", "Cắt xúc xích Chorizo thành các miếng vừa phải và bắp ngọt thành sợi.", "Cho một ít sốt cà chua và phô mai Mozzarella trên mỗi phần bánh khoai mì Casabe.", "Thêm xúc xích Chorizo, bắp ngọt, giăm bông thịt gà tây, một số quả ô liu xanh và bột ớt ngọt Paprika.", "Nướng trong 7 đến 10 phút.", "Lấy ra khỏi lò và thưởng thức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6da68a97-fb70-56a8-abbb-09ce5d2f2d7d', 'db3ce69c-042e-5f03-b271-dd3a403b49ed', 6.0, 'piece'::public.quantity_unit);
