INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a37d20d8-5b6e-5ae1-997f-ca103f2e5ec3', 'Bánh empanada Venezuela', 'rau'::public.dish_category, '["Nêm thịt với Adobo. Trong chảo, đun nóng dầu trên lửa cao vừa. Nấu thịt cho đến khi màu hồng biến mất. Khuấy hành tây, ớt chuông, tỏi, nụ bạch hoa, sốt cà chua và Sazón vào. Nấu, khuấy thường xuyên cho đến khi phần lớn chất lỏng đã bốc hơi (khoảng 20 phút). Để nguội.", "Bột đã chuẩn bị nên ẩm và nên dính kết, nhưng không nên dính vào tay. Bắt đầu với khoảng ½ chén bột và cuộn thành viên trong lòng bàn tay. Làm việc trên một tờ giấy nướng không dính, định hình viên thành vòng tròn 5 inch dày khoảng 0,3 cm. Đặt một muỗng canh đầy nhân vào một nửa vòng và dùng giấy nướng đóng bột lại thành hình nửa tròn. Để kén và cắt viền bánh, nhấn Vien của cái tô ngược lên trên bánh hình nửa tròn. Làm lại với tất cả các empanada.", "Trong chảo lớn trên lửa cao vừa, đun nóng 1 cm dầu cho đến khi nóng nhưng không khói. Nấu empanada theo đợt, lật một hoặc hai lần cho đến khi nhẹ vàng. Rổ nước trên khăn giấy. Đừng quá đông chảo hoặc để dầu quá nóng."]'::jsonb, 4);
