INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ca28361a-4023-520c-8bfc-2ea76d3588c1', 'Bánh arepa pabellón (Arepa Pabellón)', 'man'::public.dish_category, '["Chuẩn bị thịt trong chảo và nems muối, tiêu vừa đủ, đun đậu đen trên lửa trung bình trong chảo, chiên hoặc nướng chuối chín như hướng dẫn trên bao bì và cắt cà chua thành các khối nhỏ. Giữ các nguyên liệu này cho đến khi phần nhân.", "Đun nồi nướng hoặc chảo và nướng bánh arepa, cấp mỗi bên một lần cho đến khi vàng.", "Dùng dao, bẻ ra lề theo giữa, tạo khoảng trống để nhét chuối chín, đậu đen, thịt và cà chua đã cắt nhỏ.", "Ăn kèm một ít pico de gallo hoặc sốt chấm guacamole."]'::jsonb, 4);
