INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f0ed228c-695a-5d5d-becc-e20dda13832f', 'Bữa tối Canada (Jiggs Dinner)', 'man'::public.dish_category, '["Tối hôm trước, vỡ thịt bò mặn thành các miếng lớn và ngâm trong nước qua đêm, ít nhất 8-10 tiếng. Đặt đậu Hà Lan vàng tách đôi vào bát và ngâm với nước để ngâm qua đêm.", "Đổ nước thịt bò mặn và đặt nó vào nồi súp lớn. Ngâm với nước tươi, ít nhất 6-7 lít. Đặt đậu Hà Lan vàng tách đôi vào một túi vải pease pudding hoặc ba lớp vải dün và buộc, đảm bảo để chỗ cho đậu giãn nở bên trong túi.", "Đặt túi vào nồi, buộc dây vào cái xách bên ngoài để nó không dính vào đáy nồi với thịt bò mặn. Đun sôi, rồi giảm lửa và hầm nhẹ trong 2 tiếng.", "Lấy túi đậu ra và đổ nội dung vào bát, trộn với bơ và tiêu để có vị. Để một bên.", "Thêm cải của bạn vào nồi và sôi thêm 20 phút. Sau đó thêm củ cải tròn, cà rốt và khoai tây rồi sôi thêm 20 phút nữa, cho đến khi rau mềm.", "Lấy thịt bò mặn và rau khỏi nồi và đặt chúng trên đĩa.", "Sử dụng chất lỏng nấu theo hai cách; làm nước súp nồi mà một số người thích uống hoặc giảm nó để làm sốt rưới lên bữa ăn."]'::jsonb, 4);
