INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a4b002f5-1daa-59af-8277-26a0af90f2cf', 'Đậu nướng mật mía Canada (Molasses Baked Beans)', 'rau'::public.dish_category, '["Cho đậu trắng khô vào nồi Holland với 1,5 lít nước. Ngâm suốt đêm.", "Ráo và cho đậu lại vào nồi với đủ nước ngập đậu vài inch, nấu 30 phút cho đến khi đậu mềm nhưng vẫn ferme. Ráo đậu, nhớ đựng nước luộc, để riêng.", "Đậy lò 160°C. Khi lò đang đậy, nấu thịt heo trên lửa vừa-cao trong nồi Holland cho đến khi mỡ tan và thịt bắt đầu vàng, rồi thêm hành nấu cho đến khi mềm.", "Cho đậu lại vào nồi, cùng với mật mía, đường nâu, giấm táo, mù tạt nghiền, muối, tiêu và 750 ml nước luộc đậu đã giữ lại.", "Nướng không nắp 3 đến 5 giờ cho đến khi đậu mềm, sốt đã đặc và cạnh nồi trở nên dính.", "(Lưu ý: nếu đậu khô, thêm một chén nước.)"]'::jsonb, 4);
