INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1924e8ed-4b27-5b13-a247-20ef079f5359', 'Hầm rau củ Canada (Hodge Podge)', 'rau'::public.dish_category, '["Trước hết, nấu rau của bạn. Đun một nồi lớn nước có muối đến sôi. Dầm cà rốt và khoai tây trong năm phút cho đến khi cà rốt và khoai tây mềm khi đâm nĩa, rồi sắc đậu que và đậu Hà Lan trong khoảng một phút trong cùng nồi. Ráo rau và để một bên.", "Trong nồi đáy dày hoặc nồi Hà Lan, cho bơ vào trên lửa vừa, thêm rau, và nấu cho đến khi nóng qua.", "Thêm sữa và kem và đun súp đến sôi. Giảm lửa xuống thấp và nêm muối và tiêu.", "Thêm thì là và hẹ và để sôi nhẹ ít nhất 10 phút. Ăn nóng."]'::jsonb, 4);
