INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('53d2b85b-7035-5fdc-8fcd-d1aa0654827c', 'Tôm cay Jamaica (Jamaican Pepper Shrimp)', 'man'::public.dish_category, '["Trong bát vừa, trộn tôm với ớt Scotch Bonnet đã băm, gia vị đa dụng, bột hạt điều màu, và hạt tiêu Jamaica xay. Lắc tốt để phủ đều và ướp trong 10 phút.", "Đun chảo lớn trên lửa vừa. Thêm nước hầm tôm và đun sôi nhẹ. Khuấy hành tây đã cắt và tỏi, nấu cho đến khi mềm và thơm, khoảng 2 phút.", "Thêm tôm đã nêm và nhánh xạ hương, rải tôm ra trong chảo. Đậy nắp và nấu khoảng 5–7 phút, khuấy thỉnh thoảng, cho đến khi tôm chuyển sang cam và chín kỹ.", "Thêm giấm trắng, khuấy, và nấu thêm một phút. Thử; thêm muối theo khẩu vị. Dùng thìa có lỗ, chuyển tôm sang đĩa. Ăn nóng với một chút nước nấu rưới lên trên."]'::jsonb, 4);
