INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('348577a0-a283-539d-b7cc-439159e4186c', 'Bò muối và bắp cải kiểu Jamaica (Corned Beef and Cabbage – Jamaican Style)', 'man'::public.dish_category, '["Đun nóng dầu ô liu trong chảo hoặc nồi Holland trên lửa cao vừa. Thêm hành tây và ớt chuông xanh và xào trong khoảng 3-5 phút.", "Thêm tỏi và khuấy trong khoảng 1 phút.", "Thêm bắp cải đã nghiền và khuấy. Nấu trong khoảng 3-5 phút, gọi thường xuyên cho đến khi mềm.", "Thêm Thịt bò muối đóng hộp bò muối, cà chua quả mận, và xạ hương và khuấy. Thêm Tương cà Ketchup và sốt ớt chuông siêu cay Scotch Bonnet và khuấy. Giảm lửa và nấu trên mức trung bình trong khoảng 3-5 phút, cho đến khi Thịt bò muối đóng hộp bò muối đã nóng qua. Nâng khỏi lửa.", "Phục vụ với cơm trắng, bánh mì, hoặc đơn độc."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('348577a0-a283-539d-b7cc-439159e4186c', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 15.0, 'ml'::public.quantity_unit);
