INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a204e7a8-795c-50f4-a3f5-c26a6f1dc4d9', 'Cơm và đậu nồi áp suất điện Jamaica (Jamaican Instant Pot Rice and Beans)', 'rau'::public.dish_category, '["1. Hướng dẫn:", "2. Đặt nồi áp suất điện ở chế độ \"xào.\" Khi nóng, thêm dầu ô liu. Sau đó thêm hành vàng và khuấy cho đến khi mềm, khoảng 3 phút. Thêm tỏi và hành lá và khuấy thêm khoảng 30 giây nữa.", "3. Nhấn \"hủy\" trên nồi áp suất điện. Thêm gạo, nước cốt dừa, nước, muối, hạt tiêu Jamaica, và tiêu đen và khuấy.", "4. Đổ đậu đỏ Kidney không đổ nước lên trên hỗn hợp gạo. Không khuấy. Đặt nhánh xạ hương lên trên. Đậy nắp nồi áp suất điện, đảm bảo van được đặt ở \"khí kín.\"", "5. Nhấn \"thủ công\" hoặc \"nấu áp lực\" trên nồi áp suất điện và đặt cho áp suất cao trong 6 phút.", "6. Khi thời gian nấu áp suất hoàn tất, để nó thả tự nhiên trong 10 phút, rồi thả nhanh phần áp suất còn lại bằng cách di chuyển van đến \"thoát hơi\"", "7. Mở nắp và lấy nhánh xạ hương ra. Dùng nĩa để làm cho các hạt cơm phân rã. Thưởng thức!", "8. Hướng dẫn nấu trên bếp:", "9. Đun dầu ô liu trong nồi lớn trên lửa vừa. Thêm hành vàng và khuấy cho đến khi mềm, khoảng 3 phút. Thêm tỏi và hành lá và khuấy thêm khoảng 30 giây nữa.", "10. Thêm gạo, đậu đỏ Kidney không đổ nước, nước cốt dừa, nước, muối, hạt tiêu Jamaica, và tiêu đen và khuấy cho đến khi kết hợp. Đặt xạ hương lên trên. Để hỗn hợp sôi nhẹ.", "11. Đậy nắp và giảm lửa xuống thấp. Để nấu trong 18 phút trên lửa thấp, rồi bớt khỏi lửa. Để nắp ở trên trong thêm 5 phút.", "12. Mở nắp và lấy xạ hương ra. Dùng nĩa để làm cho các hạt cơm phân rã. Thưởng thức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a204e7a8-795c-50f4-a3f5-c26a6f1dc4d9', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 15.0, 'ml'::public.quantity_unit);
