INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('731f56e0-1d43-5527-af25-c3b2cc9b6b2d', 'Bánh đúc luộc Jamaica (Jamaican Boiled Dumplings)', 'rau'::public.dish_category, '["1. Hướng dẫn:", "2. Trong nồi lớn, đun nước và muối đến sôi để luộc bánh đúc.", "3. Trong bát trộn lớn, trộn bột mì và muối, khuấy để phân phối muối đều khắp bột. Dần dần thêm nước vào hỗn hợp bột, trộn bằng tay cho đến khi tạo thành bột.", "4. Chia bột thành các miếng bằng nhau, cuộn mỗi miếng thành một viên mịn. Dập nhẹ mỗi viên bằng lòng bàn tay để tạo một bánh đúc tròn. Nó nên trông như một đĩa dày.", "5. Nhẹ nhàng thả các bánh đúc vào nước sôi, một cái một lần, đảm bảo chúng không dính nhau. Bạn có thể dùng thìa gỗ để khuấy các bánh đúc trong nước.", "6. Luộc các bánh đúc trong 15-20 phút, hoặc cho đến khi chúng chín kỹ và đã nổi lên bề mặt nước. Khuấy thỉnh thoảng để ngăn dính.", "7. Dùng thìa có lỗ để lấy các bánh đúc đã chín khỏi nồi, để nước thừa ráo.", "8. Ăn kèm với các công thức yêu thích của bạn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('731f56e0-1d43-5527-af25-c3b2cc9b6b2d', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 1920.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('731f56e0-1d43-5527-af25-c3b2cc9b6b2d', '1aac59db-1947-5be3-926e-dc730387fc63', 7.5, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('731f56e0-1d43-5527-af25-c3b2cc9b6b2d', '7d6a1f7e-745c-5cd6-af33-19568749147f', 480.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a1674107-36ce-5a0f-ba24-054d39f3472c', 'Cà ri dê Jamaica (Jamaican Curry Goat)', 'man'::public.dish_category, '["1. Thiết bị:", "2. Nồi áp suất 6QT", "3. Hướng dẫn:", "4. Rửa thịt dê với giấm và nước.", "5. Nêm thịt dê với 1 1/2 muỗng canh bột cà ri, gia vị đa dụng, gừng xay, hạt tiêu Jamaica, hành tây, tép tỏi, và xạ hương. Ướp ít nhất 4 tiếng hoặc qua đêm.", "6. Lấy hành và tỏi ra khỏi dê và để một bên.", "7. Đặt nồi áp suất điện, như nồi áp suất điện, trên chế độ xào cao và thêm dầu. Thêm thịt dê và chiên cho vàng, khoảng 2-3 phút mỗi bên. Lấy dê khỏi phần chèn và thêm 1 muỗng canh dầu và phần bột cà ri còn lại và xào trong khoảng 10 giây. Sau đó thêm hành và tỏi và xào cho đến khi mềm. Khoảng 4 phút. Nếu hành trông khô, thêm một chút nước và tiếp tục xào.", "8. Thêm dê và nước vào nồi áp suất và đậy nắp nồi áp suất. Nấu trong 40 phút trên áp suất cao. Cho thả tự nhiên trong 10 phút, rồi thả phần áp suất còn lại.", "9. Khi tất cả áp suất đã được thả, mở nồi áp suất. Đặt trên chế độ xào trong 10-15 phút, thêm khoai tây và một quả ớt Scotch Bonnet nguyên. Nấu cho đến khi khoai tây đã mềm. Lấy ớt Scotch Bonnet ra."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a1674107-36ce-5a0f-ba24-054d39f3472c', '20dae192-f88f-59d3-8aeb-dce61b5ad94f', 1360.8, 'g'::public.quantity_unit);
