INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('de5c8841-423b-5ce8-939a-365d68f7a498', 'Bánh ngọt Jamaica (Jamaican Festival)', 'rau'::public.dish_category, '["Đun một nồi đáy dày dầu có ít nhất 7 cm dầu hoặc dùng chiên nồi nếu bạn có một. Bật lửa ở mức vừa cho đến khi nhiệt độ đạt 175°C.", "Thêm bột mì đa dụng, bột ngô hạt thô, đường tinh, bột nở, và muối vào bát lớn và khuấy để kết hợp.", "Thêm chiết xuất vani và sữa và khuấy cho đến khi hỗn hợp kết hợp. Sau đó dùng tay của bạn để nhẹ nhàng tạo hỗn hợp thành một viên.", "Nhúp từng phần bột và cuộn chúng thành hình oval dài. Làm khoảng 12 bánh đúc.", "Khi dầu đã đạt nhiệt độ 175°C, chiên bột trên tất cả các bên, cho đến khi vàng. Điều này sẽ mất khoảng 4-6 phút.", "Lấy bột ra và để ráo dầu thừa. Ăn và thưởng thức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('de5c8841-423b-5ce8-939a-365d68f7a498', '7d6a1f7e-745c-5cd6-af33-19568749147f', 360.0, 'ml'::public.quantity_unit);
