INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('beac6e4f-0872-5588-8175-ac022e0dbc4a', 'Bánh đúc chiên Jamaica (Jamaican Fried Dumplings)', 'rau'::public.dish_category, '["Thêm bột mì, bột nở, và muối vào bát lớn và khuấy để kết hợp. Đổ sữa vào và khuấy cho đến khi kết hợp. Sau đó cuộn hỗn hợp thành một viên và nhẹ nhàng nghiền cho đến khi nó kết hợp.", "Gỡ khoảng 10 phần bột và hình thành chúng thành viên. Đặt chúng một bên.", "Trong chảo 25 cm, đun đủ dầu trên lửa vừa để chiên các bánh đúc, cho đến khi dầu khoảng 175°C.", "Khi các bánh đúc đã vàng trên một bên, lật chúng và nấu cho đến khi cả hai bên đều vàng, khoảng 2-3 phút mỗi bên.", "Khi hoàn thành, lấy các bánh đúc khỏi dầu và đặt chúng lên giấy bếp hoặc giá để nguội để để ráo dầu thừa.", "Ăn và thưởng thức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('beac6e4f-0872-5588-8175-ac022e0dbc4a', '7d6a1f7e-745c-5cd6-af33-19568749147f', 480.0, 'ml'::public.quantity_unit);
