INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('864c2256-dfb5-52b4-bbf0-5b49075fd415', 'Cơm và đậu Jamaica (Jamaican Rice and Peas)', 'rau'::public.dish_category, '["1. Thiết bị: Nồi Hà Lan", "2. Thêm gạo, nước cốt dừa, đậu đỏ Kidney, nước, muối kosher, hạt tiêu Jamaica xay, và tiêu đen vào nồi lớn và khuấy cho đến khi kết hợp. Đặt hành lá, xạ hương, và ớt Scotch Bonnet lên trên. Đun hỗn hợp đến sôi.", "3. Khi đã sôi, giảm lửa xuống thấp và đậy nắp. Để nấu với nắp đậy trong 18 phút trên lửa thấp, rồi bớt khỏi lửa. Để nắp ở trên trong thêm 5 phút.", "4. Mở nắp và lấy hành lá, ớt Scotch Bonnet, và xạ hương ra. Dùng nĩa để làm cho các hạt cơm và đậu phân rã. Ăn và thưởng thức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('864c2256-dfb5-52b4-bbf0-5b49075fd415', '4a081187-4d43-536a-9103-19f259b0316c', 480.0, 'ml'::public.quantity_unit);
