INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6ed92f83-c2b3-53f5-b928-a767834e427d', 'Gà nấu với cơm Mandi (Chicken Mandi)', 'man'::public.dish_category, '["Bước 1. Vệ sinh và cắt gà; ướp ngắn với muối, nghệ và chút dầu.", "Bước 2. Rửa và ngâm gạo Basmati 20–30 phút.", "Bước 3. Trong nồi lớn, đun nóng Ghee hoặc dầu. Chiên hành tây đã kẹo cho đến khi vàng. Thêm tỏi đã nhẽn và ớt xanh và chiên 1–2 phút.", "Bước 4. Thêm các gia vị nguyên (thảo quả, đinh hương, quế, lá nguyệt quế) và gia vị nhuyễn (ngò rí, thì là Cumin). Khuấy cho đến khi thơm.", "Bước 5. Thêm các miếng gà, chiên nhẹ cho vàng và thêm đủ nước/nước dùng gà để ngập. Hầm cho đến khi gà gần chín.", "Bước 6. Lấy gà ra; đo phần nước còn lại và thêm gạo đã ngâm. Đun sôi, sau đó giảm lửa, đậy nắp và nấu gạo cho đến khi gần chín.", "Bước 7. Trả gà vào nồi gạo ở trên, đậy nắp chặt và hấp trên lửa thấp trong 10–15 phút để hương vị trộn lẫn.", "Bước 8. (Tùy chọn) Để tạo mùi khói auténtic: đun một kleines than cho đến khi đỏ rải, đặt nó vào một chiếc nilon nhỏ ở chính giữa nồi, thêm một thìa cà phê bơ/dầu lên than rồi đậy nắp ngay để khử khói trong 5–10 phút. Lấy than ra.", "Bước 9. Trangs trí bằng hành tây đã chiên, ngò rí đã kẹo và ăn với chutney hoặc raita."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6ed92f83-c2b3-53f5-b928-a767834e427d', '44a6a37a-69a3-5573-9fd1-730baf90fb5b', 1.0, 'piece'::public.quantity_unit);
