INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6cd71f25-93c4-5e02-8843-6bdb56355ba3', 'Cơm mandi bò', 'man'::public.dish_category, '["1. Rửa thịt bò và cắt thành các miếng lớn. Nems nhẹ với muối và bột nghệ.", "2. Đun dầu dê/dầu trong nồi lớn. Thêm hành đã cắt lát và xào cho đến khi hơi vàng.", "3. Thêm tỏi, ớt xanh và cà chua; nấu cho đến khi mềm.", "4. Thêm hỗn hợp gia vị mandi: ngò rí, cumin, tiêu đen, quế, thảo quả, đinh hương và lá nguyệt quế.", "5. Thêm các miếng thịt bò và khuân trên lửa trung bình cho đến khi thịt được phủ tốt bởi gia vị.", "6. Đổ nước hoặc nước dùng bò. Đậy nắp và hầm nhẹ cho đến khi thịt bò mềm (khoảng 1,5–2 giờ tùy phần).", "7. Lấy thịt bò ra cẩn thận và đặt một bên. Lọc và đo lường nước dùng.", "8. Thêm gạo basmati đã rửa và ngâm vào nước dùng (thông thường 1 chén gạo = 1,5–2 chén chất lỏng). Điều chỉnh nems và đun đến sôi.", "9. Giảm lửa, đậy nắp và nấu gạo cho đến khi mềm mịn.", "10. Đặt các miếng thịt bò lên trên gạo và hấp trên lửa thấp 10 phút để hương vị kết hợp.", "11. Tùy chọn: Để có mùi khói, đặt một mảnh than nóng nhỏ trên giấy bạc trong nồi, thêm 1 muỗng cà phê bơ/dầu, ngay lập tức đậy nắp trong 5 phút. Bớp than ra trước khi phục vụ.", "12. Dùng nĩa lả gạo và phục vụ cơm mandi bò với salad hoặc chutney."]'::jsonb, 4);
