INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e85f03cc-4dbc-5546-986b-cdf5e18861dc', 'Cá mặn và callaloo Jamaica', 'rau'::public.dish_category, '["Ngâm cá mặn trong nước qua đêm. Sau đó, đun cá mặn trong nước trên bếp cho đến khi nước sôi. Bạn sẽ thấy bọt trên trên. Lấy ra khỏi bếp và để thoát nước. Để một bên và xé cá mặn khi nó nguội.", "Chiên xúc xích khói trong chảo trên lửa trung bình cho đến khi giòn. Lấy xúc xích khói khỏi bếp và xé bỏ phần lớn mỡ xúc xích khói, để lại khoảng 1 muỗng canh trong chảo.", "Thêm hành vàng, hành lá, ớt chuông siêu cay Scotch Bonnet và tỏi vào chảo và khuân. Nấu khoảng 2 phút cho đến khi hành mềm. Thêm cá mặn vào chảo và khuân. Nấu khoảng một phút.", "Sau đó, thêm callaloo, cà chua quả mận, xạ hương, và tiêu đen. Khuân trộn và nấu cho đến khi nóng đều, khoảng 2 phút.", "Thưởng thức"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('e85f03cc-4dbc-5546-986b-cdf5e18861dc', '8c42b1a4-d98a-5ef8-bea9-023e120b7eca', 226.8, 'g'::public.quantity_unit);
