INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d8e8b4a2-b956-5cf3-a5c0-e76254b6f364', 'Cà ri tôm Jamaica (Jamaican Curry Shrimp Recipe)', 'man'::public.dish_category, '["Nêm tôm với 1 muỗng canh bột cà ri và gia vị đa dụng và để một bên khoảng 10 phút trong khi bạn chuẩn bị các nguyên liệu khác như cắt hành, ớt, và tỏi.", "Đun 2 muỗng canh dầu ô liu trong chảo lớn trên lửa vừa. Thêm hành tây vàng đã cắt lát, ớt chuông đỏ, ớt chuông xanh, ớt Scotch Bonnet, nếu dùng, và tỏi đã băm và khuấy trong 5 phút, cho đến khi ớt hơi mềm.", "Thêm 1,5 muỗng canh bột cà ri vào chảo và khuấy thêm một phút.", "Sau đó thêm nước cốt dừa, tôm đã nêm, sốt cà chua, và xạ hương, đảm bảo tôm được phủ trong sốt.", "Để sốt sôi nhẹ và tiếp tục nấu trên lửa vừa, khuấy thỉnh thoảng và lật tôm vào nửa đường, cho đến khi tôm chín kỹ cả hai bên. Điều này sẽ mất khoảng 5-6 phút. Nêm muối và tiêu theo khẩu vị."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d8e8b4a2-b956-5cf3-a5c0-e76254b6f364', '3560d1a2-dfa1-5d89-9d31-e951e14fe111', 453.6, 'g'::public.quantity_unit);
