INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('67c4910d-aab5-5197-b5eb-3eaf28e3d9dd', 'Cải hấp Jamaica (Jamaican Steamed Cabbage)', 'rau'::public.dish_category, '["Thêm tất cả nguyên liệu vào chảo lớn trên lửa vừa và đậy nắp.", "Nấu trên lửa vừa trong 10 phút, khuấy thỉnh thoảng.", "Sau 10 phút, giảm lửa xuống thấp và tiếp tục nấu thêm 5 phút, cho đến khi cải mềm và nhừ. Bớt khỏi lửa và lấy nhánh xạ hương ra trước khi ăn."]'::jsonb, 4);
