INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fed731ee-af26-5608-a388-7918ac341d02', 'Bò xào cải xanh', 'man'::public.dish_category, '["Ướp bò:", "Trong bát vừa, khuân cùng các nguyên liệu ướp bò (1 muỗng cà phê nước tương, 1 muỗng cà phê rượu gạo Trung Quốc, 1/2 muỗng cà phê bột bắp, 1/8 muỗng cà phê tiêu đen).", "Thêm lát bò và khuân cho đến khi được phủ. Để 10 phút.", "Làm sốt:", "Trong bát nhỏ, khuân cùng các nguyên liệu sốt (2 muỗng canh dầu hào, 1 muỗng cà phê rượu gạo Trung Quốc, 1 muỗng cà phê nước tương, 60 ml nước dùng gà). Đặt một bên.", "Luộc hoặc hấp bông cải xanh:", "Đun nồi nước đến sôi. Thêm bông cải xanh và nấu cho đến khi vừa chín, còn giòn, khoảng 2 phút. Để thoát nước hoàn toàn.", "Xào bò:", "Đun chảo lớn hoặc wok trên lửa cao cho đến khi một giọt nước nói no và bốc hơi ngay khi chạm vào bề mặt. Thêm dầu nấu và quay cho bọc đều.", "Thêm bò và ngay lập tức lan tỏa ra toàn bộ bề mặt của wok hoặc chảo thành một lớp duy nhất (lưu ý không chạm nhau).", "Để bò chiên không quấy trong 1 phút. Lật các lát bò ngược lại, thêm tỏi vào chảo, và chiên thêm 30 giây đến 1 phút cho đến khi không còn hồng.", "Thêm sốt, bột bắp và bông cải xanh:", "Đổ sốt và hỗn hợp bột bắp (1 muỗng cà phê bột bắp tan trong 1 muỗng canh nước). Khuân cho đến khi sốt sôi và đặc, khoảng 30 giây. Khuân bông cải xanh vào.", "Phục vụ ngay, với cơm hấp hoặc đơn lẻ."]'::jsonb, 4);
