INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5f41673b-8628-574f-b54d-332df8c34a90', 'Cơm chiên gà (Chicken Fried Rice)', 'man'::public.dish_category, '["Cơm chiên ngon nhất làm bằng cơm còn lại ít nhất một ngày cũ. Nếu không nó sẽ dính chảo.", "Nếu bạn không có cơm còn lại từ đêm hôm trước, nấu một đợt cơm và rải nó trên một khay nướng lớn hoặc một vài đĩa lớn. Để cơm khô khoảng 1 đến 2 giờ trước khi dùng cho cơm chiên.", "Cơm dính chảo rất dễ, vì vậy hãy đảm bảo dùng một chảo hoặc nồi không có bề mặt dính. Tôi thường chiên trong chảo carbon steel đã nguội của tôi, nhưng nồi sắt hoặc chảo không dính cũng hoạt động tốt. Bạn có thể cần thêm chút dầu nếu vật không thả ra dễ dàng.", "Chuẩn bị gà:", "Kết gà thành các miếng nhỏ khoảng 1/4-inch đến 1/2-inch. Rắc 1/2 muỗng cà phê muối lên gà và trộn kết hợp. Đặt gà một bên khoảng 10 phút (tôi thường dùng thời gian này để cắt tất cả các loại rau).", "Trộn trứng:", "Đun nóng một chảo lớn hoặc chảo nướng trên lửa cao. Xoáy một thìa dầu vào và cho trứng đã đánh. Dùng espátula để vội vã trứng nhanh, nghiền những mảng trứng thành các miếng nhỏ khi chúng kết hợp. Chuyển trứng ra một đĩa.", "Nấu gà:", "Thêm một thìa dầu khác vào chảo hoặc nồi. Cho gà và nấu trong 4 đến 5 phút, gọi đôi khi. Tắt lửa và chuyển gà đã nấu ra một đĩa.", "Dùng espátula của bạn, kẹp mọi mảnh gà còn dính vào chảo để chúng không cháy trong bước tiếp theo. Bạn cũng có thể dùng khăn giấy để lau chảo hoặc nồi.", "Nấu rau:", "Xoáy một thìa dầu vào chảo trên lửa cao. Cho hành tây đã diced vào và nấu chúng trong 1 phút, cho đến khi chúng bắt đầu mềm. Trộn tỏi đã minced và gừng xay vào và nấu cho đến khi thơm, khoảng 30 giây. Thêm cà rốt đã diced và nấu trong 2 phút, gọi thường xuyên. Thêm 1/2 muỗng cà phê muối và đậu Hà Lan vào, trộn kết hợp.", "Nấu cơm:", "Thêm cơm vào chảo hoặc nồi trên trên rau và trộn kết hợp. Dùng phần sau của espátula, nghiền các mảng cơm lớn để nhỏ ra. Thêm phần trắng và xanh của hành lá đã cắt (lưu phần xanh tối) và bột ngũ vị hương. Trộn kết hợp. Nếu cơm bắt đầu dính chảo, khuấy thêm ít dầu.", "Rưới nước tương và dầu mè thơm nguyên chất lên cơm và trộn kết hợp. Khuấy gà đã nấu, trứng đã trộn, và phần xanh tối của hành lá vào. Khuấy ngắn gọn để kết hợp, và nấu thêm 1 đến 2 phút.", "Ăn:", "Nếm, và thêm nước tương nếu cần. Ăn ngay lập tức."]'::jsonb, 4);
