INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('68d4e70f-f2ae-55a4-984b-c2b01477958a', 'Mì Singapore xào tôm (Singapore Noodles with Shrimp)', 'man'::public.dish_category, '["Với hành tây ngọt, tìm Vidalia, OSO Sweet, hoặc Walla Walla. Các loại ngọt siêu phù hợp hơn cho xào này vì ở cuối nấu, hành vẫn có chút giòn.", "Làm sốt:", "Trong tô, trộn dầu mè, xì dầu và giấm gạo.", "Luộc mì gạo:", "Đun nồi lớn nước cho sôi, thêm mì và dùng kéo để lật cho mì ngập nước. Nấu trong 2 phút, hoặc cho đến khi mì mềm nhưng vẫn có chút giòn (chúng sẽ nấu thêm một chút khi bạn thêm vào chảo).", "Rarget nước, vò dưới nước lạnh, và dùng kéo để cắt mì thành các đoạn ngắn hơn nhiều lần.", "Chao trứng:", "Trong tô nhỏ đánh trứng. Đun chảo hoặc nồi ninh trên lửa vừa. Thêm 1 muỗng canh dầu đậu phộng hoặc dầu canola. Thêm trứng và chao trong 2 phút, hoặc cho đến khi tạo thành các mảnh trứng lớn và mềm. Chuyển từ chảo ra đĩa hoặc tô.", "Nấu rau:", "Thêm 1 muỗng canh dầu còn lại vào chảo. Khi nóng, thêm gừng, tỏi, cà rốt, ớt Jalapeño, hành tây và muối. Nấu, khuấy liên tục, trong 2 phút hoặc cho đến khi rau bắt đầu mềm.", "Thêm các thành phần còn lại:", "Rắc hỗn hợp rau với 1 muỗng canh dầu đậu phộng hoặc canola còn lại. Khi dầu nóng, thêm chả, cải, hành lá, ớt đỏ và bột cà ri vào chảo. Nấu, khuấy liên tục, trong 1 phút.", "Thêm tôm và nấu, khuấy, trong 3 phút nữa hoặc cho đến khi tôm hồng và chín đều.", "Thêm mì theo từng đợt:", "Thêm trứng, hỗn hợp sốt và nửa mì vào chảo. Trộn trong 1 phút.", "Thêm mì còn lại và tiếp tục trộn thêm 1 phút cho đến khi kết hợp hoàn toàn và hỗn hợp nóng qua.", "Phục vụ:", "Nếm nems và thêm thêm muối hoặc xì dầu nếu muốn. Rắc lá ngô rí và phục vụ."]'::jsonb, 4);
