INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8696e330-e30c-5dec-bc89-c37582d40046', 'Đậu hũ non sốt mè và xì dầu (Silken Tofu with Sesame Soy Sauce)', 'rau'::public.dish_category, '["Chuẩn bị đậu hũ:", "Rarget đậu hũ và nhẹ nhàng lấy nó từ bao bì ra đĩa lớn. Cẩn thận cắt đậu hũ thành miếng dày 1,25 cm theo chiều ngang. Bằng lòng bàn tay, nhẹ nhàng đẩy các lát đậu hũ sang bên để chúng quạt ra trên đĩa.", "Trang trí bằng topping và phục vụ:", "Rưới xì dầu và sốt mè lên trên. Sau đó trang trí bằng hành lá và hạt mè, và phục vụ.", "Đậy kín phần còn lại và để trong tủ lạnh trong 2 ngày. Bạn có thể ăn lạnh ngay từ tủ lạnh hoặc hâm nóng bằng vi sóng theo các lần 30 giây cho đến khi nóng."]'::jsonb, 4);
