INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0df3503c-621d-587f-96ff-cbf77a8a3345', 'Trứng chiên Foo Young (Egg Foo Young)', 'man'::public.dish_category, '["Làm sốt:", "Trong một nồi nhỏ, thêm nước dùng bò không nêm muối, nước tương, Rượu Thiệu Hưng, sốt hào, và tiêu đen hạt/bột trên lửa trung bình. Đánh cùng nhau và đun sôi nhẹ.", "Kết hợp bột bắp và nước trong một bát nhỏ và đánh cho đến khi tan. Thêm vào nồi và đánh cho đến khi sốt đặc và bọc phần sau của thìa, 2 đến 3 phút. Đậy nắp nồi và giữ nóng trên mức thấp nhất có thể.", "Làm bột trứng chiên:", "Trong một bát vừa, đánh cùng nhau bột bắp và nước cho đến khi tan. Thêm trứng gà, muối, và đường. Đánh cho đến khi kết hợp tốt và không còn các mảng trứng trắng.", "Thêm hành lá, giá đỗ xanh, và tôm. Khuấy cho đến khi mọi thứ đều được phủ.", "Chiên trứng chiên:", "Thêm dầu thực vật vào một wok lớn; nó nên đạt khoảng 5cm lên các bên. Đun nóng dầu trên mức cao vừa cho đến khi những bọt nóng mạnh hình thành xung quanh một thìa gỗ đã chọc vào.", "Với một thìa nĩa, nhẹ nhẽ và chậm thêm 1/4 của bột trứng chiên. Trứng chiên nên ngay lập tức nổi bọt và phồng lên như phép màu. Chiên cho đến khi vàng nụi và giòn trên mỗi mặt, khoảng 2 phút mỗi mặt. Nếu có những điểm sáng, dùng thìa nĩa để nhẹ nhàng thêm dầu nóng lên nó.", "Lưu ý", "Trứng chiên có thể hơi khó để lật. Cách dễ nhất là đặt một dụng cụ trong mỗi tay (một cái lưới, nĩa có lỗ, kìm, và đũa lớn đều là những ứng viên tốt) và nhẹ nhẽ khuyến khích trứng chiên qua, kéo một bên và đẩy lên phía kia.", "Lấy trứng chiên ra và đặt nó trên một cái khay nướng đã lót khăn giấy. Để nguội trong 5 phút. Cùng lúc đó, lặp lại với phần bột còn lại để làm 4 trứng chiên. Nếu cần, thêm thêm dầu vào chảo giữa các đợt.", "Phục vụ và thưởng thức:", "Đặt mỗi trứng chiên lên một lớp cơm. Rưới sốt nóng lên trên và phục vụ ngay lập tức."]'::jsonb, 4);
