INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ea237ece-febe-5c13-bb2e-fcadf39a349b', 'Đậu đũa xào kiểu Tứ Xuyên (Sichuan Style Stir-Fried Chinese Long Beans)', 'rau'::public.dish_category, '["Đậu đũa có thể tìm thấy ở cả màu xanh và tím. Cả hai đều có hương và kết cấu tương tự, và loại nào cũng có thể dùng cho công thức này.", "Nếu bạn không có chảo xào, dùng chảo xào lớn và chắc chắn có mép ít nhất 5 cm."]'::jsonb, 4);
