INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fa8feb06-1e8f-515d-9de5-ff036daf1a42', 'Cà tím xào kiểu Tứ Xuyên (Sichuan Eggplant)', 'rau'::public.dish_category, '["Công thức này yêu cầu cà tím Á hoặc cà tím Nhật. Chúng dài và mỏng so với cà tím Châu Âu hoặc cầu, và mềm mại hơn. Nếu không tìm được có thể thay bằng cà tím cầu, nhưng món thực sự ngon nhất với cà tím Á.", "*Nhiều cửa hàng thực phẩm hiện có hành đạo nguyên liệu Á. Bạn có thể tìm được sốt ớt đậu, hỗn hợp ớt bảo quản nghiền nhuyễn với đậu nành, đó hoặc tại bất kỳ chợ Á nào. (Đừng nhầm với sốt đậu đen hoặc sốt ớt-tỏi.)", "**Hoa tiêu Tứ Xuyên có sẵn tại một số cửa hàng và trên mạng với giá khá rẻ. Chúng không cay như ớt khác mà có hương chanh và gây cảm giác tê như nước ga.", "Chuẩn bị cà tím, sốt ớt, hỗn hợp bột ngô, giấm và hành lá:", "Bắt đầu chuẩn bị nguyên liệu. Cắt cà tím thành tư dọc và cắt thành miếng lớn và để riêng.", "Trong tô nhỏ, trộn nước dùng gà, đường và xì dầu và để riêng.", "Trong tô thứ hai, trộn sốt ớt đậu, tỏi, gừng và hoa tiêu Tứ Xuyên và để riêng.", "Trong tô thứ ba, trộn bột ngô với một muỗng canh nước và để riêng.", "Cuối cùng, trong tô thứ tư, trộn hành lá và giấm và để riêng.", "Xào cà tím:", "Đặt dầu vào chảo xào lớn trên lửa vừa-cao cho đến khi dầu gần khói. Thêm cà tím và xào, để nó nằm vài giây mỗi khi di chuyển để nó vàng và bong bóng. Nếu cà tím hút hết dầu và một số miếng không có thì thêm một ít dầu.", "Thêm sốt ớt đậu, tỏi, gừng và hoa tiêu Tứ Xuyên và xào:", "cho đến khi thơm, khoảng 30 giây.", "Thêm hỗn hợp nước dùng gà:", "xoay lửa về vừa-thấp và ninh trong 90 giây.", "Thêm hỗn hợp bột ngô:", "và trộn cùng cho đến khi sốt đặc một chút.", "Thêm hành lá và giấm:", "và nấu trong 15 giây để giảm vị cay xùi của chúng một chút.", "Trang trí bằng ngô rí và phục vụ."]'::jsonb, 4);
