INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1b1e3e80-d4bd-5c25-aab3-628d7a827eb1', 'Tôm xào đậu Hà Lan (Shrimp With Snow Peas)', 'man'::public.dish_category, '["Bạn cũng có thể dùng đậu Hà Lan ngọt cho công thức này. Tiết kiệm thời gian chuẩn bị bằng cách chuẩn bị đậu, gừng và tỏi trong khi tôm ướt.", "Ướt tôm:", "Trộn tất cả thành phần ướt trong bát lớn, rồi thêm tôm. Trộn đều. Để trong 15 đến 20 phút trong khi bạn chuẩn bị đậu, gừng và tỏi.", "Xào gừng và tỏi:", "Đun chảo xào lớn trên lửa cao trong 1 phút. Thêm dầu đậu phộng và để nóng, khoảng 30 giây. Thêm gừng và tỏi và trộn đều. Xào trong khoảng 30 giây.", "Thêm tôm, đậu Hà Lan, xì dầu, nước dùng:", "Thêm tôm và tất cả nước ướp vào chảo (vớt hết marinade bằng muỗng nhôm). Thêm đậu Hà Lan, xì dầu và nước dùng gà. Xào cho đến khi tôm hồng, khoảng 2 phút.", "Thêm hành lá và hoàn thành bằng dầu mè:", "Thêm hành lá và xào thêm 1 phút. Tắt bếp và thêm dầu mè. Trộn chung một lần nữa và phục vụ với cơm hấp."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1b1e3e80-d4bd-5c25-aab3-628d7a827eb1', '37b860de-aac4-5988-9271-8656fd005a7d', 10.0, 'ml'::public.quantity_unit);
