INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('30aa78b9-46b2-54b1-902b-986894af8275', 'Gà sốt chua ngọt (Sweet and Sour Chicken)', 'man'::public.dish_category, '["Bọc gà bằng lòng trắng trứng:", "Trong bát, trộn gà với lòng trắng trứng, 1/2 muỗng cà phê muối, và bột ngô. Khuấy để bọc gà đều. Để trong 15 phút ở nhiệt độ phòng hoặc qua đêm trong tủ lạnh.", "Làm sốt chua ngọt:", "Đánh trộn nước dứa, giấm, sốt cà chua, 1/2 muỗng cà phê muối, và đường nâu.", "Xào gà trên lửa cao:", "Đun chảo xào lớn trên lửa cao cho đến khi một giọt nước đục và bốc hơi ngay lập tức. Rồi 1 muỗng canh dầu nấu vào và xoay để phủ. Quan trọng là chảo phải rất nóng.", "Thêm gà và đống các miếng thành một lớp. Để gà chiên không chạm trong 1 phút, cho đến khi đáy vàng.", "Lật ngược lại và chiên mặt khác trong 1 phút. Gà nên vẫn hồng ở giữa. Đặt gà ra bát sạch, để càng nhiều dầu trong chảo càng tốt.", "Xào ớt chuông và gừng:", "Xoay lửa về vừa và thêm 1 muỗng cà phê dầu nấu còn lại. Để dầu nóng trước khi thêm các mảnh ớt chuông và gừng. Chiên trong 1 phút.", "Thêm dứa, sốt, và sau đó, gà:", "Thêm mảnh dứa và sốt chua ngọt. Xoay lửa lên cao. Khi sốt sôi, thêm các mảnh gà trở lại.", "Để ninh trong 1 đến 2 phút, cho đến khi gà chín qua. Thời gian phụ thuộc vào cách bạn đã cắt gà. Cách tốt nhất để biết gà đã chín là lấy một miếng ra và cắt vào. Nếu vẫn hồng, thêm một phút vào nấu.", "Điều chỉnh nems và phục vụ:", "Nếm sốt và thêm thêm đường nâu hoặc giấm cho phù hợp khẩu vị, nếu bạn muốn.", "Phục vụ nóng với cơm trắng hoặc gạo lứt hấp."]'::jsonb, 4);
