INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e95e15a9-960d-5b4b-9e4d-e50e233ce195', 'Cải thảo tôm khô Trung Quốc', 'man'::public.dish_category, '["Tôm khô tạo hương vị mặn umami cho món Trung Quốc này. Bạn có thể tìm thấy nó ở các cửa hàng châu Á trong phần đông hoặc tủ lạnh. Tìm tôm khô nhỏ, khoảng 0,6 cm. Nếu dùng tôm khô vừa hoặc lớn, ngâm tôm với nhiều nước hơn (240 ml cho tôm vừa, 300 ml cho tôm lớn) và trong thời gian dài hơn (45 đến 60 phút), rồi cắt thành những mảnh nhỏ 0,6 cm. Để làm món chay, bỏ tôm khô và dùng bốn đến năm nấm shiitake khô, đã ngâm và lát mỏng.", "Ngâm nở tôm khô:", "Cho tôm khô vào bát nhỏ và rót nước sôi qua. Phủ đĩa nhỏ và để 30 phút cho tôm ngâm nở. Tôm sẽ nhạt màu hơn và phồng nhẹ.", "Chuẩn bị cải thảo:", "Trong lúc đó, chia cải thảo nửa theo chiều dọc. Rửa cải và lắc khô. Cắt bỏ cuống cải và vứt đi.", "Sắp xếp hai bát lớn. Cắt phần cải còn lại thành từng miếng 2,5 cm, cho các phần trắng dày ở đáy cải vào một bát và phần lá xanh mỏng phía trên vào bát kia.", "Ráo tôm:", "Khi tôm đã ngâm nở, ráo và đổ bỏ nước.", "Nấu tôm và cải:", "Trong wok hoặc chảo lớn trên lửa lớn, cho dầu đậu phộng, xoay tròn để phủ chảo.", "Đun cho đến khi dầu trông nóng hổi, rồi cẩn thận thêm hành lá, gừng và tôm khô đã ngâm nở, chú ý vì nguyên liệu ẩm có thể làm dầu nóng bắn lên. Đảo bằng thìa cho đến khi hành lá xanh rực và hỗn hợp thơm mùi, khoảng 1 phút.", "Thêm phần trắng dày của cải thảo vào chảo và hạ lửa trung bình cao. Tiếp tục nấu và khuấy 3 đến 4 phút, hoặc cho đến khi viền các mảnh cải bắt đầu hơi trong nhưng phần giữa các mảnh cải vẫn trắng không trong.", "Hạ lửa trung bình thấp và thêm phần lá xanh của cải vào chảo. Nấu cho đến khi lá héo, khoảng 2 phút.", "Làm hồ năng:", "Trong bát nhỏ, trộn xì dầu, nước lạnh và bột bắp, khuấy tạo hồ. Rồi rót qua cải và tiếp tục nấu và khuấy cho đến khi sốt đặc nhẹ như độ đặc của sữa nguyên kem.", "Nems món xào:", "Nems món xào với muối và tiêu, rồi nếm và thêm thêm muối và tiêu nếu muốn. Cải sẽ trong và mờ như lụa, với chút tôm khô khắp nơi."]'::jsonb, 4);
