INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4ed3fadb-a8c0-5133-8c31-b4a743b1538f', 'Salad dưa leo mè (Sesame Cucumber Salad)', 'rau'::public.dish_category, '["Chuẩn bị dưa leo:", "Bóc vỏ dưa leo. Cắt chúng thành tư cột, dọc. (Nếu hạt khổ, lấy hạt ra và vứt đi.) Cắt dưa leo lại, ngang, thành miếng dày 1,25 cm.", "Trộn salad:", "Đặt dưa leo vào tô phục vụ. Rắc muối. Trộn với dầu mè, sốt giấm gạo, húng quế (nếu dùng), và ớt khô. Rắc hạt mè rang nếu dùng."]'::jsonb, 4);
