INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b3449337-2435-5747-b9bf-cb6f3839dc4a', 'Đậu cô ve dẹt nghiền (Runner Bean Mash)', 'rau'::public.dish_category, '["Rửa và cắt đậu cô ve dẹt. Cho vào nồi nhỏ với nước muối và đun sôi.", "Nấu đậu khoảng 10 phút cho đến khi vừa chín, còn dai một chút. Rarget nước và để riêng.", "Trong lúc đó, thêm khoai tây và nấu cho đến khi mềm.", "Đun nóng chảo nhỏ với một ít bơ và xào hành tây cho đến khi trong suốt. Thêm tỏi và nấu ngắn. Thêm đậu cô ve dẹt vào chảo và xào trong vài phút.", "Trong lúc đó, nghiền khoai tây bằng cụ nghiền. Thêm một miếng bơ và một chút sữa tươi. Thêm hỗn hợp đậu và phô mai nghiền. Nems muối, tiêu và mù tạt.", "Chiên thịt xông khói và phục vụ với đậu cô ve dẹt nghiền."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('b3449337-2435-5747-b9bf-cb6f3839dc4a', '2831e594-4210-5c6e-93f2-76eca3880bf2', 400.0, 'g'::public.quantity_unit);
