INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2cd03c18-b5f2-59b3-ac0f-b39cfa49afe7', 'Khoai tây nghiền táo kiểu Hà Lan (hete bliksem)', 'rau'::public.dish_category, '["Rửa và bóc vỏ khoai tây, cắt thành các khổ đồng đều. Luộc trong nước muối khoảng 10 phút, rồi thêm táo đã rửa và cắt nhỏ vào nước sôi. Thêm thanh quế. Luộc thêm 10 phút hoặc cho đến khi táo và khoai mềm theo ý thích. Tôi thích các khổ khá to, nhưng đó là sở thích cá nhân.", "Cùng lúc đó nướng thịt xông khói trong chảo khô cho đến khi giòn rồi để một bên và thoát dầu trên khăn giấy.", "Cắt một vài miếng táo và đun hóa một ít bơ trong chảo. Thêm miếng táo vào và thêm một ít siro cây phong cùng bột quế. Đun sôi nhẹ cho đến khi táo mềm.", "Chuẩn bị một đĩa với một quả trứng gà đã đánh tan và một đĩa với hạt mè. Cắt phô mai theo kích thước cần thiết. Càng nhỏ càng dễ xử lý.", "Nhúng phô mai vào trứng và đảm bảo phủ đều tất cả các mặt. Sau đó nhúng phô mai vào hạt mè và đảm bảo phủ kín khắp nơi.", "Đun chảo không dính trên lửa cao cho đến khi nóng. Đặt miếng phô mai vào và nướng cho đến khi hạt mè vàng. Bắt buộc làm nhanh hoặc phô mai sẽ tan hoàn toàn. Lật và nướng mặt kia.", "Lọc táo và khoai rồi nghiền chung với nhau. Nếm và thêm quế và muối nếu cần. Bớp thanh quế trước khi nghiền."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2cd03c18-b5f2-59b3-ac0f-b39cfa49afe7', 'bcbe1657-c16d-51a2-87b4-02fdd277c9f8', 250.0, 'g'::public.quantity_unit);
