INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d0c10ce6-eecf-5627-b173-30da099e71d6', 'Trái cây và hạt loại Afghanistan (Haft Mewa)', 'rau'::public.dish_category, '["Rửa quả mơ và cả hai loại nho khô và đặt vào bát - ngâm với nước lạnh đến 5cm trên các loại quả.", "Đặt óc chó, pistas và hạnh nhân vào một bát hoặc nồi khác và thêm nước sôi. Để ngâm, sau đó bóc tất cả vỏ khi chúng mềm. Đây là công việc hơi phiền và có thể mất thời gian - nhưng chắc chắn đáng làm! Đổ bỏ nước.", "Kết hợp các loại quả với các loại hạt và anh đào, kể cả nước chúng đã ngâm. Thêm nước hoa hồng, đậy hỗn hợp và để trong tủ lạnh nghỉ trong hai ngày. Khi bạn để hỗn hợp, nước sẽ trở nên ngọt và đặc như si-rơ, tạo nên độ đặc đặc biệt cho món ăn.", "Để ăn, dùng muỗng lấy trái cây, hạt và nước vào các bát hoặc cốc riêng lẻ, và thưởng thức!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d0c10ce6-eecf-5627-b173-30da099e71d6', '310a52cf-75d4-5fd7-971e-1f34e5c18b33', 110.0, 'g'::public.quantity_unit);
