INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('eeb586b8-8c77-5227-909f-ce2deb746066', 'Bí đỏ sốt sữa chua Afghanistan (Kadu Borani)', 'rau'::public.dish_category, '["Bóc bí đỏ và cắt thành các miếng rộng 1 cm. Chiên sâu trong dầu cho đến khi vàng và để một bên.", "Sử dụng cùng chảo và dầu, chiên sâu hành cho đến khi vàng. Lấy hành ra và nghiền với tỏi (nếu dùng sốt tỏi, trộn nó vào hành sau khi nghiền).", "Thêm một lượng nhỏ dầu vào chảo trên lửa vừa. Khi nóng, thêm nghệ. Trộn muối vào 240 ml nước và thêm nó vào nghệ. Thêm một lớp bí đỏ, rồi một lớp hành và tỏi. Lặp lại bước này cho đến khi bí đỏ, hành và tỏi đã được dùng hết.", "Thêm đường và 240 ml nước. Giảm lửa và nấu cho đến khi nước đã giảm.", "Thêm 1-2 muỗng canh sữa chua đã tan vào đĩa, thêm bí đỏ lên trên với một lớp sữa chua đã tan nữa. Cuối cùng, thêm một chút ớt xanh và ăn!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('eeb586b8-8c77-5227-909f-ce2deb746066', 'd92c1f73-564a-5fda-8a71-464baefa051d', 1.0, 'piece'::public.quantity_unit);
