INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8e838cdb-e626-5cc4-b3d9-6bafd2d33a66', 'Cơm cừu Mastawa', 'man'::public.dish_category, '["Cho thịt cừu cắt miếng vào chảo lớn với hành tây. Thêm nghệ và đủ nước ngập. Đun sôi rồi nấu nhẹ cho đến khi thịt rất mềm và dễ tách từ xương.", "Khi thịt đang nấu, cắt vỏ cam thành sợi mỏng, loại bỏ càng nhiều phần trắng càng tốt. Để ngâm trong bát nước.", "Khi thịt mềm, khoát ra khỏi chảo và khi nguội nắm tay được, xé thịt từ xương thành sợi bằng tay. Trả thịt vào chảo.", "Rửa gạo hạt ngắn rồi cho vào chảo với muối theo khẩu vị. Nước hầm thịt ngập gạo khoảng 2 cm, thêm nước nếu cần. Đun sôi lại, hạ lửa vừa, nấu không nắp, khuấy thỉnh thoảng cho đến khi gạo vừa chừ và nước cạn khô.", "Thêm sữa chua tự nhiên, khuấy kỹ nhưng cẩn thận. Chiên tép tỏi nghiền trong dầu và thêm vào món cùng với thì là, tiêu đen, đậu gà và thêm muối theo khẩu vị.", "Trộn đều, rồi phủ miệng chảo bằng khăn sạch dày và nắp. Để trên lửa nhỏ khoảng nửa giờ cho vị thấm.", "Thưởng thức với bánh nan ấm để thêm cảm thụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8e838cdb-e626-5cc4-b3d9-6bafd2d33a66', '53d68eb2-9589-5956-abbd-25c77ed291c9', 700.0, 'g'::public.quantity_unit);
