INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('595f6581-1864-5035-af8b-25628b8c8fbe', 'Bolani nhân khoai tây Afghanistan', 'rau'::public.dish_category, '["Đặt bột mì và một muỗng cà phê muối vào bát trộn. Rồi thêm nước cho đến khi đủ. Khuôn tạo thành hỗn hợp cứng.", "Đặt hỗn hợp lên bề mặt sạch và xoa uống khoảng 5-10 phút cho đến khi hỗn hợp co giãn, mịn và bóng. Tròn thành viên, bao bằng khăn ẩm và đặt một bên ít nhất nửa tiếng.", "Bóc và rửa khoai tây và luộc trong nước muối cho đến khi mềm. Lọc nước và nghiền kỹ. Thêm hành lá, muối và tiêu đen.", "Chia hỗn hợp thành 3 hoặc 4 viên. Trình mỗi viên mỏng càng tốt trên bề mặt đã bón nhẹ bột (dày không quá 1,5mm - nếu hỗn hợp quá dày bolani sẽ bị cứng)", "Dùng cutter tròn 13-15cm (Tôi thường dùng nắp chảo hoặc nắp nồi), và cắt càng nhiều vòng tròn có thể. Trên mỗi vòng tròn rải 1-2 muỗng canh khoai đã nghiền. Ẩm các cạnh của hỗn hợp, gấp lên và kín lại.", "Bolani nên được rải ra trên bề mặt đã bón nhẹ bột cho đến khi sẵn sàng chiên. Đun đủ dầu thực vật trong chảo chiên và chiên nhẹ một hoặc hai bolani mỗi lần, cho vàng hai bên.", "Đảm bảo giữ bolani đã chiên ấm cho đến khi hết, và phục vụ ngay lập tức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('595f6581-1864-5035-af8b-25628b8c8fbe', '7d6a1f7e-745c-5cd6-af33-19568749147f', 450.0, 'g'::public.quantity_unit);
