INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('595f6581-1864-5035-af8b-25628b8c8fbe', '536d44c3-0096-59d4-af3e-23452f94bdc8', 5.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0f140df9-2206-5329-a7b7-79abf2f3753f', 'Cừu hầm sữa chua kiểu Albania (Tavë Kosi)', 'man'::public.dish_category, '["Bước nướng cừu: Trong nồi lớn có nắp, đun bơ và dầu ô liu cùng rồi thêm cừu cắt nhỏ. Phi cừu trên lửa vừa khoảng 5 phút.", "Thêm tỏi, kinh giới cay, 300 ml nước và nêm muối cùng tiêu. Trộn đều trước khi đậy nắp. Hầm sôi nhẹ 50 phút, khuấy vài lần để tránh cừu cháy.", "Nước cốt hầu như đã cạn khô nên thêm thêm 150 ml nước cùng gạo. Trộn đều, đun sôi, đậy nắp và để chỉ 10 phút. Nên kiểm tra vào khoảng 8 phút – muốn nước cạn hầu hết chỉ còn lớp ẩm dầu trên cừu và gạo.", "Đặt cừu và gạo vào nồi hầm, hỗn hợp nên phủ đầy đáy và còn ít nhất 5 cm cho sữa chua. Hoặc chia thành bốn tô gốm.", "Bước làmroux: Trong nồi nhỏ đun bơ trên lửa vừa rồi thêm 2 muỗng canh bột mì, khuấy liên tục 2 phút (thêm ít bột nếu cần). Hỗn hợp không nên đặc quá cũng không loãng quá, màu sẽ tối nhẹ. Đổ vào tô và để một bên.", "Bước làm hỗn hợp sữa chua: Trong tô trộn cho sữa chua, trứng và nêm muối cùng tiêu. Trộn đều rồi thêm hỗn hợp bột bơ, khuấy nhanh trong 1 phút để đảm bảo trộn thật kỹ.", "Đổ hỗn hợp sữa chua lên cừu và gạo đã nướng và rắc chút kinh giới cay lên trên.", "Bước nướng: Đặt ở kệ dưới lò 180 độ trong 35 phút rồi chuyển lên kệ giữa thêm 10 phút. Món thành công khi sữa chua nở cao và vằn vàng hình thành.", "Để nguội 5 – 10 phút trước khi phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('0f140df9-2206-5329-a7b7-79abf2f3753f', '53d68eb2-9589-5956-abbd-25c77ed291c9', 600.0, 'g'::public.quantity_unit);
