INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9ee36eb2-02eb-5165-a129-9e60f384aa11', 'Món nướng tỏi tây không thịt (Tavë me Presh ska Mish)', 'rau'::public.dish_category, '["Bước chuẩn bị món: Chiên tỏi tây trong ít dầu ô liu vài phút cho đến khi bắt đầu vàng.", "Bước chuẩn bị hỗn hợp: Thêm ớt chuông đỏ đã nướng, tỏi, nước dùng, kinh giới cay, ngô tây, húng quế tây, muối, tiêu và paprika. Trộn đều, thêm gạo và trộn lại.", "Để sôi. Hầm sôi nhẹ 2 phút.", "Đổ hỗn hợp vào khay nướng cao ít nhất 5 cm. Trộn đều và đảm bảo bề mặt bằng phẳng.", "Bước nướng: Đặt vào lò đã đun ở 180 độ. Nướng trong 1 giờ.", "Bước đựng món: Khi đã nấu chín, tắt lò và để cửa lò mở, để món nướng tỏi tây nguội 10 phút trước khi phục vụ."]'::jsonb, 4);
