INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a6218130-632e-5db7-88fa-53d1042c5d97', 'Bánh bí đỏ mùa hè Albania (Lakror me Kungull Summer Squash Pie)', 'rau'::public.dish_category, '["1. Chuẩn bị:", "2. Trong một bát trộn trộn cùng bí đỏ mùa hè, đường, trứng gà và bột nở. Thêm bột mì và tiếp tục trộn, bạn đang tìm một hỗn hợp đặc và dính. Thêm thêm một chút bột mì nếu hỗn hợp vẫn mỏng và hơi chảy.", "3. Trong một khay nướng tròn lớn (khoảng 5 cm sâu) chà một chút dầu ô liu lên đáy và viền.", "4. Gắp hỗn hợp lên khay và trải ra đều, sau đó rót một lượng nhỏ dầu ô liu lên tay của bạn và chà nhẹ theo hình tròn lên trên hỗn hợp. Điều này sẽ dập nó xuống và để lại một bóng nhẹ nhàng.", "5. Nướng:", "6. Nướng trong lò trong 40 phút ở 180 độ – mặt trên nên là màu vàng nâu khi đã nấu.", "7. Để ăn:", "8. Để nguội trước khi cắt thành các hình vuông và ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a6218130-632e-5db7-88fa-53d1042c5d97', 'd92c1f73-564a-5fda-8a71-464baefa051d', 2.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a6218130-632e-5db7-88fa-53d1042c5d97', '8a301d33-ca8b-52a8-aa71-ca6feca05e46', 2.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a6218130-632e-5db7-88fa-53d1042c5d97', '6511004e-c078-51d9-90e7-492186b8e9c1', 300.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a6218130-632e-5db7-88fa-53d1042c5d97', '31aae023-31d6-5e9f-8b25-85f63f761312', 1.25, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a6218130-632e-5db7-88fa-53d1042c5d97', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 5.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('acf4a3a0-bd9c-5236-99f7-5426c46f79fd', 'Bánh mì Kulaç Albania (Kulaç Soda Bread)', 'rau'::public.dish_category, '["1. Chuẩn bị:", "2. Trên một khay nướng lớn hoặc một bề mặt làm việc sạch, trộn cùng các nguyên liệu khô - bột mì, bột nở và muối.", "3. Làm một giếng ở giữa và thêm sữa chua. Dùng tay của bạn chậm trộn các nguyên liệu cùng nhau để bắt đầu tạo thành bột.", "4. Nghiền bột trên một bề mặt đã rắc bột, thêm thêm bột mì nếu bạn thấy kết cấu quá dính. Bột đã sẵn sàng khi nó có kết cấu của bột pizza và vẫn hơi dính một chút, điều này chỉ nên mất vài phút.", "5. Trên một khay nướng thêm một chút dầu và đặt bột lên trên. Hình thành và dập bột thành hình tròn đảm bảo chiều cao của bột khoảng 5 cm.", "6. Phủ bột với một chút dầu ô liu, đảm bảo nó được phủ đầy đủ.", "7. Bạn có thể nướng Kulaç như nó là hoặc bạn có thể tạo các hình dạng cũng giúp nấu đều. Các hình dạng phổ biến nhất là sử dụng phần sau của một nĩa để nhấn nhẹ xuống tạo các vết rãnh khắp nơi hoặc chọc bột bằng nĩa.", "8. Nướng:", "9. Đặt trên kệ dưới của lò đã đun nóng. Nướng trong 40 phút hoặc cho đến khi bột vàng và chắc khi chạm.", "10. Làm nguội:", "11. Khi lấy ra khỏi lò, đứng thẳng hoặc đặt lên một giá làm nguội để cho Kulaç nguội.", "12. Để ăn:", "13. Cắt Kulaç như bạn cắt một bánh thành 8 lát. Nếu bạn đang ăn nóng bạn có thể muốn gãy và kéo bánh mì ra với tay của bạn thay thế."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('acf4a3a0-bd9c-5236-99f7-5426c46f79fd', '6511004e-c078-51d9-90e7-492186b8e9c1', 450.0, 'g'::public.quantity_unit);
