INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6b75329c-fa58-57a4-9b2b-001635a7eb48', 'Bánh nướng kỉara và gạo Albania', 'man'::public.dish_category, '["Đang nấu", "Chiên kỉara trong chút dầu ô liu vài phút cho đến khi bắt đầu vàng.", "Thêm hành tây và thịt xay và chiên cho đến khi mọi thứ vàng. Đảm bảo bạn giữ khuấy để ngăn kỉara dính và cháy.", "Thêm gạo và khuấy cùng nhau vài phút đảm bảo gạo được hòa tốt và phủ trong các loại nước mát.", "Thêm nước dùng cừu, muối và tiêu. Khuấy tốt và để đến khi đun sôi. Để sôi 2 phút.", "Nướng", "Rót hỗn hợp vào khay nướng lớn, đặt ở kệ dưới của lò đã đậy ở 180 độ. Để nướng tối đa 1 giờ. Món ăn sẵn sàng khi toàn bộ nước đã bay hơi và gạo mềm.", "Đặt ra", "Khi chín tắt lò và giữ cửa mở để bánh nướng kỉara và gạo nguội 10 phút trước khi dùng."]'::jsonb, 4);
