INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('97c20138-829e-5991-a890-7a122fdc72c1', 'Lá nho ngâm giấm nhồi thịt Dolma Japrak (Dolma Japrak Stuffed Vine Leaves)', 'rau'::public.dish_category, '["Chuẩn bị", "Thêm hành tây vào chảo xào và chiên trong 5 phút trong dầu ô liu cho đến khi hành tây bắt đầu nâu.", "Tắt lửa và thêm thịt cừu xay, gạo, tiêu đen hạt/bột, bột ớt ngọt Paprika, viên súp hầm rau củ quả, ngô tây và húng quế tây. Trộn tất cả nguyên liệu cùng nhau.", "Mở cẩn thận lá nho ngâm giấm. Đặt một lá nho trên tay của bạn với phần gốc ở dưới lòng bàn tay và phần nhọn chỉ lên trên. Thêm một lá nho thứ hai với phần nhọn pointing xuống và gốc của lá ở trên ngón tay của bạn. Nên có một lớp chồng đè tốt. Bạn có thể làm điều này trên một bề mặt phẳng nếu muốn.", "Đặt một thìa soupe của hỗn hợp thịt và gạo vào chính giữa các lá. Gấp phần dưới của lá lên trên hỗn hợp, gấp cả hai bên và cuộn lá lên phía trên kín hỗn hợp vào một hình gói.", "Lếp một lớp lá nho phủ đáy của một cái nồi sâu và sau đó thêm gói lá nho lên trên.", "Làm càng nhiều gói lá nho quanto hỗn hợp thịt và gạo sẽ tạo thêm mỗi cái vào nồi. Đặt các gói cạnh nhau cho đến khi nồi được bao phủ, sau đó bắt đầu một lớp khác ở trên.", "Nấu", "Đổ vào nồi đủ nước sôi để chỉ phủ phần trên của các lá nho và đun sôi. Để hầm với nắp trong 1.5 tiếng. Tất cả nước nên được hấp thụ nhưng hãy bổ sung thêm chút nước sôi nếu điều này xảy ra trước khi thời gian hết.", "Phục vụ", "Lấy ra khỏi nồi và để nguội trong 10 phút trước khi phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('97c20138-829e-5991-a890-7a122fdc72c1', '52dce710-5daf-57c6-b600-fe9a301a1b42', 600.0, 'g'::public.quantity_unit);
