INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7adc92da-df05-5aaf-b1cc-33e6bc5d9fa2', 'Hầm cải và thịt Albania (Lakra me Mish Cabbage and Meat Stew)', 'man'::public.dish_category, '["1. Nấu:", "2. Thêm một chút dầu ô liu vào chảo xào hoặc nồi (có nắp). Khi nóng thêm hành tây, bò đã cắt, ớt chuông đỏ và chiên trong 5 phút khuấy thỉnh thoảng. Thịt nên được vớn hoàn toàn.", "3. Thêm paprika, sốt cà chua, mảnh ớt và nems muối và tiêu. Trộn cùng nhau và tiếp tục chiên trong 2 phút.", "4. Thêm cải và khuấy hỗn hợp cùng nhau. Chiên hỗn hợp khi khuấy thỉnh thoảng trong 3-5 phút. Hầu hết dầu nên đã bay hơi.", "5. Rót nước sôi vào chảo, đảm bảo rằng mức nước hoàn toàn ngâm cải, cộng thêm khoảng 2,5 cm trên đó. Đậy nắp và đun sôi.", "6. Để hầm nhẹ trong 2,5 tiếng. Hầm đã sẵn sàng khi cải mềm và thịt mềm.", "7. Để ăn:", "8. Ăn vào các bát rộng và để nguội trong 5 phút."]'::jsonb, 4);
