INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('13ac126e-06f6-56d8-8752-41644c4b060b', 'Trinxat bắp cải và khoai tây nướng', 'man'::public.dish_category, '["Đun nước có muối sôi trong nồi lớn.", "Thêm bắp cải và khoai tây vào, nấu cho đến khi mềm khoảng 30-40 phút.", "Khi mềm, rổ nước thật tốt.", "Đặt rau trở lại nồi và bật bếp ở mức thấp. Để hơi.", "Cùng lúc, nấu thịt xông khói, giữ lại mỡ để chiên hash.", "Cắt thịt xông khói thành các mảnh nhỏ.", "Nghiền khoai tây và bắp cải bằng máy nghiền và thêm tỏi băm vào.", "Thêm muối và tiêu theo khẩu vị.", "Dùng khuôn cho mỗi phần ăn, ép hỗn hợp hash vào khuôn với thịt xông khói lên trên, chiên trong mỡ thịt xông khói đã giữ cho đến khi vàng nâu, lật lại và làm lại mặt bên kia.", "Lấy khỏi khuôn và trang trí với ngô tay cắt nhỏ.", "Nếu muốn làm một hash lớn, chỉ cần dùng chảo, ép hỗn hợp hash vào chảo với mảnh thịt xông khói và mỡ đã giữ, rồi lật lại một lần khi vàng nâu. Cắt thành các phần.", "Trang trí với ngô tay cắt nhỏ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('13ac126e-06f6-56d8-8752-41644c4b060b', 'aa6aa92a-7305-56f9-a580-8185600358a5', 0.5, 'piece'::public.quantity_unit);
