INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f76b200e-93d3-5d8f-bc9c-3ff03bc036ae', 'Bánh mì cà chua Andorra (Pa Amb Tomaquet)', 'rau'::public.dish_category, '["Nướng lát bánh mì -- trong máy nướng hoặc nướng trong lò 205°C -- cho đến khi giòn và vàng. (Thời gian nướng/nướng phụ thuộc hoàn toàn vào loại và độ dày bánh mì của bạn.)", "Lấy một tép tỏi và chà mặt cắt xuống trên bề mặt một lát bánh mì.", "Lấy nửa cà chua và chà mặt cắt xuống trên bề mặt bánh mì.", "Rưới dầu ô liu nhẹ lên bánh mì đều đặn. Rắc chút muối.", "Làm tương với các lát bánh mì còn lại. Sau đó dùng ngay khi chúng còn ấm ấm!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f76b200e-93d3-5d8f-bc9c-3ff03bc036ae', '9fe43610-47bc-5587-989c-c8735715e3d3', 2.0, 'piece'::public.quantity_unit);
