INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('43e36edd-8517-536b-afbe-5d43d306596f', 'Rau muống xào thịt heo băm, đậu nành lên men và tỏi (Cambodian Stir-fried Morning Glory with Pork, Fermented Soybeans, and Garlic)', 'man'::public.dish_category, '["Trong chảo lớn, đun nóng 1 muỗng canh dầu ăn trên lửa vừa. Khi dầu nóng, cho tỏi vào xào khoảng 30 giây, cho thơm nhưng đừng để cháy.", "Cho thịt heo băm vào chảo, dùng muỗng liếm bóp nhẹ. Xào cho đến khi thịt chín đều và vàng, khoảng 2-3 phút.", "Cho hạt đậu nành vào, nêm thêm 1 phút, khuấy trộn kỹ với thịt heo.", "Cho rau muống đã cắt vào, xào 2-3 phút để giữ màu xanh lá cây tươi và độ giòn.", "Kiểm tra nêm nếm, điều chỉnh với nước mắm hoặc đường nếu cần. Dùng ra đĩa ăn ngay với cơm nấu nóng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('43e36edd-8517-536b-afbe-5d43d306596f', 'e48d94ab-7c13-5049-89e1-c30dbe91bd4c', 1.0, 'piece'::public.quantity_unit);
