INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1821ec30-7b3c-5b14-a3cf-7f2107cb66f5', 'Cá chiên giòn với gừng và đậu nành lên men (Crispy fried fish with ginger and fermented soybeans)', 'man'::public.dish_category, '["Chiên gừng trong nhiều dầu cho đến khi vàng và hơi giòn. Đặt một bên để sau.", "Cắt cá thành sợi. Bóp cá trong một lớp rất mỏng của bột chiên giòn Tempura.", "Chiên cá trong nhiều dầu cho đến khi vàng nụi và giòn. Bạn có thể dùng cùng dầu bạn đã dùng để chiên gừng.", "N destroying tỏi và cắt nó thành các miếng nhỏ. Kẹo hành lá.", "Ráo hạt đậu nành bằng rổ ráo. Nếu bạn đang dùng đậu mặn (đậu nành trong sa sa rất mặn), bạn cần rửa đậu trong nước trước khi bạn thêm chúng vào món ăn.", "Thêm một thìa soupe dầu vào chảo sâu hoặc nồi lớn, và xào tỏi cho đến khi hơi vàng.", "Thêm hạt đậu nành và xào trong vài phút. Nếu hạt đậu nành rất mặn, thêm ¼- ½ thìa soupe đường để cân bằng hương vị.", "Thêm nước lọc và nấu trong một phút.", "Ngay trước khi phục vụ, khuấy vào gừng đã chiên, hành lá, và cá đã chiên giòn. Phục vụ với cơm nấu."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1821ec30-7b3c-5b14-a3cf-7f2107cb66f5', 'd53f6c80-8c7e-50fb-a58e-500d1e4e01c8', 480.0, 'ml'::public.quantity_unit);
