INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('75932acf-00ae-51a9-891d-2b8b2860341e', 'Bò luc lac', 'man'::public.dish_category, '["Chiên trứng sốt mais và đặt một bên. Băm nhuyễn tỏi. Rửa lá xà lách và để thoát nước tốt. Cắt lát mỏng hành tây và cà chua.", "Cắt thăn nội bò thành các khối 2–3 cm. Ướp với muối biển, đường thốt nốt, rượu nấu Trung Quốc, dầu hào, nước tương và dầu mè. Khuân tốt.", "Đun chảo chiên trên lửa cao với dầu nấu. Thêm tỏi đã cắt nhỏ và khuân cho đến khi tỏi hơi vàng. Thêm thịt bò đã ướp (với toàn bộ sốt ướp) và nấu 5–7 phút, tùy mức chín bạn muốn cho thịt bò.", "Rang khô tiêu đen Kampot trong chảo chiên trên lửa trung bình thấp trong 2–3 phút cho đến khi thơm. Xay tiêu đã rang, đặt vào bát, rồi thêm muối biển và nước cốt chanh xanh. Khuân tốt.", "Trên đĩa phục vụ, sắp xếp lớp xà lách, rồi lớp cà chua, rồi lớp hành tây. Đổ thịt bò đã nấu lên trên rau và đặt trứng chiên lên trên. Phục vụ với sốt tiêu Kampot và cơm hương thơm.", "Rang nóng và nhanh, lok lak tốt nhất khi thịt bò vẫn mềm và nhiều nước, với sốt chấm đậm đà, tươi sáng để cắt qua độ béo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('75932acf-00ae-51a9-891d-2b8b2860341e', '446ae650-eca1-5c1b-b6b9-f902078f2ac8', 1000.0, 'g'::public.quantity_unit);
