INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d998d5cf-f25f-5811-b1af-a954c2867357', 'Quả cầu gạo nếp Num E (Num E)', 'rau'::public.dish_category, '["Cho kem dừa vào nồi nhỏ trên lửa nhỏ. Cắt 3 lá dứa thành sợi lớn và thêm vào nồi cùng đường nâu, muối và gừng. Đun sôi, rồi nấu thêm 2 phút. Tắt bếp, lấy lá dứa ra và để nguội.", "Cắt phần 4 lá déra còn lại, xay với 1/4 chén nước cho đến khi rất xanh, rồi lọc thật tốt. Trong bát, cho 200 g bột nếp mịn, thêm chút nước lá dứa và nhéen cho đến khi mịn.", "Bóc và cắt củ dền, xay với 1/4 chén nước cho đến khi đỏ, rồi lọc thật tốt. Trong bát, cho 200 g bột nếp mịn, thêm chút nước củ dền và nhéen cho đến khi mịn.", "Đun sôi 3 lít nước trong nồi vừa-lớn. Chia mỗi bột thành các miếng nhỏ, cuộn thành quả khoảng 1/3 kích thước bóng bàn tenis, rồi thả vào nước sôi. Khi chúng nổi, vớt ra và đặt vào nước đá tươi để giữ chúng riêng.", "Ráo thật tốt, rồi đặt các quả màu trộn vào siro đường dừa đã nguội và khuấy. Dùng trong bát nhỏ (thêm nhãn và dừa xé sợi theo ý muốn).", "Thêm các loại nước sắc dần dần—mỗi loại bột hấp thụ khác nhau. Bạn muốn một loại bột mịn và đàn hồi, không dính tay."]'::jsonb, 4);
