INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fe1b97d6-395e-5675-8c4c-0b56a12c6a26', 'Salad Meang Nem (Meang Nem)', 'man'::public.dish_category, '["Rửa gạo, ngâm trong nước khoảng 10 phút, rồi ráo tốt. Đun nóng wok hoặc chảo lớn trên lửa vừa. Cho gạo vào và khuấy liên tục cho đến khi均匀 vàng đậm và rất thơm, khoảng 5 phút. Đưa vào bát để nguội. Nghiền mịn bằng máy nghiền gia vị hoặc cối chùi, rồi lách qua lưới mịn để loại bỏ các mảnh lớn. Để riêng.", "Cắt hành tím thành lát mỏng theo chiều dọc. Băm nhuyễn củ riềng, đầu hành ngâm chua, ớt và vỏ cam bào. Nghiền thô đậu phộng rang. Đun chảo trên lửa thấp, cho dừa xé sợi vào và rang với khuấy 2-3 phút. Để riêng.", "Trong bát lớn, trộn nước cốt chanh xanh, nước cam, đường thốt nốt, nước muối ngâm hành và nước mắm. Khuấy cho đến khi hoàn toàn tan và trộn đều.", "Trong bát trộn, trộn tôm khô, dừa rang, gia vị đã băm và nước sốt. Trộn đều. Thêm bột gạo rang và khuấy lại. Rắc đậu phộng rang nghiền thô lên trên.", "Đặt salad vào đĩa lớn. Mỗi khách đỗn một chút vào bát nhỏ của mình, cuộn trong lá xanh cùng rau và thưởng thức bằng từng miếng vừa ăn.", "Cho phiên bản chay, bỏ tôm khô và nước mắm. Nems theo khẩu vị với xì dầu và một chút muối biển, giữ cân bằng ngọt chua."]'::jsonb, 4);
