INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d07cad29-b790-504a-8a82-312edb829d5b', 'Cải chua Som Pak (Som Pak)', 'rau'::public.dish_category, '["Cắt cải bắp và cắt thành từng miếng 2,5 cm.", "Cho cải bắp vào bát lớn và thêm nước lạnh để rửa.", "Rửa cải bắp. Rửa và ráo ba lần.", "Trong bát sạch lớn, rót nước lọc vào.", "Cho cải bắp và hành lá vào hỗn hợp nước muối.", "Thêm muối."]'::jsonb, 4);
