INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('63ac1cfa-760b-56a1-9c4c-68f792552c8d', 'Naem Khao Lào (Lao Naem Khao)', 'man'::public.dish_category, '["Cắt hành tây và hành tím thành lát mỏng. Ngâm trong bát nước đá khi chuẩn bị các món còn lại.", "C ür cả dừa. Cho vào bát lớn.", "Cho dừa vào bát lớn. Cho gạo. Dùng tay, trộn dừa và gạo với nhau.", "Cuộn hỗn hợp thành bánh gạo hình quả cầu dài 5 cm.", "Đun nóng dầu ăn trong nồi hoặc chảo.", "Đập hai quả trứng vào một cái bát lớn, đánh tan. Nhúng các quả bánh vào hỗn hợp trứng. Sau đó thả các quả vào dầu nấu.", "Để các quả chuyển màu vàng đậm. Chiên đều cho đến khi giòn, rất giòn và vàng. Rớt ra, đặt trên khăn giấy để ráo dầu thừa.", "Khi đã nguội, bóp nát các quả bánh gạo và cho vào bát lớn hơn.", "Ráo hành tây và hành tím.", "Làm cho chắc xé xúc xích heo thành từng miếng nhỏ. Có thể dùng dao, nhưng phương pháp truyền thống là xé.", "Trong bát lớn, thêm hành tây, hành tím, xúc xích heo chua, tỏi ngâm chua, nước cốt chanh xanh, nước mắm, đường, ngò rí, bạc hà cay, bạc hà.", "Rắc đậu phộng rang lên trên. Ăn kèm xà lách, ớt khô và các loại rau tươi khác.", "Cách bảo quản Naem Khao", "Naem Khao có thể bảo quản trong tủ lạnh 4 ngày. Sau đó có thể dùng lạnh.", "Không được đông lạnh.", "Cách ăn Naem Khao", "Nam Khao thường ăn kèm lá xà lách và nhiều loại thảo mộc khác như bạc hà cay, bạc hà, húng quế, và tía tô."]'::jsonb, 4);
