INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('eafb0a1c-29e6-53cc-9a08-6b0a184dc40a', 'Tôm nướng sốt hành lá Angola', 'man'::public.dish_category, '["Làm sốt bằng cách trộn tất cả các nguyên liệu và xay nhuyễn thành hỗn hợp đặc.", "Đặt tôm lên xiên và rưới sốt lên trên.", "Nướng cho đến khi chín (chúng sẽ mất màu trong suốt), khoảng 3-4 phút mỗi mặt.", "Phục vụ với sốt thêm ở bên."]'::jsonb, 4);
