INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e3587538-ee2e-5051-9256-e5d355b90bc3', 'Xoài trộn Mango chow', 'rau'::public.dish_category, '["Trộn tất cả nguyên liệu trong một bát và ăn kèm với mọi món."]'::jsonb, 4);
