INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e263c9a3-ade4-5aca-9d0c-1c2c981aa0e7', 'Bánh Koulenje Armenia (Koulenje)', 'rau'::public.dish_category, '["Rắc bột mì, bột nở, muối, và đường cùng nhau. Trong một bát riêng, đánh 6 trứng gà, rồi trộn với bơ và sữa.", "Rắc một muỗng canh sev dzandig (hạt đen) và tất cả mahleb lên trên các nguyên liệu khô. Làm một lỗ ở giữa các nguyên liệu khô và đổ nguyên liệu ướt vào cùng một lúc, khuấy vài nét cho đến khi bột có thể đảo ra trên một tấm thớ đã rắc bột. Thêm thêm bột mì nếu cần; nó không nên quá dính.", "Nghiền hỗn hợp nhẹ nhàng, chỉ vài lần, rồi keo giãn nó cho đến khi dày 1,2 cm. Cắt nó thành các hình hình thoi, vòng tròn, hoặc các sợi dài có thể cuộn và vằn thành các bo bánh mì. Chọc từng miếng vài lần với một nĩa.", "Đánh trứng gà thứ bảy với thêm sev dzandig (hạt đen) được thêm vào. Mở men này lên từng miếng koulenje và đặt trên khay bánh có lót giấy nướng.", "Nướng ở 200°C trong 12-15 phút cho đến khi hơi vàng. Để nguội trên giá. Những món này ngon nhất khi ăn nóng. Bạn có thể hâm nóng chúng bằng cách gói trong giấy bạc."]'::jsonb, 4);
