INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0af247b7-c0f5-5ca4-9841-ba743e9caa2b', 'Lá nho nhồi (Stuffed Grape Leaves)', 'rau'::public.dish_category, '["Rửa gạo trong nước lạnh cho đến khi nước trong.", "Xào hành tây trong dầu ô liu cho đến khi mềm.", "Thêm gia vị và khuấy cho đến khi thơm.", "Thêm các thành phần còn lại.", "Đun cho sôi nhẹ, rồi ninh trong 30 phút cho đến khi hết nước dùng và gạo mềm.", "Phục vụ như món phụ hoặc nhân cho dolmas."]'::jsonb, 4);
