INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f905e827-5f79-5d42-9a39-89066781546b', 'Sốt sữa chua dừa Armenia (Jajek)', 'rau'::public.dish_category, '["Đặt sữa chua, nước, tỏi và muối vào máy xay và xay trong vài giây. Chuyển vào bát và trộn với bạc hà và dưa leo. Thường ăn lạnh trong vài giờ.", "Khi ăn, thêm một vài tảng đá để tăng thêm sự tươi mát! Làm khoảng bốn phần."]'::jsonb, 4);
