INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('bed9cd06-55c4-5cba-b899-c36bee5f813d', 'Đùi cừu nướng kiểu Armenia', 'man'::public.dish_category, '["Cho tất cả nguyên liệu trên vào nồi nướng ít nhất hai ngày trước khi ăn. Khuấy thỉnh thoảng trong những ngày đó để marinade lan đều. Nướng lò 175°C một giờ đến một giờ nửa cho đến khi thịt cắt ra không còn đỏ.", "Cũng có thể nướng trên xiên nếu muốn xắn thịt cùng các loại rau khác rồi nướng. Có thể đông lạnh."]'::jsonb, 4);
