INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1037b38c-74fc-5ff5-bbae-2a7740d2334e', 'Bánh arepa (arepa)', 'rau'::public.dish_category, '["Đặt bột ngô vào bát và thêm nước muối ấm dần dần, trộn với bột cho đến khi hết nước và bột trở thành hỗn hợp. Để nghỉ năm phút. Bây giờ định hình hỗn hợp thành các bánh tròn khoảng 3 inch đường kính và 1/2 inch dày. Trong chảo đã nhẹ nhàng bơ, nấu chậm các bánh arepa cho đến khi có lớp vỏ mỗi bên. Rồi đặt chúng vào nồi và nướng trong lò ở 175°C trong khoảng 20 phút, cho đến khi các bánh arepa nghe tiếng rỗng khi nhẹ nhàng gõ.", "Để tăng hương vị: thay vì chỉ dùng nước, hãy dùng nước dùng gà hoặc bò."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1037b38c-74fc-5ff5-bbae-2a7740d2334e', '1aac59db-1947-5be3-926e-dc730387fc63', 5.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1037b38c-74fc-5ff5-bbae-2a7740d2334e', '12fe5889-1eaf-59e9-b1ea-7748e8c37010', 240.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1037b38c-74fc-5ff5-bbae-2a7740d2334e', '1eb578e9-212c-5483-b32a-79a2865ea699', 300.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('75635bd8-be9b-540a-9dc5-d7e773a2e37c', 'Bánh cá balchi di pisca', 'man'::public.dish_category, '["Các bánh cá ngon này cũng có thể làm bằng cá hồi hoặc phi lê cá. Thay thế một hộp cá hồi lớn hoặc 450 g cá trắng cho cá tuyết.", "Ngâm trong hai mươi bốn giờ:", "1 cá tuyết muối, hoặc bakijow. Xé bỏ nước.", "Đặt cá tuyết vào nồi với nước tươi ngập. Đun sôi nhẹ cho đến khi cá xùi dễ dàng khi kiểm tra bằng răng nĩa. Lọc, giữ lại một chút nước dùng. Cách xương cá và đặt một bên để dùng sau. Trong nồi, đun sôi nước tươi ngập: 3 khoai tây vừa, bóc vỏ và cắt khối. Khi khoai mềm, để thoát nước tốt. Thêm cá tuyết và nghiền hai nguyên liệu cùng nhau.", "Đặt vào bình xay điện:", "1 cà chua, bóc vỏ và cắt nhỏ", "1/2 ớt chuông xanh, cắt nhỏ", "1 hành tây vừa, bóc vỏ và cắt nhỏ", "1 tép tỏi, cắt mảnh", "1/2 muỗng cà phê sốt Tabasco, hoặc ớt cay đã băm", "Một chút nhục đậu khấu", "Muối và tiêu vừa đủ", "Xay trong vài giây và đổ sốt lên hỗn hợp cá đã nghiền. Trộn các nguyên liệu tốt và thêm 1 trứng đã đánh tan. Hỗn hợp nên đủ cứng để định hình thành các bánh khoảng 1,5 inch đường kính. Nếu quá khô, thêm nước dùng cá từng muỗng canh. Chiên các bánh trong chất béo nóng cho đến khi vàng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('75635bd8-be9b-540a-9dc5-d7e773a2e37c', '8c42b1a4-d98a-5ef8-bea9-023e120b7eca', 1.0, 'piece'::public.quantity_unit);
