INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('05efbf10-afc6-5eda-b19b-e5e457776b70', 'Que phô mai chiên (Cheese Sticks)', 'rau'::public.dish_category, '["Cắt phô mai Mozzarella thành sợi dài và đặt vào tủ lạnh để ngăn nó bị mềm. Trộn bột mì, bơ và trứng gà trong một bát, và thêm đường, muối và dầu ô liu theo khẩu vị vào hỗn hợp. Sau đó thêm dần sữa tươi và xên tốt cho độ sánh phù hợp.", "Lăn bột bằng thanh lăn bột và cắt thành sợi dài (2 đến 3 cm) và sau đó cuộn sợi bột quanh sợi phô mai tạo thành xoắn ốc. Đảm bảo bột bọc phô mai hoàn toàn để nó không nở ra khi chiên. Lăn sợi phô mai và bột qua bột mì để ngăn chúng dính khi chiên. Đun nóng dầu ăn trong chảo chiên cho đến khi nóng trước khi đặt que phô mai, và chiên cho đến khi vàng màu."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('05efbf10-afc6-5eda-b19b-e5e457776b70', '6511004e-c078-51d9-90e7-492186b8e9c1', 240.0, 'ml'::public.quantity_unit);
