INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c613edd2-4d34-58e8-bd9e-c5ae52c6cceb', 'Sate nướng (Satee)', 'man'::public.dish_category, '["Để làm nước ướp cho satee, cho vào bình máy xay điện:", "1 lá hành tây, cắt thô 2 tép tỏi", "Nước cốt 2 quả chanh", "2 muỗng canh đường 240 ml xì dầu", "1 muỗng cà phê muối 1 muỗng cà phê ngò rí bột cho bò (hoặc gà) hoặc 1 muỗng cà phê gừng bột cho heo", "240 ml dầu", "Xay nhuyễn và đổ qua:", "2250 g thịt bò hoặc heo nui, cắt thành khối", "KHÔNG ngâm qua đêm, chỉ ngâm vài giờ.", "Xếp thịt lên: 36 xiên", "Xay nhuyễn:", "240 ml dầu", "2 muỗng canh xì dầu", "Đổ vào chiếc đĩa lớn.", "Để thịt không khô, cuộn mỗi xiên trong sốt gia vị trước khi chiên.", "Satee cũng rất ngon khi nướng n than."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c613edd2-4d34-58e8-bd9e-c5ae52c6cceb', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 1.0, 'piece'::public.quantity_unit);
