INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0faef185-6019-52f9-a9f3-9cbf611627e5', 'Bánh nặn kiểu Tirol', 'man'::public.dish_category, '["Cắt nhỏ hành tím và cắt giăm bông hun khói hoặc xúc xích thành các khối nhỏ. Đun nóng bơ hoặc bơ tinh khiết trong chảo và hẹn hành tím trong đó cho đến khi trong suốt. Thêm thịt và ngô tay và chiên cùng nhau nhanh trước khi lấy khỏi lửa.", "Cho bánh mì vào tô. Đánh trộn sữa tươi với trứng và nêm nếp đặn với muối, tiêu và nhục đậu khấu. Đổ lên bánh mì. Khuấy hỗn hợp xúc xích và hành cùng bột mì vào. Trộn đều tạo thành hỗn hợp tương đối đặc (thêm bánh mì hoặc bột mì nếu cần) và nêm nếm lại theo khẩu vị. Làm phẳng bề mặt bột và để khoảng 30 phút.", "Đun nóng lượng nước có muối đủ dùng trong nồi lớn. Dùng hỗn hợp để tạo các bánh nặn nhỏ (dùng làm trang trí trong canh) hoặc bánh nặn vừa, tùy yêu cầu. Ướt tay thường xuyên bằng nước lạnh trong giai đoạn này để bánh nặn có hình dạng trơn nhẵn.", "Cho vào nước sôi, đun sôi lại, giảm lửa và hầm sôi nhẹ 8-20 phút, tùy theo kích thước.", "Lấy ra khỏi nước, khô thật tốt và dùng rắc ngô tay cắt nhỏ và bơ đã nung (màu nâu hạt)."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('0faef185-6019-52f9-a9f3-9cbf611627e5', '9fe43610-47bc-5587-989c-c8735715e3d3', 200.0, 'g'::public.quantity_unit);
