INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('aefa447d-0a35-5834-a425-fab79336c9ae', 'Bánh nướng phô mai Áo (Kaspressknödel - Cheese Dumplings)', 'rau'::public.dish_category, '["Trộn bánh mì trắng đã cắt khối với sữa, nêm muối, và để hỗn hợp nghỉ một lúc.", "Bây giờ thêm khoai tây đã xay, phô mai đã xay, trứng gà, và ngô tay.", "Cho bơ vào và chiên hành đã cắt khối cho đến khi vàng nâu và thêm vào hỗn hợp.", "Thêm bột mì và nhẹ nhàng nghiền bột. Hình thành các bánh tròn, dập nhẹ chúng và chiên cả hai bên trong bơ cho đến khi vàng nâu.", "Ăn trong nước dùng trong sáng."]'::jsonb, 4);
