INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c8fc3335-3e9c-5ade-95ed-21bf5e8e622c', 'Bò luộc kiểu Áo (Tafelspitz)', 'man'::public.dish_category, '["Cắt đôi hành tây không bóc sẹo theo chiều ngang, chiên các bề mặt cắt không cần thêm béo cho đến khi vàng đều.", "Đun sôi khoảng 3 lít nước trong nồi lớn. Thêm các loại củ cải, tỏi tây, nửa trái hành, lá nguyệt quế, hạt tiêu đen, đun sôi. Thêm thịt và xương đã rửa, tùy theo loại thịt, hầm trong nước sôi nhẹ cho đến khi mềm, mất khoảng 2,5 – 3 giờ. Thêm nước nếu cần và bỏ bọt trên bề mặt.", "Nêm muối đặn, nhưng chỉ sau khoảng 2 giờ.", "Khi thịt đã mềm, lấy ra khỏi nồi và giữ ấm trong chút nước canh. Nêm lại phần canh còn lại bằng muối theo khẩu vị rồi lọc (tùy chọn). Dùng kèm bánh từ bột mì lúa mì hoặc \"Frittaten\" (lát bánh xốp – món đi kèm canh truyền thống của Áo) và ngò tây cắt tinh như món khai vị. Sau đó, lát thịt bò luộc cắt chéo và xếp trên đĩa đã hâm nóng, hoặc dùng trong canh nóng trong bát canh trang trí.", "Dùng kèm khoai tây nướng, hỗn hợp bánh mì và củ cải ngựa, đậu que xanh trong sốt ngò thì là, hoặc cải xôi trộn phô mai và sốt ngô tay. Nếu các loại củ cải được dùng cùng lúc, hãy nấu một phần riêng để ăn vẫn còn giòn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c8fc3335-3e9c-5ade-95ed-21bf5e8e622c', 'c9a85c2e-12a8-501d-8172-b731d9ed81b6', 1500.0, 'g'::public.quantity_unit);
