INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2dafe0ad-53a2-52d2-b0e2-0b9d005075fc', 'Bánh nướng Tendir Choreyi kiểu Azerbaijan (Tendir Choreyi)', 'rau'::public.dish_category, '["Lưu ý về bánh nướng tendir (tandoori): tên gọi từ lò đất chamada tandoor, truyền thống dùng để nướng. Không có lò tandoor thì khó đạt hương vị gốc, nên món này nướng trong lò thông thường. Đây là cách người Azerbaijan làm bánh tendir khi không có lò tandoor.", "Nguyên liệu bánh này tương tự bánh mì Pháp cơ bản, nhưng hình dạng khác và rải hạt anh túc trên bề mặt làm bánh đẹp mắt. Đây có lẽ là món đẹp nhất tôi từng nướng.", "Như mọi lần tôi dùng máy làm bánh, nhưng lần này không men nở men trước. Tôi chỉ đặt vào bình đựng men ở đầu máy, rồi thêm nước, bột mì và muối vào thùng. Tôi chọn chương trình làm bột rồi đi đón con từ trường.", "Bánh này dùng nguyên liệu cơ bản, gồm bột mì và muối.", "Nếu muốn làm theo cách thủ công: Trộn men với nước và để vài phút. Sau đó cho bột mì và muối vào bát lớn. Dan dần thêm nước và men, trộn bằng tay cho đến khi bột thành viên.", "Tháo bột ra bề mặt đã rắc ít bột mì. Cuộn bột 8 đến 10 phút, hoặc cho đến khi mịn. Đặt vào bát lớn, đậy, rồi để men nở ở nơi ấm cho đến khi tăng gấp đôi (thường mất 1 đến 1,5 giờ).", "Bột sau khi đã men nở.", "Để bột phồng xuống và tháo ra bề mặt đã rắc ít bột mì. Dãn bột thành hình dài oval, rồi dùng láp cuộn bột cuộn đến dày khoảng 1,2 cm. Chuyển ra khay nướng đã bớt dầu hoặc không dính và để thêm 15 phút.", "Sau khi dãn và cuộn, bột của bạn hình thành dạng này.", "Cắt các đường kẻ xuyên nhau trên mặt bột, khoảng bốn đường mỗi chiều. Chọc lòng đỏ trứng đã đánh chung (trộn với ít nước để dễ dùng) và rải hạt anh túc.", "Các đường kẻ, nước khoán trứng và hạt anh túc tạo nên vẻ đặc trưng cho bánh.", "Nướng trong lò đã đun khoảng 200 độ trong 20 đến 25 phút, cho đến khi vàng trên mặt."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('2dafe0ad-53a2-52d2-b0e2-0b9d005075fc', '72402080-cec2-5ab8-a324-5717a41e779c', 12.5, 'ml'::public.quantity_unit);
