INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('58410c1a-dc85-54e3-9dba-fe2d9018bfdd', 'Cá nấu cà ri củ cải trắng kiểu Bangladesh', 'man'::public.dish_category, '["Nếu bạn sử dụng cá rohu thì thường đã đông lạnh. Ngâm trong nước lạnh 30-45 phút để đông cạn và khi vẫn hơi chắc, bóc vảy và cắt mỗi miếng thành tư phần và rửa trong nước muối lạnh vài lần. Để thoát nước và bỏ một bên. Nếu sử dụng thay thế như cá tuyết, cắt thành các khối 2,5 inch rồi rửa, để thoát nước và bỏ một bên.", "Cắt hai đầu củ cải trắng và bóc vỏ bằng máy bóc khoai tây. Cắt nửa theo chiều ngang rồi cắt mỗi nửa xuống giữa theo chiều dọc. Bây giờ cắt thành các miếng nửa trăng dày 2cm. Rửa và bỏ một bên.", "Đặt nồi lớn trên lửa trung bình và thêm dầu. Khi dầu nóng thêm tỏi đã nghiền và khuân một phút cho đến khi vàng nhạt.", "Thêm hỗn hợp hành và muối và nấu 3-5 phút, cho đến khi hành mềm và trong suốt, khuân đôi khi", "Đổ 200 ml nước rồi đậy nắp và nấu 10 phút, khuân một hay hai lần", "Sau 10 phút thêm gia vị đã xay và khuân vài phút cho đến khi gia vị chín qua. Đậy nắp và nấu 5 phút trên lửa nhỏ rồi khuân củ cải trắng vào. Sau khoảng một phút thêm 200 ml nước. Đậy nắp và nấu 10 phút trên lửa trung bình", "Thêm các miếng cá vào chảo và trộn kỹ cho đến khi cá được phủ bởi gia vị. Lắc nhẹ chảo và đậy nắp và nấu 5 phút trên lửa trung bình. Rất quan trọng là không khuân nồi sau giai đoạn này", "Cùng lúc đó, đun sôi ít nước. Sau khi 5 phút kết thúc cẩn thận đổ 500 ml nước nóng vào chảo. Khi làm điều này hãy đổ vào các bên chảo để không đổ nước sôi trực tiếp lên cá", "Lắc nhẹ chảo rồi đậy nắp và đun sôi nhẹ trên lửa lớn 15 phút. Thêm ngò rí đã cắt nhỏ và ớt và tiếp tục nấu thêm 5 phút rồi tắt bếp. Phục vụ ngay với cơm và các miếng chanh xanh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('58410c1a-dc85-54e3-9dba-fe2d9018bfdd', '899ea84f-dd81-5f70-8275-deb44df8b7c5', 450.0, 'g'::public.quantity_unit);
