INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6b9e6e64-2dfb-5ed5-a0e6-254c9473f73e', 'Cà ri gà Bengal với khoai tây', 'man'::public.dish_category, '["Đun dầu ô liu trong chảo lớn trên lửa trung bình cao. Nấu khuân hành trong dầu nóng cho đến khi hành trong suốt, khoảng 5 phút. Thêm hỗn hợp gừng tỏi đã nghiền và tiếp tục nấu thêm 5 phút. Giảm lửa xuống trung bình; khuân cà chua vào hỗn hợp và nấu cho đến khi cà chua men men, 5 đến 10 phút. Nems ớt bột cayenne, cà ri, garam masala, nghệ và cumin; nấu khuân thêm 5 phút.", "Thêm gà và khoai tây vào hỗn hợp trong chảo; hầm nhẹ, khuân đôi khi, cho đến khi khoai mềm và gà không còn màu hồng ở giữa, khoảng 20 phút. Rắc ngò rí vào hỗn hợp và tiếp tục hầm thêm 10 phút. Phục vụ nóng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6b9e6e64-2dfb-5ed5-a0e6-254c9473f73e', '0a034779-ab6b-5cb4-b1c3-cee1fd1092f9', 30.0, 'ml'::public.quantity_unit);
