INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('74661146-a297-5739-b520-7d8994785c70', 'Gan gà pâté (Chicken Liver Pate Recipe)', 'man'::public.dish_category, '["Vệ sinh gan gà khỏi dây thần kinh và mật.", "Cho vào nồi nấu cùng các nguyên liệu khác đã kẹo thô.", "Nêm và đậy bằng sữa tươi.", "Đậy nắp nồi và nấu trong lò chậm (150°C) trong 2 giờ.", "Xay nhuyễn trong máy xén.", "Điều chỉnh nêm nếm.", "Thêm rượu Sherry hoặc brandy.", "Đặt vào đĩa và đậy bằng bơ đã nung"]'::jsonb, 4);
