INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('655778c9-e255-57a6-8478-c72f98a64a24', 'Bánh mì muối Barbados', 'rau'::public.dish_category, '["Rây nửa bột mì, trộn với muối và men nở trong bát trộn lớn, rồi thêm nước ấm dần dần cho đến khi hỗn hợp tạo thành bột cứng. Thêm bột đã rây thêm cho đến khi có bột đủ cứng để xoa uống.", "Bón nhẹ bột lên bề mặt làm việc, xoa uống bột 10 phút cho đến khi mịn và co giãn, rồi đặt vào bát đã bơ. Đặt bát ở nơi ấm 40-50 phút cho đến khi bột dội đôi. Bạn biết bột đã sẵn sàng khi đốt một ngón tay và sự lún vẫn còn.", "Đun lò đến 220°C.", "Bây giờ chia bột thành 12 phần bằng nhau, tròn mỗi phần thành viên nắm tay, và đặt trên khay nướng đã bơ. Bây giờ đặt lại ở nơi ấm thêm 40 phút hoặc cho đến khi bột dội đôi kích thước.", "Bây giờ đặt vào giữa lò và nướng 25-30 phút cho đến khi các bánh vàng giòn và nghe tiếng rỗng khi nhẹ nhàng gõ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('655778c9-e255-57a6-8478-c72f98a64a24', '72402080-cec2-5ab8-a324-5717a41e779c', 2.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('655778c9-e255-57a6-8478-c72f98a64a24', '11a0cbfb-93b7-5aa5-b933-be65fa2e39bc', 10.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('655778c9-e255-57a6-8478-c72f98a64a24', '1aac59db-1947-5be3-926e-dc730387fc63', 5.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('655778c9-e255-57a6-8478-c72f98a64a24', '41e2849c-302d-5cf6-9f07-ca579b4604a3', 30.0, 'ml'::public.quantity_unit);
