INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('655778c9-e255-57a6-8478-c72f98a64a24', '1eb578e9-212c-5483-b32a-79a2865ea699', 600.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ce73c72c-cd24-57bd-aa89-366fd4390db9', 'Cháo đậm vị Barbados', 'man'::public.dish_category, '["Rửa miếng bò hầm và đặt vào bát trộn với nước chanh vàng hoặc chanh xanh.", "Đặt một bên; trong khi đó cắt tỏi thành các lát nhỏ, cắt hành tây. Cắt nhỏ húng quế tây và xạ hương.", "Bây giờ bạn cần phải rất cẩn thận khi cắt ớt scotch bonnet; bạn muốn các miếng nhỏ, có thể làm bằng dao dài cố gắng không chạm ớt, hoặc bạn có thể đeo găng tay cao su để cắt. Rửa tay ngay sau đó và đừng chạm vào mắt; các loại ớt này thực sự đ거운 tay và mắt nếu chúng tiếp xúc với da!", "Bây giờ rửa nước chanh hoặc chanh vàng khỏi miếng bò hầm. Và cắt thịt thành các khối.", "Ngoài ra, cắt móng heo và đuôi bò thành các khối.", "Đổ đầy nồi lớn bằng nước và đun sôi.", "Thêm móng heo.", "Khi móng heo đã sôi, xé thoát nước dư, và bây giờ thêm miếng bò hầm và ngập với nước nóng tươi.", "Bây giờ thêm tỏi, hành tây và ớt đã cắt nhỏ của bạn.", "Bây giờ thêm thanh quế, đinh hương, húng quế tây và xạ hương cùng một chút muối và đường vừa đủ.", "Bây giờ hầm nhẹ cho đến khi thịt mềm. Hương vị của món này tỏ ra trong vài ngày và do đó càng ngon mỗi lần bạn đun lại; hãy đảm bảo bạn luôn đun lại toàn bộ nồi đến điểm sôi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('ce73c72c-cd24-57bd-aa89-366fd4390db9', 'a229cbc1-b981-5972-8a85-f366457c475e', 2.0, 'piece'::public.quantity_unit);
