INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('23153ef9-ec38-5f2a-8bfa-7028e2184d4f', 'Mít nướng sốt bơ Barbados', 'rau'::public.dish_category, '["Cắt mít, loại bỏ hạt ở lõi, và bóc vỏ. Luộc trong nước muối với ít hành và dầu, trên lửa cao cho đến khi mềm và lọc nước.", "Cùng lúc đó, nung bơ trong chảo chiên và hơi vàng các vòng hành. Thêm tỏi, cà chua, ngô tây, nước chanh xanh, muối, và tiêu. Tiếp tục xào trong vài phút. Thêm nước, đun đến sôi và hầm nhẹ trong 5-10 phút.", "Cắt mít đã nguội thành lát và đặt vào đĩa phục vụ. Đổ sốt bơ lên trên mít.", "Trang trí bằng ngô tây đã cắt nhỏ.", "Phục vụ 4 người."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('23153ef9-ec38-5f2a-8bfa-7028e2184d4f', '7d35f13f-7ad7-5fc7-afba-911ce6398b30', 0.5, 'piece'::public.quantity_unit);
