INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f619c72a-c296-577e-83cb-b6593aea0e9c', 'Roti gà và khoai tây (Chicken and Potato Roti)', 'man'::public.dish_category, '["Cho một chén nước dùng gà vào nồi đun sôi và cho ba muỗng thìa đường vào nồi lớn trên lửa cao; nấu cho đến khi đường caramel hóa, sau đó cho đồng gà xúc lát vào và khuấy cho đến khi gà vàng.", "Thêm hành tây đã kẹo, tỏi, ngò tây, xạ hương, gia vị sốt nướng cay Jerk, muối và ớt chuông siêu cay Scotch Bonnet nguyên – không cắt ớt! Giảm lửa xuống thấp và để hầm trong 25 phút.", "Trong một bát trộn lớn, lách bột mì, và thêm một chút muối để nếm.", "Bây giờ thêm thìa đầu tiên của chất béo làm bánh, và bằng ngón tay, xát bột vào chất béo cho đến khi tạo thành hỗn hợp giống như bột mì.", "Sau đó thêm thìa thứ hai của chất béo làm bánh và xát vào bột cho đến khi nó trông giống như bột mì.", "Bây giờ thêm thìa thứ ba của chất béo làm bánh và lặp lại quá trình.", "Bạn đã dùng hết bột rồi. Bát của bạn nên toàn bột mì; nếu còn bột mới, dùng thêm một thìa chất béo làm bánh cho đến khi hết bột mới.", "Thêm một ít nước lọc và khuấy bằng dao bơ; tiếp tục thêm ít nước cho đến khi hỗn hợp tạo thành bột nguội mềm.", "Bây giờ rắc bột lên bề mặt và lăn bột mỏng; bạn muốn lăn các vòng mỏng – hỗn hợp này nên làm ít nhất 12 da roti.", "Đậy bằng khăn trong khi quay lại nồi.", "Bây giờ gọt khoai tây và cắt thành các miếng nhỏ vừa ăn.", "Sau 25 phút hầm, thêm ½ chén nước và khoai tây vào hồ.", "Bây giờ đậy nắp và nấu trong 30 phút trên lửa thấp.", "Lật khay nướng ngang lên, nhẹ nhàng lót giấy bạc, và đặt trên bếp trên lửa cao; nấu mỗi da roti trong 1 phút trên mỗi mặt cho đến khi vàng nhưng không giòn.", "Bây giờ xếp các da roti đã nấu lên, lấy nồi ra sau 30 phút, và lấy ớt chuông siêu cay Scotch Bonnet nguyên ra.", "Mang toàn bộ nồi đến bàn với một chỗ đĩa; mỗi người lấy da roti, đặt phẳng trên cân, cho phần nhân vào giữa da roti, và gói quanh nhân ăn."]'::jsonb, 4);
