INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('10288564-b3bd-5e51-8d5c-98e19ff2a683', 'Bánh mì ngọt Barbados', 'rau'::public.dish_category, '["Thêm toàn bộ bột mì, bột nở (baking powder) và muối vào bát trộn lớn.", "Đun hóa bơ trong nồi.", "Trộn dừa và phần lớn đường trong bát khác – lưu lại phần còn lại để phủ các bánh sau đó, nho khô, trứng, sữa, tinh chất hạnh nhân, tinh chất vani và bơ đã nung chảy.", "Trộn tốt cho đến khi có hỗn hợp kem dịu.", "Thêm hỗn hợp này vào bát chứa bột mì, bột nở và muối. Trộn cho đến khi tạo thành bột cứng.", "Bây giờ chia hỗn hợp giữa các khay nướng.", "Bây giờ đun sôi nước.", "Trộn hai muỗng canh đường với nước nóng và quét lên trên mỗi bánh.", "Nướng ở giữa lò trong 1 giờ.", "Để nguội trong khay trước khi phục vụ; cắt lát và phục vụ với một ấm tươi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('10288564-b3bd-5e51-8d5c-98e19ff2a683', '1a55c39d-95d5-505d-8ed9-36b3d7089043', 600.0, 'ml'::public.quantity_unit);
