INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7d2bbef7-f93f-591d-81fb-69b8fd5ab539', 'Viên thịt sốt si-rô Liège', 'man'::public.dish_category, '["Làm viên thịt", "1) Trộn thịt băm với hành tây, tỏi, trứng, bột chiên xù, mù tạt, ngô tây, muối và tiêu.", "2) Định hình thành viên thịt. Theo truyền thống, các nhà hàng Liège phục vụ một hoặc hai viên thịt rất lớn, tùy theo khẩu phần.", "3) Để nấu vào buổi tối giữa tuần, tôi giữ chúng nhỏ hơn để chúng vàng nhanh hơn và chín qua nhanh hơn.", "Rang viên thịt", "4) Đun nóng bơ hoặc dầu trong chảo lớn.", "5) Rang viên thịt mọi bên cho đến khi có lớp vỏ đẹp.", "6) Lấy chúng ra khỏi chảo và đặt một bên.", "Làm sốt", "7) Trong cùng chảo, nung chảy 1 muỗng canh bơ.", "8) Thêm hành đã cắt lát và nấu cho đến khi mềm và hơi caramel hóa.", "9) Rắc đường nâu vào và để nó tan vào hành.", "Đég lại và thêm nước dùng", "10) Thêm giấm và cạo tất cả các mảnh vàng đen từ chảo.", "11) Khuân mù tạt và si-rô Liège vào.", "12) Đổ nước dùng bò (và bia nếu dùng).", "13) Thêm lá nguyệt quế.", "14) Khuân cho đến khi si-rô tan và sốt trông bóng.", "Hầm nhẹ và điều chỉnh", "15) Trả viên thịt vào chảo.", "16) Đậy nắp và hầm nhẹ trong 25–30 phút (ít hơn nếu viên thịt của bạn nhỏ, lâu hơn nếu chúng là boulets lớn truyền thống). Khuân đôi khi và để sốt đặc tự nhiên.", "17) Nếm và điều chỉnh: thêm si-rô cho độ ngọt, thêm giấm cho độ chua, thêm mù tạt cho độ sâu. Sốt nên chua ngọt, giàu và mịn.", "18) Phục vụ với khoai tây chiên hoặc khoai nghiền."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('7d2bbef7-f93f-591d-81fb-69b8fd5ab539', '61b6c1bc-2369-5a04-8c51-5a4569d3d0ba', 300.0, 'g'::public.quantity_unit);
