INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('cd989d29-c49c-5714-ae28-d638c2f5aafe', 'Salad khoai tây Liège (Liegeoise Salad)', 'rau'::public.dish_category, '["Rửa sạch khoai tây nhưng không bóc vỏ. Cắt thành từng miếng vừa ăn. Cho vào nồi lớn với nước và một chút muối. Đun sôi tốt. Nấu khoai cho đến khi mềm rồi vớt ra bằng cuch đón ráo. Giữ khoai ở nhiệt độ phòng.", "Cắt gốc và vệ sinh đậu que. Cho vào nồi nước nóng đã sôi khoai. Nấu đậu que cho đến khi gần mềm (giữ giòn). Ráo và làm lạnh ngay dưới vòi nước lạnh để dừng quá trình nấu.", "Cho thịt xông khói vào chảo không dính, đun trên lửa vừa. Chiên thịt xông khói vài phút cho đến khi chín đều. Rồi下 chảo khỏi bếp để thịt xông nguội một chút.", "Trộn dầu ô liu, giấm rượu vang trắng và mù tạt. Cho khoai đã nấu, đậu que, thịt xông khói, hành tây băm, ngô tây và sốt mù tạt vào. Nems tiêu và muối.", "Trộn đều. Kiểm tra nems nếm và thêm giấm, tiêu hoặc muối theo khẩu vị. Đổ salad vào bát lớn hoặc 2 đĩa sâu và trang trí với trứng luộc. Dùng ấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('cd989d29-c49c-5714-ae28-d638c2f5aafe', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 350.0, 'g'::public.quantity_unit);
