INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3edadc56-e36f-5af4-a462-4a51f584f6e1', 'Stoemp bègi', 'man'::public.dish_category, '["1. Thêm khoai tây và tỏi đã cắt nhỏ vào nồi cao và rót nước vòi vào cho đến khi khoai ngập hoàn toàn.", "2. Thêm muối. Rồi đặt nồi trên lửa cao và đun nước sôi. Nấu khoai cho đến khi mềm. Cùng lúc đó rửa và để thoát nước lá cải savoy. Cắt lát mỏng nó.", "3. Thêm một muỗng canh bơ vào chảo không dính lớn. Đặt nó trên lửa trung bình cao. Khi đã nung chảy, thêm lá cải savoy. Nems một chút tiêu và muối.", "4. Xào lá cải savoy trong 15 đến 20 phút cho đến khi lá cải mềm và nhừ. Rồi tắt bếp và lấy lá cải ra khỏi bếp. Cùng lúc đó, chiên xúc xích (hoặc bacon lát nếu bạn dùng cả hai) trong chảo không dính trong một muỗng canh bơ hoặc dầu cho đến khi vàng và chín qua.", "5. Chuyển xúc xích (và bacon) vào đĩa và che bằng nắp hoặc giấy bạc để giữ thịt ấm. Trong cùng chảo còn mỡ, thêm hành đã cắt và thêm bơ và nấu nhẹ trên lửa trung bình trong 10 phút cho đến khi hành mềm. (Tôi thường thêm bacon lát cũng, nếu tôi chỉ phục vụ stoemp với xúc xích.)", "6. Rồi thêm bia và tăng lửa lên. Để bia đặc lại cho đến khi có sốt bia và hành ngon (bạn có thể thêm ít bột hoặc đặc sốt nếu thích). Trả thịt xúc xích đã chiên vào chảo và đậy nắp để giữ ấm.", "7. Lọc khoai và tỏi đã nấu, trả chúng vào nồi bạn đã nấu cùng với lá cải savoy đã xào và ngô tây đã cắt nhỏ. Rắc một chút tiêu, muối và nhục đậu khấu. Thêm sữa và phần bơ không muối còn lại.", "8. Nghiền khoai, ngô tây và lá cải savoy chung với nhau. Thêm thêm bơ hoặc sữa nếu cần. Cũng kiểm tra nems và thêm thêm tiêu, nhục đậu khấu hoặc muối nems nếu cần. Lấy hỗn hợp lá cải nghiền lên đĩa và đặt xúc xích chiên (và bacon) lên trên. Rưới sốt bia và hành lên trên. Phục vụ nóng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3edadc56-e36f-5af4-a462-4a51f584f6e1', '9598f70a-4e6e-5688-8b05-ba83b22a0035', 2.0, 'piece'::public.quantity_unit);
