INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b233a868-d684-5e7f-8c16-5aa879a7fa50', 'Cháo bò bí đỏ', 'man'::public.dish_category, '["Cắt thịt bò thành các khối 2,5 cm. Bằm bột mì lên các miếng thịt cho đến khi tất cả mặt đều được phủ.", "Trong nồi súp lớn, nung bơ trên lửa trung bình cao. Trong các lượng nhỏ, rang thịt bò cho đến khi vàng mọi bên, lấy thịt bò đã vàng ra và đặt vào một bát lớn khi bạn làm. Khi thịt bò đã vàng, thêm hành tây và tỏi vào nồi. Xào hành và tỏi trong một phút, cạo đáy nồi khi bạn khuân.", "Trả thịt bò đã rang vào nồi và thêm nước dùng bò, nhuyễn bí đỏ, sốt Worcestershire, muối và tiêu. Khuân tốt và đun đến sôi. Khi chất lỏng đã sôi, giảm lửa xuống trung bình thấp và hầm nhẹ trong 3 giờ, khuân đôi khi.", "Thêm khoai tây, cà rốt và nhánh xạ hương vào nồi và tăng lửa lên trung bình. Nấu thêm 30 phút. Nems muối vừa đủ và phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('b233a868-d684-5e7f-8c16-5aa879a7fa50', 'fda67982-c921-54e6-9568-e2184abae4d6', 1360.8, 'g'::public.quantity_unit);
