INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('28df5565-7716-5b97-b76e-4c6b6d17e2a1', 'Thịt bò xé kiểu Botswana (Seswaa)', 'man'::public.dish_category, '["Đun lò lên 160°C. Cắt thịt thành các mảng lớn rồi nướng trong một bát thích hợp để nấu chậm trong lò như nồi tán đúc sắt.", "Thêm cả củ hành tây đã bóc, muối, tiêu đen vồ nát, nước và lá nguyệt quế. Đun sôi rồi nắp và đưa vào lò trong 4 giờ.", "Sau 4 giờ, lấy ra khỏi lò và đặt trên bếp để nấu khô phần lớn nước còn lại. Dùng thìa gỗ để vặn hoặc nghiền thịt, thịt sẽ xé khá dễ dàng và sẽ xuất hiện xé sợi. Bạn có thể nướng thịt thêm nếu muốn.", "Kiểm tra nems rồi phục vụ với polenta hoặc cháo ngã mì đặc hơn được gọi là pap hoặc sadza, và một bên rau xanh."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('28df5565-7716-5b97-b76e-4c6b6d17e2a1', 'fda67982-c921-54e6-9568-e2184abae4d6', 1000.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('28df5565-7716-5b97-b76e-4c6b6d17e2a1', 'be4dc3f9-4e61-5a09-9d75-cb23bb2f6711', 1.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('28df5565-7716-5b97-b76e-4c6b6d17e2a1', 'a2e23e5b-d849-523d-842e-53a37a195718', 3.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('28df5565-7716-5b97-b76e-4c6b6d17e2a1', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 1000.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8374a2d6-199b-5f9f-99b3-34b7a5cca87e', 'Bánh mì mỏng Phaphatha Botswana (Phaphatha Flatbreads)', 'rau'::public.dish_category, '["Trong bát máy xay đứng, trộn các nguyên liệu khô: bột mì, bột nở, muối, và đường.", "Với móc nhéen ở mức thấp, rót sữa vào.", "Tiếp tục nhéen cho đến khi có một quả bóng bột nhỏ.", "Lấy bột ra khỏi bát, dầu nhẹ bát, và đưa quả bóng bột trở lại bát. Phủ và để riêng để nghỉ 15-30 phút.", "Chia quả bóng bột thành 12 phần, mỗi phần lớn lượng vừa nhau.", "Đun ít dầu trong chảo lớn bằng. Ch압 một quả bóng bột bằng lòng bàn tay và làm thành hình tròn hơi lớn hơn bằng phần bàn tay, để lại hình tròn dày khoảng 10 cm đường kính. Đặt vào chảo nóng. Làm tương với số lượng tròn vừa vặn với chảo của bạn.", "Sau 3-4 phút, khi đáy hơi vàng ở các điểm, lật và nấu thêm 1-2 phút trên mặt thứ hai."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8374a2d6-199b-5f9f-99b3-34b7a5cca87e', '6511004e-c078-51d9-90e7-492186b8e9c1', 500.0, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8374a2d6-199b-5f9f-99b3-34b7a5cca87e', '31aae023-31d6-5e9f-8b25-85f63f761312', 15.0, 'ml'::public.quantity_unit);
