INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c29e4ca3-d96a-5f22-a84c-a40e5d381a08', 'Cải bó xôi cà ri Botswana (Curried Spinach from Botswana)', 'rau'::public.dish_category, '["Đun nóng dầu ăn trong chảo trên lửa trung bình. Khi nóng, thêm hành tây đã cắt và nấu cho đến khi hơi nâu.", "Thêm bột cà ri và muối theo khẩu vị và nướng trong vài giây.", "Thêm cà chua đã kẹo và nước lọc, khuấy tốt, và nấu cho đến khi cà chua bắt đầu nát, 5-7 phút.", "Thêm cải bó xôi đã kẹo (hoặc cải bó xô baby) và nấu thêm 7-10 phút nữa, cho đến khi mềm và héo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c29e4ca3-d96a-5f22-a84c-a40e5d381a08', '2c098e8b-ed4b-56da-83e4-8e7b82eeb4f9', 1.0, 'piece'::public.quantity_unit);
