INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c29e4ca3-d96a-5f22-a84c-a40e5d381a08', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 60.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('bb953379-db32-5a68-9c28-e37412d22cf5', 'Bánh phô mai Brazil (pão de queijo)', 'rau'::public.dish_category, '["Đun lò đến 220°C. Nhớ bơ hoặc dầu khay nướng và đặt một bên.", "Đun sữa, bơ và muối trong nồi vừa và đun đến sôi. Lấy ra khỏi bếp và thêm bột năng. Khuân mạnh, rồi để nguội một chút.", "Đổ hỗn hợp vào máy xay đứng để khuân hỗn hợp cho đến khi nguội, hoặc dùng muỗng gỗ và khuân bằng tay. Khuân trứng một cái một lần, đợi cho đến khi mỗi cái hoàn toàn kết hợp trước khi thêm cái tiếp theo. Khi hỗn hợp bóng và đã trộn, thêm phô mai Parmesan. Khuân lại cho đến khi trộn.", "Đổ hỗn hợp lên khay nướng thành các viên 1 muỗng canh, cách nhau 5cm. Nướng 30 phút cho đến khi giòn và vàng. Lấy ra khỏi lò và ăn khi còn ấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bb953379-db32-5a68-9c28-e37412d22cf5', 'f9ef1ba9-7da5-599e-ad08-11ab8b7e76d9', 5.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bb953379-db32-5a68-9c28-e37412d22cf5', 'e81db4ae-c639-5019-a8b5-aaf0a4395dbd', 250.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bb953379-db32-5a68-9c28-e37412d22cf5', '5a79c587-c78a-529c-b4ea-eb619d193848', 125.0, 'g'::public.quantity_unit);
