INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('79bbb3c2-5aaa-5dfa-b911-66bddf2762a8', 'Bắp nướng sốt tỏi mayonnaise và phô mai băm (Grilled corn with garlic mayo & grated cheese)', 'rau'::public.dish_category, '["Luộc bắp ngô trong 5 phút. Để trong nước cho đến khi bạn sẵn sàng nướng. Trộn tỏi và sốt mayonnaise trong một bát nhỏ. Vừa trước khi nướng than, lấy bắp khỏi nồi, khô khăn và chà sốt mayonnaise vào mỗi bắp.", "Nêm nếm bắp và nướng cho đến khi có dấu nướng, khoảng 5 phút. Lấy ra và rắc phô mai Parmesan và ngô rí lên trên. Vắt chanh xanh lên để ăn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('79bbb3c2-5aaa-5dfa-b911-66bddf2762a8', '52c75230-e161-504a-9c45-fb94bcd8ffed', 6.0, 'piece'::public.quantity_unit);
