INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('7050cafc-938e-58a8-91c8-562a0a99648f', 'Salsa cà chua và ớt khói (Smoky tomato pepper salsa)', 'rau'::public.dish_category, '["Đặt tất cả thành phần vào máy xí nhuyễn và xay nhẹ cho đến khi cắt nhỏ, nhưng không quá mịn. Đổ vào tô phục vụ và thêm nems và một chút đường."]'::jsonb, 4);
