INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('53fa6289-3be1-5241-b671-9b50d9cd9fb5', 'Sốt xanh creamy Aji (Creamy Aji green sauce)', 'rau'::public.dish_category, '["Đặt tất cả nguyên liệu vào máy xén hoặc máy chế biến thực phẩm và xay thành một sốt. Thêm nêm nếm, sau đó rót vào tách phục vụ."]'::jsonb, 4);
