INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('628b0bd4-9923-588d-b9c3-f90e3fa8fd69', 'Súp tôm moqueca Bahia', 'man'::public.dish_category, '["Đặt tôm vào bát với 2 muỗng canh nước chanh xanh, 1 muỗng cà phê muối và 1 muỗng canh tỏi đã băm. Để trong tủ lạnh 1 giờ.", "Đun nóng dầu dừa trong nồi lớn. Thêm hành lá và hành tây và chiên 5 phút, rồi thêm ớt chuông đỏ, ớt khô dạng vảy, paprika và tỏi còn lại.", "Đổ cà chua, nước cốt dừa và ít muối vào. Đun sôi nhẹ và để đặc trong 10 phút. Thêm tôm, toàn bộ sốt ướp và nước chanh xanh còn lại. Đun sôi nhẹ cho đến khi tôm trắng, khoảng 3 phút. Phục vụ với ngò rí tươi và gạo."]'::jsonb, 4);
