INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('eca036fa-3b86-5e42-acc0-19dea8ef36b0', 'Feijoada Brazil', 'man'::public.dish_category, '["Đun nồi súp lớn nặng có nắp khớp, thêm xúc xích khói và chiên cho đến khi giòn. Lấy ra và giữ dầu trong chảo. Trong từng đợt, rang sườn, xúc xích và vai heo. Nems mỗi đợt với muối và tiêu.", "Lấy thịt ra và đặt một bên. Thêm hành, tỏi và ớt vào chảo. Đổ thêm ít dầu ô liu nếu cần thêm. Nems muối và tiêu và chiên 8 phút cho đến khi mềm.", "Thêm thịt, lá nguyệt quế, giấm rượu vang trắng và đậu đen đã để thoát nước. Đổ đủ nước để ngập, khoảng 650 ml. Đun đến sôi và giảm lửa xuống hầm nhẹ. Đậy nắp và nấu trong 2 giờ, hoặc cho đến khi đậu mềm và thịt mềm. Nếu có quá nhiều chất lỏng trong nồi, hãy mở nắp trong giờ cuối. Bạn cũng có thể dùng nồi hiển điện theo phương pháp ngắn (4 giờ) hoặc làm phiên bản nhanh bằng nồi áp lực trong từng đợt trong 30 phút mỗi lần. Cách khác là nấu trong lò trong 3-4 giờ ở 160°C.", "Phục vụ với cơm, một chút ngô tây hoặc ngò rí, sốt ớt cay và các miếng cam."]'::jsonb, 4);
