INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3ef4143b-7f82-5e9d-a337-210285042a00', 'Bánh acaraje đậu đen nhân tôm (Acaraje)', 'man'::public.dish_category, '["Làm nhân: cho hành tím tây, gừng, tỏi, ớt đỏ và một chút muối vào máy xay thực phẩm. Xay nhuyễn cho mịn. Đun nóng dầu thực vật trong chảo chiên và đổ hỗn hợp xay vào. Chiên 5 phút cho đến khi chín hết. Thêm tôm sú tươi sống, cà chua quả mận và ngò rí (rau mùi) đã cắt nhỏ. Chắt chanh xanh vào và nems muối vừa đủ. Nấu thêm 3 phút cho đến khi tôm chín hết. Tắt bếp.", "Rửa và để thoát nước đậu mắt đen. Đổ vào máy xay thực phẩm cùng tỏi và ớt xanh. Xay nhuyễn cho mịn. Lát ra bát và thêm hành tím tây, bột mì đa dụng, muối, bột ớt và bột nở (baking powder). Trộn rồi cuộn thành 16 viên.", "Đun lò đến 190°C. Đun nóng 8cm dầu cọ hoặc dầu thực vật trong chảo wok hoặc nồi sắc nặng. Khi một miếng bánh mì nhỏ cho tiếng chèo vào dầu, thả 4-5 viên vào dầu. Chiên cho vàng giòn, khoảng 4-5 phút. Để thoát dầu trên giấy bếp và làm tương tự cho đến khi hết. Có thể để chúng ấm trong lò khi hoàn tất. Cắt bánh acaraje ra giữa theo chiều dọc và cho nhân tôm vào. Ăn kèm sốt ớt nóng."]'::jsonb, 4);
