INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e718c6d8-eee3-573a-984b-87acdd596f89', 'Sup đậu trắng đơn giản (Easy White Bean Soup)', 'canh'::public.dish_category, '["Đặt đậu trắng Cannellini vào một nồi lớn và ngập nước lạnh. Ngâm ít nhất 4 giờ hoặc qua đêm. Ráo và x kısm trước khi dùng trong sup.", "Kẹo một trong hai hành tây và để lại một cái nguyên. Kẹo cà rốt.", "Đun nóng dầu thực vật trong một nồi lớn trên lửa trung bình. Thêm hành tây và cà rốt. Nấu trong 2 phút. Thêm đậu, nước, ớt chuông đỏ, đầu hành tây, muối, tiêu đen, bạc hà khô, xạ hương, thảo mộc rau mùa hè, Vegeta và cà chua xay nhuyễn. Khuấy, đun sôi, sau đó giảm xuống hầm nhẹ và nấu trong 2 giờ, hoặc cho đến khi đậu mềm.", "Lấy ớt chuông đỏ và đầu hành tây ra. Nghiền đầu hành tây. Gọt ớt chuông đỏ và cắt lát. Trả vào nồi.", "Thêm thêm muối và tiêu đen, nếu cần. Trangs trí bằng ngô tây đã kẹo. Phục vụ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('e718c6d8-eee3-573a-984b-87acdd596f89', '408d726e-6ef4-593c-a77b-e4481c2da478', 453.6, 'g'::public.quantity_unit);
