INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9aa2daff-b823-5c1e-acc7-b2057b476230', 'Súp nấm bào ngư Bulgaria (Oyster Mushroom Soup)', 'canh'::public.dish_category, '["Vệ sinh nấm – thường tôi rửa dưới nước lạnh, khô và cắt bỏ cuống.", "Cắt nấm thành sợi mỏng.", "Tan bơ trong nồi nhỏ. Thêm nấm và nấu 10 phút cho đến khi nấm thả nước.", "Trộn bột mì và nước, đánh cho không còn cục và cho vào nồi. Thêm muối và sữa tươi.", "Nấu thêm 10 phút.", "Trong bát nhỏ hoặc lọ, trộn tỏi và giấm rượu vang đỏ.", "Dùng súp với 1-2 muỗng canh (hoặc thêm) hỗn hợp tỏi và giấm cùng ớt chuông đỏ nóng."]'::jsonb, 4);
