INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('ada678b3-1e23-5fd5-82d6-1969e9dcaa6d', 'Lá cải với thịt bò xay Bulgaria', 'man'::public.dish_category, '["Đun chảo lớn hoặc braiser trên bếp ở mức trung bình. Thêm dầu ô liu.", "Một braiser với thịt bò xay đã nấu", "Nấu thịt:", "Thêm thịt xay vào chảo. Dùng máy nghiền khoai hoặc muỗng gỗ để bóc nhỏ thành các mảnh nhỏ. Nấu 3–4 phút cho đến khi vàng.", "Thêm rau và gia vị:", "Khuân hành, cà rốt, ớt chuông đỏ, tỏi và sốt cà chua đặc vào. Nems muối, tiêu đen, paprika hun khói, cumin xay và gia vị Ý (nếu dùng). Nấu 2–3 phút, khuân thường xuyên.", "Một braiser với thịt bò xay, cà rốt, hành, ớt, tỏi và gia vị.", "Thêm lá cải và chất lỏng:", "Thêm lá cải đã cắt nhỏ, giấm táo hoặc nước chanh vàng (nếu dùng), và nước. Khuân trộn tốt. Giảm lửa xuống trung bình thấp, đậy nắp và nấu trong 30 phút. Khuân đôi khi để ngăn lá cải dính đáy chảo.", "Một nồi với thịt bò xay, rau và lá cải trên bếp.", "Kiểm tra chín:", "Mở nắp và kiểm tra kết cấu của lá cải. Nếu cần, tăng lửa lên trung bình cao và nấu thêm 5–7 phút để bơm hơi nước dư và hoàn thành nấu.", "Một braiser với thịt băm và món lá cải trên bếp.", "Trang trí và phục vụ:", "Rắc ngô tây đã cắt nhỏ hoặc thảo mộc tươi trước khi phục vụ."]'::jsonb, 4);
