INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('90b58092-99f8-52b3-98c2-2d6308289c03', 'Ớt chuông đỏ nhồi phô mai cottage và feta (Cottage Cheese And Feta Stuffed Peppers)', 'rau'::public.dish_category, '["Cắt ớt chuông đỏ theo chiều dọc và lấy hạt ra.", "Trong một bát kết hợp 3.5 oz (100 grams) phô mai Feta, 7 oz (200 grams) phô mai tươi cottage, 1 tbsp ngô tây đã kẹo (tùy chọn), 1 tbsp ngô tây đã kẹo (tùy chọn), 1/4 tsp muối (nhiều hoặc ít theo khẩu vị) và 1 tbsp nước cốt chanh vàng.", "Nhổ ớt chuông đỏ với hỗn hợp. Đậy trên bằng ngô tây đã kẹo và ngô tây.", "Phục vụ."]'::jsonb, 4);
