INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c2a30a8f-9597-57f1-8afb-aa281498d3ba', 'Salad xanh Bulgaria', 'rau'::public.dish_category, '["Đặt xà lách đã cắt vào bát lớn.", "Thêm củ cải đỏ, dưa leo và hành lá.", "Rưới giấm táo và dầu ô liu lên trên.", "Nems muối và khuân nhẹ để trộn.", "Đặt trứng đã luộc đã cắt, ô liu, thì là và (hoặc) ngô tây nếu dùng lên trên và phục vụ ngay lập tức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c2a30a8f-9597-57f1-8afb-aa281498d3ba', 'fb69a885-8246-5835-9f28-2712a3b7e9e7', 0.5, 'piece'::public.quantity_unit);
