INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d1e04d3e-9e6b-5b6d-8e61-51339cafffd0', 'Bánh mì Keto Bulgaria (Keto Banitsa)', 'rau'::public.dish_category, '["Đun lò đến 180°C.", "Đánh trứng trong một bát, dùng nĩa (không cần máy xay).", "Thêm dần bơ đã tan, đánh trộn để kết hợp.", "Thêm các loại phô mai (Mozzarella, feta và kem phô mai), khuấy để kết hợp. Sau đó thêm bột nở và đánh trộn.", "Bớt bơ vào một khay nướng vuông 20×20 cm và đổ hỗn hợp bên trong. Rắc hạt mè lên trên (tùy chọn).", "Nướng trong 20 phút, cho đến khi vàng.", "Để nó nguội trong 5-10 phút bên trong khay, rồi cắt thành các miếng và ăn.", "Giữ trong tủ lạnh trong tối đa 3 ngày."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d1e04d3e-9e6b-5b6d-8e61-51339cafffd0', '8a301d33-ca8b-52a8-aa71-ca6feca05e46', 4.0, 'piece'::public.quantity_unit);
