INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('12da28c6-7f11-5619-911a-5e6b9b4fe893', 'Cà ri cá kiểu Campuchia (amok trey)', 'man'::public.dish_category, '["Trong bát vừa, trộn nước cốt dừa, sốt cà ri đỏ, nước mắm, đường nâu và nước dùng gà, khuôn đến khi mịn — đảm bảo sốt không có cục.", "Đun nóng dầu thực vật trong chảo lớn trên lửa trung bình (khoảng 175°C) cho 30 giây cho đến khi bề mặt nhấp nhô.", "Đổ hỗn hợp nước cốt dừa vào chảo và đun sôi nhẹ, khuân đôi khi, khoảng 3-4 phút.", "Thêm khối cá và lá chanh thái vào chảo, ngập hoàn toàn trong sốt.", "Giảm lửa xuống nhỏ, đậy nắp chảo và nấu 10 phút cho đến khi cá trong suốt và dễ phân tách bằng nĩa — tránh nấu quá để cá giữ độ mềm.", "Đổ trứng gà đã đánh tan vào chậm, nấu thêm 2 phút cho đến khi sốt đặc lên một chút, tạo độ đặc giàu như kem flan.", "Trong khi cà ri sôi nhẹ, chuẩn bị lá chuối bằng cách đưa qua ngọn lửa bếp trong 10 giây để làm cho uốn được, hoặc dùng giấy bếp làm phương án thay thế.", "Đổ cà ri vào giữa từng tấm lá chuối vuông, gấp các mép thành gói chặt để kẹt hơi nước.", "Đặt các gói vào giỏ hấp trên nước sôi và hấp 10 phút cho đến khi nóng đều và thơm.", "Mở các gói cẩn thận và trang trí bằng ngò rí tươi và miếng chanh xanh trước khi ăn."]'::jsonb, 4);
