INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('4b94fde4-840d-50e5-8379-24911d7c0416', 'Heo nướng cơm Bai Sach Chrouk', 'man'::public.dish_category, '["Trong bát lớn, trộn nước cốt dừa, nước tương, dầu hào, mật ong, tỏi đã băm và tiêu đen để làm sốt ướp.", "Thêm vai heo đã cắt lát mỏng vào sốt ướp, đảm bảo từng miếng được phủ đều, rồi đậy nắp và để trong tủ lạnh ít nhất 30 phút để hương vị thẩm vào.", "Trong lúc heo ướp, rửa gạo jasmine dưới nước lạnh cho đến khi nước trong lành để bớt bột ninh, giúp tránh các hạt gạo dính nhau.", "Trong nồi vừa, trộn gạo đã rửa và 960 ml nước, đun sôi trên lửa lớn, rồi giảm lửa xuống hầm nhẹ, đậy nắp và nấu 15 phút cho đến khi nước cạn hết và gạo mềm.", "Đun nồi nướng hoặc nồi nướng ngoài trời ở mức trung bình cao (khoảng 205°C) và quét nhẹ dầu thực vật để tránh dính.", "Lấy heo ra khỏi sốt ướp, lắc để thoát sốt dư, và đặt lên nồi nướng nóng, nấu 3-4 phút mỗi bên cho đến khi ngòi và chín hết với nhiệt độ bên trong 65°C.", "Mẹo: Tránh đặt quá đông trên nồi nướng để đảm bảo chài vàng đều và caramel hóa sốt ướp.", "Khi heo đã nướng, để nghỉ 5 phút trước khi cắt để giữ nước và độ mềm.", "Mẹo: Nếu thích món có sốt hơn, hầm sốt ướp còn lại trong nồi nhỏ 5 phút cho đến khi đặc một chút và rưới lên trên heo.", "Dùng nĩa lả gạo đã nách để tách các hạt và phục vụ nóng kèm các lát heo nướng.", "Sắp xếp dưa leo cắt lát mỏng và lá ngò rí tươi lên trên làm trang trí tươi mát.", "Mẹo: Để có vị cay thêm, phục vụ kèm rau muối hoặc chắt nước chanh xanh để cân bằng hương vị đậm, mặn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('4b94fde4-840d-50e5-8379-24911d7c0416', '96832287-9a53-56d5-998b-525e0d148893', 650.0, 'g'::public.quantity_unit);
