INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3128e6b7-cec3-5d83-8bb3-5c884422ea6f', 'Súp bún Nom Banh Chok Campuchia (Nom Banh Chok – Cambodian Noodle Soup)', 'canh'::public.dish_category, '["Đun dầu ăn trong nồi lớn trên lửa vừa cho đến khi nóng hổi, khoảng 2 phút.", "Thêm tỏi băm và xào cho đến khi thơm và nhẹ vàng, khoảng 1 phút, khuấy liên tục để tránh cháy.", "Thêm các miếng gà và nấu cho đến khi không còn trong mọi mặt, khoảng 5 phút, khuấy thỉnh thoảng.", "Rót 240 ml nước vào và đun sôi trên lửa lớn, sẽ mất khoảng 8 phút.", "Hạ lửa nhỏ, khuấy nước mắm, muối và đường vào, và hôi không nắp 20 phút để phát triển vị.", "Khi nương hôi, nấu bánh phở theo hướng dẫn trên bao bì cho đến khi vừa chừ, rồi ráo và rửa dưới nước lạnh để dừng nấu.", "Chia bún đã nấu đều ra bốn bát.", "Đổ nương nóng và gà lên bún trong mỗi bát.", "Trangs trí mỗi bát bằng giá đỗ, lá bạc hà băm và lát ớt đỏ tuỳ chọn.", "Dùng ngay với lát chanh xanh ở bên cạnh để vắt lên nương."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3128e6b7-cec3-5d83-8bb3-5c884422ea6f', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 1920.0, 'ml'::public.quantity_unit);
