INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('349ec094-0b3b-5226-a13e-183913ab063e', 'Cà ri đỏ Campuchia (Samlar Kari – Khmer Red Curry)', 'man'::public.dish_category, '["Đun 1 muỗng canh dầu thực vật trong nồi lớn hoặc nồi ninh trên lửa vừa-cao cho đến khi rọi, khoảng 2 phút.", "Thêm 450 g miếng gà vào nồi và chiên cho đến khi vàng mọi mặt, khoảng 5-7 phút, khuấy đôi khi để không dính.", "Lấy gà ra khỏi nồi và đặt trên đĩa, để lại dầu và nước cốt trong nồi.", "Giảm lửa về vừa và thêm 1 củ hành tây đã thái vào nồi, nấu cho đến khi mềm và trong suốt, khoảng 4 phút.", "Khuấy vào 3 tép tỏi đã băm và 1 muỗng canh gừng đã xén, nấu trong 1 phút cho thơm, tránh bị cháy.", "Thêm 2 muỗng canh sốt cà ri đỏ vào nồi và nấu trong 1 phút, khuấy liên tục để rang gia vị và làm đậm hương.", "Đổ vào 1 lon nước cốt dừa và 240 ml nước dùng gà, kẹp đáy nồi để hòa các mảnh cháy vào làm giàu hương.", "Khuấy vào 1 muỗng canh nước mắm và 1 muỗng canh đường cho đến khi tan hoàn toàn, rồi trả gà đã chiên vào nồi.", "Đun hỗn hợp cho sôi nhẹ, rồi giảm lửa về thấp, nắp nắp và ninh trong 15 phút để các hương vị hòa vào nhau.", "Thêm 240 ml măng tre và 1 chiếc ớt chuông đỏ đã thái vào nồi, nấu không nắp thêm 5 phút cho đến khi rau vừa chín còn giòn.", "Bớt bấm nồi và khuấy vào 240 ml lá húng quế tây cho đến khi hơi march, khoảng 1 phút, để giữ hương thơm tươi.", "Phục vụ cà ri khi nóng, trang trí bằng lát chanh xanh."]'::jsonb, 4);
