INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('d5e543d6-86c5-57d1-a06a-70a66a1e113a', 'Chấm Prahok Ktis Campuchia', 'man'::public.dish_category, '["Đun 2 muỗng canh dầu thực vật trong chảo lớn trên lửa vừa-cao cho đến khi nóng hổi, khoảng 1 phút.", "Thêm 4 tép tỏi băm và 2 hành tím đã băm mịn vào chảo, khuấy liên tục cho đến khi thơm và nhẹ vàng, 2-3 phút.", "Mẹo: Giữ lửa vừa để tránh cháy—tỏi có thể đắng nếu nấu quá mức.", "Thêm 450 g thịt heo xay vào chảo, đập nát bằng muỗng, và nấu cho đến khi không còn màu hồng, 5-7 phút.", "Khuấy 3 muỗng canh mắm Prahok vào và nấu 1 phút để hòa kết vị, nghiền nhẹ vào thịt heo.", "Rót 240 ml kem dừa vào, khuấy để trộn, rồi giảm nhiệt xuống trung bình thấp và hôi 10 phút cho đến khi hỗn hợp đặc nhẹ.", "Mẹo: Hôi nhẹ để tránh làm kem dừa đông—hơi bọt ổn định là lý tưởng.", "Thêm 2 muỗng canh nước mắm, 1 muỗng canh đường thốt nốt, và 2 ớt Thái đã băm, khuấy cho đến khi đường tan, khoảng 2 phút.", "Vớt chảo khỏi bếp và khuấy 2 muỗng canh nước cốt chanh xanh vào, trộn thật kỹ.", "Mẹo: Thêm nước cốt chanh ngoài bếp để bảo tồn vị chua tươi tươi mà không nấu mất đi.", "Chuyển sốt chấm vào bát dùng và trang trí với 1/4 chén lá ngô rí tươi đã băm.", "Để sốt chấm nguội 5 phút trước khi dùng để vị hòa hợp."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('d5e543d6-86c5-57d1-a06a-70a66a1e113a', '5e2f9050-b7fc-59c7-b3b5-04d1d825ee50', 453.6, 'g'::public.quantity_unit);
