INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fc2e5c5a-222d-5508-a85a-c2c077de44be', 'Bánh gạo nếp Num Ansom (Num Ansom – Sticky Rice Cake)', 'rau'::public.dish_category, '["Ráo gạo nếp đã ngâm thật khô trong lưới mịn.", "Trong bát vừa, trộn kem dừa, đường thốt nốt và muối, khuấy cho đến khi đường tan hoàn toàn.", "Thêm gạo đã ráo vào hỗn hợp kem dừa, trộn nhẹ cho mỗi hạt đều được phủ. Để 15 phút để hấp thụ nước.", "Chuẩn bị nồi hấp bằng cách lấp nồi dưới với 5 cm nước và đun sôi trên lửa lớn.", "Trải một miếng lá chuối vuông phẳng lên bề mặt làm việc, mặt sáng lên trên. Cho 1/4 chén hỗn hợp gạo vào giữa, trải thành hình chữ nhật 10 cm.", "Đặt 2 muỗng canh hồ đậu xanh thành đường dọc giữa hình chữ nhật gạo.", "Gói lá chuối lên trên nhân theo chiều dọc, rồi gói hai bên lại tạo thành gói chặt. Mẹo: Ép chặt để nén gạo, giúp gói giữ hình dạng khi hấp.", "Kết gói bằng chỉ bếp, buộc chặt nhưng không quá chặt để cho phép giãn nở.", "Lặp lại bước 5–8 với phần nguyên liệu còn lại để tạo tổng cộng 8 gói.", "Xếp các gói thành một lớp trong giỏ hấp, để khoảng cách nhỏ giữa chúng cho hơi nước lưu thông.", "Đậy nắp nồi hấp và hấp trên lửa trung bình 90 phút, kiểm tra giữa chừng để đảm bảo nước chưa cạn khô—thêm nước nóng nếu cần. Mẹo: Các gói chín khi lá chuối chuyển thành xanh đậm và gạo cảm thấy chắc khi chạm.", "Cẩn thận lấy các gói ra khỏi nồi hấp và để nguội 20 phút trước khi mở gói. Mẹo: Làm nguội định hình kết cấu, giúp cắt sạch hơn.", "Mở lá chuối và cắt mỗi gói thành các lát dày 2,5 cm để dùng."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('fc2e5c5a-222d-5508-a85a-c2c077de44be', '880f8ce1-30ff-5a05-ab2a-a4f71a5177c7', 480.0, 'ml'::public.quantity_unit);
