INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('fc2e5c5a-222d-5508-a85a-c2c077de44be', '74d6c1c5-a7cb-5e1b-9946-8bc4e8253635', 240.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('78a9f494-a15c-56c2-8378-f08cc6e3706d', 'Bánh mì Num Pang Campuchia (Num Pang – Cambodian Baguette Sandwich)', 'man'::public.dish_category, '["Trong bát vừa, đánh chung xì dầu và mật ong để tạo nước ướp.", "Thêm sợi đùi gà vào nước ướp, đảm bảo mỗi miếng được phủ đều, và để 20 phút ở nhiệt độ phòng.", "Khi gà đang ướp, trộn cà rốt đã thái sợi, củ cải trắng, giấm gạo và đường cát trong một bát riêng, khuấy cho đến khi đường tan để muối chua rau.", "Trong bát nhỏ, trộn kỹ sốt Mayonnaise và sốt Sriracha để làm sốt aioli cay.", "Đun dầu ăn trong chảo lớn hoặc wok trên lửa vừa-cao cho đến khi nóng hổi, khoảng 2 phút.", "Thêm sợi gà đã ướp vào chảo nóng thành một lớp, nấu 4-5 phút mỗi mặt cho đến khi nhiệt độ bên trong đạt 74°C và tạo vỏ màu vàng nâu.", "Khi gà đang nướng, nướng nhẹ các phần bánh mì Baguette đã chia trong lô tô hoặc dưới lò nướng 2-3 phút cho đến khi rì rì ở các cạnh.", "Đắp một lớp dày sốt aioli cay vào bên trong mỗi bánh mì đã nướng.", "Ráo cà rốt và củ cải trắng đã muối chua khỏi nước của chúng, rồi xếp vào nửa dưới của mỗi bánh mì.", "Đặt sợi gà đã nấu đều lên trên rau muối chua trong mỗi bánh mì.", "Trangs trí gà với lá ngô rí tươi và dưa leo lát mỏng.", "Đóng các bánh mì bằng cách nhẹ nhàng nhấn nửa trên của mỗi bánh mì xuống."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('78a9f494-a15c-56c2-8378-f08cc6e3706d', '02e4bb06-59e8-59b7-8a7a-e67b34e73df6', 4.0, 'piece'::public.quantity_unit);
