INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('880fca6d-c255-5257-b95d-ec89a0008eb7', 'Bánh xèo Cambodia mặn (Khmer Banh Xeo – Cambodian Savory Pancake)', 'man'::public.dish_category, '["Đánh trộn bột gạo, tinh bột bắp, nước cốt dừa, nước, và nghệ trong một bát cho đến khi mịn, rồi để nghỉ trong 15 phút—điều này giúp bột hấp thụ nước cho kết cấu tốt hơn.", "Đun chảo không dính 25 cm trên lửa cao vừa (190°C) và thêm 1/2 muỗng canh dầu thực vật.", "Xào lát thịt ba chỉ heo trong 3–4 phút cho đến khi hơi vàng, rồi đẩy sang một bên của chảo.", "Thêm lát hành tây và nấu trong 1 phút cho đến khi hơi mềm.", "Khuấy hỗn hợp bột ngắn và đổ khoảng 120 ml vào chảo, ngay lập tức xoay để phủ đáy mỏng.", "Rắc giá đỗ qua một nửa của bánh xèo và đậy nắp chảo trong 2 phút để hấp giá đỗ.", "Mở nắp và nấu thêm 3–4 phút cho đến khi viền cuộn và chuyển thành vàng nâu và giòn.", "Gấp nửa bánh xèo qua giá đỗ bằng một cái đải lật, rồi chuyển sang đĩa.", "Lặp lại các bước 2–8 với hỗn hợp bột và nguyên liệu còn lại, thêm dầu nếu cần để ngăn dính.", "Ăn ngay với nước mắm để chấm."]'::jsonb, 4);
