INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3afa9f64-ce73-5d0a-8dd8-51a85a834fb8', 'Sup chua Campuchia (Samlar Machu Kreung – Cambodian Sour Stew)', 'man'::public.dish_category, '["Đun 1 muỗng canh dầu thực vật trong nồi lớn trên lửa vừa-cao cho đến khi rọi, khoảng 1 phút.", "Thêm 450 g đùi gà không xương không da vào nồi và chiên cho đến khi vàng mọi mặt, khoảng 5-7 phút, khuấy đôi khi để không dính.", "Đổ 960 ml nước vào nồi và đun sôi, rồi giảm lửa về sôi nhẹ.", "Khuấy vào 2 muỗng canh cốt me chua, 1 muỗng canh nước mắm và 1 muỗng cà phê đường cho đến khi tan hoàn toàn, khoảng 1 phút.", "Thêm 1 cuống sả và 2 lá chanh Thái vào nồi, rồi nắp nắp và ninh trong 10 phút để nước dùng thấm hương.", "Mẹo: Đập nhẹ sả trước khi thêm giúp thoát tinh dầu, món thơm hơn.", "Thêm 240 ml dứa đã cắt, 240 ml cà chua bi và 240 ml đậu que vào nồi, khuấy nhẹn để trộn.", "Ninh không nắp trong 10-12 phút, hoặc cho đến khi đậu que vừa chín còn giòn và cà chua bắt đầu mềm.", "Mẹo: Tránh nấu quá rau để duy trì màu sắc tươi và độ giòn trong món cuối cùng.", "Khuấy vào 1 ớt Thái và ninh thêm 2 phút để hòa hương cay.", "Mẹo: Nếm nước dùng và điều chỉnh thêm cốt me chua hoặc nước mắm nếu muốn, nhưng làm dần dần để không làm mất cân bằng hương.", "Bớt bấm nồi và vớt bỏ sả và lá chanh Thái trước khi phục vụ.", "Trình bày món sốt hầm nóng trong tô, tùy chọn trang trí bằng rau thơm tươi như ngô rí."]'::jsonb, 4);
