INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('275ca1b4-1945-5cd2-891a-48405738579e', 'Bánh chiên ốc biển (Conch Fritters)', 'man'::public.dish_category, '["Lưu ý: Làm hỗn hợp ốc sớm một ngày và để trong tủ lạnh để dành thời gian cho hương vị trộn lẫn. Sốt Tartar cũng có thể được chuẩn bị trước. Chỉ cần kết hợp tất cả nguyên liệu và trộn tốt. Đậy nắp và để trong tủ lạnh.", "Dùng máy xén thực phẩm để xén cùng nhau các mảnh ốc xà cừ biển, ớt chuông đỏ và ớt chuông xanh, hành tây và ớt cay. Khi xong, thêm nước cốt chanh xanh, tỏi đã nhẽn, tiêu đen, muối, húng quế tây khô, và vụn ớt chuông đỏ; hãy đảm bảo trộn kỹ. Sau đó thêm trứng gà và trộn lại. Cuối cùng, thêm bột mì đa dụng một thìa soupe một lần và trộn cho đến khi kết hợp. Bạn có thể bọc bằng nilon và để ngủ trong tủ lạnh trong một giờ hoặc qua đêm.", "Khi sẵn sàng chiên, đổ vào chảo chiên sâu khoảng 3,8 đến 5 cm dầu nhiệt cao theo lựa chọn của bạn. Đặt bếp trên mức nhiệt trung bình thấp.", "Dùng hai thìa để hình thành các viên khoảng 2,5 cm và thả chúng vào dầu nóng một lúc một viên. Mỗi bánh chiên nên chiên khoảng 5-7 phút hoặc cho đến khi vàng nụi và bên trong chín qua. Lặp lại cho đến khi bạn đã dùng hết hỗn hợp ốc xà cừ biển. Phục vụ với sốt Tartar của bạn và khoanh chanh xanh."]'::jsonb, 4);
