INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('06148a82-4cde-540f-8423-86348342c5e2', 'Cơm và đậu đỏ (Rice and Beans)', 'rau'::public.dish_category, '["Nấu đậu đỏ Kidney cho đến khi mềm, thêm gạo, nước cốt dừa, hành tây, tiêu đen và muối, rồi cho đủ nước chỉ ngập nguyên liệu. Đặt ớt chuông siêu cay Scotch Bonnet lên trên, cẩn thận không vỡ chúng. Ninh cho đến khi gạo mềm. Bỏ ớt trước khi phục vụ."]'::jsonb, 4);
