INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('327f5ada-0a80-5e32-a0de-0a1ddfc4e8af', 'Salad khoai tây kiểu Cayman (Cayman Style Potato Salad)', 'rau'::public.dish_category, '["Gọt và cắt khoai tây thành khối, luộc trong nước muối cho đến khi mềm. Cắt ớt chuông xanh, ớt chuông đỏ và hành tây, để một bên. Trộn cùng sốt Mayonnaise, mù tạt, đường và tiêu đen, để một bên. Ráo khoai tây khi đã mềm và đặt vào bát trộn lớn. Thêm các nguyên liệu còn lại và trộn kỹ. Salad có thể ăn nóng, nhưng thường được ăn sau khi để trong tủ lạnh 2 đến 3 giờ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('327f5ada-0a80-5e32-a0de-0a1ddfc4e8af', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 10.0, 'piece'::public.quantity_unit);
