INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c121c344-d09e-59dc-81c4-5099661d561e', 'Cua chiên (Fried Crab)', 'man'::public.dish_category, '["Rửa cua và luộc trong nồi lớn nước trong 15 phút, lấy ra khỏi nước sôi và để nguội. Vỡ chân và mở lưng để lấy hết thịt, để một bên.", "Bỏ hạt khỏi ớt Scotch Bonnet và cắt nhỏ ớt và hành tây. Xào hành tây và ớt Scotch Bonnet trong dầu trên lửa vừa cho đến khi hành bắt đầu trong suốt. Thêm thịt cua, tiêu đen và muối, thỉnh thoảng khuấy. Nấu trên lửa vừa thêm 5 đến 10 phút.", "Ăn kèm \"bread kind\", một món địa phương gồm nhiều loại rau cây cần mỳ bao gồm bí đỏ, bí ngô, chuối nếp, khoai tây, khoai mì và trái mì.", "Tùy chọn: Thịt cua đã nêm cũng có thể nhồi vào lưng cua đã làm sạch và nướng. Phăng lưng cua đã nhồi bằng giấy bạc và nướng ở 175°C trong 30 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c121c344-d09e-59dc-81c4-5099661d561e', '2d22ec0c-f687-5647-bea0-1336a5557450', 453.6, 'g'::public.quantity_unit);
