INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('334f8fbe-d835-59bd-af49-0c47e0b580f1', 'Bò muối và đậu (Salt Beef and Beans)', 'man'::public.dish_category, '["Ngập bò muối đã cắt thành miếng bằng nước và đun sôi. Lặp lại nếu cần, rarget và thay nước để loại bỏ một phần mặn. Trong nồi riêng, cho đậu vào nước, thêm nước cốt dừa, lá nguyệt quế, hạt tiêu Jamaica, tỏi nguyên, ớt chuông siêu cay Scotch Bonnet nguyên và hành lá. Đun chậm sôi và ninh trong khoảng 2 giờ, hoặc cho đến khi đậu mềm. Thêm bò muối, hành tây, xạ hương và tỏi nhám và ninh thêm 20 phút. Điều chỉnh gia vị nếu cần. Bỏ lá nguyệt quế và ớt Scotch Bonnet, cẩn thận không vỡ ớt. Phục vụ với cơm trắng và salad hoặc rau bạn chọn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('334f8fbe-d835-59bd-af49-0c47e0b580f1', 'e4b74399-1857-5c4a-9c76-391b72db8994', 453.6, 'g'::public.quantity_unit);
