INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('416d6c0b-d636-5f4d-90a4-5ba324523035', 'Sopaipillas kiểu Chile (Chilean-Style Sopaipillas)', 'rau'::public.dish_category, '["Gọt, lấy hạt và cắt bí ngô tròn Zapallo thành các mẩu. Đặt vào nồi, ngập nước lọc, và đun sôi trên lửa cao vừa. Nấu cho đến khi bí ngô mềm và dễ đâm bằng nĩa, 15 đến 20 phút. Ráo nước và để nguội hơi.", "Trộn bột mì đa dụng, bột nở và muối cùng nhau trong một bát trộn, và đặt một bên. Khuấy bí ngô và bơ đã nung cùng nhau. Khuấy hỗn hợp bột vào hỗn hợp bơ cho đến khi kết hợp. Đổ bột ra trên bề mặt đã rắc bột nhẹ và xên cho đến khi mềm và mịn, thêm chút bột mì nếu cần. Đậy bột bằng khăn và để nghỉ 15 phút.", "Lăn bột dày 1/8-inch, và cắt thành các vòng đường kính 3-inch. Chọc mỗi vòng vài lần bằng nĩa để làm lỗ và ngăn nở.", "Đổ dầu hạt cải vào chảo lớn và sâu và đun trên lửa cao cho đến khi nóng, 195 C. Đặt một số vòng bột vào dầu nóng; nấu cho đến khi nhẹ vàng, 3 đến 4 phút. Ráo lên khăn giấy. Nấu phần vòng bột còn lại theo đợt."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('416d6c0b-d636-5f4d-90a4-5ba324523035', '4c51d431-cf38-57e8-a3a8-62661570b78e', 255.15, 'g'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('416d6c0b-d636-5f4d-90a4-5ba324523035', '7d6a1f7e-745c-5cd6-af33-19568749147f', 1200.0, 'ml'::public.quantity_unit);
