INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('416d6c0b-d636-5f4d-90a4-5ba324523035', 'cdadb656-1960-506f-b7e6-70b7cd2bb6bc', 480.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('0686096f-f5a7-5f28-86a6-2e3c2766d280', 'Empanada Chile (Chilean Empanada)', 'man'::public.dish_category, '["Làm phần nhân: Nung bơ trong chảo lớn trên lửa trung bình. Thêm hành tây, tỏi, lá Oregano khô, thì là Cumin, muối và tiêu đen; nấu và khuấy cho đến khi hành tây vàng nụi, 5 đến 7 phút. Thêm thịt heo xay và nấu cho đến khi hoàn toàn nâu và vụn, 7 đến 10 phút nữa. Ráo mỡ khỏi chảo. Khuấy vào nho khô, quả ô liu đen và trứng đã luộc chín.", "Trộn nước lọc và bột bắp cùng nhau trong một bát nhỏ; rót vào chảo và khuấy cho đến khi chất lỏng đặc. Nâng khỏi lửa và đặt một bên.", "Làm vở bánh: Đánh trộn sữa tươi và chất béo làm bánh đã nung cùng nhau trong một bát cho đến khi đều đều. Trộn bột mì và muối cùng nhau trong một bát lớn riêng. Đổ hỗn hợp sữa vào hỗn hợp bột; đánh trộn cho đến khi được kết hợp và tạo thành bột. Để nghỉ trong 10 phút.", "Đun lò trước đến 400 F (200 C). Lót khay nướng bằng giấy nướng.", "Lăn bột trên bề mặt đã rắc bột nhẹ đến độ dày 1/8 inch. Cắt thành 12 vòng bằng cắt bánh tròn hoặc ly. Cho phần nhân vào chính giữa mỗi vòng. Gấp mỗi vòng nửa và ép các cạnh bằng nĩa để kín. Chà phần trên bằng trứng gà đã đánh. Đặt empanadas lên khay nướng đã chuẩn bị.", "Nướng trong lò đã đun trước cho đến khi vàng nụi, khoảng 25 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('0686096f-f5a7-5f28-86a6-2e3c2766d280', '5b335556-d749-5751-acbe-0db2ff3196c9', 15.0, 'ml'::public.quantity_unit);
