INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f6c4162c-ff4c-51b0-b6fe-6af16327ad1c', 'Dobladitas Chile (Chilean Dobladitas)', 'rau'::public.dish_category, '["Đun lò trước đến 450 F (230 C). Nhớt một khay nướng.", "Đánh trộn bột mì đa dụng, 240 ml bơ đã nung, sữa tươi, bột nở và muối cùng nhau trong một bát cho đến khi bắt đầu khớp nhau. Đổ bột ra trên bề mặt đã rắc bột nhẹ; xên cho đến khi mịn và dẻo.", "Lăn bột dày ⅛-inch; cắt thành các vòng 8-inch. Chà các vòng bằng phần 3 thìa soupe bơ đã nung còn lại. Gấp mỗi vòng nửa, sau đó gấp nửa nữa để tạo thành tam giác. Ép chắc các lớp; đặt lên khay nướng đã chuẩn bị.", "Nướng trong lò đã đun trước cho đến khi vàng nụi, khoảng 15 phút. Ăn khi ấm"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f6c4162c-ff4c-51b0-b6fe-6af16327ad1c', '7d6a1f7e-745c-5cd6-af33-19568749147f', 960.0, 'ml'::public.quantity_unit);
