INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('dc8c3600-6cd2-5c04-86f7-945eba1ba712', 'Bánh khoai tây Chile (Pastel de Papas)', 'man'::public.dish_category, '["Cho khoai tây vào nồi lớn và ngập nước có muối; đun sôi. Giảm lửa trung bình thấp và hôi cho đến khi mềm, khoảng 20 phút.", "Khi khoai đang nấu, đun dầu trong chảo lớn trên lửa vừa. Cho hành;nấu và khuấy cho đến khi trong, khoảng 5 phút, thêm tỏi vào phút cuối. Khuấy cà chua đã đục và cà chua xay nhuyễn vào; nấu cho đến khi cà chua mềm và bắt đầu mất hình dạng, 3 đến 5 phút.", "Thêm thịt bò xay vào chảo; nấu và khuấy cho đến khi vàng và ngוות, khoảng 10 phút. Khuấy phô mai Panquehue, ngô tây, và bột ớt Cayenne vào; nems muối và tiêu. Tắt bếp và để cho đến khi cần.", "Đầy lò 175°C. Mỡ ô n wun 2 quart.", "Ráo khoai trong cái rổ, rồi để hơi nước bay 1 đến 2 phút. Chuyển khoai trở lại nồi, thêm bơ và muối, và nghiền cho đến khi mịn. Để nguội cho đến khi hơi ấm, 5 đến 10 phút, rồi khuấy trứng đánh tan vào.", "Rải nửa khoai nghiền lên đáy ô nướng đã chuẩn bị. Xếp lớp hỗn hợp thịt bò xay lên trên, rồi phủ hoàn toàn bằng khoai còn lại.", "Nướng trong lò đã đậy cho đến khi khoai nóng và hơi vàng trên bề mặt, khoảng 40 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('dc8c3600-6cd2-5c04-86f7-945eba1ba712', '0606db96-81d8-5339-9d5f-b8f38f16a6f6', 1200.0, 'ml'::public.quantity_unit);
