INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5d2c04e6-4b1b-5431-ba91-de5181e6655e', 'Bánh nêm phô mai chiên (Empanadas Fritas de Queso)', 'rau'::public.dish_category, '["Cho bột mì đa dụng, bột nở và muối vào bát trộn lớn. Pha nát mỡ heo nước với sữa tươi trong nồi, đun cho đến khi sữa nóng. Đổ sữa nóng vào hỗn hợp bột, khuấy cho đến khi tạo thành bột dẻo. Đặt bột lên bề mặt đã rắc bột, nghiền nhẹ cho đến khi mịn và dẻo. Cuộn lại, để nghỉ 15 phút.", "Đun nóng lò đến 190°C.", "Đặt bột lên bề mặt đã rắc bột, keo giãn thành dày 0,6 cm. Cắt thành các vòng tròn đường kính 10 cm. Mở lòng trắng trứng lên viền ngoài mỗi vòng tròn, đặt một chút phô mai Thụy Sĩ ở giữa. Dập mỗi vòng tròn thành nửa tròn, dùng ngón tay hoặc bấm nhẹ viền để kín. Đặt các bánh nêm lên khay nướng đã lót giấy nướng. Mở lòng trắng trứng còn lại lên mặt trên.", "Nướng trong lò đã nóng cho đến khi vàng đều, khoảng 20 phút.", "Hoặc có thể chiên sâu các bánh nêm trong dầu nóng 190°C. Nếu chiên sâu, không mở lòng trắng trứng lên phần ngoài của các bánh nêm. Để ráo trên giấy."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5d2c04e6-4b1b-5431-ba91-de5181e6655e', '7d6a1f7e-745c-5cd6-af33-19568749147f', 720.0, 'ml'::public.quantity_unit);
