INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5d2c04e6-4b1b-5431-ba91-de5181e6655e', 'b83a4a6f-22ac-5d6c-81e1-a8abf33e4963', 240.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('02842220-123d-58f2-a27a-4ec40545af04', 'Bánh ngô Chile (Pastel de Choclo)', 'man'::public.dish_category, '["Cho trứng vào nồi nhỏ và ngập nước. Đun sôi, nới bếp, và để trứng trong nước nóng 15 phút.", "Trong lúc đó, đun dầu trong chảo trên lửa vừa. Cho hành tây, tỏi, 1 chút muối, 1/4 muỗng cà phê bột ớt ngọt, và tiêu đen; nấu cho đến khi thơm, khoảng 2 phút. Thêm thịt bò, 1 muỗng cà phê muối còn lại, 1/4 muỗng cà phê bột ớt ngọt còn lại, và tiêu đen; nấu và khuấy cho đến khi thịt bò hầu hết vàng, khoảng 5 phút. Thêm gà, nho khô, và ô liu xanh.", "Vớt trứng ra khỏi nước nóng, làm lạnh dưới vòi nước lạnh chảy, và bóc vỏ. Băm thô; thêm vào hỗn hợp thịt bò. Giữ pino nóng.", "Trộn bắp ngọt và húng quế tây trong máy xay hoặc bát của máy xay thực phẩm; xay cho đến khi mịn. Đổ vào nồi nhỏ trên lửa vừa. Thêm bơ; nấu và khuấy cho đến khi đặc, 7 đến 10 phút. Khuấy sữa, 2 muỗng cà phê đường, và muối; nấu cho đến khi đặc thành hồ, khoảng 15 phút nữa.", "Đầy lò 175°C.", "Rải pino vào ô nướng. Phủ hồ ngô; rắc chút đường lên trên.", "Nướng trong lò đã đậy cho đến khi bề mặt vàng, khoảng 20 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('02842220-123d-58f2-a27a-4ec40545af04', '8a301d33-ca8b-52a8-aa71-ca6feca05e46', 2.0, 'piece'::public.quantity_unit);
