INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('bf374647-8c36-5c01-941a-b5cf933420f6', 'Buñuelos Colombia (Colombian Buñuelos Recipe)', 'rau'::public.dish_category, '["Đặt tất cả nguyên liệu, ngoại trừ dầu, vào bát vừa và trộn tốt bằng tay cho đến khi thu được bột nguội mềm và mịn.", "Hình thành các viên nhỏ bằng tay.", "Trong nồi sâu, đun nóng dầu thực vật đến 150°C (ấm, không quá nóng). Cẩn thận thả các viên vào dầu ấm và chiên khoảng 3 đến 4 phút hoặc cho đến khi vàng nụi.", "Lấy ra khỏi dầu và ráo trên đĩa đã lót khăn giấy. Phục vụ.", "N chiên Buñuelos Colombia ở nhiệt độ đúng rất quan trọng. Dầu không thể quá nóng hoặc quá lạnh. Hãy đảm bảo dầu được đun nóng đến 150 đến 160 ."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('bf374647-8c36-5c01-941a-b5cf933420f6', '37b860de-aac4-5988-9271-8656fd005a7d', 360.0, 'ml'::public.quantity_unit);
