INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('197f7eb5-da8c-5392-a182-b0def31e91a7', 'Sườn heo sốt Creole kiểu Colombia (Chuletas de Cerdo a la Criolla)', 'man'::public.dish_category, '["Đặt sườn cốt lết heo vào túi nilon kín. Thêm mù tạt, thì là Cumin, tỏi, muối và tiêu đen.", "Để trong tủ lạnh trong 1 giờ hoặc qua đêm. Đảm bảo sườn cốt lết heo được phủ đều.", "Trong chảo lớn, đun nóng dầu thực vật trên lửa trung bình. Đặt sườn cốt lết heo vào chảo và nấu trong 3 phút mỗi mặt. Lấy heo khỏi chảo và giữ trên đĩa nóng.", "Thêm hành tây và cà chua vào cùng chảo nơi heo đã được chiên vàng, thêm một thìa soupe dầu nếu cần. Nấu trên lửa cao trong khoảng 5-7 phút cho đến khi vàng và mềm, khuấy thường xuyên để tránh cháy. Thêm sườn cốt lết heo đã nấu đã giữ lại và đậy nắp, giảm lửa xuống trung bình thấp và hầm cho đến khi heo mềm và hơi hồng ở chính giữa, khoảng 15 phút. Chia sườn cốt lết heo vào các tách, rót sốt lên trên, thêm ngò rí và phục vụ ngay lập tức."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('197f7eb5-da8c-5392-a182-b0def31e91a7', '277679d9-8810-544e-aa68-7703e85c1a4d', 4.0, 'piece'::public.quantity_unit);
