INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('9e0c213b-8a5e-5dcd-b6b4-aaf6dc489d56', 'Bánh phô mai Colombia (almojabanas)', 'rau'::public.dish_category, '["Đun lò đến 205°C.", "Trộn bột ngô hạt thô và phô mai trong máy xay thực phẩm.", "Thêm các nguyên liệu còn lại và trộn đều.", "Chia thành 8 phần bằng nhau và tròn thành viên.", "Đặt trên khay nướng đã bơ và nướng khoảng 25 đến 30 phút, hoặc cho đến khi vàng. Ăn khi ấm."]'::jsonb, 4);
