INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1f1b4291-b6c6-5f07-b01b-bc2478d12266', 'Gà sốt mù tạt kem (Creamy Mustard Chicken)', 'man'::public.dish_category, '["Vắt khô gà và nems các miếng với muối, tiêu đen và bột ớt ngọt Paprika.", "Đun nồi trên lửa cao vừa và thêm dầu ô liu. Để dầu nóng trong vài giây. Thêm gà và nấu cho đến khi nghén tất cả các mặt lật các miếng vài lần cho đến khi vàng nụi khoảng 10 phút.", "Chuyển gà đã nâu sang đĩa và đặt một bên. Thêm hành tây và tỏi vào chảo và nấu khoảng 2 phút hoặc cho đến khi mềm. Thêm nước dùng gà, mù tạt, mật ong và kem béo. Nems muối và tiêu đen hạt/bột.", "Khuấy tốt và trả các miếng gà trở lại chảo. Đậy nắp chảo và nấu trên lửa thấp trong khoảng 45 phút hoặc cho đến khi gà chín. Nhiệt độ cuối cùng cho má đùi gà nên là 75°C.", "Phục vụ nóng trên cơm trắng và trangs trí bằng ngô tây đã kẹo."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('1f1b4291-b6c6-5f07-b01b-bc2478d12266', '2305f189-d0c5-5702-86ff-04abb829593d', 8.0, 'piece'::public.quantity_unit);
