INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fc2c7e6a-2ad1-5889-a1fd-ca2879b928a3', 'Gà sốt cam (Chicken in Orange Sauce Recipe (Pollo a la Naranja))', 'man'::public.dish_category, '["Cho dầu ô liu và bơ vào nồi lớn trên lửa vừa. Thêm hành tây đã kẹo, ớt chuông đỏ và tỏi. Nấu khoảng 3 phút, gọi thường cho đến khi rau mềm.", "Thêm má đùi gà và nêm muối và tiêu đen. Nấu khoảng 1 phút trên mỗi mặt.", "Thêm nước dùng gà và nước cam và nấu khoảng 2 phút, kẹp đáy nồi bằng thìa gỗ. Thêm đường nâu và đậy nắp nồi. Giảm lửa xuống trung bình và nấu khoảng 45 phút hoặc cho đến khi gà chín.", "Cho sốt lên trên gà và ăn với cơm trắng. Trangs trí bằng ngò rí tươi."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('fc2c7e6a-2ad1-5889-a1fd-ca2879b928a3', '2305f189-d0c5-5702-86ff-04abb829593d', 4.0, 'piece'::public.quantity_unit);
