INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('a1793296-cc72-5727-9ce3-0e31fc285c51', 'Sup ngô kem (Creamy Corn Soup Recipe)', 'canh'::public.dish_category, '["Đặt ngô nguyên bắp, nước lọc, viên súp gà, tỏi, muối, tiêu đen hạt/bột, ngò rí, khoai tây và hành lá vào nồi lớn và đun sôi. Giảm lửa xuống mức trung bình thấp và hầm trong khoảng 4 phút hoặc cho đến khi ngô mềm.", "Nâng khỏi lửa. Xay nhuyễn sup trong máy xén và trả về nồi, thêm kem béo và đun nóng trên lửa trung bình trong 15 phút, gọi đôi khi.", "Đổ vào tách, trangs trí bằng ngò rí và khoai tây chiên.", "Ghi chú", "*Ngô tươi hoặc ngô đông lạnh sẽ hoạt động cho công thức sup này. Tôi thường dùng ngô tươi, nhưng tôi dùng hạt ngô hữu cơ trong mùa đông để làm sup này.", "*Để bảo quản: Đặt sup ngô đã nguội vào bình kín và để trong tủ lạnh trong vòng 3 ngày."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('a1793296-cc72-5727-9ce3-0e31fc285c51', '52c75230-e161-504a-9c45-fb94bcd8ffed', 4.0, 'piece'::public.quantity_unit);
