INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('b497bd88-580c-5a03-bec3-fb4dd2b6f2e2', 'Bánh thịt bò bắp mì Colombia (Lomo de Res Apanado)', 'man'::public.dish_category, '["Đặt từng miếng thăn giữa hai miếng nylon lớn và dùng búa, đập cho đến khi dày khoảng 0,6 đến 1,3 cm. Đặt thăn đã đập vào bình kính, thêm sốt aliños và để nghỉ khoảng 3 giờ hoặc qua đêm trong tủ lạnh.", "Thêm bột mì, bột chiên xù, gia vị và ngô tây vào đĩa hoặc bát.", "Bọc thăn mọi mặt bằng hỗn hợp bột, rồi trứng, và cuối cùng hỗn hợp bột lại.", "Khi các miếng thăn đã được bọc, bạn có thể thêm chúng ngay vào chảo với dầu để nấu hoặc xếp lên giấy bếp cho đến khi sẵn sàng chiên.", "Thêm dầu vào chảo lớn trên lửa trung bình. Ngay khi nó bắt đầu khói nhẹ, thêm thăn bắp mì và nấu khoảng 3 đến 4 phút mỗi mặt cho đến khi vàng. Lấy chúng ra khỏi dầu và đặt trên đĩa đã lót khăn giấy để thoát dư dầu và phục vụ."]'::jsonb, 4);
