INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('be6ca32f-a6cc-51a0-9579-6887f3bc49c7', 'Nồi đậu đen Costa Rica', 'rau'::public.dish_category, '["Thêm tất cả các nguyên liệu vào nồi áp lực Instant, khóa nắp và đặt Instant ở áp lực cao trong 35 phút. Khi đậu đã nấu xong, để áp lực thoát tự nhiên trong 20 phút trước khi giải phóng áp lực còn lại. Mở nắp và phục vụ!", "Để đậu nguội hoàn toàn trước khi lưu vào tủ lạnh hoặc tủ đông."]'::jsonb, 4);
