INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('340b0ca9-75f2-54fc-877f-a87fac72fc0f', 'Salsa xoài nhiệt đới (Mango Tropical Salsa)', 'rau'::public.dish_category, '["Trong bát lớn, trộn tất cả nguyên liệu với nhau, trộn kỹ! Đậy nắp và để trong tủ lạnh ít nhất 15 phút trước khi ăn. Ăn kèm chips.", "Tôi khuyên nên làm salsa này trước khi ăn 15 đến 20 phút, nếu làm quá sớm sẽ hơi nước. Chuẩn bị tất cả nguyên liệu đã cắt sẵn và chỉ trộn cùng lúc khách đến."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('340b0ca9-75f2-54fc-877f-a87fac72fc0f', 'caf82c3b-825a-5c73-bf1b-e7186bcd700b', 60.0, 'ml'::public.quantity_unit);
