INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3b8edd24-e713-519d-aef7-010d2bf84659', 'Đậu que xào Picadillo Costa Rica (Picadillo de Vainicas)', 'man'::public.dish_category, '["Trong nồi vừa trên lửa vừa, thêm ít dầu ô liu, hành tây, ớt, và tỏi và nấu cho đến khi hành trong.", "Trong thời gian đó, băm nhuyễn đậu que.", "Thêm vào nồi, thịt bò xé, đậu que, xạ hương, muối và tiêu, và trộn tốt. Thêm nước, đậy nắp và nấu 15 phút, mở nắp và nấu thêm 5 phút hoặc cho đến khi đậu que mềm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('3b8edd24-e713-519d-aef7-010d2bf84659', 'fa434aac-0d62-5f7a-8b3d-b499457132b5', 453.6, 'g'::public.quantity_unit);
