INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('128a1c77-159d-52db-8d79-7dbdd53f747c', 'Gà sốt Costa Rica (Pollo en Salsa)', 'man'::public.dish_category, '["Cắt ớt, hành tây và cà chua và để riêng. Bật nồi áp lực ở chế độ xào trong 8 phút. Thêm ít dầu ô liu và cho hành, tỏi, cà chua, ớt chuông, thì là, hoặc hy lạp, muối và tiêu vào và xào trong 4 phút.", "Thêm gà và nấu 2 phút mỗi mặt, khuấy thường xuyên. Thêm nước dùng gà, đậy nắp và đặt nồi áp lực ở mức cao trong 20 phút. Khi xong giải phóng áp lực và nếu cần, thêm ít muối hơn. Tôi thích dùng với chút nước dùng qua cơm và đậu."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('128a1c77-159d-52db-8d79-7dbdd53f747c', '53912b45-176d-5ec9-81db-addf1adaa05f', 4.0, 'piece'::public.quantity_unit);
