INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('e1c23021-55ad-5f67-bf3a-2c44f41ecf08', 'Gạo và đậu đen Costa Rica (Gallo pinto)', 'rau'::public.dish_category, '["Đun chảo trên lửa cao vừa, thêm dầu ô liu và để nóng. Thêm hành tây, ớt, ngô rí, tỏi, cumin, muối và tiêu, nấu trong 3 đến 5 phút cho đến khi hành trong suốt.", "Trộn đậu đen vào, khuấy và giảm lửa xuống vừa, thêm sốt Lizano, khuấy và nấu thêm 5 phút.", "Thêm gạo vào, khuấy và nấu thêm vài phút, để hòa quyện tất cả hương vị vào gạo. Thời gian nấu phụ thuộc vào cách bạn thích gallo pinto, một số người thích hơi ướt và một số người khác thích hơi rang hoặc khô.", "Tôi thích không quá khô, vì vậy tôi nấu khoảng 5 đến 7 phút."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('e1c23021-55ad-5f67-bf3a-2c44f41ecf08', '67dda1de-e3fa-57fb-84fd-83d727ebbdef', 160.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('e1c23021-55ad-5f67-bf3a-2c44f41ecf08', '4a081187-4d43-536a-9103-19f259b0316c', 300.0, 'ml'::public.quantity_unit);
