INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('25d19154-7d14-5781-950d-f8e3046300a6', 'Bò xé kiểu Cuba (Ropa Vieja)', 'man'::public.dish_category, '["Cắt steak thành 4 miếng hình chữ nhật. Thấm khô bằng khăn giấy; nems muối 1,5 muỗng cà phê xung quanh.", "Trong nồi lớn trên lửa vừa-cao, đun nóng 2 muỗng canh dầu thực vật. Làm việc theo từng đợt, chiên steak cho đến khi vàng cả hai mặt, 5 đến 6 phút. Chuyển ra đĩa.", "Trong cùng nồi trên lửa vừa, đun nóng 2 muỗng canh dầu còn lại. Nấu ớt chuông đỏ, ớt chuông vàng, hành tây và 1,5 muỗng cà phê muối, khuấy đôi khi, cho đến khi hơi mềm, 4 đến 5 phút. Thêm tỏi, sốt cà chua xay nhuyễn, bột ớt Paprika hun khói, thì là Ai Cập và lá Oregano khô và nấu, khuấy đôi khi, cho đến khi rau mềm và gia vị thơm, 1 đến 2 phút thêm.", "Thêm rượu vang trắng khô, kẹp các mảnh cháy đen đáy chảo, và nấu, khuấy đôi khi, cho đến khi giảm một nửa, khoảng 2 phút. Thêm cà chua đóng hộp cùng nước cốt của chúng và lá nguyệt quế. Nhập nhạt cà chua để nát, rồi lays bò vào kho nhắm. Thêm nước để ngập bò, nếu cần, và đun sôi nhỏ lửa. Giảm lửa thành vừa-thấp; nắp lại và ninh cho đến khi steak đủ mềm để xé, 2,5 đến 3 giờ. Chuyển steak ra đĩa và xé nhèrem bằng 2 nĩa.", "Khuấy steak đã xé lại vào kho nhắm. Đun sôi nhỏ lửa và nấu, khuấy, cho đến khi nước cốt giảm thành sốt phủ steak, 5 đến 10 phút. Khuấy oliu nhồi; nems muối.", "Đổ ropa vieja lên cơm và đậu. Trang trí bằng ngô rí."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('25d19154-7d14-5781-950d-f8e3046300a6', '8dbd3b2d-e147-5d10-9733-cad012530756', 907.2, 'g'::public.quantity_unit);
