INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fda8f71b-ee63-5a16-9027-f6bd7c33b103', 'Súp đậu đen Cuba', 'canh'::public.dish_category, '["Trong nồi lớn trên lửa trung bình, đun dầu. Thêm hành và nấu cho đến khi mềm và trong suốt, khoảng 5 phút. Thêm ớt jalapeño và tỏi và nấu cho đến khi thơm, khoảng 2 phút. Thêm sốt cà chua đặc, khuân để bọc rau, và nấu thêm một phút. Nems muối, tiêu, cumin và bột ớt và khuân để bọc.", "Thêm đậu đen và nước dùng gà. Khuân súp, thêm lá nguyệt quế, và đun đến sôi. Ngay lập tức giảm lửa xuống hầm nhẹ và để hương cho đến khi hơi đặc và đặc hơn, 15 đến 20 phút. (Nếu muốn súp mỏng hơn, thêm thêm nước dùng gà nếu cần.)", "Lấy lá nguyệt quế ra và để nguội hơi. Dùng máy xay tay hoặc máy xay thực phẩm, khuân súp cho đến khi đạt độ đặc mong muốn.", "Phục vụ với một chút kem chua, bơ quả lát, và ngò rí."]'::jsonb, 4);
