INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('1aed6074-c14e-5f3e-ba99-45fec61fb86c', 'Sandwich Cuba (Cuban Sandwich)', 'man'::public.dish_category, '["Đặt sườn cốt lết heo vào cái đĩa nướng kính 3-qt. Dùng nĩa, chọc lỗ vào heo khắp nơi; nêm muối khắp người. Rưới dầu và lắc để phủ.", "Trong một bát nhỏ, kết hợp vỏ chanh vàng và nước cốt, vỏ chanh xanh và nước cốt, lá Oregano khô, tiêu đen xay, bột tỏi, thì là Cumin, và bột hành tây. Thêm nửa marinade vào heo và để nghỉ 10 đến 15 phút.", "Cùng lúc đó, sắp xếp một giá ở chính giữa lò; đun trước đến 220°C. Thêm mù tạt Dijon và sốt Mayonnaise vào marinade còn lại và khuấy cho đến khi mịn.", "Chuyển heo vào lò và nướng cho đến khi mức nhiệt độ kế đo lắp vào phần dày nhất đăng ký 60°C, 15 đến 20 phút.", "Để xây sandwiches, cắt bánh mì kiểu Cuba nửa theo chiều ngang, sau đó cắt mỗi miếng nửa theo chiều dọc cho 4 miếng tổng cộng. Bôi bơ lên ngoài bánh mì ở trên và dưới. Bôi hỗn hợp mù tạt lên các bên cắt. Trên 2 miếng bánh mì, xếp mỗi miếng với 2 oz. phô mai, 4 oz. giăm bông, nửa heo đã nướng, 4 lát dưa leo muối thì là, và phần 2 oz. phô mai còn lại. Đóng với các miếng bánh mì còn lại và gói mỗi sandwich trong giấy bạc.", "Đun nóng một cái chảo sắt đúc lớn trên lửa trung bình. Đặt các sandwich đã gói giấy bạc vào chảo, sau đó đặt một cái chảo nặng khác lên trên để tạo một cái máy ép sandwich homemade. Nếu bạn không có một cái chảo nặng khác, áp chảo xuống bằng một cái chảo nhẹ hơn hoặc khay nướng, sau đó đặt trên chút sản phẩm đóng hộp.", "Nướng sandwiches, lật giữa chừng, cho đến khi nướng và phô mai đã nung, 3 đến 4 phút mỗi mặt. Cắt mỗi sandwich nửa và phục vụ."]'::jsonb, 4);
