INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f4b850dd-1284-507b-aec6-0abb8cf4d8a6', 'Khoai mì nướng Cuba', 'rau'::public.dish_category, '["Đun lò đến 230°C. Đun sôi một nồi lớn nước. Cắt hai đầu khoai mì và cắt mỗi cái thành nửa theo chiều ngang. Đặt chúng đứng và dùng dao sắc để cắt vỏ khoai mì. Cắt mỗi miếng theo chiều dọc rồi cắt theo chiều dọc một lần nữa để tạo tổng cộng 16 miếng. Bớp phần sợi giữa của mỗi miếng.", "Đặt khoai mì đã cắt vào nước sôi và để sôi cho đến khi mềm khi đâm nĩa, 8 đến 10 phút. Dùng thìa rỗng, lấy ra khỏi nồi và đặt trên khay cắt đã lót khăn giấy. Thấm khô bằng khăn giấy khác.", "Đặt khoai mì đã khô vào bát lớn và trộn với dầu. Nems bột ớt, muối và tiêu và trộn lại để phủ đều. Đặt khoai mì lên khay nướng lớn thành một lớp đều.", "Nướng cho đến khi vàng và giòn, khoảng 25 phút, lật ở giữa.", "Cùng lúc đó làm sốt chấm: Trong máy xay nhỏ hoặc máy xay tay, trộn bơ quả, kem chua, nước chanh xanh và ngò rí, xay cho đến khi mịn. Nems muối và tiêu.", "Phục vụ khoai mì ngay với sốt chấm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('f4b850dd-1284-507b-aec6-0abb8cf4d8a6', '5a0b2039-fb9a-5527-aa34-cd72cacf8f22', 2.0, 'piece'::public.quantity_unit);
