INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6a3ea784-3c57-597c-b2c7-3e2da8aba756', 'Salad gà nấm và xông khói (Chicken Salad With Mushrooms and Bacon)', 'man'::public.dish_category, '["Đặt ngực gà vào nồi và ngập nước. Đun sôi, thêm 1 thìa cà phê muối và hầm khoảng 15 phút. Cho gà nguội và sau đó xé thịt bằng hai nĩa.", "Kẹo nhỏ hành tím tây/hành đỏ.", "Trộn sốt Mayonnaise, kem tươi Crème Fraîche, mù tạt Dijon và giấm táo vào một. Nêm muối, tiêu và thêm mù tạt Dijon theo khẩu vị. Trộn cùng hành và gà.", "Chiên xông khói cho đến khi giòn và chuyển lên đĩa đã lót khăn giấy.", "Rửa nấm, cắt lát và chiên trong cùng chảo với xông khói cho đến khi vàng (khoảng 5 phút). Nems một chút muối và tiêu.", "Sắp xếp salad gà vào đĩa ăn, phủ xông khói giòn, nấm và ngô tây đã kẹo. Ăn trên một miếng bánh sáng hoặc bánh đen."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('6a3ea784-3c57-597c-b2c7-3e2da8aba756', 'ad351e7b-f3ad-58e4-ac0a-01692efe9c9e', 300.0, 'g'::public.quantity_unit);
