INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6fd429aa-d67d-59f1-ba0d-e5c719bcb156', 'Bánh mì lúa mì Đan Mạch (Hveder - Danish Wheat Buns)', 'rau'::public.dish_category, '["Đun sữa trong nồi cho đến khi ấm khi chạm (25°C). Chuyển sữa vào bát trộn và tan men nở trong sữa.", "Thêm các nguyên liệu còn lại ngoại trừ bơ và nghiền kỹ. Dùng máy xay bếp để nghiền bột nếu bạn có một.", "Cắt bơ thành khối và thêm vào bột. Nghiền trong 5 đến 10 phút cho đến khi bột dẻo và mịn.", "Đậy nắp bột và để nở trong nơi ấm trong 45 phút.", "Chuyển bột lên bàn đã rắc bột và chia thành 10-12 miếng bằng nhau. Cuộn từng miếng thành một bánh mì tròn và sắp xếp các bánh mì gần nhau trên khay nướng đã lót hoặc đĩa chịu nhiệt (khoảng 20 x 30 cm). Đậy nắp các bánh mì và để nở khoảng 1 tiếng cho đến khi chúng tăng gấp đôi kích thước.", "Đun lò đến 180°C trên chế độ quạt.", "Đánh trứng trong một bát nhỏ và mở trứng lên trên các bánh mì. Nướng trên kệ lò ở giữa trong 14 đến 16 phút cho đến khi các bánh mì có bề mặt vàng đẹp. Ăn nóng hoặc nướng với bơ."]'::jsonb, 4);
