INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('2020c7e5-f613-547b-bf05-ed37857f61aa', 'Bánh nướng thịt heo Đan Mạch (Frikadeller - Danish Meatballs)', 'man'::public.dish_category, '["Băm nhịn hành tây và tỏi.", "Trộn muối vào thịt heo băm. Thêm bột mì và yến mạch, sau đó hành tây và tỏi, rồi trứng. và cuối cùng sữa tươi. Khuấy hỗn hợp thịt cho đến khi chắc. Để trong tủ lạnh ít nhất 30 phút. Bạn cũng có thể làm hỗn hợp trước một ngày và để trong tủ lạnh.", "Đun chảo trên lửa vừa. Thêm bơ vào chảo và dùng thìa để hình thành các bánh nướng thịt heo theo kích thước bạn thích. Chúng tôi khuyên dùng khoảng 2 muỗng canh hỗn hợp cho mỗi bánh nướng.", "Chiên cho đến khi tạo lớp vỏ vàng đẹp cả hai bên và chín kỹ bên trong.", "Ăn nóng với salad khoai tây cổ điển kèm theo."]'::jsonb, 4);
