INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('fae1a4c8-8b91-51b4-bf33-2c966224bbb4', 'Bánh mì mở khoai tây Đần Mạch', 'man'::public.dish_category, '["Rửa sạch khoai và cho vào nồi nhỏ với nước và 1 muỗng canh muối. Đun sôi và nấu khoai khoảng 10 phút. Tắt bếp và để khoai trong nước 5 phút. Ráo khoai và để nguội một chút. Hãy nhớ rằng khoai có nhiều kích thước, thời gian nấu có thể thay đổi – nếu chúng không dễ trượt từ nĩa khi đâm và nâng ra khỏi nước, chúng chưa chín.", "Chiên lát thịt xông khói và chuyển sang đĩa đựng khăn giấy.", "Bóc vỏ hành tím và lát thành vòng mỏng.", "Đổ bột mì vào bát và trộn hành trong bột. Vớt hành ra và lắc dớt bột thừa.", "Đun dầu trong nồi trên lửa vừa. Bạn có thể kiểm tra dầu có đủ nóng hay không bằng cách cho một miếng hành nhỏ vào nồi. Nếu dầu bồng bềnh xung quanh hành, dầu đã sẵn sàng.", "Cho càng nhiều vòng hành càng được vào nồi thành một lớp. Không cho quá nhiều vòng hành cùng lúc.", "Chiên hành vài phút cho đến khi vàng nâu. Chuyển hành sang đĩa đựng khăn giấy và rắc muối. Lặp lại quy trình cho đến khi hết hành đã chiên.", "Đổ bơ lên một lát bánh mì đen lúa mạch Rye và xếp lát khoai tây tròn (hoặc, nếu khoai rất nhỏ, khoai cắt nửa) lên trên. Trangs trí bánh mì khoai mở của bạn với sốt Mayonnaise tốt, hành chiên giòn, thịt xông khói chiên và lá hẹ lát."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('fae1a4c8-8b91-51b4-bf33-2c966224bbb4', '0a54a485-30f4-57d2-a177-c6e2072ecafe', 500.0, 'g'::public.quantity_unit);
