INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('79987e97-6cb9-50f5-81ab-0e99aecab00c', 'Salad khoai tây cổ điển (Classic Potato Salad)', 'rau'::public.dish_category, '["Luộc khoai tây non vụ mới trong nước muối nhẹ trong 10 đến 12 phút. Ráo nước khi nửa khoai tây xé với nĩa và nâng ra dễ dàng rơi lại vào nồi. Để nửa khoai tây đứng và nguội.", "Gỡ và loại bỏ các đầu xơ của măng tây, sau đó cắt thành các miếng nhỏ. Bạn có thể đổ nước sôi lên măng tây đã cắt và để ngâm trong 2 phút nếu bạn thích ít hơi sống hơn.", "Kẹo nhỏ hẹ, hành tím tây và củ cải đỏ.", "Khuấy các nguyên liệu sốt cùng nhau và nems với muối và tiêu đen hạt/bột.", "Giữ một ít hẹ để trangs trí và trộn phần còn lại của rau với sốt.", "Nems với muối và tiêu đen hạt/bột, trangs trí bằng hẹ và phục vụ như món ăn kèm."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('79987e97-6cb9-50f5-81ab-0e99aecab00c', '0a54a485-30f4-57d2-a177-c6e2072ecafe', 600.0, 'g'::public.quantity_unit);
