INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('54cb7e96-7077-5fcf-8e23-d095890ceb97', 'Bánh mì black rye Denmark (Danish Rye Bread)', 'rau'::public.dish_category, '["Kết hợp lúa mạch đen nguyên cám và nước lọc trong một nồi và đun sôi. Đậy nắp và hầm trong 2 đến 3 phút.", "Chuyển lúa mạch đen đã luộc vào một bát trộn và kết hợp với bia đen, sữa bơ và muối.", "Tan men nở tươi trong hỗn hợp này và sau đó thêm các loại hạt dinh dưỡng.", "Thêm bột mì đa dụng và bột mì đen Rye, và xên khoảng 10 phút. Bạn cũng có thể dùng máy trộn bếp để xên bột.", "Chuyển bột vào một cái khay nướng đã nhớt dầu (2.5 l) và làm mịn bằng espátula.", "Chọc lỗ trên bề mặt bằng nĩa và đậy khay nướng bằng nilon bọc. Để bột nở trong 1½ giờ ở nhiệt độ phòng, hoặc trong 24 giờ trong tủ lạnh.", "Đun lò trước đến 200°C và nấu bánh trên kệ dưới trong khoảng 75 phút. Kiểm tra để chắc khô ở chính giữa, hoặc nếu dùng mức nhiệt lò, đặt nó để tắt khi chính giữa đạt 98°C", "Để bánh nguội hoàn toàn trước khi cắt lát.", "Lưu ý", "Nếu bạn để bột nở trong tủ lณะ, để nó ở nhiệt độ phòng trong 1 giờ trước khi nấu."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('54cb7e96-7077-5fcf-8e23-d095890ceb97', '56c0375c-1f3d-590d-bb93-8e71ebe11f95', 200.0, 'g'::public.quantity_unit);
