INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('f6f5d873-cb03-535c-bd93-6510464a490e', 'Cánh gà chiên siêu giòn (Extra crispy chicken wings)', 'man'::public.dish_category, '["Rửa cánh gà, khô khăn giấy.", "Đặt vào bát lớn.", "Nêm bột tỏi, muối, tiêu đen và nghệ (bạn có thể thêm gia vị khác nếu muốn).", "Ướp ít nhất một giờ.", "Đổ bột khoai mì lên đĩa.", "Lăn cánh gà trong bột sắn, đặt lên rácks hoặc đĩa để đứng. Để ít nhất 30 phút đến một giờ.", "Đun dầu ăn trong nồi cho đến khi nóng.", "Cho cánh gà vào chảo trên lửa vừa, chiên đến khi nhẹ vàng.", "Để ráo trên giấy, để cánh gà nghỉ ít nhất 10 phút, rồi trả về chảo nóng trên lửa lớn và chiên cho đến khi vàng.", "Thưởng thức."]'::jsonb, 4);
