INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('6af26a40-7bc8-52f7-bfb4-191155549149', 'Chuối nấu nhồi (Stuffed plantain cups)', 'rau'::public.dish_category, '["Bóc và rửa chuối nấu", "Thấm chúng khô", "Cắt chúng thành lát dày 4 cm", "Đun dầu lên để chiên đậm chuối nấu", "Ném chuối nấu vào dầu nóng cho chúng ngập", "Chiên chúng trong khoảng 7 phút", "Đặt chúng trên khăn giấy trong khoảng năm phút. Bạn không muốn chúng quá khô", "Dùng bình vắt chanh, ép lát chuối nấu thành chén", "Đặt trên khăn giấy hoặc khay", "Rồi đặt chén vào chiên đậm hoặc nồi với đủ dầu để ngập chúng", "Lấy ra khi vàng", "Nhồi với nhân bạn thích", "Thưởng thức!"]'::jsonb, 4);
