INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8b10b968-dc89-53a0-b329-a54c5844cf9e', 'Bánh mì bơ mini', 'rau'::public.dish_category, '["Trộn bột làm bánh mì, đường, men nở tức thì và muối trong bát trộn hoặc bát lớn.", "Thêm sữa ấm và bắt đầu nhéen bột.", "Khi bột đã mịn và dẻo, thêm bơ lạt và tiếp tục nhéen.", "Để bột nở trong bát đậy nắp cho đến khi tăng gấp hai, khoảng 90 phút.", "Đổ bột ra bề mặt rắc ít bột, chia bột và tròn tất cả các miếng thành quả bóng mịn.", "Mỡ nhẹ các khay nướng.", "Đặt bột lên khay.", "Đậy nắp các khay và để bánh nở cho đến khi phồng và mềm.", "Dùng chải, sơn trứng trắng lên bánh.", "Gần cuối thời gian nở, đậy lò 190°C.", "Mở nắp các khay, nướng 28 đến 32 phút cho đến khi vỏ bánh vàng.", "Vớt ra khỏi lò và thưởng thức!"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('8b10b968-dc89-53a0-b329-a54c5844cf9e', '2799d316-42f3-5e4d-bf3c-a54e5261f254', 2268.0, 'g'::public.quantity_unit);
