INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3a37b1fe-db79-5f02-a53d-994a80f5bb3a', 'Trứng muối cá tuyết (Codfish deviled eggs)', 'man'::public.dish_category, '["Đun trứng gà sôi trong 15 phút. Để trứng gà ở trong nước thêm 5 phút. Chạy dưới nước lạnh", "để trứng gà nguội thêm", "Để trứng gà nghỉ", "Bóc trứng gà", "Cắt trứng gà thành nửa và lấy lòng đỏ, đặt chúng vào bát", "Nghiền lòng đỏ trứng trong bát", "Trộn tất cả nguyên liệu ngoại trừ ngò tây và tiêu đen hạt/bột", "Đổ hỗn hợp vào túi croissant hoặc túi nilon", "Đổ hỗn hợp vào các lát trứng", "Thêm cá tuyết vào bên rộng của trứng", "Trangs trí bằng tiêu đen hạt/bột nghiền và ngô tây"]'::jsonb, 4);
