INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('85c9cc77-62c8-52d9-8272-3fba2cb85f20', 'Taco mít Dominica', 'rau'::public.dish_category, '["Đặt nồi lớn nước đun sôi, thêm mít, và để nấu khoảng 30 phút", "Lấy mít ra khỏi nồi và để nguội vài phút", "Chầm mít chắc và dùng dao lớn sắc cắt thành các lát mỏng", "Cắt càng nhiều như bạn cần", "Rồi cắt bỏ vỏ và lõi (Bạn có thể để lại lõi nếu muốn)", "Dùng nhẹ gấp thành hình vỏ taco, dùng hai căm để giữ nó vào.", "Đặt trên đĩa hoặc khay lớn và lặp lại quy trình này cho tất cả các lát mít", "Đun dầu chiên sâu, dùng que cắm chấm mít các lát vào chảo,", "Bạn có thể hướng dẫn các lát bằng que cắm chấm nếu cần", "Bạn có thể để lại các căm nhỏ trong vỏ taco và lấy chúng ra sau khi chúng đã nấu. Hoặc, bạn có thể làm như tôi đã làm. Nếu bạn dùng các căm lớn hơn, bạn có thể cần lấy chúng ra một cách an toàn. Hãy rất cẩn thận vì bạn cần điều chỉnh nó trong dầu nóng.", "Lấy ra khi vàng", "Đặt lên khăn giấy", "Làm lại cho phần còn lại của các vỏ", "Nhân vào vỏ với nhân bạn thích. Tôi đã chọn cá tuyết/ cá mặn"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('85c9cc77-62c8-52d9-8272-3fba2cb85f20', '7d35f13f-7ad7-5fc7-afba-911ce6398b30', 1.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('85c9cc77-62c8-52d9-8272-3fba2cb85f20', '8242f2bf-b031-5864-97d5-c1d35e094d8a', 1.0, 'piece'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('c6010a3a-c605-5f4e-8246-079924d0d3a9', 'Bánh mì Mastiff Dominica (Dominica mastiff bread)', 'rau'::public.dish_category, '["Trộn tất cả nguyên liệu khô trong một bát lớn (đường, muối và men nở tức thì)", "Trộn bằng một thìa gỗ lớn", "Thêm chất béo làm bánh Shortening hoặc lard và trộn", "Trộn kỹ bằng tay của bạn", "Thêm nước lọc ấm và trộn bột cho đến khi cứng", "Thêm thêm bột mì cho đến khi bột không dính", "Bạn có thể thêm bột lên một cái thớ đã rắc bột để đảm bảo nó được xên đúng cách", "Xên khoảng 8-10 phút", "Hình thành bột thành một cái tròn lớn và đậy để nghỉ trong 45 phút", "Xên bột lại trên một cái thớ đã rắc bột nhẹ (xên là phần quan trọng nhất của quá trình công thức này.", "Hình thành bột thành các kiểu bánh mong muốn của bạn và đặt trên một khay nướng hoặc khay bánh", "Để bánh nghỉ trong 25 phút", "Đun lò trước đến 190°C", "Nấu cho đến khi vàng nụi", "Hướng dẫn khi dùng men nở tươi", "Trộn 3½ 240 ml nước ấm (45°C đến 50°C), men nở và đường", "Thêm một chút muối và 225g bột mì đã lách vào hỗn hợp", "Khuấy hỗn hợp bằng một thìa gỗ", "Đặt ở một nơi ấm trong khoảng một giờ", "Hỗn hợp nên trông bọt với bọt", "Lách phần bột còn lại vào một cái bát lớn", "Đổ hỗn hợp men vào cái bát lớn qua bột", "Thêm chất béo làm bánh Shortening hoặc lard và trộn", "Thêm thêm bột mì cho đến khi bột không dính", "Bạn có thể thêm bột lên một cái thớ đã rắc bột để đảm bảo nó được xên đúng cách", "Xên khoảng 8-10 phút", "Hình thành bột thành một cái tròn lớn và đậy để nghỉ trong 45 phút", "Để bánh nghỉ trong 25 phút", "Đun lò trước đến 190°C", "Nấu cho đến khi vàng nụi"]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('c6010a3a-c605-5f4e-8246-079924d0d3a9', '6511004e-c078-51d9-90e7-492186b8e9c1', 1360.8, 'g'::public.quantity_unit);
