INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('23b6c1d6-5e89-5ee8-81b4-c51cfb6e5044', 'Bánh sắn (Cassava bread)', 'rau'::public.dish_category, '["Trộn các nguyên liệu khô trong một bát.", "Thêm nước lọc và trộn kỹ.", "Khi hỗn hợp có độ sánh như bột nguội, cuộn thành các viên nhỏ.", "Cuộn các viên bằng lòng bàn tay, rồi áp nhẹ thành đĩa.", "Trong một đĩa, phủ các viên với phần bột mì Pháp còn lại để tạo độ sánh thô.", "Đặt trên nồi nướng tấm sắt đúc nóng, nhấn nhẹ để làm phẳng và nướng cả hai mặt cho đến khi nhẹ vàng.", "Lấy ra và ăn hoặc thêm món ăn kèm đặc biệt của bạn."]'::jsonb, 4);
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('23b6c1d6-5e89-5ee8-81b4-c51cfb6e5044', '55961ee3-d882-571a-bd54-7c9dae859388', 720.0, 'ml'::public.quantity_unit);
