INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('40f7a942-a6f0-50df-8623-312f05406b18', 'Cánh gà lollipop (Chicken Lollipop)', 'man'::public.dish_category, '["Rửa gà với chanh", "Ráo nước và nêm gà", "Dùng kéo, cắt qua thịt ở đầu của cánh gà", "Thêm tất cả nguyên liệu nêm vào cánh gà", "Đổ dầu vào chiên áp suất, hoặc nồi cho đến mức khoảng 12,5 cm để gà sẽ bị ngập", "Chiên cho đến khi vàng trung bình, thêm sốt yêu thích của bạn (tôi dùng sốt mật ong tỏi nướng) để đặt vào lò", "Hoặc chiên cho đến khi vàng nếu bạn không đặt vào lò", "Dùng cọ silicon thêm sốt lên gà và đặt vào lò"]'::jsonb, 4);
