INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('5271ba7f-92cc-5d95-b109-c10ba835c1b7', 'Gói chuối nấu Dominica (plantain rolls)', 'rau'::public.dish_category, '["Bóc vỏ chuối nấu", "Lát chúng thành lát dày 0,6 cm (theo chiều ngang)", "Đun dầu trong chảo chiên và thêm lát chuối nấu của bạn vào chảo", "chuối nấu chiên giòn", "Khi chúng bắt đầu vàng nâu, lật chúng", "Vớt ra khỏi chảo khi cả hai mặt đều vàng, và đặt chúng trên đĩa đựng khăn giấy để hấp thụ dầu", "Đặt miếng lá lưới cá tuyết vào đầu lát chuối nấu của bạn và cuộn nó", "Giữ cuộn bằng que tăm hoặc xiên (tôi thích dùng xiên tre ghim)", "Trangs trí và thưởng thức!"]'::jsonb, 4);
