INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('5271ba7f-92cc-5d95-b109-c10ba835c1b7', 'dda12c43-6125-554d-9644-0c26114cca9a', 60.0, 'ml'::public.quantity_unit);
INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('447e12b0-1b43-571f-9e93-786da31ae4bd', 'Salad đu đủ Dominica (Papaya salad)', 'rau'::public.dish_category, '["Cắt, bóc vỏ và xé sợi đu đủ. Tôi đã dùng máy xé sợi tay. Nếu bạn không có máy xé, dùng máy bào.", "Bóc vỏ và xé sợi cà rốt.", "Cắt hành lá rất nhỏ", "Lát cà chua thành nửa", "Tôi sau đó trộn tất cả nguyên liệu", "Tôi rắc đậu phộng lên trên"]'::jsonb, 4);
