INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('3bbba31c-b72d-5de5-b4ef-359bc4076a40', 'Bánh chiên cà rốt và đậu (Carrot and Bean Fritters)', 'rau'::public.dish_category, '["Đổ các loại đậu đóng hộp vào rổ ráo, lột nước.", "Xén cà rốt rồi thêm đậu, trộn và nghiền cùng nhau. Nêm với tỏi, xạ hương, muối và tiêu đen hạt/bột.", "Hình thành hỗn hợp thành vien tròn, nhúng nhẹ vào bột chiên xù, rồi ép nhẹ các bánh chiên.", "Chiên các bánh chiên trong dầu nóng trong thời gian ngắn cho đến khi vàng. Đặt lên khay nướng đã nhớt dầu hoặc lót giấy nướng, nướng ở 200°C trong 10 phút."]'::jsonb, 4);
