INSERT INTO public.recipes (id, name, category, instructions, servings) VALUES ('8170c50b-4e83-51f9-95cb-9e8405faa686', 'Salad chua cà và cá (Sauerkraut and Fish Salad)', 'man'::public.dish_category, '["Luộc trứng và nướng lát bánh mì.", "Trộn sốt salad. Lưu ý: bạn có thể phục vụ salad này với sốt kem chua. Món sẽ khác nhưng vẫn rất ngon.", "Trộn chua cà, lát trứng, cá và miếng bánh mì. Phục vụ."]'::jsonb, 4);
